-- ============================
-- TAX SECTIONS (1.1 - 1.4)
-- ============================
INSERT INTO tax_sections (article_id, section_number, content, order_index, synced_to_vector_store, created_at,
                          updated_at)
VALUES ((SELECT id FROM tax_articles WHERE article_number = '1'),
        '1.1',
        'Azərbaycan Respublikasının Vergi Məcəlləsi Azərbaycan Respublikasında vergi sistemini, vergitutmanın ümumi əsaslarını, vergilərin müəyyən edilməsi, ödənilməsi və yığılması qaydalarını, vergi ödəyicilərinin və dövlət vergi orqanlarının, habelə vergi münasibətlərinin digər iştirakçılarının vergitutma məsələləri ilə bağlı hüquq və vəzifələrini, vergi nəzarətinin forma və metodlarını, vergi qanunvericiliyinin pozulmasına görə məsuliyyəti, dövlət vergi orqanlarının və onların vəzifəli şəxslərinin hərəkətlərindən (hərəkətsizliyindən) şikayət edilməsi qaydalarını müəyyən edir.',
        1,
        false,
        NOW(),
        NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '1'),
        '1.2',
        'Bu Məcəllə ilə Naxçıvan Muxtar Respublikasında və bələdiyyələrdə vergitutmanın ümumi əsasları və vergilər müəyyən edilir.',
        2,
        false,
        NOW(),
        NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '1'),
        '1.3',
        'Bu Məcəllə ilə müəyyən olunan anlayışlar və qaydalar vergitutma məqsədi ilə müəyyən edilir və müstəsna olaraq bu Məcəllə və onun əsasında qəbul edilmiş digər normativ hüquqi aktlar ilə tənzimlənən vergitutma və vergi nəzarəti ilə bağlı münasibətlər hüdudlarında tətbiq olunur.',
        3,
        false,
        NOW(),
        NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '1'),
        '1.4',
        'Bu Məcəllənin vergitutmanın ümumi əsasları, vergilərin ödənilməsi qaydaları (ödənilməsi mənbələri istisna olmaqla), vergi ödəyicilərinin və dövlət vergi orqanlarının, habelə vergi münasibətlərinin digər iştirakçılarının vergitutma məsələləri ilə bağlı hüquq və vəzifələri, vergi nəzarətinin forma və metodları, vergi qanunvericiliyinin pozulmasına görə məsuliyyət, dövlət vergi orqanlarının və onların vəzifəli şəxslərinin hərəkətlərindən (hərəkətsizliyindən) şikayət edilməsi qaydaları ilə bağlı müddəaları məcburi dövlət sosial sığorta haqqı, icbari tibbi sığorta haqqı və işsizlikdən sığorta haqqına münasibətdə də tətbiq olunur.',
        4,
        false,
        NOW(),
        NOW());
