INSERT INTO tax_sections (article_id, section_number, content, order_index, synced_to_vector_store, created_at,
                          updated_at)
VALUES ((SELECT id FROM tax_articles WHERE article_number = '2'),
        '2.1',
        'Azərbaycan Respublikasının vergi qanunvericiliyi Azərbaycan Respublikasının Konstitusiyasından, bu Məcəllədən və onlara uyğun olaraq qəbul edilmiş Azərbaycan Respublikasının qanunvericilik aktlarından ibarətdir.',
        1,
        false,
        NOW(),
        NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '2'),
        '2.2',
        'Bu Məcəllənin əsasında və ya onun icrası məqsədi ilə qəbul edilmiş normativ hüquqi aktlar bu Məcəllənin müddəalarına zidd olmamalıdır.',
        2,
        false,
        NOW(),
        NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '2'),
        '2.3',
        'Vergi qanunvericiliyi aktları ilə digər sahə qanunvericilik aktları arasında bu Məcəllənin 2.7-ci maddəsində nəzərdə tutulan hallar istisna olmaqla, vergitutma və vergi nəzarəti məsələləri üzrə ziddiyyət yarandıqda, vergi qanunvericiliyinin aktları tətbiq edilir.',
        3,
        false,
        NOW(),
        NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '2'),
        '2.4',
        'Aşağıdakılar istisna olunmaqla, vergi qanunvericiliyindən başqa digər qanunvericilik aktlarına vergitutma və vergi nəzarəti məsələləri daxil edilə bilməz:',
        4,
        false,
        NOW(),
        NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '2'),
        '2.4.1',
        'Azərbaycan Respublikasının İnzibati Xətalar Məcəlləsində nəzərdə tutulan vergi münasibətlərinə aid inzibati xətalar haqqında müddəalar;',
        5,
        false,
        NOW(),
        NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '2'),
        '2.4.2',
        'Azərbaycan Respublikasının Cinayət Məcəlləsində nəzərdə tutulan vergi cinayətləri haqqında müddəalar;',
        6,
        false,
        NOW(),
        NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '2'),
        '2.4.3',
        'vergi öhdəliklərinin üstünlüyü haqqında müflisləşmə və iflas haqqında qanunvericilikdə nəzərdə tutulan müddəalar;',
        7,
        false,
        NOW(),
        NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '2'),
        '2.4.4',
        'büdcə qanunvericiliyində vergilərlə bağlı müddəalar;',
        8,
        false,
        NOW(),
        NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '2'),
        '2.4.5',
        'vergilər üzrə dövlət təminatlarının verilməsi ilə bağlı müddəalar;',
        9,
        false,
        NOW(),
        NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '2'),
        '2.4.6',
        'hasilatın pay bölgüsü haqqında, əsas boru kəməri haqqında və digər bu qəbildən olan sazişlərdə və ya qanunlarda nəzərdə tutulan müddəalar.',
        10,
        false,
        NOW(),
        NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '2'),
        '2.4.7',
        'İxrac məqsədli neft-qaz fəaliyyəti və xüsusi iqtisadi zonalar haqqında qanunlarda nəzərdə tutulan müddəalar.',
        11,
        false,
        NOW(),
        NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '2'),
        '2.4.8',
        '"Sahibkarlıq sahəsində aparılan yoxlamaların tənzimlənməsi və sahibkarların maraqlarının müdafiəsi haqqında" Azərbaycan Respublikasının Qanununda vergi yoxlamaları (kameral vergi yoxlamaları istisna olmaqla) haqqında nəzərdə tutulan müddəalar;',
        12,
        false,
        NOW(),
        NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '2'),
        '2.4.9',
        '"Ələt azad iqtisadi zonası haqqında" Azərbaycan Respublikası Qanununda nəzərdə tutulmuş müddəalar.',
        13,
        false,
        NOW(),
        NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '2'),
        '2.4-1',
        'Vergi azadolmalarının və güzəştlərinin verilməsi ilə bağlı müddəalar yalnız bu Məcəllə ilə müəyyənləşdirilir. Bu Məcəllədən başqa digər normativ hüquqi aktlarda, o cümlədən bu Məcəllənin 2.4-cü maddəsində (bu Məcəllənin 2.4.9-cu maddəsi istisna olmaqla) göstərilən normativ hüquqi aktlarda vergi azadolmaları və güzəştləri ilə bağlı müddəalar nəzərdə tutula bilməz. Sahibkarlıq və investisiya fəaliyyətini təşviq edən vergi azadolmaları və güzəştləri fərdi xarakter daşımamalıdır.',
        14,
        false,
        NOW(),
        NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '2'),
        '2.5',
        'Azərbaycan Respublikasının tərəfdar çıxdığı beynəlxalq müqavilələrdə vergilər haqqında bu Məcəllə ilə və ona müvafiq olaraq qəbul edilmiş normativ hüquqi aktlarla nəzərdə tutulmuş müddəalardan fərqli müddəalar müəyyən edildikdə, həmin beynəlxalq müqavilələrin müddəaları tətbiq edilir.',
        15,
        false,
        NOW(),
        NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '2'),
        '2.6',
        'Azərbaycan Respublikasının tərəfdar çıxdığı ikiqat vergitutmanın aradan qaldırılması haqqında beynəlxalq müqavilə ilə bu müqavilə bağlanan dövlətin rezidentinə verilən vergi güzəştlərinə və üstünlüklərinə münasibətdə vergidən yayınma məqsədilə istifadə edilirsə, o cümlədən həmin müqavilə onu bağlamış dövlətin rezidenti olmayan şəxs tərəfindən qeyd edilən güzəştlərin və üstünlüklərin alınması üçün istifadə edilirsə, bu Məcəllənin 2.5-ci maddəsinin müddəaları tətbiq olunmur.',
        16,
        false,
        NOW(),
        NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '2'),
        '2.7',
        'Bu Məcəllə qüvvəyə minənədək və ya o, qüvvəyə mindikdən sonra qanunla təsdiq olunmuş hasilatın pay bölgüsü haqqında, əsas boru kəməri haqqında və digər bu qəbildən olan sazişlərdə və ya qanunlarda, o cümlədən neft və qaz haqqında, ixrac məqsədli neft-qaz fəaliyyəti və xüsusi iqtisadi zonalar haqqında qanunlarda bu Məcəllədə və vergilər haqqında digər normativ hüquqi aktlarda nəzərdə tutulmuş müddəalardan fərqli müddəalar müəyyən edildikdə, həmin sazişlərin və ya qanunların müddəaları tətbiq edilir.',
        17,
        false,
        NOW(),
        NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '2'),
        '2.7-1',
        'Ələt azad iqtisadi zonasında vergitutma və vergi nəzarəti, vergi azadolmaları və güzəştləri ilə bağlı məsələlər "Ələt azad iqtisadi zonası haqqında" Azərbaycan Respublikası Qanununun tələblərinə uyğun olaraq tənzimlənir.',
        18,
        false,
        NOW(),
        NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '2'),
        '2.8',
        'Növbəti ilin dövlət büdcəsi layihəsi çərçivəsində vergi siyasəti, vergi inzibatçılığı və vergi dərəcələrinin müəyyən edilməsi ilə bağlı Azərbaycan Respublikasının Vergi Məcəlləsinə dəyişikliklər edilməsi zərurəti yarandıqda həmin qanun layihələri və layihələrdə nəzərdə tutulan vergi azadolmalarının və güzəştlərinin müvafiq icra hakimiyyəti orqanının müəyyən etdiyi orqan (qurum) tərəfindən müəyyən edilmiş qaydada aparılan qiymətləndirilməsinin nəticələrinə dair arayış müvafiq icra hakimiyyəti orqanına cari ilin may ayının 1-dək, müvafiq icra hakimiyyəti orqanı tərəfindən isə Azərbaycan Respublikasının Milli Məclisinə cari ilin may ayının 15-dən gec olmayaraq təqdim edilir.',
        19,
        false,
        NOW(),
        NOW());



