       ((SELECT id FROM tax_articles WHERE article_number = '3'),
        '3.3',
        'Hər kəsin konstitusiya hüquqlarının və azadlıqlarının həyata keçirilməsinə maneçilik törədən vergilərin müəyyən edilməsinə yol verilmir.',
        3,
        false,
        NOW(),
        NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '3'),
        '3.4',
        'Azərbaycan Respublikasının vahid iqtisadi məkanını pozan (xüsusilə, Azərbaycan Respublikasının ərazisində malların (işlərin, xidmətlərin) və pul vəsaitlərinin azad yerdəyişməsini bilavasitə və ya dolayısı ilə məhdudlaşdıran və ya digər yolla vergi ödəyicilərinin qanuni fəaliyyətini məhdudlaşdıran, yaxud maneçilik törədən) vergilərin müəyyən edilməsinə yol verilmir.',
        4,
        false,
        NOW(),
        NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '3'),
        '3.5',
        'Heç bir şəxs əldə etdiyi mənfəətdən (gəlirdən) eyni növ vergini bir dəfədən artıq ödəməyə məcbur edilə bilməz.',
        5,
        false,
        NOW(),
        NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '3'),
        '3.6',
        'Vergilər siyasi, ideoloji, etnik, konfessional və vergi ödəyiciləri arasında mövcud olan digər xüsusiyyətlər əsas götürülməklə müəyyən edilə bilməz və diskriminasiya xarakteri daşıya bilməz. Mülkiyyət formasından və ya fiziki şəxslərin vətəndaşlığından və ya kapitalın yerindən asılı olaraq vergilərin müxtəlif dərəcələrinin müəyyən edilməsi qadağandır. Azərbaycan Respublikasına gətirilən mallar üçün həmin malların hansı ölkədən gətirilməsindən asılı olaraq bu Məcəlləyə və gömrük qanunvericiliyinə uyğun olaraq müxtəlif gömrük rüsumu dərəcələrinin müəyyən edilməsi mümkündür.',
        6,
        false,
        NOW(),
        NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '3'),
        '3.7',
        'Azərbaycan Respublikasının vergiləri yalnız bu Məcəllə ilə müəyyən edilir, onların dəyişdirilməsi və ya ləğv edilməsi bu Məcəlləyə dəyişiklik edilməsi ilə həyata keçirilir.',
        7,
        false,
        NOW(),
        NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '3'),
        '3.8',
        'Heç bir şəxsin üzərinə bu Məcəllə ilə müəyyən edilən vergilərin xüsusiyyətlərinə malik olan və bu Məcəllə ilə müəyyən edilməyən, yaxud bu Məcəllə ilə müəyyən edilən qaydalardan fərqli olaraq müəyyən edilən vergilər ödəmək vəzifəsi qoyula bilməz.',
        8,
        false,
        NOW(),
        NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '3'),
        '3.9',
        'Vergilər haqqında qanunvericilik elə tərzdə formalaşdırılmalıdır ki, hər kəs hansı vergiləri, hansı qaydada, nə vaxt və hansı məbləğdə ödəməli olduğunu dəqiq bilsin.',
