        11,
        false,
        NOW(),
        NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '3'),
        '3.12',
        'Fiziki və hüquqi şəxslərin vergilərə aid normativ hüquqi aktlarla azad tanış olmaq imkanı təmin edilməlidir.',
        12,
        false,
