INSERT INTO tax_sections (article_id, section_number, content, order_index, synced_to_vector_store, created_at,
                          updated_at)
VALUES ((SELECT id FROM tax_articles WHERE article_number = '4'),
        '4.1',
        'Azərbaycan Respublikasında aşağıdakı vergilər müəyyən edilir və ödənilir:',
        1,
        false,
        NOW(),
        NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '4'),
        '4.1.1',
        'dövlət vergiləri;',
        2,
        false,
        NOW(),
        NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '4'),
        '4.1.2',
        'muxtar respublika vergiləri;',
        3,
        false,
        NOW(),
        NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '4'),
        '4.1.3',
        'yerli vergilər (bələdiyyə vergiləri).',
        4,
        false,
        NOW(),
        NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '4'),
        '4.2',
        'Dövlət vergiləri dedikdə, bu Məcəllə ilə müəyyən edilən və Azərbaycan Respublikasının bütün ərazisində ödənilməli olan vergilər nəzərdə tutulur.',
        5,
        false,
        NOW(),
        NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '4'),
        '4.3',
        'Muxtar respublika vergiləri dedikdə, Naxçıvan Muxtar Respublikasında bu Məcəlləyə müvafiq olaraq Naxçıvan Muxtar Respublikasının qanunları ilə müəyyən edilən və Naxçıvan Muxtar Respublikasında ödənilən vergilər nəzərdə tutulur.',
        6,
        false,
        NOW(),
        NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '4'),
        '4.4',
        'Yerli vergilər (bələdiyyə vergiləri) dedikdə, bu Məcəllədə və müvafiq qanunla müəyyən edilən, bələdiyyələrin qərarlarına əsasən tətbiq edilən və bələdiyyələrin ərazilərində ödənilən vergilər nəzərdə tutulur. Bələdiyyələr tərəfindən tətbiq edilən digər məcburi ödənişlər müvafiq qanunla müəyyən edilir. Yerli vergilərin (bələdiyyə vergilərinin) dərəcələri vergi qanunvericiliyində təsbit edilmiş hədlər daxilində müəyyən edilir. Vergi qanunvericiliyinə uyğun olaraq bələdiyyələr öz ərazilərində vergi ödəyicilərinin ayrı-ayrı kateqoriyalarını yerli vergilərdən tam və ya qismən azad etmək, vergi dərəcəsini azaltmaq barədə qərar qəbul edə bilərlər.',
        7,
        false,
        NOW(),
        NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '4'),
        '4.5',
