       ((SELECT id FROM tax_articles WHERE article_number = '13'),
        '13.2.7.9',
        'qəyyumlar və qəyyumluğa götürülənlər, onların arasındakı ev təsərrüfatı birliyi nəticəsində biri o biri ilə valideyn və övlad kimi bağlı olduqda.',
        27,
