        NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '13'),
        '13.2.8',
        'Mal - hər hansı maddi və ya qeyri-maddi əmlak (aktiv), o cümlədən elektrik və istilik enerjisi, qaz və su. Əlavə dəyər vergisinin (ƏDV) məqsədləri üçün qeyri-maddi aktivlər, pul vəsaiti və torpaq mal sayılmır.',
        28,
        false,
        NOW(),
        NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '13'),
        '13.2.9',
        'Qeyri-maddi aktivlər - intellektual, o cümlədən ticarət nişanları, digər sənaye mülkiyyəti obyektləri, virtual aktivlər, habelə müvafiq qanunvericiliklə müəyyən edilmiş qaydada vergi ödəyicisinin mülkiyyət hüququnun obyekti kimi tanınan digər analoji hüquqlar.',
        29,
        false,
        NOW(),
        NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '13'),
        '13.2.10',
        'Malların təqdim edilməsi – mallar üzərində mülkiyyət hüququnun başqasına verilməsi, habelə bunlarla məhdudlaşdırılmayan, malların satışı, mübadiləsi, hədiyyə verilməsi, natura şəklində əməkhaqqı ödənilməsi və natura şəklində digər ödəmələr, həmçinin girov qoyulmuş mallar üzrə mülkiyyət hüququnun girov saxlayana və ya digər şəxsə keçməsi, bina tikintisi fəaliyyəti ilə məşğul olan şəxslər tərəfindən yaşayış və qeyri-yaşayış sahələrinin notarial qaydada təsdiq edilməklə, habelə notarial qaydada təsdiq edilmədən bağlanmış müqavilələr üzrə, həmçinin mənzil-tikinti kooperativi üzvlərinin ümumi yığıncağının qərarı ilə özgəninkiləşdirilməsi. Bina tikintisi fəaliyyəti ilə məşğul olan şəxslər tərəfindən yaşayış və qeyri-yaşayış sahələrinin təqdim edilməsi üzrə alqı-satqı müqavilələrinin sonradan eyni şəxslə notarial qaydada təsdiq edilməsi bu maddənin məqsədləri üçün vergi tutulan təqdimetmə hesab edilmir.',
        30,
        false,
        NOW(),
        NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '13'),
        '13.2.11',
        'Xidmət (iş) - malların təqdim edilməsi sayılmayan, nəticələri maddi ifadə kəsb edən fəaliyyət. ƏDV-nin məqsədləri üçün pul vəsaitinə və torpağa mülkiyyət, habelə torpaqdan istifadə hüququnun başqasına verilməsi, torpağın icarəyə verilməsi, həmçinin işəgötürənə muzdlu işçi kimi xidmət göstərilməsi istisna olunur. Xidmətlərin göstərilməsi (işlərin görülməsi) zamanı istifadə olunan mallar ayrıca təqdim edilmirsə və ya xidmətin (işin) dəyərinə daxil edilməyən kompensasiyalı xərclər müqavilədə və ya ödəniş sənədlərində ayrıca göstərilmirsə, həmin mallar və ya xərclər xidmətin (işin) ayrılmaz tərkib hissəsi hesab edilir.',
        31,
        false,
        NOW(),
        NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '13'),
        '13.2.12',
        'Gəlir – malların (işlərin və xidmətlərin) təqdim edilməsi ilə bağlı əməliyyatların ümumi dəyəri, habelə satışdankənar gəlir. Vergitutma məqsədləri üçün gəlirin əldə edilmə vaxtı bu Məcəllənin 132-ci və 135-ci maddələri ilə müəyyən olunur. Bina tikintisi fəaliyyəti ilə məşğul olan şəxslər tərəfindən tikilən binalardan dövlətə yaşayış və qeyri-yaşayış sahələri ayrıldıqda, dövlətə ayrılan yaşayış və qeyri-yaşayış sahələrinin təqdim edilməsi üzrə dövriyyələr vergiyə cəlb olunan gəlir hesab edilmir. Satışdankənar gəlirlər - digər müəssisələrin fəaliyyətində payçı kimi iştirakdan gəlir, müəssisəyə məxsus səhmlər, istiqrazlar və digər qiymətli kağızlardan əldə olunan gəlirlər, habelə mal və xidmət (iş) istehsalı və satışı ilə bilavasitə bağlı olmayan əməliyyatdan götürülən digər gəlirlər, o cümlədən cərimə və zərərin ödənilməsi şəklində alınmış məbləğ, xarici valyuta əməliyyatları üzrə artan məzənnə fərqi, qanunvericiliyə müvafiq iddia müddəti keçmiş kreditor və deponent borc məbləğləri.',
        32,
        false,
        NOW(),
        NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '13'),
        '13.2.13',
        'Vergi ödəyicisinin, alıcının, sifarişçinin və ya hər hansı şəxsin adı - hüquqi şəxsin dövlət qeyydiyatına alınmış adı, fiziki şəxsin adı, atasının adı və soyadı.',
        33,
        false,
        NOW(),
        NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '13'),
        '13.2.14',
