VALUES ((SELECT id FROM tax_articles WHERE article_number = '13'),
        '13.2.15',
        'Dividend - hüquqi şəxsin öz təsisçilərinin (payçılarının) və yaxud səhmdarlarının xeyrinə xalis mənfəətinin (sadələşdirilmiş vergi ödəyiciləri tərəfindən vergi və xərclər çıxıldıqdan sonra gəlirin) bölüşdürülməsi, o cümlədən hüquqi şəxs ləğv edilərkən xalis mənfəəti hesabına formalaşan əmlakın (aktivlərin) bölüşdürülməsi, habelə səhmlərin (payların) xalis mənfəət hesabına artırılan nominal dəyəri hüdudlarında geri alınması ilə bağlı pul və ya digər ödəmələr şəklində etdiyi ödəniş. Hüquqi şəxsin ləğvi ilə bağlı əmlakın bölüşdürülməsi nəticəsində əldə edilən gəlir (bölüşdürülməmiş mənfəət hesabına formalaşan əmlak istisna olmaqla), həmçinin səhmdarların səhmlərinin faiz nisbətini dəyişdirməyən səhmlərin bölüşdürülməsi, səhmlərin (hissələrin, payların) nominal dəyəri (bölüşdürülməmiş mənfəət hesabına səhmlərin (payların) artan nominal dəyəri istisna olmaqla) hüdudlarında geri alınması ilə bağlı edilən ödənişlər dividend sayılmır.',
        42,
        false,
        NOW(),
        NOW());

