       ((SELECT id FROM tax_articles WHERE article_number = '13'),
        '13.2.16.14-1',
        'bu Məcəllənin 128-ci maddəsində nəzərdə tutulan güzəştli vergi tutulan ölkələrdə və ya ərazilərdə təsis edilmiş (qeydiyyatdan keçmiş) şəxslərə, o cümlədən onların digər ölkələrdə olan filial və ya nümayəndəliklərinə, habelə güzəştli vergi tutulan ölkələrdə və ya ərazilərdə olan bank və digər ödəniş hesablarına rezidentlər və qeyri-rezidentlərin Azərbaycan Respublikasındakı daimi nümayəndəlikləri, habelə vergi orqanında uçotda olmayan rezident fiziki şəxslər tərəfindən birbaşa və ya dolayısilə edilən ödənişlər.',
