        '13.2.45',
        'İdman oyunları ilə əlaqədar aparılan mərc oyunlarının satıcısı - idman oyunları ilə əlaqədar aparılan mərc oyunlarının operatoru ilə bağlanmış müqaviləyə əsasən fəaliyyət göstərən və mərc oyununun iştirakçıları ilə idman oyunları ilə əlaqədar aparılan mərc oyunlarının operatoru arasındakı bütün əlaqələri mərkəzi mərc sisteminə bağlı olaraq təmin edən şəxs;',
        100,
        false,
        NOW(),
        NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '13'),
        '13.2.46',
        'Üçüncü şəxs - vergi orqanı tərəfindən kameral və ya səyyar qaydada yoxlanılan, vergi ödəyicisinin fəaliyyətində malların (işlərin, xidmətlərin) təqdim edilməsi ilə bilavasitə əlaqəli olan rezident və ya qeyri-rezident şəxs;',
        101,
        false,
        NOW(),
        NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '13'),
        '13.2.47',
        'Vergi riskləri - vergi öhdəliklərinin hər hansı səbəbdən düzgün müəyyən edilməməsi nəticəsində vergi ödəyicisinin maliyyə itkilərinə məruz qalmasının mümkünlüyü;',
        102,
        false,
        NOW(),
        NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '13'),
        '13.2.48',
        'Vergi risklərinin minimallaşdırılması - vergi ödəyicisinin vergi hesablamalarının tam və ya qismən yerinə yetirməsinə mənfi təsirlərin azaldılması və ya aradan qaldırılması;',
        103,
        false,
        NOW(),
        NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '13'),
        '13.2.49',
        'Vergi partnyorluğu sazişi - vergi orqanı ilə vergi ödəyicisi arasında vergi risklərinin minimallaşdırılması məqsədi ilə könüllü şəkildə bağlanmış niyyət razılaşması;',
        104,
        false,
        NOW(),
        NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '13'),
        '13.2.49-1',
        'vergi öhdəliyinin əvvəlcədən müəyyənləşdirilməsi barədə qərar – gələcəkdə həyata keçiriləcək vergi tutulan əməliyyatlar üzrə vergi öhdəliklərinin və vergi qanunvericiliyinin tətbiq edilməsinin doğuracağı hüquqi nəticələrin vergi orqanı tərəfindən əvvəlcədən müəyyən edilməsini təsdiq edən bu Məcəllənin 77-1-ci maddəsində nəzərdə tutulan sənəd;',
        105,
        false,
        NOW(),
        NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '13'),
        '13.2.49-2',
        'könüllü açıqlama – səyyar vergi yoxlaması və ya üfüqi monitorinq başa çatdıqdan sonra yoxlama (monitorinq) zamanı aşkar edilməyən və vergi öhdəliyinin, habelə məcburi dövlət sosial sığorta, işsizlikdən sığorta və icbari tibbi sığorta haqları üzrə öhdəliyin yaranmasına səbəb olan halların vergi ödəyiciləri tərəfindən vergi orqanlarına könüllü olaraq bəyan edilməsi, habelə səyyar vergi yoxlamasının keçirilməsindən asılı olmayaraq həmin halların bu Məcəllənin 85.5-ci maddəsində göstərilən 3 illik müddətdən əvvəlki dövrlər üzrə könüllü olaraq bəyan edilməsi;',
        106,
        false,
        NOW(),
        NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '13'),
        '13.2.50',
        'İri vergi ödəyicisi - bu Məcəllənin məqsədləri üçün aşağıdakı meyarlardan ən azı birinə uyğun olan vergi ödəyicisi (büdcə təşkilatları istisna olmaqla):',
        107,
        false,
        NOW(),
        NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '13'),
        '13.2.50.1',
        'əvvəlki 3 ilin hər birində mülkiyyətində olan əsas vəsaitlərinin ilin sonuna qalıq dəyəri 2.500.000 manatdan və əvvəlki 3 il üzrə orta illik dövriyyəsi (ƏDV-siz) 1.250.000 manatdan çox olduqda;',
        108,
        false,
        NOW(),
        NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '13'),
        '13.2.50.2',
        'son 3 vergi ili ərzində bu Məcəllə ilə müəyyən edilmiş bütün vergi və vergi olmayan digər ödənişlərin hesablanmış məbləği hər il üçün 500.000 manatdan çox olduqda;',
        109,
        false,
        NOW(),
        NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '13'),
        '13.2.50.3',
        'Azərbaycan Respublikasının qanunlarına uyğun olaraq təbii inhisarçılara və ya bazarda hökmran mövqe tutan subyektlərə aid olunan vergi ödəyiciləri, o cümlədən onların Azərbaycan Respublikasının rezidenti olan törəmə təsərrüfat cəmiyyətləri.',
        110,
        false,
        NOW(),
        NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '13'),
        '13.2.51',
        'Xüsusi vergi rejimli müəssisə - qanunla təsdiq edilmiş hasilatın pay bölgüsü, əsas ixrac boru kəməri haqqında və digər belə sazişlər və ya qanunlar, o cümlədən neft və qaz haqqında, ixrac məqsədli neft-qaz fəaliyyəti haqqında və xüsusi iqtisadi zonalar haqqında qanunlar çərçivəsində fəaliyyət göstərən, vergitutma və vergi nəzarəti məsələlərində müəyyən dövr ərzində vergilərin hesablanması və ödənilməsi xüsusi qaydalarla müəyyən edilən vergi ödəyiciləri, habelə xarici ölkələrin Azərbaycan Respublikasının ərazisində yerləşən diplomatik və analoji nümayəndəlikləri, konsulluq idarələri və digər rəsmi nümayəndəlikləri;',
        111,
        false,
        NOW(),
        NOW());

