VALUES ((SELECT id FROM tax_articles WHERE article_number = '13'),
        '13.2.52',
        'Sənaye parkının rezidenti – müvafiq icra hakimiyyəti orqanı tərəfindən müəyyən edilmiş qaydada sənaye parkının rezidentinin qeydiyyat şəhadətnaməsini almış və sənaye parkında fəaliyyət göstərən hüquqi şəxs və ya hüquqi şəxs yaratmadan sahibkarlıq fəaliyyətini həyata keçirən fiziki şəxs;',
        112, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '13'),
        '13.2.53',
        'Texnologiyalar parkının rezidenti – müvafiq icra hakimiyyəti orqanı tərəfindən müəyyən edilmiş qaydada texnologiyalar parkının qeydiyyat şəhadətnaməsini almış və texnologiyalar parkında və ya texnologiyalar parkından kənar fəaliyyət göstərən hüquqi şəxs və ya hüquqi şəxs yaratmadan sahibkarlıq fəaliyyətini həyata keçirən fiziki şəxs;',
        113, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '13'),
        '13.2.54',
        'bina – insanların yaşaması, fəaliyyəti, təbiət təsirlərindən qorunması, onlara sosial, mədəni və məişət xidmətlərinin göstərilməsi, istehsalat sahələrinin yerləşdirilməsi, maddi dəyərlərin saxlanması üçün nəzərdə tutulmuş qapalı həcm-fəza quruluşuna malik olan tikinti obyekti;',
        114, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '13'),
        '13.2.55',
        'ticarət fəaliyyəti – istehsalçılar tərəfindən özlərinin istehsal etdiyi malların təqdim edilməsi istisna olmaqla, malların təqdim edilməsi ilə əlaqədar sahibkarlıq fəaliyyəti;',
        115, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '13'),
        '13.2.56',
        'ictimai iaşə fəaliyyəti – fəaliyyət göstərdiyi xidmət obyektinin ərazisində və ya səyyar qaydada alıcıya istehlak məqsədilə hazırlanmış (bişirilmiş) qida (yeyinti) məhsullarının təqdim edilməsi ilə əlaqədar sahibkarlıq fəaliyyəti;',
        116, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '13'),
        '13.2.57',
        'tikinti-quraşdırma işlərinə başlama anı – tikintisinə icazə verilmiş tikinti obyektinin layihəsində, habelə Azərbaycan Respublikası Şəhərsalma və Tikinti Məcəlləsinin 80.4-cü maddəsində nəzərdə tutulan tələblərə riayət edilmiş barəsində məlumatlandırma icraatı tətbiq edilən tikinti obyektinin layihəsinin memarlıq-planlaşdırma bölməsində nəzərdə tutulmuş tikinti obyektinin inşası üzrə bilavasitə tikinti-quraşdırma işlərinə başlama anı;',
        117, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '13'),
        '13.2.58',
        'investisiya təşviqi sənədi - investisiya fəaliyyətini həyata keçirən hüquqi şəxslərə və fərdi sahibkarlara müvafiq icra hakimiyyəti orqanının müəyyən etdiyi qaydaya uyğun olaraq verilən, bu Məcəllənin 102.1.23-cü, 106.1.17-ci, 164.1.26-cı, 199.11-ci və 207.5-ci maddələrində (bu Məcəllənin 67-2-ci maddəsi nəzərə alınmaqla) və "Gömrük tarifi haqqında" Azərbaycan Respublikasının Qanununda nəzərdə tutulmuş güzəştlərin əldə edilməsinə əsas verən sənəddir;',
        118, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '13'),
        '13.2.59',
        'Maliyyə bazarlarına nəzarət orqanı – maliyyə bazarlarında tənzimləmə və nəzarətin həyata keçirilməsi məqsədilə müvafiq icra hakimiyyəti orqanının yaratdığı qurum;',
        119, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '13'),
        '13.2.60',
        'kənd təsərrüfatı məhsullarının istehsalı – sənaye üsulu (o cümlədən xüsusi broyler təsərrüfatları, avtomatlaşdırılmış tövlə sistemləri və sair) da daxil olmaqla, heyvanların və quşların yetişdirilməsi, bəslənməsi, diri şəkildə olarkən onlardan məhsulların (ilkin formada, yarımfabrikat kimi istifadə olunaraq yeni məhsula çevrilmədən, kimyəvi tərkibi dəyişdirilmədən, konservləşdirilmədən) əldə edilməsi, bitkiçilik məhsullarının becərilməsi. Bu maddənin və bu Məcəllənin 13.2.61-ci maddəsinin müddəaları balıqçılığa (balıq kürüsünün istehsalı istisna olmaqla) da şamil edilir. Emal əməliyyatlarına məruz qalan balıq məhsulları istisna olmaqla, balıqyetişdirmə fəaliyyətini həyata keçirən şəxslər tərəfindən kəsilmə və dondurulma əməliyyatlarına məruz qalan balıq məhsulları bu Məcəllənin məqsədləri üçün kənd təsərrüfatı məhsullarına bərabər tutulur;',
        120, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '13'),
        '13.2.61',
        'kənd təsərrüfatı məhsullarının satışı – bu Məcəllənin məqsədləri üçün aşağıdakı tələblər çərçivəsində kənd təsərrüfatı məhsullarının təqdim edilməsi:',
        121, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '13'),
        '13.2.61.1',
        'istehsal olunan (o cümlədən sənaye üsulu ilə, xüsusi broyler təsərrüfatlarında, avtomatlaşdırılmış tövlə sistemlərində və digər yerlərdə) canlılar diri şəkildə, habelə onlardan diri şəkildə olarkən əldə edilmiş məhsullar ilkin formada, heç bir kimyəvi təsirə məruz qalmadan təqdim edilməlidir;',
        122, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '13'),
        '13.2.61.2',
        'bitkiçilik məhsulları və digər kənd təsərrüfatı məhsulları təqdim edilərkən təbiətdə olduğu ilkin formasını saxlamalı, kimyəvi tərkibi dəyişdirilməməli, konservləşdirilməməlidir;',
        123, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '13'),
        '13.2.62',
        'pərakəndə satış – malların alıcıya satışının (təqdim edilməsinin) son istehlak məqsədi ilə və yalnız bu Məcəllədə müəyyən edilmiş qaydada qəbz və ya nəzarət-kassa aparatının çeki (sahibkarlıq fəaliyyətini həyata keçirən hüquqi və fiziki şəxslərin tələbi ilə qaimə-faktura və ya elektron-qaimə faktura və ya elektron vergi hesab-fakturası) təqdim edilməklə həyata keçirilməsi üzrə ticarət fəaliyyəti;',
