        'transfer qiyməti – bu Məcəllənin 14-1.2-ci maddəsində göstərilən şəxslər arasında aparılan əməliyyatlar zamanı müəyyən edilən və müstəqil şəxslər arasında eyni şərtlər daxilində həyata keçirilən müqayisə edilə bilən əməliyyatlarda təsbit olunan qiymətlərə uyğun olmalı qiymət;',
