       ((SELECT id FROM tax_articles WHERE article_number = '13'),
        '13.2.66',
        'maliyyə institutu – bu Məcəllənin məqsədləri üçün aşağıdakı fəaliyyətlərdən ən azı birini həyata keçirən vergi ödəyicisi:',
        128, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '13'),
        '13.2.66.1',
        'bank fəaliyyəti;',
        129, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '13'),
        '13.2.66.2',
        'həyatın yığım sığortası və (və ya) annuitet sığortası fəaliyyəti;',
        130, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '13'),
        '13.2.66.3',
        'depozitar fəaliyyəti – bu Məcəllənin məqsədlərinə uyğun olaraq, depozitar dedikdə, fəaliyyətinin əhəmiyyətli hissəsini digər şəxslər üçün maliyyə aktivlərinin saxlanılmasını təşkil edən hüquqi şəxs nəzərdə tutulur. Müəssisənin aşağıdakı müddətlərdən daha az olan müddət ərzində digər şəxslər üçün maliyyə aktivlərinin saxlanılması və əlaqədar maliyyə xidmətlərinin göstərilməsi fəaliyyətindən əldə etdiyi mənfəət onun ümumi fəaliyyəti üzrə əldə etdiyi mənfəətin ən azı 20%-ni təşkil edirsə, maliyyə aktivlərinin saxlanılması təşkilatın fəaliyyətinin əhəmiyyətli hissəsini təşkil etmiş hesab olunur:',
        131, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '13'),
        '13.2.66.3.1',
        'maliyyə institutunun depozitar kimi təsbit edildiyi ildən əvvəlki ilin 31 dekabrında (və ya təqvim ili olmayan hesabat dövrünün son günündə) başa çatan üç illik müddət;',
        132, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '13'),
        '13.2.66.3.2',
        'müəssisənin fəaliyyət göstərdiyi müddət;',
        133, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '13'),
        '13.2.66.4',
        'qiymətli kağızların (veksellər, depozitar qəbzi və sair), törəmə maliyyə alətlərinin, xarici valyutaların məzənnə, faiz dərəcəsi və indeks alətləri, qiymətli kağızlarla ticarət və ya əmtəə üzrə fyuçerslərin müştəri üçün və ya müştərinin adından aparılan ticarət fəaliyyəti;',
        134, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '13'),
        '13.2.66.5',
