        'bu Məcəllənin 13.2.66.1 – 13.2.66.5-ci maddələrində qeyd olunmuş fəaliyyətlərdən hər hansı biri ilə məşğul olan şəxs tərəfindən idarə olunan hüquqi şəxsin həyata keçirdiyi fəaliyyət;',
        136, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '13'),
        '13.2.67',
        'maliyyə institutlarında vergi monitorinqi – maliyyə institutları tərəfindən vergi və maliyyə məlumatlarının mübadiləsini nəzərdə tutan, Azərbaycan Respublikasının tərəfdar çıxdığı beynəlxalq müqavilələrin tələblərinə əməl edilməsi işinə nəzarət tədbirləri;',
        137, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '13'),
        '13.2.68',
        'elektron audit – vergi ödəyicisinin elektron formatda saxlanılan maliyyə (mühasibat) məlumatlarına xüsusi proqram təminatı vasitəsilə birbaşa və ya məsafədən çıxış imkanı yaradılmaqla aparılan vergi yoxlaması;',
        138, false, NOW(), NOW()),
