        'vergi üstünlüyü – vergi tutulan əməliyyatın faktiki iqtisadi göstəriciləri dəyişmədən, vergilərin bu Məcəllədə müəyyən edilmiş müddətlərdə və məbləğdə ödənilməsindən yayınma;',
