        141, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '13'),
        '13.2.72',
        'elektron kabinet – vergi ödəyicisi kimi uçota alınma zamanı təqdim edilən ərizəyə əsasən müvafiq icra hakimiyyəti orqanının müəyyən etdiyi orqanın (qurumun) informasiya sistemində yaradılan, gücləndirilmiş elektron imza və (və ya) vergi orqanı tərəfindən verilən kod-parol (bu Məcəllənin 218.4.1-ci və 220.10-cu maddələrində, habelə "Sosial sığorta haqqında" Azərbaycan Respublikası Qanununun 14.5.1-1.3-cü maddəsində nəzərdə tutulan vergi ödəyicilərinə münasibətdə) ilə daxil olmağa imkan verən, vergi ödəyicisi ilə vergi orqanı arasında qarşılıqlı məlumat mübadiləsini təmin edən fərdi elektron səhifə;',
        142, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '13'),
        '13.2.73',
        'iqtisadi maraqlar mərkəzi – vergi ödəyicisinin əsas nəzarət orqanlarının yerləşdiyi yerdən asılı olmayaraq, digər təsərrüfat subyektləri (obyektləri), o cümlədən istehsal sahələri ilə müqayisədə vergi ödəyicisinin fəaliyyəti üzrə gəlirlərinin formalaşmasında daha çox iştirak edən təsərrüfat subyektinin (obyektinin), o cümlədən istehsal sahəsinin yerləşdiyi yer;',
        143, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '13'),
        '13.2.74',
        'kapital – aktivlərdən bütün öhdəliklər çıxıldıqdan sonra vergi ödəyicisinin xalis aktivlərinin dəyəri;',
        144, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '13'),
        '13.2.75',
        'məcburi nişanlama – bu Məcəllənin 50-2.1-ci maddəsində nəzərdə tutulan qaydalarda müəyyən olunmuş malların idxalı, istehsalı, satışı və dövriyyəsinə vergi nəzarətinin həyata keçirilməsi məqsədilə həmin mallara tətbiq olunan məcburi nişanlama kodu və digər qoruyucu elementlər;',
        145, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '13'),
        '13.2.76',
        'aksiz markası – aksizli malların idxalı, istehsalı, satışı və dövriyyəsinə vergi nəzarətinin həyata keçirilməsi məqsədilə həmin mallara kağız daşıyıcıda yapışdırılan nəzarət markası;',
        146, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '13'),
        '13.2.77',
        'innovasiya fəaliyyəti – iqtisadi və ya sosial səmərə əldə etmək məqsədi ilə elmi-tədqiqat və təcrübə-konstruktor işləri və onların nəticələrinin tətbiqi əsasında yeni və ya təkmilləşdirilmiş mal (iş, xidmət), texnoloji proses yaradılmasına və yerinə yetirilməsinə istiqamətlənmiş fəaliyyət;',
        147, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '13'),
        '13.2.78',
        'KOB klaster şirkəti – müvafiq icra hakimiyyəti orqanının müəyyən etdiyi orqan (qurum) tərəfindən müəyyən edilmiş meyarlara cavab verən və müvafiq icra hakimiyyəti orqanının müəyyən etdiyi orqan (qurum) ilə razılaşdırmaqla mikro, kiçik və orta sahibkarlığın inkişafını dəstəkləyən müvafiq icra hakimiyyəti orqanının müəyyən etdiyi orqanın (qurumun) KOB klaster şirkətinin şəhadətnaməsi verdiyi hüquqi şəxs;',
        148, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '13'),
        '13.2.79',
        'KOB klasterinin iştirakçısı – KOB klasterində fəaliyyət göstərmək üçün KOB klaster şirkəti ilə müqavilə bağlamış, mikro, kiçik və orta sahibkarlıq subyekti olan və mikro, kiçik və orta sahibkarlığın inkişafını dəstəkləyən müvafiq icra hakimiyyəti orqanının müəyyən etdiyi orqan (qurum) tərəfindən KOB klasterinin iştirakçısı şəhadətnaməsi verilmiş hüquqi və ya fiziki şəxs;',
        149, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '13'),
        '13.2.80',
        'startap – innovativ təşəbbüsə əsaslanaraq həyata keçirilən, müvafiq icra hakimiyyəti orqanının müəyyən etdiyi orqan (qurum) tərəfindən müəyyən edilmiş meyarlara cavab verən və mikro, kiçik və orta sahibkarlığın inkişafını dəstəkləyən müvafiq icra hakimiyyəti orqanının müəyyən etdiyi orqan (qurum) tərəfindən "Startap" şəhadətnaməsi verilmiş şəxslərin həyata keçirdiyi sahibkarlıq fəaliyyəti;',
        150, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '13'),
        '13.2.81',
        'əmtəəsiz əməliyyat – vergi nəzarəti tədbiri zamanı aşkarlanan, başqa əməliyyatı pərdələmək məqsədilə və ya bu cür məqsəd olmadan aparılan və faktiki olaraq mallar, işlər və xidmətlər təqdim edilmədən mənfəət (gəlir) əldə etmək məqsədilə rəsmiləşdirilən uydurma və (və ya) yalan əqd çərçivəsində aparılan əməliyyatlar;',
        151, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '13'),
        '13.2.82',
        'riskli vergi ödəyicisi – müvafiq icra hakimiyyəti orqanının müəyyən etdiyi orqanın (qurumun) təsdiq etdiyi risk meyarlarına cavab verən, o cümlədən əmtəəsiz və (və ya) riskli əməliyyatlar aparan şəxsdir. Vergi ödəyicisinin riskli vergi ödəyicilərinin siyahısına daxil edilməsi və həmin siyahıdan çıxarılması qaydasını və şərtlərini müvafiq icra hakimiyyəti orqanının müəyyən etdiyi orqan (qurum) müəyyən edir. Vergi ödəyicisinin riskli vergi ödəyicilərinin siyahısına daxil edilməsi və həmin siyahıdan çıxarılması barədə qərar müvafiq icra hakimiyyəti orqanının müəyyən etdiyi orqan (qurum) tərəfindən qəbul edilir;',
        152, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '13'),
        '13.2.83',
        'transmilli şirkətlər qrupu – müxtəlif ölkələrdə rezident olan iki və ya daha çox müəssisənin daxil olduğu və ya bir ölkədə rezident olan və başqa ölkədə daimi nümayəndəlik vasitəsilə fəaliyyət göstərən müəssisənin daxil olduğu şirkətlər qrupu. Transmilli şirkətlər qrupuna daxil olan müəssisə dedikdə həmin müəssisə, həmin müəssisənin törəmə və asılı müəssisələri, habelə filial və nümayəndəlikləri nəzərdə tutulur;',
        153, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '13'),
        '13.2.84',
        'malların ixrac qeydi ilə satışı – malların ixrac edilməsi məqsədilə istehsalçılar tərəfindən ixracatçılara müvafiq icra hakimiyyəti orqanının müəyyən etdiyi orqan (qurum) tərəfindən müəyyən edilmiş qaydada satışı;',
        154, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '13'),
        '13.2.85',
        'nəzarət olunan xarici müəssisə - bu Məcəllənin 14-2.1-ci maddəsinin tələblərinə uyğun olan və vergitutma məqsədləri üçün qeyri-rezident müəssisə.',
        155, false, NOW(), NOW());


