-- ============================
-- TAX SECTIONS (14.1 - 14.10)
-- ============================
INSERT INTO tax_sections (article_id, section_number, content, order_index, synced_to_vector_store, created_at,
                          updated_at)
VALUES ((SELECT id FROM tax_articles WHERE article_number = '14'),
        '14.1',
        'Bazar qiyməti malın (işin, xidmətin) tələblə təklifin qarşılıqlı təsiri nəticəsində təşəkkül tapan qiyməti deməkdir.',
        1, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '14'),
        '14.2',
        'Bu maddədə başqa hallar nəzərdə tutulmamışdırsa, vergitutma məqsədləri üçün malların (işin, xidmətin) qiyməti tərəflərin əməliyyatda (əqddə) təsbit etdikləri qiymət qəbul edilir. Əks hal sübuta yetirilmirsə, bu qiymət bazar qiyməti kimi qəbul edilir.',
        2, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '14'),
        '14.3',
        'Bu Məcəllənin 14-1.2-ci maddəsində nəzərdə tutulan şəxslər arasında həyata keçirilən əməliyyatlar istisna olmaqla, bazar qiyməti nəzərə alınmaqla vergilərin hesablanması aşağıdakı hallarda həyata keçirilə bilər:',
        3, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '14'),
        '14.3.1',
        'Barter (mal mübadiləsi), idxal-ixrac əməliyyatları aparıldıqda;',
        4, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '14'),
        '14.3.2',
        'təsərrüfat əqdləri qarşılıqlı surətdə asılı olan şəxslər arasında həyata keçirildikdə;',
        5, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '14'),
        '14.3.3',
        '30 gün ərzində vergi ödəyicilərinin eyni xüsusiyyətli və ya eyni cinsli mallara (işə, xidmətə) tətbiq etdikləri qiymətlərin səviyyəsi, bu Məcəllənin 14.6.1-ci maddəsinin tələbləri, o cümlədən müvafiq icra hakimiyyəti orqanının müəyyən etdiyi orqan (qurum) tərəfindən müəyyən edilmiş təbii itki normaları daxilində zayolmadan əmələgələn itkilər nəzərə alınmaqla, bazarda eyni (analoji) mal (iş, xidmət) üçün müvafiq əməliyyatlar zamanı təşəkkül tapan qiymətlərin səviyyəsindən topdansatış ticarət fəaliyyəti sahəsində 10 faizdən, tikinti və istehsal fəaliyyəti sahəsində 20 faizdən, digər fəaliyyət sahələrində 30 faizdən çox (aşağı və yuxarı) fərqləndikdə;',
        6, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '14'),
        '14.3.4',
        'müəssisənin əmlakı qalıq dəyərindən artıq qiymətə sığortalandığı halda;',
        7, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '14'),
        '14.3.5',
        'daşınmaz əmlakın (sahibkarlıq fəaliyyəti məqsədləri üçün istifadə olunmayan yaşayış fondu istisna olmaqla) vergitutma məqsədləri üçün aylıq icarə haqqının məbləğinin müəyyən edilməsi zərurəti yarandıqda;',
        8, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '14'),
        '14.3.6',
        'vergi ödəyicisi tərəfindən vergi nəzarəti tədbiri zamanı malların (işlərin, xidmətlərin) təqdim edilməsinə (alınmasına) dair sənədlər təqdim edilmədikdə (mövcud olmadıqda).',
        9, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '14'),
        '14.4',
        'Bazar qiyməti mal (iş, xidmət) satılan anadək, lakin malın (işin, xidmətin) təqdim edildiyi andan çoxu 30 gün keçənədək (əvvəl və ya sonra) ən yaxın tarixdə eyni (analoji) mal (iş, xidmət) üçün müvafiq əməliyyatlar zamanı təşəkkül tapan qiymətlərə əsasən müəyyənləşdirilir. Bu zaman qiymətli kağızın bazar qiyməti bu qiymətli kağızın təqdim edildiyi andan əvvəlki ən yaxın tarixdə həmin emitentin eyni qiymətli kağızları üçün fond birjasının kotirovkasına əsasən müəyyənləşdirilir, bu şərtlə ki, kotirovkalar yuxarıda göstərilən qaydaya uyğun elan edilsin.',
        10, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '14'),
        '14.5',
        'Bazar qiyməti müəyyənləşdirilərkən, bu Məcəllənin 18-ci maddəsi ilə müəyyən edilən qarşılıqlı surətdə asılı olan şəxslər arasındakı əməliyyat yalnız o halda nəzərə alına bilər ki, onların münasibətləri həmin əməliyyatın nəticəsinə təsir göstərməmiş olsun.',
        11, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '14'),
        '14.6',
        'Bu Məcəllənin 14.4 və 14.5-ci maddələrinin müddəalarını tətbiq etmək mümkün olmadıqda, malın (işin, xidmətin) bazar qiyməti bu maddənin tələblərinə uyğun olaraq müəyyən edilir. Bu zaman malın (işin, xidmətin) istehsalına və (və ya) təqdim edilməsinə çəkilən adi məsrəflər (alınma qiyməti və ya qalıq dəyəri), nəqletmə, saxlanma, sığorta və digər bu cür məsrəflər, həmçinin adətən qarşılıqlı surətdə bağlı olmayan şəxslər arasında əməliyyatlar zamanı tələb və təkliflər amilinə əsasən əlavə yığım və güzəştlər nəzərə alınır. Bu güzəştlər malın keyfiyyətinin və ya digər istehlak xüsusiyyətlərinin itdiyi, yaxud yararlılıq müddətinin bitdiyi (bitməyə yaxınlaşdığı) və başqa bu cür hallarda da nəzərə alınır.',
        12, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '14'),
        '14.6.1',
        'Malların (işlərin, xidmətlərin) bazar qiymətləri müəyyənləşdirilərkən qiymətlərə təsir edə bilən aşağıdakı amillər nəzərə alınır:',
        13, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '14'),
        '14.6.1.1',
        'göndərilmiş malların (görülmüş işlərin, göstərilmiş xidmətlərin) həcmi (əmtəə partiyasının həcmi);',
        14, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '14'),
        '14.6.1.2',
        'öhdəliklərin icra olunması müddəti, ödəniş şərtləri;',
        15, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '14'),
        '14.6.1.3',
        'mallara (işlərə, xidmətlərə) tələb və təklifin dəyişməsi, (o cümlədən istehlakçı tələbinin mövsümi olaraq artıb-azalması);',
        16, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '14'),
        '14.6.1.4',
        'malların mənşə ölkəsi, alındığı və ya təqdim edildiyi yer;',
        17, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '14'),
        '14.6.1.5',
        'malların (işlərin, xidmətlərin) göndərilmə şərtləri;',
        18, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '14'),
        '14.6.1.6',
        'malların keyfiyyətinin və digər istehlak göstəricilərinin səviyyəsi;',
        19, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '14'),
        '14.6.1.7',
        'marketinq siyasətinin aparılması ilə əlaqədar olaraq analoqu olmayan yeni malların (işlərin, xidmətlərin) bazara çıxarılması, yaxud malların (işlərin, xidmətlərin) yeni bazara çıxarılması, istehlakçıların tanış olması məqsədilə əmtəə nümunələrinin təqdim edilməsi;',
        20, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '14'),
        '14.6.1.8',
        'işlərin görülməsi, xidmətlərin göstərilməsi, o cümlədən təmir, tikinti, quraşdırma işləri, nəqliyyat, icarə, təhsil, tibb xidmətləri və digər sahələr üzrə bazar qiymətləri müəyyənləşdirilərkən işlərin görüldüyü, xidmətlərin göstərildiyi ərazi, onların keyfiyyət göstəriciləri və qiymətlərə təsir edə bilən digər şərtlər nəzərə alınır.',
        21, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '14'),
        '14.6.2',
        'Malların (işlərin, xidmətlərin) keyfiyyəti ilə əlaqədar qiymətlər bazar qiymətlərindən aşağı səviyyədə müəyyənləşdirilərkən keyfiyyətin səviyyəsi səlahiyyətli şəxs tərəfindən təsdiq olunmalıdır.',
        22, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '14'),
        '14.6.3',
        'Eyni xüsusiyyətli və ya eyni cinsli mallarla (işlərlə, xidmətlərlə) müvafiq əmtəə (iş, xidmət) bazarında heç bir əməliyyat aparılmadıqda, rəsmi və açıq mənbələrdən bu malların (işlərin, xidmətlərin) bazar qiymətləri haqqında məlumat toplamaq mümkün olmadıqda, aşağıdakı qiymətləndirmə üsullarından istifadə edilə bilər:',
        23, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '14'),
        '14.6.3.1',
        'Sonrakı (təkrar) satış qiymətinə əsasən. Malların (işlərin, xidmətlərin) bazar qiyməti həmin malların (işlərin, xidmətlərin) sonrakı (təkrar) satış qiymətinə əsasən müəyyən olunur. Bazar qiyməti sonrakı satış qiymətindən tətbiq olunmuş əlavələr çıxılmaqla müəyyənləşdirilir.',
        24, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '14'),
        '14.6.3.2',
        'Dəyərin toplanması üsuluna əsasən. Bazar qiymətləri malları (işləri, xidmətləri) təqdim edənin əsaslandırılmış xərclərini və mənfəətini toplamaqla hesablanır.',
        25, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '14'),
        '14.6.3.3',
        'Ekspert rəyinə əsasən. Malların (işlərin, xidmətlərin) bazar qiymətləri müqavilə əsasında cəlb edilmiş ekspert tərəfindən müəyyənləşdirilir.',
        26, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '14'),
        '14.6.4',
        'Müəyyənləşdirilmiş bazar qiymətlərindən ancaq vergitutma məqsədləri üçün istifadə edilir və mallar (işlər, xidmətlər) qanunvericilikdə nəzərdə tutulmuş qaydada faktiki satış qiyməti ilə uçota alınır.',
        27, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '14'),
        '14.6.5',
        'Alınmış malların (işlərin, xidmətlərin) alış qiyməti bazar qiymətlərindən topdansatış ticarət fəaliyyəti sahəsində 10 faizdən, tikinti və istehsal fəaliyyəti sahəsində 20 faizdən, digər fəaliyyət sahələrində 30 faizdən çox yuxarıdırsa və onların dəyəri gəlirdən çıxılan xərclərə aid edilibsə, alınmış malların (işlərin, xidmətlərin) faktiki alış dəyərinin əsassız artırılması aşkar edildiyi halda həmin malların (işlərin, xidmətlərin) dəyəri gəlirdən çıxılan xərclərə bazar qiymətləri ilə aid edilir və vergilər yenidən hesablanır.',
        28, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '14'),
        '14.6.5.1',
        'alınmış malların (işlərin, xidmətlərin) faktiki alış dəyərinin əsassız artırılması aşkar edildiyi halda;',
        29, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '14'),
        '14.6.5.2',
        'malgöndərəni (iş görəni, xidmət göstərəni) müəyyənləşdirmək mümkün olmadıqda.',
        30, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '14'),
        '14.6.6',
        'Vergi ödəyicilərinin təqdim olunan mallara (işlərə, xidmətlərə) tətbiq etdikləri qiymətlərin səviyyəsi bu Məcəlləyə əsasən müəyyənləşdirilən bazar qiymətlərindən topdansatış ticarət fəaliyyəti sahəsində 10 faizdən, tikinti və istehsal fəaliyyəti sahəsində 20 faizdən, digər fəaliyyət sahələrində 30 faizdən çox aşağı olduqda, vergilər bazar qiymətləri əsasında, yuxarı olduqda isə faktiki təqdimolunma qiymətləri ilə hesablanır.',
        31, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '14'),
        '14.7',
        'Hər bir tərəfin mal (iş, xidmət) göndərməsi və əvəzinə digər mal (iş, xidmət) almasına uyğun olan əməliyyatların məcmusu mal (iş, xidmət) mübadiləsi əməliyyatını təşkil edir. Həmin əməliyyatların gedişində verilən (alınan) malların (işlərin, xidmətlərin) bazar qiymətləri bu maddənin müddəalarına uyğun olaraq müəyyən edilir.',
        32, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '14'),
        '14.8',
        'Vergi ödəyicisinin dövlət vergi orqanına bu və ya digər əməliyyatda malın (işin, xidmətin) bazar qiymətinin bu maddədə göstərildiyindən fərqli qaydada müəyyənləşdirilməsi barədə sübutlar vermək hüququ vardır.',
        33, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '14'),
        '14.9',
        'Malın (işin, xidmətin) bazar qiyməti müəyyənləşdirilərkən və təsbit olunarkən malın (işin, xidmətin) bazar qiymətləri və birja kotirovkaları haqqında rəsmi məlumat mənbələrindən, dövlət və yerli hakimiyyət orqanlarının məlumat bazalarından, vergi ödəyicilərinin dövlət vergi orqanlarına verdikləri məlumatdan, yaxud reklam mənbələrinin məlumatından və digər müvafiq məlumatlardan istifadə edilir.',
        34, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '14'),
        '14.10',
        'Qiymətləri müvafiq icra hakimiyyəti orqanı tərəfindən tənzimlənən mallar (işlər, xidmətlər) təqdim olunarkən (ixrac istisna olmaqla) və alınarkən vergitutma məqsədləri üçün müvafiq icra hakimiyyəti orqanı tərəfindən müəyyənləşdirilən qiymətlər əsas götürülür.',
        35, false, NOW(), NOW());

