        NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '14-1'),
        '14-1.2.3',
        'Azərbaycan Respublikasının rezidenti və (və ya) qeyri-rezidentin Azərbaycan Respublikasındakı daimi nümayəndəliyi ilə güzəştli vergi tutulan ölkələrdə təsis edilmiş (qeydiyyatdan keçmiş) subyektlər arasında;',
        9,
        false,
        NOW(),
        NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '14-1'),
        '14-1.2.4',
        'bu Məcəllənin 14-1.2.1-14-1.2.3-cü maddələrində göstərilən hallar istisna olmaqla, Azərbaycan Respublikasının rezidenti və ya qeyri-rezidentin Azərbaycan Respublikasındakı daimi nümayəndəliyi ilə qeyri-rezident şəxslər arasında, bu şərtlə ki:',
        10,
        false,
        NOW(),
        NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '14-1'),
        '14-1.2.4.1',
        'şəxslər beynəlxalq əmtəə birjalarında ticarət olunan məhsullar üzrə əməliyyat aparmış olsunlar və (və ya);',
        11,
        false,
        NOW(),
        NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '14-1'),
        '14-1.2.4.2',
        'Azərbaycan Respublikasının rezidenti və ya qeyri-rezidentin Azərbaycan Respublikasındakı daimi nümayəndəliyinin vergi ili ərzində ümumi gəlirləri 30 milyon manatdan çox və hər bir qeyri-rezident şəxslə apardığı əməliyyatların həcminin ümumi gəlirlərdə (xərclərdə) xüsusi çəkisi 30 faizdən artıq olsun.',
        12,
        false,
        NOW(),
        NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '14-1'),
        '14-1.3',
        'Bu Məcəllənin 14-1.2-ci maddəsində nəzərdə tutulan şəxslər arasında aparılan əməliyyatlar zamanı vergi ödəyicisinin təqdim etdiyi mallara (işlərə, xidmətlərə) tətbiq etdiyi qiymətlər eyni əməliyyat üçün bu Məcəllənin 14-1.2-ci maddəsində göstərilən şəxslər istisna olmaqla, digər şəxslər arasında eyni şəraitdə təşəkkül tapan qiymətlərin aşağı həddindən az olduqda, vergilər transfer qiyməti ilə, yuxarı həddindən çox olduqda isə faktiki satış qiyməti ilə hesablanır.',
        13,
        false,
        NOW(),
