        NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '14-2'),
        '14-2.1.1',
        'Azərbaycan Respublikasının rezidenti hesab edilən şəxs özü və ya qarşılıqlı surətdə asılı olduğu rezident və ya qeyri-rezident şəxslə birlikdə birbaşa və ya dolayısilə xarici müəssisədə 50 faizdən çox səsvermə hüququna və ya onun nizamnamə kapitalının 50 faizindən çoxuna və ya həmin xarici müəssisənin mənfəətinin 50 faizindən çox hissəsini əldə etmək hüququna sahibdirsə və;',
        2,
        false,
        NOW(),
        NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '14-2'),
        '14-2.1.2',
        'nəzarət olunan xarici müəssisənin mənfəətindən faktiki ödənilən vergi, bu Məcəlləyə uyğun olaraq həmin mənfəətdən ödənilməli mənfəət vergisinin 75 faizinə və ya daha aşağı hissəsinə bərabər olarsa və;',
        3,
        false,
        NOW(),
        NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '14-2'),
        '14-2.1.3',
        'xarici müəssisənin illik gəlirlərinin 30 faizindən çox olan hissəsi aşağıdakı gəlirlərdən ibarət olarsa:',
        4,
        false,
        NOW(),
        NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '14-2'),
        '14-2.1.3.1',
        'maliyyə aktivlərindən əldə edilən faiz;',
        5,
        false,
        NOW(),
        NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '14-2'),
        '14-2.1.3.2',
        'əqli mülkiyyətdən əldə edilən royalti;',
        6,
