        8,
        false,
        NOW(),
        NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '14-2'),
        '14-2.1.3.5',
        'sığorta, bankçılıq və digər maliyyə əməliyyatlarından əldə edilən gəlirlər;',
        9,
        false,
        NOW(),
        NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '14-2'),
        '14-2.1.3.6',
        'heç bir iqtisadi dəyər yaratmayan mal və xidmətlərdən gəlir əldə edən müəssisələr üzrə gəlir.',
        10,
        false,
        NOW(),
        NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '14-2'),
        '14-2.2',
        'Nəzarət olunan xarici müəssisənin mənfəətinin Azərbaycan Respublikasının rezidenti hesab edilən şəxsin vergi tutulan gəlirlərinə daxil edilməsi qaydası, habelə nəzarət olunan xarici müəssisə haqqında arayışın rezident fiziki və hüquqi şəxslər tərəfindən vergi orqanına təqdim edilmə forması və qaydası müvafiq icra hakimiyyəti orqanının müəyyən etdiyi orqan (qurum) tərəfindən təsdiq edilir.',
