       ((SELECT id FROM tax_articles WHERE article_number = '14-2'),
        '14-2.3',
        'Bu maddəyə uyğun olaraq nəzarət olunan xarici müəssisənin mənfəəti Azərbaycan Respublikasında vergiyə cəlb edilərkən eyni vergitutma obyektindən iki dəfə vergilərin hesablanmasına yol verilmir və həmin mənfəətdən ödənilən (tutulan) vergi məbləği nəzərə alınır.',
