VALUES ((SELECT id FROM tax_articles WHERE article_number = '15'),
        '15.1',
        'Vergi ödəyicisinin aşağıdakı hüquqları vardır:',
        1, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '15'),
        '15.1.1',
        'vergi orqanlarından qeydiyyat (uçot) yeri üzrə qüvvədə olan vergilər və onların ödənilməsi qaydasını və şərtlərini tənzimləyən normativ hüquqi aktlar, vergi ödəyicilərinin hüquq və vəzifələri, vergi orqanlarının və onların vəzifəli şəxslərinin səlahiyyətləri haqqında əvəzsiz olaraq yazılı məlumat almaq;',
        2, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '15'),
        '15.1.2',
        'vergi orqanlarından vergi qanunvericiliyinin tətbiq edilməsi məsələlərinə dair yazılı izahatlar almaq;',
        3, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '15'),
        '15.1.2-1',
        'vergi öhdəliyinin əvvəlcədən müəyyənləşdirilməsi barədə qərarın qəbul edilməsi məqsədilə vergi orqanlarına ərizə ilə müraciət etmək;',
        4, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '15'),
        '15.1.3',
        'bu Məcəllə ilə müəyyən edilmiş hallarda və qaydada vergi güzəştlərindən istifadə etmək;',
        5, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '15'),
        '15.1.4',
        'artıq ödənilmiş və ya artıq tutulmuş vergilərin vaxtında geri qaytarılmasını və ya əvəzləşdirilməsini tələb etmək;',
        6, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '15'),
        '15.1.5',
        'vergi münasibətlərində bilavasitə və ya öz nümayəndəsi vasitəsi ilə iştirak etmək;',
        7, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '15'),
        '15.1.6',
        'vergi yoxlaması ilə bağlı tərtib edilən aktların (protokolların) və vergi orqanlarının qərarlarının surətini almaq;',
        8, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '15'),
        '15.1.7',
        'vergi orqanlarından və onların vəzifəli şəxslərindən vergi ödəyicisinə münasibətdə vergilər haqqında qanunvericiliyə riayət olunmasını tələb etmək;',
        9, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '15'),
        '15.1.8',
        'vergi orqanlarının və onların vəzifəli şəxslərinin Vergi Məcəlləsinə və digər vergi normativ hüquqi aktlarına uyğun olmayan aktlarını (qərarlarını) və tələblərini yerinə yetirməmək;',
        10, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '15'),
        '15.1.9',
        'müəyyən edilmiş qaydada vergi orqanlarının və onların vəzifəli şəxslərinin hərəkətlərindən (hərəkətsizliyindən) inzibati qaydada və (və ya) məhkəməyə şikayət etmək;',
        11, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '15'),
        '15.1.10',
        'qanunvericiliklə müəyyən edilmiş qaydada kommersiya və (və ya) vergi sirrinin qorunmasını tələb etmək;',
        12, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '15'),
        '15.1.11',
        'vergi orqanlarının və ya onların vəzifəli şəxslərinin qeyri-qanuni aktları (qərarları) və hərəkətləri (hərəkətsizliyi) nəticəsində dəymiş zərərin tam ödənilməsini, qanunvericiliklə müəyyən edilmiş qaydada tələb etmək;',
        13, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '15'),
        '15.1.12',
        'vergi yoxlamalarının aktları və digər materialları ilə tanış olmaq, vergi orqanlarına və onların vəzifəli şəxslərinə vergilərin hesablanması və ödənilməsi, habelə keçirilən vergi yoxlamalarının aktları üzrə öz rəyini bildirmək;',
        14, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '15'),
        '15.1.13',
        'Xronometraj metodu ilə aparılan sonuncu müşahidədən sonra bu Məcəllənin 50-1.2-ci maddəsində göstərilən müddətlərə riayət olunmaqla istehsal həcminin və ya satış dövriyyəsinin dəyişməsi ilə əlaqədar xronometraj metodu ilə yeni müşahidənin aparılmasını vergi orqanlarından tələb etmək.',
        15, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '15'),
        '15.1.14',
        'vergi orqanlarında müəyyən edilmiş qaydada uçota alınması üçün nəzarət-kassa aparatının müəyyən olunmuş modelini sifariş vermək.',
        16, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '15'),
        '15.1.15',
        'bu Məcəllənin 16.1.8-ci maddəsinin müddəaları nəzərə alınmaqla pul hesablaşmalarını müvafiq icra hakimiyyəti orqanının müəyyən etdiyi orqan (qurum) tərəfindən müəyyən edilən meyarlara cavab verən və müvafiq icra hakimiyyəti orqanının müəyyən etdiyi orqanın (qurumun) elektron informasiya sisteminə real vaxt rejimində qoşulmuş nəzarət-kassa aparatları vasitəsilə həyata keçirmək;',
        17, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '15'),
        '15.1.15-1',
        'vergi risklərinin minimallaşdırılması məqsədi ilə "Vergi partnyorluğu sazişi" bağlamaq üçün müvafiq icra hakimiyyəti orqanının müəyyən etdiyi formada ərizə ilə vergi orqanlarına müraciət etmək;',
        18, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '15'),
        '15.1.15-2',
        'bu Məcəllənin 165.3-cü maddəsinə uyğun olaraq ƏDV-nin qaytarılması şərti ilə satışı həyata keçirmək üçün müvafiq icra hakimiyyəti orqanının müəyyən etdiyi formada ərizə ilə vergi orqanlarına müraciət etmək;',
        19, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '15'),
        '15.1.15-3',
        'hesablanmış, yenidən hesablanmış, ödənilmiş və artıq ödənilmiş vergilər, məcburi dövlət sosial sığorta, işsizlikdən sığorta və icbari tibbi sığorta haqları, faizlər, maliyyə sanksiyaları və inzibati cərimələrlə bağlı vergi orqanlarından elektron və (və ya) kağız daşıyıcılarda üzləşmə aktı tələb etmək;',
        20, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '15'),
        '15.1.15-4',
        'bu Məcəllənin 16.1.11-14-cü maddəsinə uyğun olaraq müvafiq icra hakimiyyəti orqanının müəyyən etdiyi orqanın (qurumun) müəyyən etdiyi qaydada, bu Məcəllənin 30.8-ci maddəsinin tələbləri nəzərə alınmaqla həmin vergi ödəyicilərinin vergi orqanında olan məlumatlarına çıxış əldə etmək; (5 dekabr 2023-cü il tarixli 1033-VIQD nömrəli Azərbaycan Respublikasının Qanununun 1.4.2-ci maddəsi bu Qanunun 1.4.2-ci maddəsində nəzərdə tutulan qayda ilə eyni gündə qüvvəyə minir.)',
        21, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '15'),
        '15.1.16',
        'bu Məcəllə və qanunlarla müəyyən edilmiş digər hüquqlardan istifadə etmək.',
        22, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '15'),
        '15.2',
        'Vergi ödəyicisinin hüquqları və qanuni maraqları qanunvericilik normaları ilə təmin edilir. Vergi ödəyicisinin hüquqlarının və qanuni maraqlarının müdafiəsi qaydası bu Məcəllə və digər qanunlarla müəyyən edilir. Vergi ödəyicisinin hüquqları və qanuni maraqları vergi orqanlarının və onların vəzifəli şəxslərinin səlahiyyətləri ilə təmin edilir. Vergi ödəyicisinin hüquqlarının və qanuni maraqlarının təmin olunmaması və ya lazımınca təmin olunmaması qanunla müəyyən edilmiş məsuliyyətə səbəb olur.',
        23, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '15'),
        '15.3',
        'Vergi ödəyicisi vergi münasibətlərində bilavasitə və bu Məcəllədə başqa hallar nəzərdə tutulmamışdırsa, öz qanuni və ya səlahiyyətli nümayəndəsi vasitəsi ilə iştirak edə bilər.',
        24, false, NOW(), NOW());

