-- ============================
-- TAX SECTIONS (16.1 - 16.11.4)
-- ============================
INSERT INTO tax_sections (article_id, section_number, content, order_index, synced_to_vector_store, created_at,
                          updated_at)
VALUES ((SELECT id FROM tax_articles WHERE article_number = '16'),
        '16.1',
        'Vergi ödəyicisinin aşağıdakı vəzifələri vardır:',
        1, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '16'),
        '16.1.1',
        'qanunla müəyyən edilmiş vergiləri, habelə bu Məcəllə ilə müəyyən edilmiş qaydada hesablanmış faizləri, tətbiq edilmiş maliyyə sanksiyalarını və digər məcburi ödənişləri ödəmək;',
        2, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '16'),
        '16.1.2',
        'vergi orqanlarından vergi ödəyicisinin eyniləşdirmə nömrəsini (VÖEN) almaq;',
        3, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '16'),
        '16.1.3',
        'qanunvericiliklə nəzərdə tutulmuş qaydada gəlirlərinin (xərclərinin), o cümlədən vergidən azad edilən gəlirlərinin (xərclərinin) və vergitutma obyektlərinin uçotunu aparmaq;',
        4, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '16'),
        '16.1.3-1',
        '"Mühasibat uçotu haqqında" Azərbaycan Respublikasının Qanununa əsasən mühasibat uçotunu məcburi qaydada elektron formada aparmalı şəxslər tərəfindən siyahısı və forması müvafiq icra hakimiyyəti orqanının müəyyən etdiyi orqan (qurum) tərəfindən müəyyən edilən məlumatların müvafiq icra hakimiyyəti orqanının müəyyən etdiyi orqana (quruma) təqdim edilməsini təmin etmək;',
        5, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '16'),
        '16.1.4',
        'vergi orqanlarına bu Məcəllə ilə müəyyən edilmiş hallarda və qaydada, auditor tərəfindən yoxlanılması nəzərdə tutulduğu hallarda isə auditor rəyi əlavə edilməklə, vergi hesabatını, habelə bu Məcəllənin 14-1.2.1-14-1.2.3-cü maddələrində göstərilən şəxslər üzrə transfer qiymətləri əsas götürülməklə apardığı əməliyyatların ümumi dəyəri 500.000 manatdan artıq olduqda və 14-1.2.4-cü maddədə göstərilən şəxslər üzrə həmin maddədə nəzərdə tutulan hallarda müvafiq icra hakimiyyəti orqanının müəyyən etdiyi orqanın (qurumun) müəyyən etdiyi formada mənfəət (gəlir) vergisi bəyannaməsi üçün nəzərdə tutulan müddətlərdə arayışı təqdim etmək;',
        6, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '16'),
        '16.1.4-1',
        'bu Məcəllənin 14-1.9-cu maddəsində nəzərdə tutulan müvafiq icra hakimiyyəti orqanının müəyyən etdiyi orqan (qurum) tərəfindən müəyyən edilən qaydalarda nəzərdə tutulmuş sənədləri və məlumatları vergi orqanının tələbi ilə təqdim etmək;',
        7, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '16'),
        '16.1.4-2',
        'mikro və kiçik sahibkarlıq subyektləri istisna olmaqla, istehsal fəaliyyəti ilə məşğul olan vergi ödəyiciləri tərəfindən istehsal olunan məhsulun vahidinə tələb olunan xammal və material sərfi normaları barədə forması müvafiq icra hakimiyyəti orqanının müəyyən etdiyi orqan (qurum) tərəfindən təsdiq edilən məlumatı hər il yanvar ayının 31-dək elektron qaydada vergi orqanına təqdim etmək. İstehsal prosesi ilə, o cümlədən yeni məhsul növünün istehsalına başlanılması ilə bağlı olaraq təqdim edilmiş məlumatda il ərzində dəyişiklik olarsa, dəyişikliklə bağlı dəqiqləşdirilmiş məlumatı təqvim ili ərzində vergi orqanına təqdim etmək;',
        8, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '16'),
        '16.1.4-3',
        'bu Məcəllənin 14-2.2-ci maddəsində nəzərdə tutulan arayışı müvafiq icra hakimiyyəti orqanının müəyyən etdiyi orqanın (qurumun) müəyyən etdiyi formada mənfəət (gəlir) vergisi bəyannaməsi üçün nəzərdə tutulan müddətdə vergi orqanına təqdim etmək;',
        9, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '16'),
        '16.1.5',
        'vergi orqanlarının vergi qanunvericiliyinin aşkar edilmiş pozuntularının aradan qaldırılması haqqında qanuni tələblərini icra etmək, habelə vergi orqanlarının vəzifəli şəxslərinin qanuni fəaliyyətinin icra edilməsinə maneçilik törətməmək;',
        10, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '16'),
        '16.1.6',
        'bu Məcəllə ilə müəyyən edilmiş hallarda və qaydada vergi orqanlarına və onların vəzifəli şəxslərinə zəruri olan kağız və elektron daşıyıcılarda olan məlumatları və sənədləri (orta və iri sahibkarlıq subyektləri eləcə də maliyyə hesabatlarını), mühasibat uçotu elektron formatda aparıldığı halda, vergi ödəyicisinin özünün, filiallarının və digər struktur bölmələrinin elektron daşıyıcılarında olan məlumatlara və uçot bazalarına, habelə kommunal və rabitə xidmətləri göstərən vergi ödəyiciləri tərəfindən abunəçilər üzrə göstərilən və vergilərin hesablanmasına əsas verən xidmətlərin müddəti, həcmi, dəyəri, ödənişləri və digər iqtisadi göstəricilərini hesablayan və özündə əks etdirən, digər xidmət təminatçıları ilə qarşılıqlı hesablaşmaların aparılması üçün məlumatları saxlayan sistemlərə birbaşa və ya məsafədən çıxış imkanı yaratmaqla, həmin məlumatları vergi orqanının tələbi ilə təqdim etmək;',
        11, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '16'),
        '16.1.7',
        'qanunvericiliklə müəyyən edilmiş müddətdə mühasibat uçotu sənədlərini və vergilərin hesablanması və ödənilməsi üçün zəruri olan digər sənədlərin, habelə alınan gəliri (hüquqi şəxslər üçün çəkilən xərcləri də) və ödənilən (tutulan) vergiləri təsdiq edən sənədlərin saxlanılmasını təmin etmək;',
        12, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '16'),
        '16.1.7-1',
        'bu Məcəllənin 220.10-cu maddəsində nəzərdə tutulan fəaliyyət növlərini "Sadələşdirilmiş vergi üzrə sabit məbləğin, məcburi dövlət sosial sığorta və icbari tibbi sığorta haqqının ödənilməsi haqqında qəbz" almaqla həyata keçirmək;',
        13, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '16'),
        '16.1.7-2',
        'vergi orqanında uçotda olan sifarişçi tərəfindən bu Məcəllənin 220.10-cu maddəsinə uyğun olaraq fərdi qaydada fəaliyyət göstərən şəxslərin həmin dövr üzrə vergi öhdəliyinin yerinə yetirilməsini təsdiq edən "Sadələşdirilmiş vergi üzrə sabit məbləğin, məcburi dövlət sosial sığorta və icbari tibbi sığorta haqqının ödənilməsi haqqında qəbz" təqdim etməklə işlərə cəlb edilməsini təmin etmək;',
        14, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '16'),
        '16.1.8',
        'aşağıdakı fəaliyyət növləri istisna olmaqla, pərakəndə ticarət, ictimai iaşə fəaliyyəti, yerləşmə vasitələri hesab edilən mehmanxana (hotel) və mehmanxana tipli digər obyektlər, tibb müəssisələri və özəl tibbi praktika ilə məşğul olan fiziki şəxslər, bərbərxanalar, gözəllik salonları və kosmetoloji mərkəzlər tərəfindən göstərilən xidmətlər üzrə pul hesablaşmalarını müvafiq icra hakimiyyəti orqanının müəyyən etdiyi orqan (qurum) tərəfindən müəyyən edilən meyarlara cavab verən və müvafiq icra hakimiyyəti orqanının müəyyən etdiyi orqanın (qurumun) elektron informasiya sisteminə real vaxt rejimində qoşulmuş nəzarət-kassa aparatı vasitəsi ilə həyata keçirmək:',
        15, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '16'),
        '16.1.8.1',
        'qəzet və jurnalların satışı (belə satış dövriyyəsinin ümumi dövriyyədəki payı 50 faizdən çox olduqda);',
        16, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '16'),
        '16.1.8.2',
        'kənd təsərrüfatı məhsullarının bazarlarda, yarmarkalarda və səyyar qaydada satışı;',
        17, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '16'),
        '16.1.8.3',
        'səyyar, bazarlarda və digər kütləvi ticarət yerlərində piştaxtadan, avtomobildən və qoşqu vasitələrindən pərakəndə satış fəaliyyəti;',
        18, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '16'),
        '16.1.8.4',
        'qiymətli kağızların, lotereya biletlərinin, idman mərc oyunu biletlərinin və elektron idman mərc oyunu biletlərinin satışı;',
        19, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '16'),
        '16.1.8.5',
        'elektrik enerjisi, qaz, su, isti su təchizatı və mərkəzi qızdırma sistemi obyektlərinin fəaliyyəti;',
        20, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '16'),
        '16.1.8.6',
        'bu Məcəllənin 220.10-cu maddəsinə əsasən fərdi qaydada göstərilən bərbər fəaliyyəti;',
        21, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '16'),
        '16.1.9',
        'lotereya biletlərinin, idman mərc oyunu biletlərinin və elektron idman mərc oyunu biletlərinin alışı istisna olmaqla nağd pul hesablaşmaları aparılan zaman alıcıya çek, qəbz, ödəniş xidməti təchizatçılarının çıxarışları və digər ciddi hesabat blanklarını təqdim etmək və həmin çek, ödəniş xidməti təchizatçılarının çıxarışları və ya ciddi hesabat blanklarında qanunvericiliklə müəyyən edilmiş məlumatların əks etdirilməsini təmin etmək;',
        22, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '16'),
        '16.1.10',
