        27, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '16'),
        '16.1.11-4',
        'maliyyə institutları tərəfindən hüquqi və fiziki şəxslərə hesab açıldıqda və ya maliyyə xidmətləri göstərildikdə, Azərbaycan Respublikasının normativ hüquqi aktlarının, habelə vergi və maliyyə məlumatlarının mübadiləsini nəzərdə tutan Azərbaycan Respublikasının tərəfdar çıxdığı beynəlxalq müqavilələrin tələblərinə əməl edilməsini və bu Məcəllənin 76-1.1-ci maddəsinə uyğun olaraq maliyyə institutları tərəfindən təqdim edilməsi nəzərdə tutulan məlumatların əks olunduğu forması müvafiq icra hakimiyyəti orqanı tərəfindən təsdiq edilən elektron hesabatların və vergi orqanının tələbi əsasında dəqiqləşdirilmiş elektron hesabatların təqdim edilməsini təmin etmək;',
