       ((SELECT id FROM tax_articles WHERE article_number = '16'),
        '16.1.11-9',
        'bu Məcəllənin 50-2.1-ci və 194.1-ci maddələrində nəzərdə tutulan qaydaların tələblərinə riayət etmək;',
        39, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '16'),
        '16.1.11-10',
