        40, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '16'),
        '16.1.11-11',
        'neft-qaz sahəsində fəaliyyəti olan və ya dövlət sektoruna aid edilən, habelə "Yaşıl dəhliz" buraxılış sistemindən istifadə edən vergi ödəyiciləri istisna olmaqla, digər vergi ödəyiciləri tərəfindən idxal ediləcək mallar barədə müvafiq icra hakimiyyəti orqanının müəyyən etdiyi orqan (qurum) tərəfindən təsdiq edilən formada və qaydada aşağıdakı məlumatları malların gömrük nəzarətindən çıxdığı vaxtadək (hava nəqliyyatı ilə daşınan malların gömrük nəzarətindən çıxdığı vaxtdan 1 iş günü müddətində) uçotda olduğu vergi orqanına vermək:',
