        42, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '16'),
        '16.1.11-11.2',
        'mallar digər şəxslərə məxsus yerlərdə məsuliyyətli mühafizəyə və ya saxlanca verildiyi halda tərəflər arasında bağlanmış müqavilə və malların saxlanma yeri barədə;',
        43, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '16'),
        '16.1.11-11.3',
        'mallar sifariş əsasında gətirildiyi halda sifariş verən şəxslər barədə (sifarişçi vergi ödəyicisi olduqda VÖEN-i, fiziki şəxs olduqda adı, soyadı, atasının adı və FİN-i) və hər bir sifarişçi üzrə sifarişin məbləği barədə. Vergi ödəyicisinin vergi orqanında uçota alınmış bir və ya bir neçə təsərrüfat subyekti (obyekti) olduğu halda bu maddədə nəzərdə tutulan məlumat forması vergi orqanına təqdim edilmir. Bu halda idxal edilmiş mallar həmin təsərrüfat subyektinə (obyektinə) və ya təsərrüfat subyektlərinə (obyektlərinə) boşaldılmış hesab olunur. Bu maddənin tələbləri qeyri-sahibkarlıq və şəxsi istifadə üçün idxal olunan mallara şamil edilmir.',
        44, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '16'),
        '16.1.11-12',
        'lotereya təşkilatçısı tərəfindən lotereya biletlərinin, idman mərc oyunları operatoru tərəfindən idman mərc oyunu biletlərinin və elektron mərc oyunu biletlərinin satışı, lotereya biletlərinin və idman mərc oyunlarının satıcılarının haqları (mükafatları) haqqında məlumatların müvafiq icra hakimiyyəti orqanının müəyyən etdiyi orqan (qurum) tərəfindən təsdiq edilmiş formada lotereya təşkilatçısının və idman mərc oyunları operatorunun malik olduqları müvafiq olaraq informasiya sistemi və mərkəzi mərc oyunu sistemi vasitəsilə gündəlik əsasla müvafiq icra hakimiyyəti orqanının müəyyən etdiyi orqanın (qurumun) informasiya sisteminə ötürülməsini təmin etmək;',
        45, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '16'),
        '16.1.11-13',
        'taksi sifarişi operatorları tərəfindən malik olduqları informasiya sistemi vasitəsilə müvafiq icra hakimiyyəti orqanının müəyyən etdiyi orqanın (qurumun) müəyyən etdiyi aylıq məlumatları hər ay başa çatdıqdan sonra növbəti ayın 20-dən gec olmayaraq, müvafiq icra hakimiyyəti orqanının müəyyən etdiyi orqanın (qurumun) elektron informasiya sisteminə ötürmək;',
        46, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '16'),
        '16.1.11-14',
        'təsərrüfat əməliyyatları aparılan zaman malları (işləri, xidmətləri) ona təqdim edən vergi ödəyicilərinin işgüzar nüfuzunun, maliyyə vəziyyətinin, qanuni sahibliyində müvafiq malların mövcudluğunun, habelə iş və xidmətlərin təqdim edilməsi üçün müvafiq işçi və digər resurslara, bilik və bacarığa malik olmasının yoxlanılması məqsədilə həmin vergi ödəyicilərindən müvafiq təsdiqedici sənədlər əldə etmək; (5 dekabr 2023-cü il tarixli 1033-VIQD nömrəli Azərbaycan Respublikasının Qanununun 1.5.2-ci (16.1.11-14-cü maddəyə münasibətdə) maddəsi bu Qanunun 1.4.2-ci maddəsində nəzərdə tutulan qayda ilə eyni gündə qüvvəyə minir.)',
        47, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '16'),
        '16.1.11-15',
        'kənd təsərrüfatı məhsulları bazarları və kənd təsərrüfatı kooperativi bazarları istisna olmaqla, bazarların mülkiyyətçiləri (bazarlar idarəetməyə verildikdə idarəediciləri) tərəfindən əmlak icarəyə verildikdə əmlakı icarəyə götürənin təsərrüfat subyektinin (obyektinin) vergi orqanında uçota alınması həyata keçirildikdən sonra onun həmin təsərrüfat subyektlərində (obyektlərində) fəaliyyət göstərməsinə şərait yaratmaq;',
        48, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '16'),
        '16.1.11-16',
        'kənd təsərrüfatı məhsulları bazarları və kənd təsərrüfatı kooperativi bazarları istisna olmaqla, bazarlarda daşınmaz əmlak həmin əmlakın mülkiyyətçiləri (bazarlar idarəetməyə verildikdə idarəediciləri) tərəfindən, habelə əmlak icarəyə verildikdə icarəyə götürən tərəfindən sahibkarlıq fəaliyyəti məqsədləri üçün istifadə edildikdə təsərrüfat subyektinin (obyektinin) girişində həmin təsərrüfat subyektinin (obyektinin) vergi orqanında uçota alınması ilə bağlı (vergi ödəyicisinin adı və VÖEN-i göstərilməklə) məlumatı (arayışı) əks etdirmək (yerləşdirmək);',
        49, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '16'),
        '16.1.11-17',
        'kənd təsərrüfatı məhsulları bazarları və kənd təsərrüfatı kooperativi bazarları istisna olmaqla, bazarların mülkiyyətçiləri (bazarlar idarəetməyə verildikdə idarəediciləri) tərəfindən icarə müqaviləsinə xitam verilmiş və faktiki olaraq həmin obyektdə fəaliyyət göstərməyən, habelə fəaliyyətini davam etdirən vergi ödəyiciləri barədə forması müvafiq icra hakimiyyəti orqanının müəyyən etdiyi orqan (qurum) tərəfindən təsdiq edilmiş məlumatı elektron formada hər rüb başa çatdıqdan sonra növbəti ayın 20-dək uçotda olduğu vergi orqanına təqdim etmək;',
        50, false, NOW(), NOW()),
