        52, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '16'),
        '16.3',
        'Vergi ilində vergi ödəyicisi sahibkarlıq fəaliyyətini və ya digər vergi tutulan əməliyyatlarını müvəqqəti dayandırdıqda, həmin fəaliyyətin və ya əməliyyatların dayandırılması günündən gec olmayaraq vergi orqanına müvafiq icra hakimiyyəti orqanının müəyyən etdiyi formada arayış təqdim edilməlidir. Arayışda sahibkarlıq fəaliyyətinin və ya digər vergi tutulan əməliyyatların dayandırılmasının müddəti göstərilməlidir. Vergi ödəyicisinin sahibkarlıq fəaliyyətini və ya digər vergi tutulan əməliyyatlarını müvəqqəti dayandırdığı dövrdə faktiki olaraq fəaliyyət göstərməsi müəyyən edildikdə vergi ödəyicisinə bildiriş göndərilməklə sahibkarlıq fəaliyyətini və ya digər vergi tutulan əməliyyatlarını müvəqqəti dayandırdığı dövrlər üzrə vergi orqanına hesabatlar təqdim etməsi tələb olunur.',
