        55, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '16'),
        '16.6',
        'Sığortaçılar və təkrarsığortaçılar tərəfindən hüquqi şəxslərə, onların filial və nümayəndəliklərinə və fərdi sahibkarlara məxsus sığortalanmış (təkrarsığortalanmış) əsas vəsaitlər barədə məlumat rüb bitdikdən sonra növbəti ayın 20-dək müvafiq icra hakimiyyəti orqanının müəyyən etdiyi orqan (qurum) tərəfindən müəyyən edilmiş formada müvafiq icra hakimiyyəti orqanının müəyyən etdiyi orqana (quruma) təqdim edilir.',
        56, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '16'),
        '16.7',
        'Kart təşkilatları tərəfindən bu Məcəllənin 165.5-ci və 228-ci maddələrinə uyğun olaraq nağdsız qaydada aparılmış ödənişlər barədə məlumat ay bitdikdən sonra növbəti ayın 20-dək müvafiq icra hakimiyyəti orqanının müəyyən etdiyi orqan (qurum) tərəfindən müəyyən edilmiş formada müvafiq icra hakimiyyəti orqanının müəyyən etdiyi orqana (quruma) təqdim edilir.',
