       ((SELECT id FROM tax_articles WHERE article_number = '16'),
        '16.8',
        'Bina tikintisi fəaliyyəti ilə məşğul olan aşağıdakı şəxslər yaşayış və qeyri-yaşayış sahələrinin təqdim edilməsi ilə bağlı hər bina üzrə müvafiq icra hakimiyyəti orqanının müəyyən etdiyi orqan (qurum) tərəfindən təsdiq edilən məlumat formasını hər rüb başa çatdıqdan sonra növbəti ayın 20-dən gec olmayaraq vergi orqanına təqdim edir:',
        58, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '16'),
        '16.8.1',
        '2020-ci il 1 yanvar tarixindən sonra tikinti-quraşdırma işlərinə başlamış;',
        59, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '16'),
        '16.8.2',
        'sadələşdirilmiş verginin ödəyicisi olmayan, 2020-ci il 1 yanvar tarixinədək tikinti-quraşdırma işlərinə başlamış, lakin tikintisi başa çatmayan, habelə bina üzrə təqdim edilməmiş yaşayış və qeyri-yaşayış sahələri olan şəxslər.',
        60, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '16'),
        '16.9',
        'Transmilli şirkətlər qrupunun maliyyə ilində məcmu gəliri 750 milyon avronun manat ekvivalentindən çox olduqda, Azərbaycan Respublikasının tərəfdar çıxdığı beynəlxalq müqavilələr çərçivəsində digər dövlətlərin səlahiyyətli orqanları ilə avtomatlaşdırılmış məlumat mübadiləsinin həyata keçirilməsi məqsədilə transmilli şirkətlər qrupuna daxil olan və Azərbaycan Respublikasında vergi uçotuna alınmış vergi ödəyicisi müvafiq icra hakimiyyəti orqanının müəyyən etdiyi orqan (qurum) tərəfindən təsdiq edilmiş müddətdə, formada və qaydada hesabatı və bildirişi vergi orqanına təqdim edir. Bu maddə ilə müəyyən edilmiş hesabatın verilməsini şərtləndirən məbləğ həddi transmilli şirkətlər qrupunun maliyyə hesabatları əsasında müəyyən edilir.',
        61, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '16'),
        '16.10',
        'ƏDV-nin məqsədləri üçün qeydiyyata alınmış vergi ödəyiciləri bu Məcəllənin 149-cu maddəsində nəzərdə tutulan müddətlərdə təqdim etdikləri bəyannamələrlə eyni gündə vergi ili üzrə kreditor və debitor borcları barədə forması müvafiq icra hakimiyyəti orqanının müəyyən etdiyi orqan (qurum) tərəfindən təsdiq edilən məlumatı elektron qaydada vergi orqanına təqdim edir.',
        62, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '16'),
        '16.11',
        'Vergi ödəyicisi olan şəxslər arasında ödəniş əməliyyatı aparılarkən əməliyyatı həyata keçirən ödəniş xidməti təchizatçılarına təqdim edilən ödəniş tapşırığında aşağıdakı məlumatlar göstərilir:',
        63, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '16'),
        '16.11.1',
        'bu Məcəllənin 71-1.5-ci maddəsində göstərilən əməliyyatlar üzrə - elektron qaimə-fakturanın seriya və nömrəsi. Təqvim ayı ərzində eyni vergi ödəyicisindən müntəzəm və daimi əsaslarda alınan və elektron qaimə-fakturalar ilə rəsmiləşdirilən mallara (işlərə, xidmətlərə) görə ödəniş aparılarkən belə əməliyyatlar üzrə - tərəflər arasında bağlanmış müqavilə və ya həmin müqaviləyə əlavənin tarixi və nömrəsi;',
        64, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '16'),
        '16.11.2',
        'xarici ticarət fəaliyyəti üzrə - yük gömrük bəyannaməsinin seriya və nömrəsi, işlərin və xidmətlərin alışı ilə bağlı hesab-faktura (invoys) sənədinin tarixi və nömrəsi;',
        65, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '16'),
        '16.11.3',
        'borc ödənişləri üzrə - təyinatında borc ödənişi olduğu göstərilməklə tərəflər arasında bağlanmış borc müqaviləsinin və ya borcun ödənilməsinə dair tələbnamənin tarixi və nömrəsi.',
        66, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '16'),
        '16.11.4',
        'avans ödənişləri üzrə - təyinatında avans ödənişi olduğu göstərilməklə tələbnamənin, yaxud tərəflər arasında bağlanmış müqavilə və ya həmin müqaviləyə əlavənin tarixi və nömrəsi.',
        67, false, NOW(), NOW());

-- ============================
-- TAX ARTICLE (Maddə 17)
-- ============================
INSERT INTO tax_articles (article_number, title, chapter, active, created_at, updated_at)
VALUES ('17',
        'Vergi agenti',
        'II fəsil. Vergi ödəyicisi. Vergi agenti',
        true, NOW(), NOW());

INSERT INTO tax_sections (article_id, section_number, content, order_index, synced_to_vector_store, created_at,
                          updated_at)
VALUES ((SELECT id FROM tax_articles WHERE article_number = '17'), '17.1',
        'Vergi agenti bu Məcəlləyə uyğun olaraq vergini hesablamağa, onu vergi ödəyicisindən tutmağa və təyinatı üzrə köçürməyə borclu olan şəxsdir.',
        1, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '17'), '17.2',
        'Vergi agentinin, bu Məcəllədə başqa hallar nəzərdə tutulmamışdırsa, vergi ödəyicisi ilə eyni hüquqları vardır.',
        2, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '17'), '17.3',
        'Vergi agenti:',
        3, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '17'), '17.3.1',
        'müvafiq vergiləri düzgün və vaxtında hesablamağa, onları vergi ödəyicisindən tutmağa və təyinatı üzrə köçürməyə;',
        4, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '17'), '17.3.2',
        'vergi ödəyicilərinə ödənilən gəlirlərin, onlardan tutulan və təyinatı üzrə köçürülən vergilərin, o cümlədən hər vergi ödəyicisi üzrə ayrıca uçotunu aparmağa;',
        5, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '17'), '17.3.3',
        'vergilərin hesablanmasının, tutulmasının və ödənilməsinin düzgünlüyünə nəzarət etmək üçün zəruri sənədləri dövlət vergi orqanlarına verməyə;',
        6, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '17'), '17.3.4',
        'vergi ödəyicisindən verginin tutulmasının mümkün olmadığı hallarda, bu barədə və vergi ödəyicisinin vergi borcunun məbləği barədə vergi orqanlarına 30 gün müddətində öz qeydiyyat (uçot) yeri üzrə yazılı məlumat verməyə;',
        7, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '17'), '17.3.5',
        'bu Məcəllə ilə müəyyən edilmiş digər vəzifələri yerinə yetirməyə borcludur.',
        8, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '17'), '17.4',
        'Vergi agenti qanunla ona həvalə edilmiş vəzifələri yerinə yetirməməyə və ya lazımınca yerinə yetirməməyə görə bu Məcəllə və digər qanunlarla müəyyən edilmiş qaydada məsuliyyət daşıyır.',
        9, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '17'), '17.5',
        'Vergi agenti birbaşa və ya dolayı yolla tabe olduğu şəxsin təqsiri üzündən ona həvalə olunmuş vəzifələrin yerinə yetirilməməsinə və ya lazımınca yerinə yetirilməməsinə görə vergi agentinin bilavasitə və ya dolayısı ilə tabe olduğu şəxs bu Məcəllə və digər qanunlarla müəyyən edilmiş qaydada məsuliyyət daşıyır.',
        10, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '17'), '17.6',
        'Bu Məcəllənin 149.1.3-1-ci maddəsinə uyğun olaraq təyin olunan vergi agenti təyin olunduqdan sonra 30 gün ərzində vergi orqanlarına müvafiq icra hakimiyyəti orqanının müəyyən etdiyi formada arayış təqdim edir.',
        11, false, NOW(), NOW());

-- ============================
-- TAX ARTICLE (Maddə 18)
-- ============================
INSERT INTO tax_articles (article_number, title, chapter, active, created_at, updated_at)
VALUES ('18',
        'Qarşılıqlı surətdə asılı olan şəxslər',
        'II fəsil. Vergi ödəyicisi. Vergi agenti',
        true, NOW(), NOW());

INSERT INTO tax_sections (article_id, section_number, content, order_index, synced_to_vector_store, created_at,
                          updated_at)
VALUES ((SELECT id FROM tax_articles WHERE article_number = '18'), '18.1',
        'Vergi məqsədləri üçün qarşılıqlı surətdə asılı olan şəxslər – aralarındakı münasibətlər fəaliyyətlərinin iqtisadi nəticələrinə və ya onların təmsil etdiyi şəxslərin fəaliyyətinə bilavasitə təsir göstərə bilən fiziki şəxslər və (və ya) hüquqi şəxslərdir.',
        1, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '18'), '18.2',
        'Bu maddənin məqsədləri üçün qarşılıqlı surətdə asılı olan şəxslər aşağıdakılar sayılır:',
        2, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '18'), '18.2.1',
        'bir şəxs digər şəxsin əmlakında (nizamnamə kapitalında) bilavasitə və ya dolayısı ilə iştirak edirsə və onun iştirak payı və ya səs hüququ azı 20 faizdirsə;',
        3, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '18'), '18.2.2',
        'bir şəxs özünün xidməti vəziyyətinə görə digər şəxsə tabedir və ya bir şəxs digər şəxsin bilavasitə və ya dolayısı ilə nəzarətindədir;',
        4, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '18'), '18.2.3',
        'şəxslər üçüncü şəxsin birbaşa və ya dolayısı ilə nəzarətindədirlər;',
        5, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '18'), '18.2.4',
        'şəxslər üçüncü şəxsə birbaşa və ya dolayısı ilə birgə nəzarət edirlər;',
        6, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '18'), '18.2.5',
        'bu Məcəllənin 13.2.7-ci maddəsində göstərilən ailə üzvləri.',
        7, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '18'), '18.3',
        'Bu maddənin məqsədləri üçün bir şəxs digər şəxsə o halda nəzarət etmiş hesab olunur ki, həmin şəxs digər şəxsin fəaliyyətini məhdudlaşdırmaq və ya istiqamətləndirmək imkanına malikdir.',
        8, false, NOW(), NOW());

-- ============================
-- TAX ARTICLE (Maddə 19)
-- ============================
INSERT INTO tax_articles (article_number, title, chapter, active, created_at, updated_at)
VALUES ('19',
        'Daimi nümayəndəlik',
        'II fəsil. Vergi ödəyicisi. Vergi agenti',
        true, NOW(), NOW());

INSERT INTO tax_sections (article_id, section_number, content, order_index, synced_to_vector_store, created_at,
                          updated_at)
VALUES ((SELECT id FROM tax_articles WHERE article_number = '19'), '19.1',
        'Azərbaycan Respublikasında qeyri-rezident hüquqi şəxsin və ya qeyri-rezident fiziki şəxsin daimi nümayəndəliyi həmin şəxslərin istənilən 12 ay ərzində Azərbaycan Respublikasında üst-üstə 90 gündən az olmayaraq bilavasitə və ya müvəkkil edilmiş şəxs vasitəsilə tam və ya qismən sahibkarlıq fəaliyyətini həyata keçirdiyi yerdir.',
        1, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '19'), '19.2',
        'Daimi nümayəndəlik, əsasən aşağıdakıları əhatə edir, amma bunlarla məhdudlaşdırılmır:',
        2, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '19'), '19.2.1',
        'idarəetmə yerini;',
        3, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '19'), '19.2.2',
        'bölməni;',
        4, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '19'), '19.2.3',
        'kontoru;',
        5, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '19'), '19.2.4',
        'filialı və agentliyi;',
        6, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '19'), '19.2.5',
        'tikinti və təmir meydançaları, quraşdırma, montaj və ya yığma obyektləri, həmçinin bu cür obyektlərlə bağlı nəzarət fəaliyyəti göstərilməsini;',
        7, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '19'), '19.2.6',
        'təbii ehtiyatların kəşfiyyatı, işlənməsi və çıxarılması üzrə yerlər, istifadə olunan qurğular və ya meydançalar, qazma avadanlığı və ya gəmilər, həmçinin bu cür obyektlərlə bağlı nəzarət fəaliyyəti göstərilməsini;',
        8, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '19'), '19.2.7',
        'qeyri-rezident fiziki şəxsin sahibkarlıq fəaliyyəti üçün istifadə etdiyi bazanı (yeri);',
        9, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '19'), '19.2.8',
        'müxtəlif məsləhət xidməti üzrə yerlərini;',
        10, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '19'), '19.2.9',
        'Azərbaycan Respublikası ərazisində digər sahibkarlıq növlərinin həyata keçirildiyi istənilən hər hansı iş yerlərini;',
        11, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '19'), '19.2.10',
        'qeyri-rezident müəssisələrin və ya qeyri-rezident fiziki şəxsin Azərbaycan Respublikasındakı daimi nümayəndəliyi funksiyalarını həyata keçirən, onların adından fəaliyyət göstərən, onlar üçün müştəri bazasının toplanması və müştərilərlə işin təşkilini həyata keçirən, onların adından müqavilələri hazırlamaq və ya bağlamaq səlahiyyətlərinə malik olan və adətən belə səlahiyyətləri həyata keçirən şəxsləri;',
        12, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '19'), '19.2.11',
        'malların istehsal və ya təqdim edildiyi, işlərin görüldüyü və ya xidmətlərin göstərildiyi yeri.',
        13, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '19'), '19.2-1',
        'Bu Məcəllənin 19.2.5-ci maddəsində nəzərdə tutulan fəaliyyəti baş podratçı kimi qeyri-rezident şəxs həyata keçirdiyi halda, onun bu fəaliyyəti həyata keçirmək üçün cəlb etdiyi və qarşılıqlı surətdə asılı olduğu və (və ya) fəaliyyətinə nəzarəti həyata keçirdiyi digər subpodratçı şəxslərin bu işlər üçün göstərdiyi fəaliyyətin müddəti baş podratçının fəaliyyət müddətinə əlavə edilir. Bu maddənin müddəaları subpodratçı şəxslərin fəaliyyət müddəti 30 gündən artıq olduğu halda tətbiq edilir;',
        14, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '19'), '19.3',
        'Bu Məcəllənin 19.2-ci maddəsində müəyyən edilən müddəalardan fərqli olaraq, aşağıda göstərilən fəaliyyət növləri daimi nümayəndəlik vasitəsi ilə həyata keçirilən fəaliyyət sayılmır:',
        15, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '19'), '19.3.1',
        'qeyri-rezident müəssisəsinin özünə məxsus malların və məmulatların müstəsna olaraq saxlanması və ya nümayiş etdirilməsi;',
        16, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '19'), '19.3.2',
        'qeyri-rezident müəssisəsinin özünə məxsus olan malların və məmulatların ehtiyatlarının digər şəxs tərəfindən emal və sonradan Azərbaycan Respublikasından ixrac edilməsi məqsədi ilə saxlanması;',
        17, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '19'), '19.3.3',
        'qeyri-rezident müəssisəsinin yalnız özü üçün malların alınması və ya məlumatların toplanması;',
        18, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '19'), '19.3.4',
        'qeyri-rezident müəssisəsinin özü üçün hər hansı digər hazırlıq və ya yardımçı xarakterli fəaliyyət göstərməsi;',
        19, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '19'), '19.3.5',
        'bu Məcəllənin 19.3.1-19.3.4-cü maddələrində göstərilmiş hər hansı fəaliyyət növlərinin bir yerdə həyata keçirilməsi.',
        20, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '19'), '19.3-1',
        'Qeyri-rezident şəxs və onunla qarşılıqlı surətdə asılı olan şəxslər tərəfindən Azərbaycan Respublikasında bu Məcəllənin 19.3-cü maddəsində sadalanan fəaliyyət növlərinin hər hansı birinin birgə şəkildə həyata keçirilməsi sahibkarlıq məqsədləri daşıdığı və ya bu fəaliyyət növlərinin hər hansı biri üzrə əlaqəli şəkildə həyata keçirilməsinin nəticələri hazırlıq və ya yardımçı xarakter daşımadığı və (və ya) belə şəxslər tərəfindən həyata keçirilən fəaliyyətlər onların vahid biznes prosesinin tərkib hissəsi olaraq bir-birinə münasibətdə qarşılıqlı tamamlanma funksiyasını daşıdığı halda bu Məcəllənin 19.3-cü maddəsinin müddəaları tətbiq edilmir və həmin şəxslərin fəaliyyətinə daimi nümayəndəlik kimi baxılır.',
        21, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '19'), '19.4',
        'Bu maddənin məqsədləri üçün qeyri-rezident müəssisənin və ya qeyri-rezident fiziki şəxsin istənilən 12 ay ərzində üst-üstə 90 gündən az müddətdə Azərbaycan Respublikasında fəaliyyət göstərdiyi hər hansı yer daimi nümayəndəlik sayılmır, bu halda Azərbaycan mənbəyindən əldə olunan gəlir bu Məcəllənin 125-ci və 169-cu maddələrinə əsasən ödəniş mənbəyində vergiyə cəlb edilir.',
        22, false, NOW(), NOW());

-- ============================
-- TAX ARTICLE (Maddə 20)
-- ============================
INSERT INTO tax_articles (article_number, title, chapter, active, created_at, updated_at)
VALUES ('20',
        'Dövlət vergi orqanları və onların təyinatı',
        'III fəsil. Dövlət vergi orqanları',
        true, NOW(), NOW());

INSERT INTO tax_sections (article_id, section_number, content, order_index, synced_to_vector_store, created_at,
                          updated_at)
VALUES ((SELECT id FROM tax_articles WHERE article_number = '20'), '20.1',
        'Azərbaycan Respublikasında dövlət vergi orqanlarını müvafiq icra hakimiyyəti orqanı və bilavasitə ona tabe olan ərazi vergi orqanları təşkil edir. Vergi orqanları öz səlahiyyətləri çərçivəsində hüquq mühafizə orqanlarının səlahiyyətlərini həyata keçirirlər.',
        1, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '20'), '20.2',
        'Vergi orqanları öz fəaliyyətini yerli dövlət hakimiyyəti orqanlarından asılı olmayaraq müstəqil həyata keçirirlər. Vergi orqanları tərəfindən onların səlahiyyətləri daxilində qəbul edilən qərarlar bütün hüquqi və fiziki şəxslər üçün məcburidir.',
        2, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '20'), '20.3',
        'Vergi orqanları məhkəmələrə iddia ərizələrinin verilməsi üçün dövlət rüsumunu ödəməkdən azaddırlar.',
        3, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '20'), '20.4',
        'Vergi orqanları yerli vergilər (bələdiyyə vergiləri), habelə tutulması dövlət gömrük orqanlarının səlahiyyətlərinə aid edilmiş yol vergisi, ƏDV və aksiz istisna olmaqla, vergilərin tam və vaxtında ödənilməsinə nəzarəti həyata keçirirlər.',
        4, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '20'), '20.5',
        'Bu Məcəllə ilə nəzərdə tutulan hallarda vergi orqanlarının səlahiyyətlərini qanunla müəyyən edilmiş hallarda və qaydada yol vergisi və idxal-ixrac əməliyyatları sahəsində gömrük orqanları həyata keçirir.',
        5, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '20'), '20.6',
        'Bu Məcəllənin 20.5-ci maddəsində göstərilən orqanlar öz səlahiyyətləri daxilində bu Məcəlləyə, Azərbaycan Respublikasının Gömrük Məcəlləsinə, digər qanunlara və onlara uyğun qəbul edilmiş qanunvericilik aktlarına əsasən fəaliyyət göstərirlər.',
        6, false, NOW(), NOW());

