-- ============================
-- TAX ARTICLE (Maddə 22)
-- ============================
INSERT INTO tax_articles (article_number, title, chapter, active, created_at, updated_at)
VALUES ('22',
        'Vergi orqanları işçilərinin sosial müdafiəsi və bu orqanların maddi həvəsləndirmə və inkişaf fondu',
        'III fəsil. Dövlət vergi orqanları',
        true, NOW(), NOW());

INSERT INTO tax_sections (article_id, section_number, content, order_index, synced_to_vector_store, created_at,
                          updated_at)
VALUES ((SELECT id FROM tax_articles WHERE article_number = '22'), '22.1',
        'Vergi orqanlarının işçilərinin sosial müdafiəsinə dövlət təminat verir və onlar dövlət büdcəsinin vəsaiti hesabına icbari qaydada sığorta olunurlar. İcbari sığortanın qaydası və şərtləri qanunla müəyyən edilir. Vergi orqanının işçisinə xidməti fəaliyyəti həyata keçirdiyi zaman peşə fəaliyyəti ilə məşğul olmağa imkan verməyən ağır bədən xəsarəti yetirildikdə, ona dövlət büdcəsinin vəsaiti hesabına vəzifə maaşı ilə pensiyası arasındakı fərq ödənilir. Xidməti fəaliyyətlə əlaqədar vergi orqanının işçisinin və ya onun ailə üzvlərinin əmlakına dəymiş zərər, sonradan təqsirkar şəxsdən tutulmaqla, tam həcmdə dövlət büdcəsinin vəsaiti hesabına ödənilir.',
        1, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '22'), '22.2',
        'Vergi orqanları işçilərinin sosial müdafiəsi, o cümlədən vergi orqanlarının maddi-texniki bazasının möhkəmləndirilməsi, vergi sahəsində elmi-texniki potensialın artırılması məqsədilə vergi orqanları tərəfindən tətbiq edilən və dövlət büdcəsinə daxil olan maliyyə sanksiyaları məbləğinin 50 faizi hesabına bu orqanların büdcədənkənar fondu yaradılır. Vergi orqanlarının büdcədənkənar fondunun formalaşdırılması və onun vəsaitlərindən istifadə qaydasını müvafiq icra hakimiyyəti orqanı müəyyən edir.',
        2, false, NOW(), NOW());

-- ============================
-- TAX ARTICLE (Maddə 22-1)
-- ============================
INSERT INTO tax_articles (article_number, title, chapter, active, created_at, updated_at)
VALUES ('22-1',
        'Vergi orqanları tərəfindən tətbiq olunan maliyyə sanksiyalarından və digər vəsaitlərdən ayırmalar',
        'III fəsil. Dövlət vergi orqanları',
        true, NOW(), NOW());

INSERT INTO tax_sections (article_id, section_number, content, order_index, synced_to_vector_store, created_at,
                          updated_at)
VALUES ((SELECT id FROM tax_articles WHERE article_number = '22-1'), '22-1.1',
        'Müvafiq icra hakimiyyəti orqanının müəyyən etdiyi orqanın (qurumun) işçilərinin sosial müdafiəsinin gücləndirilməsi, maddi-texniki bazasının möhkəmləndirilməsi və elmi-texniki potensialının artırılması məqsədi ilə, habelə dövlət və ictimai əhəmiyyətli məqsədlərlə əlaqədar vergi orqanları tərəfindən tətbiq edilən və dövlət büdcəsinə daxil olan maliyyə sanksiyaları məbləğinin və məhkəmənin qərarı ilə müsadirə edilmiş aksiz markası olmayan və ya saxta aksiz markaları ilə markalanmış malların satışından əldə edilən vəsaitin müvafiq icra hakimiyyəti orqanının müəyyən etdiyi orqan (qurum) tərəfindən müəyyən edilən hissəsi müvafiq icra hakimiyyəti orqanının müəyyən etdiyi orqanın (qurumun) hesabına, qalan hissəsi isə dövlət büdcəsinə köçürülür. Bu vəsaitdən istifadə qaydası müvafiq icra hakimiyyəti orqanının müəyyən etdiyi orqan (qurum) tərəfindən müəyyən olunur.',
        1, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '22-1'), '22-1.2',
        '"Sosial sığorta haqqında" Azərbaycan Respublikası Qanununun tələblərinin pozulmasına görə vergi orqanları tərəfindən tətbiq edilən və həmin Qanunun 19-cu maddəsində nəzərdə tutulan fonda daxil olan maliyyə sanksiyası məbləğinin 43 faizi müvafiq icra hakimiyyəti orqanının müəyyən etdiyi orqanın (qurumun) maddi-texniki bazasını və işçilərinin sosial müdafiəsini gücləndirmək məqsədilə müvafiq icra hakimiyyəti orqanının müəyyən etdiyi orqanın (qurumun) hesabına, 7 faizi isə dövlət büdcəsinə köçürülür. Bu vəsaitlərin bölgüsü və onlardan istifadə qaydası müvafiq icra hakimiyyəti orqanının müəyyən etdiyi orqan (qurum) tərəfindən müəyyən olunur.',
        2, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '22-1'), '22-1.3',
        'Müvafiq icra hakimiyyəti orqanının müəyyən etdiyi orqanın (qurumun) bu Qanunun 22-1.1-ci maddəsində nəzərdə tutulan mənbələr hesabına gəlirlərinin faktiki daxilolmalarının məbləği büdcə sistemi haqqında qanunvericilikdə nəzərdə tutulan qaydada proqnozlaşdırılan gəlirlərinin məbləğindən az olduqda, bu fərq əvvəlki il üçün Azərbaycan Respublikasının dövlət büdcəsi haqqında qanunu ilə təsdiq edilən dövlət büdcəsinin gəlirləri üzrə vergi orqanlarının xətti ilə dövlət büdcəsinə nəzərdə tutulan daxilolmalardan artıq daxil olan vəsait (neft-qaz sahəsində fəaliyyət göstərən vergi ödəyiciləri (podratçılar), "Avtomobil Yolları" Məqsədli Büdcə Fondunun mədaxil mənbələri üzrə daxilolmalar, habelə müvafiq icra hakimiyyəti orqanının müəyyən etdiyi orqan (qurum) tərəfindən təsdiq edilmiş qaydada şəhər və rayonlar üzrə vergi orqanlarının xətti ilə dövlət büdcəsinə nəzərdə tutulan daxilolmalardan büdcə ilinin sonuna artıq daxil olan vəsaitin onların sərəncamında saxlanılan və istifadəsinə verilən hissəsi istisna olmaqla) hesabına müvafiq icra hakimiyyəti orqanının müəyyən etdiyi orqanın (qurumun) hesabına köçürülür.',
        3, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '22-1'), '22-1.4',
        '"Tibbi sığorta haqqında" Azərbaycan Respublikası Qanununun tələblərinin pozulmasına görə vergi orqanları tərəfindən tətbiq edilən və həmin Qanunun 15-21-ci maddəsində nəzərdə tutulan fonda daxil olan maliyyə sanksiyası məbləğinin 43 faizi müvafiq icra hakimiyyəti orqanının müəyyən etdiyi orqanın (qurumun) maddi-texniki bazasını və işçilərinin sosial müdafiəsini gücləndirmək məqsədilə müvafiq icra hakimiyyəti orqanının müəyyən etdiyi orqanın (qurumun) hesabına, 7 faizi isə dövlət büdcəsinə köçürülür. Bu vəsaitlərin bölgüsü və onlardan istifadə qaydası müvafiq icra hakimiyyəti orqanının müəyyən etdiyi orqan (qurum) tərəfindən müəyyən olunur.',
        4, false, NOW(), NOW());

-- ============================
-- TAX ARTICLE (Maddə 23)
-- ============================
INSERT INTO tax_articles (article_number, title, chapter, active, created_at, updated_at)
VALUES ('23',
        'Vergi orqanlarının hüquqları',
        'III fəsil. Dövlət vergi orqanları',
        true, NOW(), NOW());

INSERT INTO tax_sections (article_id, section_number, content, order_index, synced_to_vector_store, created_at,
                          updated_at)
VALUES ((SELECT id FROM tax_articles WHERE article_number = '23'), '23.1',
        'Vergi orqanlarının hüquqları aşağıdakılardır:',
        1, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '23'), '23.1.1',
        'bu Məcəllə ilə müəyyən edilmiş hallarda və qaydada kameral və səyyar vergi yoxlamalarını, operativ vergi nəzarətini keçirmək;',
        2, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '23'), '23.1.2',
        'vergi ödəyicilərində bütün maliyyə sənədlərini, mühasibat kitablarını, hesabatları, smetaları, nağd vəsaitləri, qiymətli kağızları və başqa qiymətliləri, bəyannamələri və vergilərin hesablanması və ödənilməsi ilə bağlı olan digər sənədləri, o cümlədən bu Məcəllənin 16.1.6-cı maddəsində nəzərdə tutulmuş məlumat və sənədləri qanunvericiliklə müəyyən edilmiş qaydada yoxlamaq, habelə yoxlamaların keçirilməsi zamanı yoxlamaya aid olan məsələlərlə bağlı vergi ödəyicilərindən və ya onun vəzifəli şəxslərindən lazımi izahatlar, arayışlar və məlumat almaq, habelə mühasibat uçotu elektron formatda aparıldığı halda vergi ödəyicisinin özünün, filiallarının və digər struktur bölmələrinin elektron daşıyıcılarındakı məlumatlarının verilməsini, həmin məlumatlara, habelə kommunal və rabitə xidmətləri göstərən vergi ödəyiciləri tərəfindən abunəçilər üzrə göstərilən və vergilərin hesablanmasına əsas verən xidmətlərin müddəti, həcmi, dəyəri, ödənişləri və digər iqtisadi göstəricilərini hesablayan və özündə əks etdirən, digər xidmət təminatçıları ilə qarşılıqlı hesablaşmaların aparılması üçün məlumatları saxlayan sistemlərə birbaşa və ya məsafədən çıxış imkanının yaradılmasını tələb etmək;',
        3, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '23'), '23.1.2-1',
        'vergi və maliyyə məlumatlarının mübadiləsini nəzərdə tutan Azərbaycan Respublikasının tərəfdar çıxdığı beynəlxalq müqavilələrə əsasən şəxslərdən həmin müqavilənin tələblərindən irəli gələn sənədləri və məlumatları elektron və (və ya) kağız daşıyıcılarda tələb etmək;',
        4, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '23'), '23.1.3',
        'vergi ödəyicilərinin gəlir götürmək üçün istifadə etdikləri, yaxud vergi tutulan obyektlərin saxlanılması ilə bağlı olan istehsal, anbar, ticarət və digər binalarında (ərazilərində) istehsal həcminin və ya satış dövriyyəsinin müəyyənləşdirilməsi məqsədilə bu Məcəllənin 50-1-ci maddəsində müəyyən edilmiş hallarda və qaydada xronometraj metodu ilə müşahidə aparmaq və baxış keçirmək, bu Məcəllə ilə müəyyən edilmiş qaydada elektron və (və ya) kağız formatda aparılan sənədləri və əşyaları götürmək, mülkiyyətində və ya istifadəsində olan əmlakın (yaşayış sahələri istisna olmaqla) bu Məcəllədə müəyyən edilmiş hallarda müvafiq icra hakimiyyəti orqanı tərəfindən təsdiq edilmiş qaydada elektron və (və ya) kağız formatda aparılan inventarizasiyasını aparmaq;',
        5, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '23'), '23.1.3-1',
        'malların, o cümlədən kənd təsərrüfatı məhsullarının topdan satışı ilə məşğul olan ticarət obyektlərində, bazarlarda nəzarət postlarının qurulmasını və bu obyektlərə bu Məcəllə ilə müəyyən edilmiş qaydada sənədləşdirilməyən, habelə elektron əmtəə-nəqliyyat qaiməsi olmayan malların gətirilməsinin qarşısının alınması səlahiyyətlərini həyata keçirmək;',
        6, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '23'), '23.1.3-2',
        'bu Məcəllənin 16.1.11-11-ci maddəsində nəzərdə tutulan məlumatları təqdim edən vergi ödəyicisinin mallarının saxlanıldığı (boşaldıldığı) yerə həmin mallar idxal edildiyi vaxtdan 3 iş günü müddətində baxış keçirmək və baxışın nəticəsini forması müvafiq icra hakimiyyəti orqanının müəyyən etdiyi orqan (qurum) tərəfindən təsdiq edilən protokolla rəsmiləşdirmək;',
        7, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '23'), '23.1.4',
        'vergi ödəyicilərindən vergi qanunvericiliyinin pozulması hallarının aradan qaldırılmasını habelə vergi ödəyicisi auditor tərəfindən yoxlanılmalı olduğu halda auditor rəyini tələb etmək;',
        8, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '23'), '23.1.5',
        'qanunla müəyyən edilmiş qaydada vergi qanunvericiliyinin pozulması ilə bağlı işlərə baxmaq, hüquqi və fiziki şəxslərin vergi borclarına faizlər hesablamaq, bu şəxslərə maliyyə sanksiyaları və inzibati cərimələr tətbiq etmək;',
        9, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '23'), '23.1.6',
        'müəyyən edilmiş müddətlərdə ödənilməmiş vergilərin, faizlərin, maliyyə sanksiyalarının və inzibati cərimələrin qanunla müəyyən edilmiş qaydada dövlət büdcəsinə və ya məqsədli dövlət fondlarına ödənilməsini təmin etmək;',
        10, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '23'), '23.1.6-1',
        'səyyar vergi yoxlamaları zamanı əsas məqsədi vergi üstünlüyü əldə etmək olan vergidən yayınma sxemi aşkar etdikdə faktiki iqtisadi göstərici əsas götürülməklə vergilərin, faizlərin, maliyyə sanksiyalarının və inzibati cərimələrin hesablanmasını təmin etmək və aşkar edilmiş vergidən yayınma sxemlərini dərc etmək;',
        11, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '23'), '23.1.7',
        'Vergi ödəyicilərinin hesablaşma, valyuta və ya digər hesablarından qanunvericiliyə müvafiq olaraq hesablanmış vergilər üzrə borcların və faizlərin, tətbiq edilmiş maliyyə sanksiyalarının dövlət büdcəsinə alınması üçün ödəniş xidməti təchizatçılarına icra (ödəniş) sənədi olan sərəncam vermək, inzibati cərimələrin alınmasını təşkil etmək;',
        12, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '23'), '23.1.8',
        'qanunla müəyyən edilmiş hallarda vergi ödəyicisinin hesablaşma, valyuta və digər hesablarına həbs qoyulması barədə məhkəmədə iddia qaldırmaq, bu Məcəllə ilə müəyyən edilmiş qaydada vergi ödəyicisinin əmlakının siyahıya alınması üçün tədbirlər görmək;',
        13, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '23'), '23.1.9',
        '"Əməliyyat-axtarış fəaliyyəti haqqında" Azərbaycan Respublikasının Qanunu ilə müəyyən olunmuş hallarda və qaydada vətəndaşların vergi məsələləri ilə bağlı sorğusunu həyata keçirtmək;',
        14, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '23'), '23.1.10',
        '"Əməliyyat-axtarış fəaliyyəti haqqında" Azərbaycan Respublikasının Qanunu ilə müəyyən olunmuş hallarda və qaydada binalara (yaşayış sahələri istisna olmaqla), qurğulara və torpaq sahələrinə daxil olmaq və baxış keçirtmək;',
        15, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '23'), '23.1.11',
        '"Əməliyyat-axtarış fəaliyyəti haqqında" Azərbaycan Respublikasının Qanunu ilə müəyyən olunmuş hallarda və qaydada nəzarət qaydasında mal alqısını həyata keçirtmək;',
        16, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '23'), '23.1.12',
        'Azərbaycan Respublikasının Cinayət-Prosessual Məcəlləsi ilə müəyyən edilmiş qaydada təhqiqat aparmaq;',
        17, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '23'), '23.1.13',
        'aksiz markası ilə markalanmalı və məcburi nişanlama ilə nişanlanmalı olan malların, habelə dini təyinatlı ədəbiyyatın (kağız və elektron daşıyıcılarında), audio və video materialların, mal və məmulatların və dini məzmunlu başqa məlumat materialların markalanmadan satışının həyata keçirilməsi aşkar edildikdə, həmin malları siyahıya almaq və vergi ödəyicisində və ya onun razılığı ilə vergi orqanlarının vəzifəli şəxsləri tərəfindən müəyyən edilən yerlərdə məsul saxlamaya qoymaq;',
        18, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '23'), '23.1.13-1',
        'nəzarət markalarının qəsdən məhv edilməsi, saxtalaşdırılması, qeyri-qanuni yolla hazırlanması, istifadəsi və satışının qarşısının alınması sahəsində nəzarəti həyata keçirmək;',
        19, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '23'), '23.1.14',
        'bu Məcəllə ilə müəyyən edilmiş qaydada mütəxəssisləri, ekspertləri, tərcüməçiləri, müşahidəçiləri cəlb etmək;',
        20, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '23'), '23.1.15',
        'məhkəmənin qərarı ilə müsadirə edilmiş aksiz markası olmayan və ya saxta aksiz markaları ilə markalanmış, habelə məcburi nişanlama ilə nişanlanmayan və ya saxta məcburi nişanlama ilə nişanlanmış malların satışını qanunvericiliyə uyğun olaraq təşkil etmək;',
        21, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '23'), '23.1.15-1',
        'hesablanmış vergilər üzrə borcların və faizlərin, tətbiq edilmiş maliyyə sanksiyalarının dövlət büdcəsinə alınması (əmlak satışı ilə bağlı olmayan ümumi qaydada iddia), yaxud hesablanmış vergilər üzrə borcların və faizlərin, tətbiq edilmiş maliyyə sanksiyalarının ödənilməsinin təmin olunması məqsədi ilə vergi ödəyicisinin siyahıya alınmış dövlət əmlakının, habelə digər daşınmaz əmlakının və dəyəri 5000 manatdan artıq olan daşınar əmlakının müvafiq icra hakimiyyəti orqanının müəyyən etdiyi orqan (qurum) vasitəsilə, habelə dəyəri 5000 manatdan artıq olmayan daşınar əmlakının isə ticarət şəbəkələrində satılması barədə məhkəmədə iddia qaldırmaq və məhkəmə qərarları üzrə həmin əmlakların satışını qanunvericiliyə uyğun olaraq təşkil etmək;',
        22, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '23'), '23.1.15-2',
        'vergi risklərinin minimallaşdırılması məqsədi ilə vergi ödəyiciləri ilə müvafiq icra hakimiyyəti orqanının müəyyən etdiyi qaydada və formada "Vergi partnyorluğu sazişi" bağlamaq;',
        23, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '23'), '23.1.15-3',
        'vergi ödəyicisi vergi öhdəliyini bu Məcəllə ilə müəyyən edilmiş müddətdə yerinə yetirmədikdə, hesablanmış vergilər üzrə borcların və faizlərin, tətbiq edilmiş maliyyə sanksiyalarının ödənilməsini təmin etmək üsulu kimi vergi ödəyicisi olan fiziki şəxsin və ya hüquqi şəxsin icra orqanının rəhbərinin ölkədən getmək hüququnun müvəqqəti məhdudlaşdırılması üçün məhkəməyə müraciət etmək;',
        24, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '23'), '23.1.15-4',
        'bu Məcəllənin 50-2.1-ci və 194.1-ci maddələrində nəzərdə tutulan qaydaların tələblərinə əməl edilməsinə nəzarət etmək;',
        25, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '23'), '23.1.15-5',
        'maliyyə institutlarında vergi monitorinqini aparmaq və bununla bağlı maliyyə institutlarından vergi və maliyyə məlumatlarının mübadiləsini nəzərdə tutan Azərbaycan Respublikasının tərəfdar çıxdığı beynəlxalq müqavilələrə uyğun olaraq həyata keçirilən maliyyə əməliyyatları barədə sənədləri və məlumatları elektron və (və ya) kağız daşıyıcılarda almaq;',
        26, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '23'), '23.1.16',
        'bu Məcəllə və Azərbaycan Respublikasının digər qanunvericilik aktları ilə vergi orqanlarının təyinatına uyğun olaraq nəzərdə tutulmuş başqa hüquqları həyata keçirmək.',
        27, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '23'), '23.2',
        'Yuxarı vergi orqanları tabeliyində olan vergi orqanlarının və onların vəzifəli şəxslərinin qeyri-qanuni aktlarını və qərarlarını ləğv edə bilərlər.',
        28, false, NOW(), NOW());

