-- ============================
INSERT INTO tax_articles (article_number, title, chapter, active, created_at, updated_at)
VALUES ('24',
        'Vergi orqanlarının vəzifələri',
        'III fəsil. Dövlət vergi orqanları',
        true, NOW(), NOW());

INSERT INTO tax_sections (article_id, section_number, content, order_index, synced_to_vector_store, created_at,
                          updated_at)
VALUES ((SELECT id FROM tax_articles WHERE article_number = '24'), '24.1',
        'Vergi orqanları:',
        1, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '24'), '24.1.1',
        'vergilərin düzgün hesablanmasına, tam və vaxtında ödənilməsinə nəzarət etməyə; vergi qanunvericiliyinə tam və dəqiq riayət etməyə;',
        2, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '24'), '24.1.1-1',
        'bu Məcəllənin 15.1.2-1-ci maddəsinə uyğun olaraq ərizə ilə müraciət etmiş vergi ödəyicilərinin həmin ərizədə göstərilən əməliyyatı ilə bağlı vergi öhdəliyinin əvvəlcədən müəyyənləşdirilməsi barədə qərar qəbul etməyə;',
        3, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '24'), '24.1.1-2',
        '"Mühasibat uçotu haqqında" Azərbaycan Respublikasının Qanunu ilə müəyyən edilmiş hallarda mühasibat uçotu sahəsində dövlət nəzarətini həyata keçirməyə;',
        4, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '24'), '24.1.2',
        'vergi ödəyicilərinin hüquqlarını və qanuni mənafelərini gözləməyə və müdafiə etməyə;',
        5, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '24'), '24.1.2-1',
        'vergi ödəyicisi olan fiziki şəxsin və ya hüquqi şəxsin icra orqanının rəhbərinin ölkədən getmək hüququnun müvəqqəti məhdudlaşdırılmasına səbəb olmuş əsaslar aradan qalxdıqdan sonra dərhal həmin məhdudlaşdırmanın götürülməsi barədə qərar qəbul etməyə;',
        6, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '24'), '24.1.2-2',
        'vergi orqanı tərəfindən siyahıya alınmış aksiz markası olmayan və ya saxta aksiz markaları ilə markalanmış, habelə məcburi nişanlama ilə nişanlanmalı olan, lakin nişanlanmamış və ya saxta məcburi nişanlama ilə nişanlanmış malların müsadirə edilməsi ilə bağlı məhkəmədə iddia qaldırmaq;',
        7, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '24'), '24.1.3',
        'vergi qanunvericiliyi və vergi qanunvericiliyində edilən dəyişikliklər barədə vergi ödəyicilərinə media ilə və ya fərdi qaydada əvəzsiz olaraq məlumat verməyə, müəyyən edilmiş hesabat formalarının doldurulması qaydalarını izah etməyə, vergilərin hesablanması və ödənilməsi barədə izahatlar verməyə, vergi ödəyicilərinə onların hüquq və vəzifələrini izah etməyə;',
        8, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '24'), '24.1.4',
        'hesablanmış və təyinatı üzrə daxil olmuş vergilərin uçotunu aparmağa və bu barədə müvafiq icra hakimiyyəti orqanlarına məlumat verməyə;',
        9, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '24'), '24.1.4-1',
        'vergi ödəyicisinin müraciəti əsasında hesablanmış, yenidən hesablanmış, ödənilmiş və artıq ödənilmiş vergilərə, məcburi dövlət sosial sığorta, işsizlikdən sığorta və icbari tibbi sığorta haqlarına, faizlərə, maliyyə sanksiyalarına və inzibati cərimələrə dair müvafiq icra hakimiyyəti orqanının müəyyən etdiyi orqanın (qurumun) təsdiq etdiyi formada üzləşmə aktını "İnformasiya əldə etmək haqqında" Azərbaycan Respublikasının Qanunu ilə müəyyən edilmiş müddətdə təqdim etməyə;',
        10, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '24'), '24.1.5',
        'vergi qanunvericiliyinin pozulması hallarına dair məlumatları toplamağa, təhlil etməyə və qiymətləndirməyə, belə halların baş verməsinə gətirib çıxaran səbəblərin və şəraitin aradan qaldırılması üçün müvafiq dövlət orqanlarına təkliflər verməyə;',
        11, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '24'), '24.1.5-1',
        'vergi ödəyicilərinin vergidən yayınması və vergi qanunvericiliyinin pozulması faktları barədə şəxslərdən müraciət daxil olduqda, müraciətdə qeyd edilən faktları həmin vergi ödəyicilərində keçiriləcək növbəti operativ vergi nəzarəti tədbiri və ya növbəti səyyar vergi yoxlaması zamanı araşdırmağa və vergi nəzarəti başa çatdıqdan sonra nəticələri barədə müraciət edən şəxslərə məlumat verməyə;',
        12, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '24'), '24.1.6',
        'vergi ödəyicilərinin, onların filiallarının, nümayəndəliklərinin və ya digər bölmələrinin (obyektlərinin), habelə nəzarət-kassa aparatlarının uçotunu aparmağa. Nəzarət-kassa aparatlarının elektron uçotunun aparılması qaydası müvafiq icra hakimiyyəti orqanının müəyyən etdiyi orqan (qurum) tərəfindən müəyyən edilir;',
        13, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '24'), '24.1.6-1',
        'bu Məcəllənin 218.4.4-cü maddəsində göstərilən fiziki şəxslərə bu Məcəllənin 220.10-cu maddəsində nəzərdə tutulmuş fəaliyyət növləri ilə məşğul olmaq üçün "Sadələşdirilmiş vergi üzrə sabit məbləğin, məcburi dövlət sosial sığorta və icbari tibbi sığorta haqqının ödənilməsi haqqında qəbz" verməyə;',
        14, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '24'), '24.1.7',
        'kommersiya və publik hüquqi şəxslərin dövlət qeydiyyatını və dövlət reyestrini aparmağa və bununla bağlı məlumatları (kommersiya hüquqi şəxslərin təsisçiləri (iştirakçıları) və onların nizamnamə kapitalındakı payları, habelə benefisiar mülkiyyətçiləri barədə məlumatlar istisna olmaqla) qanunvericiliklə müəyyən edilmiş qaydada və müddətlərdə müvafiq icra hakimiyyəti orqanlarına göndərməyə;',
        15, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '24'), '24.1.7-1',
        'bu Məcəllənin 165.3-cü maddəsinə uyğun olaraq ƏDV-nin qaytarılması şərti ilə satışı həyata keçirmək üçün müvafiq icra hakimiyyəti orqanının müəyyən etdiyi qaydada vergi ödəyicilərinin qeydiyyatını aparmağa, satıcı kimi qeydiyyata alınmış vergi ödəyicilərinin müraciəti əsasında onları müvafiq proqram təminatı ilə təchiz etməyə, ƏDV-nin qaytarılması sisteminin təşkili ilə bağlı müəyyən edilmiş gömrük sərhəd buraxılış məntəqələrində zəruri infrastrukturun yaradılmasını təmin etməyə;',
        16, false, NOW(), NOW()),
       -- QEYD: mənbə sənəddə bu bənd "24.0.7-2" kimi yazılıb (çox güman ki, əsl mətndə 24.1.7-2 olmalıdır, orijinal sənəd xətası). Olduğu kimi saxlanılıb.
       ((SELECT id FROM tax_articles WHERE article_number = '24'), '24.0.7-2',
        'bu Məcəllənin 165.4-cü maddəsinə uyğun olaraq ticarət festivalları dövründə ƏDV-nin qaytarılması şərti ilə satış üçün müvafiq icra hakimiyyəti orqanının müəyyən etdiyi qaydada vergi ödəyicilərinin qeydiyyatını aparmağa, satıcı kimi qeydiyyata alınmış vergi ödəyicilərinin müraciəti əsasında onları müvafiq proqram təminatı ilə təchiz etməyə;',
        17, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '24'), '24.1.8',
        'bu Məcəllədə və qanunvericilikdə nəzərdə tutulmuş qaydada vergi ödəyiciləri haqqında məlumatın, o cümlədən vergi, kommersiya və bank sirrinin qorunması qaydalarına riayət etməyə və onu təmin etməyə;',
        18, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '24'), '24.1.8-1',
        'vergi nəzarəti zamanı vergi orqanları tərəfindən fiziki şəxs olmayan vergi ödəyicisinin benefisiar mülkiyyətçisinin həmin vergi ödəyicisinin hüquqi şəxslərin dövlət reyestrinə daxil edilmiş benefisiar mülkiyyətçisindən fərqli olduğu müəyyən edilərsə, bu barədə maliyyə monitorinqi orqanına məlumat verməyə;',
        19, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '24'), '24.1.9',
        'vergi ödəyicilərinə vergi yoxlamalarının nəticələri haqqında aktın, habelə qanunvericiliklə müəyyən edilmiş hallarda vergi orqanının qərarının surətini verməyə;',
        20, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '24'), '24.1.10',
        'vergi ödəyiciləri tərəfindən artıq ödənilmiş vergi məbləğlərinin əvəzləşdirilməsi və ya geri qaytarılması, habelə vergi ödəyicilərindən düzgün tutulmayan vergi məbləğlərinin, maliyyə sanksiyalarının, faizlərin və inzibati cərimələrin geri qaytarılması üçün qanunvericiliklə müəyyən edilmiş tədbirləri görməyə;',
        21, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '24'), '24.1.11',
        'tabeliyində olan vergi orqanlarının fəaliyyətinə nəzarəti həyata keçirməyə;',
        22, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '24'), '24.1.12',
        'bu Məcəllə və Azərbaycan Respublikasının digər qanunvericilik aktları ilə vergi orqanlarının təyinatına uyğun olaraq müəyyən edilmiş digər vəzifələri həyata keçirməyə borcludur.',
        23, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '24'), '24.2',
        'Bu Məcəllə ilə nəzərdə tutulmuş dövlət xidmətlərinin göstərilməsi ilə əlaqədar təqdim edilməli olan sənədlərin və ya məlumatların Elektron Hökumət İnformasiya Sistemi vasitəsilə müvafiq dövlət orqanından (qurumundan) əldə edilməsi mümkün olduqda, həmin sənədlər və ya məlumatlar vergi ödəyicisindən tələb edilmir. Belə sənədlərin və ya məlumatların Elektron Hökumət İnformasiya Sistemi vasitəsilə əldə edilməsi mümkün olmadığı hallarda onların təqdim edilməsi vergi ödəyicisinin razılığı ilə sorğu əsasında müvafiq dövlət orqanından (qurumundan) tələb olunur və ya vergi ödəyicisi tərəfindən təmin edilir.',
        24, false, NOW(), NOW());

