INSERT INTO tax_sections (article_id, section_number, content, order_index, synced_to_vector_store, created_at,
                          updated_at)
VALUES ((SELECT id FROM tax_articles WHERE article_number = '26'), '26.1',
        'Vergi orqanları öz vəzifələrini mərkəzi və yerli icra hakimiyyəti orqanları, hüquq-mühafizə, maliyyə və digər dövlət hakimiyyəti orqanları ilə qarşılıqlı əlaqədə həyata keçirirlər.',
        1, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '26'), '26.2',
        'Vergi orqanlarının vəzifələrinin yerinə yetirilməsi ilə əlaqədar digər dövlət hakimiyyəti orqanları vergi orqanlarına kömək etməyə və zəruri hallarda müəyyən edilmiş qaydada onlara lazımi məlumatları verməyə borcludurlar.',
        2, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '26'), '26.2-1',
        'Vergi orqanlarının vəzifələrinin yerinə yetirilməsi ilə əlaqədar dövlət orqanlarının (qurumlarının) informasiya sistemlərində (ehtiyatlarında) olan məlumatlar normativ hüquqi aktlarla müəyyən edilmiş müddətlərdə və müvafiq icra hakimiyyəti orqanının müəyyən etdiyi orqanın (qurumun) müəyyən etdiyi qaydada müvafiq icra hakimiyyəti orqanının müəyyən etdiyi orqan (qurum) tərəfindən əldə edilir.',
        3, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '26'), '26.3',
        'Gömrük orqanları vergitutma ilə əlaqədar onlarda olan məlumatı bu Məcəllənin 20.1-ci maddəsində nəzərdə tutulan müvafiq icra hakimiyyəti orqanına verməlidir.',
        4, false, NOW(), NOW());

