INSERT INTO tax_sections (article_id, section_number, content, order_index, synced_to_vector_store, created_at,
                          updated_at)
VALUES ((SELECT id FROM tax_articles WHERE article_number = '28'), '28.1',
        'Vergi orqanlarının vəzifəli şəxslərinə tutduğu vəzifəsinə, ixtisasına və iş stajına görə xüsusi rütbələr verilir.',
        1, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '28'), '28.2',
        'Xüsusi rütbələrin verilməsi, həmin rütbələrdən məhrum edilməsi qaydası və xüsusi rütbələrlə bağlı digər məsələlər qanunvericiliklə müəyyən edilir.',
        2, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '28'), '28.3',
        'Vergi orqanlarının vəzifəli şəxslərinin xüsusi rütbələrinə uyğun olaraq xüsusi geyim forması və fərqlənmə nişanları vardır. Həmin geyim formasının və fərqlənmə nişanlarının nümunəsi müvafiq icra hakimiyyəti orqanı tərəfindən təsdiq edilir.',
        3, false, NOW(), NOW());

-- ============================
-- TAX ARTICLE (Maddə 29)
-- ============================
INSERT INTO tax_articles (article_number, title, chapter, active, created_at, updated_at)
VALUES ('29',
        'Mənafelərin toqquşması',
        'III fəsil. Dövlət vergi orqanları',
        true, NOW(), NOW());

INSERT INTO tax_sections (article_id, section_number, content, order_index, synced_to_vector_store, created_at,
                          updated_at)
VALUES ((SELECT id FROM tax_articles WHERE article_number = '29'), '29.0',
        'Vergi orqanlarının vəzifəli şəxsləri tərəfindən aşağıdakı hallarda öz xidməti vəzifələrini vergi ödəyicilərinə münasibətdə həyata keçirmək yol verilməzdir:',
        1, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '29'), '29.0.1',
        'vergi orqanlarının vəzifəli şəxsləri ilə vergi ödəyiciləri arasındakı münasibətlər ailə üzvlərinin münasibətləri olduqda;',
        2, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '29'), '29.0.2',
        'vergi orqanlarının vəzifəli şəxslərinin və ya onların ailə üzvlərinin bilavasitə və ya dolayısı ilə vergi ödəyicisində (onun fəaliyətində) maliyyə marağı olduqda.',
        3, false, NOW(), NOW());

-- ============================
-- TAX ARTICLE (Maddə 30)
-- ============================
INSERT INTO tax_articles (article_number, title, chapter, active, created_at, updated_at)
VALUES ('30',
        'Kommersiya və (və ya) vergi sirri',
        'III fəsil. Dövlət vergi orqanları',
        true, NOW(), NOW());

INSERT INTO tax_sections (article_id, section_number, content, order_index, synced_to_vector_store, created_at,
                          updated_at)
VALUES ((SELECT id FROM tax_articles WHERE article_number = '30'), '30.1',
        'Vergi orqanları və onların vəzifəli şəxsləri (vergi orqanlarında işlədikləri dövrdə və ya işdən çıxdıqdan sonra qanunvericiliklə müəyyən edilmiş müddətdə) xidməti vəzifələrini yerinə yetirərkən, vergi ödəyiciləri haqqında əldə etdikləri və ya onlara etibar edilən hər hansı məlumatın məxfiliyini qorumağa borcludurlar.',
        1, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '30'), '30.2',
        'Aşağıdakı məlumatlar istisna olmaqla, vergi orqanı və onun vəzifəli şəxsləri tərəfindən vergi ödəyicisi barədə əldə edilən istənilən məlumat vergi sirri və şəxsi həyata dair məlumat hesab olunur:',
        2, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '30'), '30.2.1',
        'vergi ödəyicisinin razılığı ilə aşkar edilən;',
        3, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '30'), '30.2.2',
        'vergi ödəyicisinin eyniləşdirmə nömrəsi və təsərrüfat subyektinin (obyektinin) uçot kodu haqqında;',
        4, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '30'), '30.2.3',
        'müəssisənin nizamnamə fondu (nizamnamə kapitalı) haqqında;',
        5, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '30'), '30.2.4',
        'vergi qanunvericiliyinin pozulması və bu pozulmalara görə məsuliyyət tədbirləri haqqında.',
        6, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '30'), '30.2.5',
        'vergilər, məcburi dövlət sosial sığorta, işsizlikdən sığorta və icbari tibbi sığorta haqları, faizlər və maliyyə sanksiyaları üzrə borclar.',
        7, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '30'), '30.2.6',
        'hüquqi şəxslərin dövlət reyestrindəki məlumatlar (kommersiya hüquqi şəxslərin təsisçiləri (iştirakçıları) və onların nizamnamə kapitalındakı payları, habelə benefisiar mülkiyyətçiləri barədə məlumatlar istisna olmaqla).',
        8, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '30'), '30.2.7',
        'vergi ödəyicisinin ƏDV-nin məqsədləri üçün qeydiyyatda olub-olmaması haqqında;',
        9, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '30'), '30.2.8',
        'bu Məcəllənin 16.3-cü maddəsinə uyğun olaraq vergi ödəyicisinin sahibkarlıq fəaliyyətinin və ya digər vergi tutulan əməliyyatlarının dayandırılıb-dayandırılmaması haqqında;',
        10, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '30'), '30.2.9',
        'vergi ödəyicisinin riskli vergi ödəyicisi olub-olmaması, habelə bu hallarla bağlı vergi orqanının qəbul etdiyi qərarlar haqqında.',
        11, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '30'), '30.3',
        '"Kommersiya sirri haqqında" Azərbaycan Respublikası Qanununa əsasən vergi ödəyicisinin kommersiya sirrini təşkil edən məlumatlar və ya vergi sirri vergi orqanları, onların vəzifəli şəxsləri tərəfindən qanunla nəzərdə tutulmuş hallar istisna olmaqla, açılmamalıdır. Kommersiya və (və ya) vergi sirrinin açılmasına əsas etibarilə, ancaq bununla məhdudlaşmayan, vergi yoxlaması zamanı vəzifələrini yerinə yetirərkən vergi orqanının vəzifəli şəxsinə, cəlb edilmiş mütəxəssisə və ya ekspertə bəlli olmuş vergi ödəyicisinin kommersiya və (və ya) vergi sirrinin istifadə edilməsi və ya başqa şəxsə verilməsi aiddir.',
        12, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '30'), '30.4',
        'Vergi orqanına daxil olmuş və kommersiya və (və ya) vergi sirrini təşkil edən məlumatların qorunmasının və əldə edilməsinin xüsusi rejimi vardır. Kommersiya və (və ya) vergi sirrini təşkil edən məlumatları müvafiq icra hakimiyyəti orqanı tərəfindən müəyyən edilən siyahı üzrə vəzifəli şəxslər əldə edə bilər.',
        13, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '30'), '30.5',
        'Kommersiya və (və ya) vergi sirrini təşkil edən məlumatların itirilməsi və yaxud belə məlumatların açılması qanunla nəzərdə tutulmuş məsuliyyətə səbəb olur.',
        14, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '30'), '30.6',
        'Bu Məcəllənin 30.1-ci maddəsində göstərilən vergi orqanları və onların vəzifəli şəxsləri vergi ödəyiciləri haqqında məlumatı ancaq aşağıdakı hallarda digər orqanlara qanunvericiliklə müəyyən edilmiş qaydada verə bilərlər:',
        15, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '30'), '30.6.1',
        'vergi orqanlarına və onların vəzifəli şəxslərinə vergi orqanlarının vəzifələrinin həyata keçirilməsi məqsədi ilə;',
        16, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '30'), '30.6.2',
        'vergi qanunvericiliyinin cinayət tərkibli pozuntuları ilə əlaqədar onların qarşısının alınması və istintaq aparılması üçün müvafiq icra hakimiyyəti orqanına;',
        17, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '30'), '30.6.3',
        'ədalət mühakiməsinin həyata keçirilməsi məqsədi ilə müvafiq məhkəmələrə;',
        18, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '30'), '30.6.4',
        'Azərbaycan Respublikasının tərəfdar çıxdığı beynəlxalq müqavilələrə uyğun olaraq digər dövlətlərin müvafiq dövlət hakimiyyəti orqanlarına;',
        19, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '30'), '30.6.5',
        '"Sosial sığorta haqqında", "İşsizlikdən sığorta haqqında", "Tibbi sığorta haqqında" Azərbaycan Respublikasının qanunlarından irəli gələn vəzifələrin icrası üçün zəruri olan hədlərdə müvafiq icra hakimiyyəti orqanının müəyyən etdiyi orqana (quruma);',
        20, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '30'), '30.6.6',
        'gömrük qanunvericiliyinin tətbiq edilməsi məqsədləri üçün gömrük orqanlarına;',
        21, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '30'), '30.6.7',
        'cinayət yolu ilə əldə edilmiş pul vəsaitlərinin və ya digər əmlakın leqallaşdırılması və terrorçuluğun maliyyələşdirilməsinin qarşısının alınması məqsədi ilə maliyyə monitorinqi orqanına;',
        22, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '30'), '30.6.7-1',
        '"Azərbaycan Respublikasının Mərkəzi Bankı haqqında", "Banklar haqqında", "Sığorta fəaliyyəti haqqında", "Bank olmayan kredit təşkilatları haqqında", "Kredit ittifaqları haqqında", "Valyuta tənzimi haqqında", "Qiymətli kağızlar bazarı haqqında", "Kraudfandinq haqqında", "İnvestisiya fondları haqqında", "Ödəniş xidmətləri və ödəniş sistemləri haqqında" Azərbaycan Respublikasının qanunlarından irəli gələrək lisenziyanın (icazənin) verilməsi, fəaliyyətə başlama üçün qeydiyyatın (reyestrin) aparılması və nəzarətin həyata keçirilməsi məqsədilə aşağıdakı məlumatları Azərbaycan Respublikası Mərkəzi Bankının sorğusu əsasında Azərbaycan Respublikasının Mərkəzi Bankına: (30.6.7-1-ci maddənin birinci abzasına Azərbaycan Respublikasının 2026-cı il 26 may tarixli 413-VIIQD nömrəli Qanunu ilə edilmiş dəyişiklik 2026-cı il dekabr 25-dən qüvvəyə minir.)',
        23, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '30'), '30.6.7-1.1',
        'kommersiya hüquqi şəxslərinin dövlət reyestrindən çıxarış və nizamnamə, kommersiya hüquqi şəxslərinin idarəetmə orqanlarının rəhbərləri, təsisçiləri (iştirakçıları) və onların nizamnamə kapitalındakı payları;',
        24, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '30'), '30.6.7-1.2',
        'fiziki şəxslərin, kommersiya hüquqi şəxslərinin və onların təsisçilərinin (iştirakçılarının) iştirakçısı olduğu hüquqi şəxslər və belə hüquqi şəxslərin nizamnamə kapitalındakı payları;',
        25, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '30'), '30.6.7-1.3',
        'fiziki şəxslərin, kommersiya hüquqi şəxslərinin və onların idarəetmə orqanlarının rəhbərlərinin, təsisçilərinin (iştirakçılarının) və bu şəxslərin iştirakçısı olduğu hüquqi şəxslərin mənfəəti (gəlir və zərəri).',
        26, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '30'), '30.6.8',
        'büdcə sistemi haqqında qanunvericiliyin və "Mühasibat uçotu haqqında" Azərbaycan Respublikası Qanununun 12.6-cı maddəsinin tətbiq edilməsi məqsədləri üçün müvafiq icra hakimiyyəti orqanının müəyyən etdiyi orqana (quruma);',
        27, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '30'), '30.6.9',
        'müvafiq icra hakimiyyəti orqanının müəyyən etdiyi orqanın (qurumun) sorğusu əsasında ipoteka kreditləşməsi və sahibkarların aldıqları kreditlərə təminat verilməsi üçün zəruri olan hədlərdə müvafiq icra hakimiyyəti orqanının müəyyən etdiyi orqana (quruma);',
        28, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '30'), '30.6.10',
        '"Kredit büroları haqqında" Azərbaycan Respublikası Qanununun 6.1-ci və 6.2-ci maddələrində nəzərdə tutulmuş fəaliyyətin həyata keçirilməsi üçün kredit bürolarına;',
        29, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '30'), '30.6.11',
        '"Hesablama Palatası haqqında" Azərbaycan Respublikasının Qanunu ilə müəyyən edilmiş vəzifələrin həyata keçirilməsi məqsədilə Azərbaycan Respublikasının Hesablama Palatasına;',
        30, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '30'), '30.6.12',
        '"Notariat haqqında" Azərbaycan Respublikasının Qanununa uyğun olaraq notariat hərəkətlərinin aparılması və bununla əlaqədar xidmətlərin göstərilməsi üçün notariuslara;',
        31, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '30'), '30.6.13',
        '"İcra haqqında" Azərbaycan Respublikasının Qanununa uyğun olaraq icra hərəkətlərinin həyata keçirilməsi üçün icra məmurlarına;',
        32, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '30'), '30.6.14',
        'sahibkarlığın inkişafı üçün təqdim olunan investisiya layihələrinin ekspertizasının həyata keçirilməsi, həmin layihələrin güzəştli kredit vəsaiti hesabına maliyyələşdirilməsi, habelə sahibkarlıq subyektlərinin manatla aldıqları kreditlərə zəmanət və faiz subsidiyasının verilməsi məqsədilə müvafiq icra hakimiyyəti orqanının müəyyən etdiyi orqana (quruma);',
        33, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '30'), '30.6.15',
        'Azərbaycan Respublikası Rəqabət Məcəlləsinin 29.7-ci və 56.1-ci maddələrinin tətbiq edilməsi məqsədləri üçün müvafiq icra hakimiyyəti orqanının müəyyən etdiyi orqana (quruma);',
        34, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '30'), '30.6.16',
        'səlahiyyətlərinin icrası ilə əlaqədar müvafiq icra hakimiyyəti orqanının müəyyən etdiyi orqanın (qurumun) sorğusu əsasında müvafiq icra hakimiyyəti orqanının müəyyən etdiyi orqana (quruma);',
        35, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '30'), '30.6.17',
        '"Dövlət satınalmaları haqqında" Azərbaycan Respublikasının Qanunu ilə müəyyən edilmiş vəzifələrin həyata keçirilməsi məqsədilə müvafiq icra hakimiyyəti orqanının müəyyən etdiyi orqana (quruma);',
        36, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '30'), '30.6.18',
        'müvafiq icra hakimiyyəti orqanının müəyyən etdiyi orqanın (qurumun) sorğusu əsasında kənd təsərrüfatı sahəsində subsidiyalara, güzəştli kreditlərə, kənd təsərrüfatı istehsal vasitələrinin güzəştli şərtlərlə satışına və lizinqinə nəzarət edilməsi, habelə ərzaq məhsullarının (dövlət ehtiyatları üçün alınan ərzaq məhsulları istisna olmaqla) mərkəzləşdirilmiş qaydada dövlət büdcəsinin vəsaitləri hesabına satın alınması məqsədləri üçün zəruri olan hədlərdə müvafiq icra hakimiyyəti orqanının müəyyən etdiyi orqana (quruma). (30.6.18-ci maddəyə Azərbaycan Respublikasının 2026-cı il 26 may tarixli 413-VIIQD nömrəli Qanunu ilə edilmiş dəyişiklik 2026-cı il dekabr 25-dən qüvvəyə minir.)',
        37, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '30'), '30.6-1',
        'Vergi orqanları və onların vəzifəli şəxsləri tərəfindən vergi ödəyicisinin vergi uçotundan çıxarılıb-çıxarılmaması, vergi ödəyicisinin fəaliyyət növlərinin adı və kodu (əsas və əlavə), vergi ödəyicisinin təsərrüfat subyektinin (obyektinin) yerləşdiyi ünvan haqqında məlumat səlahiyyətlərinin icrası ilə əlaqədar dövlət orqanlarına (qurumlarına) verilə bilər.',
        38, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '30'), '30.6-2',
        'Vergi orqanları və onların vəzifəli şəxsləri tərəfindən vergi ödəyicisinin fəaliyyət növlərinin adı və kodu (əsas və əlavə) haqqında məlumat hesabların açılması məqsədilə ödəniş xidməti təchizatçılarına verilə bilər.',
        39, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '30'), '30.7',
        'Dövlət hakimiyyəti orqanları və onların vəzifəli şəxsləri kommersiya və (və ya) vergi sirrini təşkil edən məlumatları əks etdirən sənədləri həmin sənədləri onlara təqdim etmiş vergi orqanlarına qaytarmalıdırlar.',
        40, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '30'), '30.8',
        'Vergi ödəyicisinə aid məlumat vergi ödəyicisinin yazılı icazəsi ilə digər şəxsə verilə bilər.',
        41, false, NOW(), NOW());

