INSERT INTO tax_sections (article_id, section_number, content, order_index, synced_to_vector_store, created_at,
                          updated_at)
VALUES ((SELECT id FROM tax_articles WHERE article_number = '31'),
        '31.0',
        'Vergi orqanlarının vəzifəli şəxslərinin aşağıda göstərilən vəzifələri vardır:',
        1, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '31'),
        '31.0.1',
        'bu Məcəlləyə və Azərbaycan Respublikasının digər qanunlarına ciddi riayət etmək;',
        2, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '31'),
        '31.0.2',
        'vergi orqanlarının hüquq və vəzifələrini öz səlahiyyətləri daxilində yerinə yetirmək;',
        3, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '31'),
        '31.0.3',
        'vergi ödəyicilərinə, onların nümayəndələrinə və vergi münasibətlərinin digər iştirakçılarına diqqət və nəzakətlə yanaşmaq.',
        4, false, NOW(), NOW());

