-- ============================
INSERT INTO tax_articles (article_number, title, chapter, active, created_at, updated_at)
VALUES ('33',
        'Vergi ödəyicilərinin uçotu',
        'IV fəsil. Vergi nəzarəti',
        true, NOW(), NOW());

INSERT INTO tax_sections (article_id, section_number, content, order_index, synced_to_vector_store, created_at,
                          updated_at)
VALUES ((SELECT id FROM tax_articles WHERE article_number = '33'), '33.1',
        'Vergi nəzarətinin həyata keçirilməsini təmin etmək məqsədi ilə vergi ödəyicisi olan hüquqi şəxslər, filial və nümayəndəliklər olduqları (dövlət qeydiyyatı haqqında sənədlərdə qeyd olunmuş hüquqi ünvan), vergiyə cəlb olunan gəliri Azərbaycan mənbəyindən olan və bu gəlirdən ödəmə yerində vergi tutulmayan qeyri-rezidentlər Azərbaycan mənbəyindən gəlirin alındığı yer üzrə, fərdi sahibkarlar və bu Məcəllənin müddəalarına uyğun olaraq bəyannamə verməli olan rezident fiziki şəxslər yaşadıqları, xüsusi notariuslar və xüsusi icra məmurları isə fəaliyyət göstərdiyi yer üzrə vergi orqanlarında uçota alınır. Kommersiya hüquqi şəxslərinə, publik hüquqi şəxslərə, habelə xarici kommersiya hüquqi şəxsinin nümayəndəlik və filiallarına qanunvericiliyə müvafiq qaydada dövlət qeydiyyatına alındığı zaman vergi ödəyicisinin eyniləşdirmə nömrəsi verilir və həmin andan onlar vergi uçotuna alınmış hesab olunurlar. Bu zaman verilən dövlət qeydiyyatı haqqında şəhadətnamə bu Məcəllənin məqsədləri üçün vergi ödəyicisinin vergi uçotuna alınmasını təsdiq edən şəhadətnamə hesab edilir.',
        1, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '33'), '33.2',
        'Bu Məcəllənin 34.3-1-ci maddəsinin müddəaları nəzərə alınmaqla, vergi ödəyicisinin filialı, nümayəndəliyi və ya digər təsərrüfat subyekti (obyekti) olduqda, vergi ödəyicisi həm özünün olduğu yer üzrə, həm də filialının, nümayəndəliyinin və ya digər təsərrüfat subyektinin (obyektinin) olduğu ünvan üzrə vergi uçotuna alınır. Vergi ödəyicisinin onun filialının, nümayəndəliyinin və ya digər təsərrüfat subyektinin (obyektinin) olduğu yer üzrə uçota alınması yenidən uçota alınması və uçotdan çıxarılması bu Məcəllənin müddəaları nəzərə alınmaqla müvafiq icra hakimiyyəti orqanının müəyyən etdiyi orqan (qurum) tərəfindən müəyyən edilmiş qaydada həyata keçirilir və bu barədə vergi ödəyicisinə müvafiq arayış verilir. Sahibkarlıq fəaliyyətini həyata keçirən hüquqi şəxslərin bu Məcəllənin 13.2.39.3-cü maddəsində göstərilmiş filialları, struktur bölmələri və ya digər ayrıca bölmələri, habelə qeyri-rezidentin Azərbaycan Respublikasının qanunvericiliyinə müvafiq olaraq yaradılmış filialları və daimi nümayəndəlikləri ayrıca uçota alınır və onlara VÖEN verilir. Azərbaycan Respublikasının büdcə və qeyri-kommersiya təşkilatları olduğu yerdən kənarda yerləşən və onların funksiyalarının həyata keçirilməsi məqsədilə yaradılan bölmələri ayrıca uçota alına və onlara VÖEN verilə bilər.',
        2, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '33'), '33.3',
        'Hüquqi şəxsin və sahibkarlıq fəaliyyətini hüquqi şəxs yaratmadan həyata keçirən fiziki şəxsin (bundan sonra - fərdi sahibkar) bu Məcəllə ilə vergi ödəməsi vəzifəsini şərtləndirən halların olub-olmamasından asılı olmayaraq onlar vergi orqanında vergi ödəyicisi kimi uçota alınır. Azərbaycan Respublikasında fəaliyyət göstərən xarici ölkələrin diplomatik və konsulluq nümayəndəlikləri, habelə beynəlxalq təşkilatların nümayəndəlikləri bu maddəyə uyğun olaraq vergi orqanında uçota alına bilərlər. Hüquqi şəxs yaratmadan sahibkarlıq fəaliyyətini fiziki şəxs kimi həyata keçirmək istəyən əcnəbilər və vətəndaşlığı olmayan şəxslər müvafiq icra hakimiyyəti orqanı tərəfindən verilən vəsiqə əsasında vergi orqanlarında vergi ödəyicisi kimi uçota alınırlar.',
        3, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '33'), '33.4',
        'Vergi orqanlarında uçota alınmaq üçün vergi ödəyiciləri tərəfindən (kommersiya hüquqi şəxsləri, publik hüquqi şəxslər, habelə xarici kommersiya hüquqi şəxsinin nümayəndəlik və filialları istisna olmaqla) onların olduğu və ya yaşadığı yer üzrə vergi orqanına ərizə verilir. Vergi orqanına ərizə qeyri-kommersiya hüquqi şəxsin dövlət qeydiyyatına alındığı gündən, Azərbaycan Respublikasında filial və nümayəndəlik vasitəsi ilə sahibkarlıq fəaliyyəti həyata keçirildikdə isə - filialın və ya nümayəndəliyin yaradılmasından sonra 30 gün müddətində verilməlidir. Dövlət qeydiyyatını həyata keçirən müvafiq icra hakimiyyəti orqanı bu maddənin birinci abzasında göstərilən şəxslərin dövlət qeydiyyatına alınması barəsində onlara qeydiyyat sənədləri ilə birlikdə həmin sənədlərin verilməsi tarixini əks etdirən arayış verməlidir. Daimi nümayəndəliyin vergi orqanlarında uçota alınması Azərbaycan Respublikasının hüquqi şəxsləri üçün müəyyən edilmiş qaydada həyata keçirilir. Hüquqi şəxs yaratmadan sahibkarlıq fəaliyyətini həyata keçirən fiziki şəxs ərizəni, sahibkarlıq fəaliyyətinə başladığı günədək vergi orqanına verməlidir. Ödəmə mənbəyində vergiyə cəlb olunması nəzərdə tutulmayan (tutulması mümkün olmayan) gəlirləri olan və ya royaltidən gəliri olan fiziki şəxslər, yaxud Azərbaycan Respublikasının hüdudlarından kənarda gəlir əldə edən rezident fiziki şəxslər ərizəni gəlir əldə etmək hüququ yarandığı gündən gec olmayaraq vergi orqanına verməlidirlər.',
        4, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '33'), '33.5',
        'Bu Məcəllənin 33.3-cü və 33.4-cü maddələrinin tələbləri nəzərə alınmaqla, vergi orqanında uçota alınmaq üçün ərizə təqdim etməyən fiziki şəxsi vergi orqanı öz təşəbbüsü ilə vergi uçotuna alır və 5 gün müddətində ona vergi uçotuna alınması barədə bildiriş göndərir.',
        5, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '33'), '33.6',
        'Vergi ödəyicisinin vergi uçotuna alınması yerinin müəyyən edilməsi ilə bağlı çətinliklər ortaya çıxdıqda, təqdim olunmuş məlumatlar əsasında yuxarı vergi orqanı tərəfindən qərar qəbul edilir.',
        6, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '33'), '33.7',
        'Bu Məcəllənin 33.7.1-ci maddəsində göstərilən vergi ödəyicilərinin mərkəzləşdirilmiş qaydada uçotu müvafiq icra hakimiyyəti orqanının müəyyən etdiyi orqan (qurum) tərəfindən aparılır.',
        7, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '33'), '33.7.1',
        'Aşağıdakı vergi ödəyiciləri mərkəzləşdirilmiş qaydada uçota alınırlar:',
        8, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '33'), '33.7.1.1',
        'təbii inhisar subyektləri;',
        9, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '33'), '33.7.1.2',
        'xüsusi vergi rejimli müəssisələr;',
        10, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '33'), '33.7.1.3',
        'aşağıdakı tələblərdən birinə cavab verən vergi ödəyiciləri:',
        11, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '33'), '33.7.1.3.1',
        'işçilərin orta siyahı sayı 251 və ondan yuxarı olan;',
        12, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '33'), '33.7.1.3.2',
        'balansında olan əsas vəsaitlərin orta illik qalıq dəyəri 5.000.000 manatdan yuxarı olan.',
        13, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '33'), '33.7.2',
        'Bu Məcəllənin 33.7.1-ci maddəsində göstərilən vergi ödəyicilərinə eyniləşdirmə nömrələrinin verilməsi bu Məcəlləyə uyğun olaraq həyata keçirilir.',
        14, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '33'), '33.7.3',
        'Olduqları yer üzrə vergi uçotuna alınmış şəxslər sonradan bu Məcəllənin 33.7.1.3-cü maddəsində göstərilən vergi ödəyicilərinə və ya xüsusi vergi rejimli müəssisələrə aid edildikdə, əvvəlki eyniləşdirmə nömrələri ilə mərkəzləşdirilmiş qaydada uçota alınırlar.',
        15, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '33'), '33.7.4',
        'Mərkəzləşdirilmiş qaydada uçota alınmış bu Məcəllənin 33.7.1.3-cü maddəsində göstərilən vergi ödəyicilərinin və xüsusi vergi rejimli müəssisələrin filiallarının, nümayəndəliklərinin və ya digər təsərrüfat subyektlərinin (obyektlərinin) vergi uçotu bu Məcəllə ilə müəyyən edilmiş qaydada həyata keçirilir.',
        16, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '33'), '33.7.5',
        'Olduqları yer üzrə vergi uçotuna alınmış hüquqi şəxslər xüsusi vergi rejimi üzrə fəaliyyətə başladığı gündən sonra 15 gün müddətində mərkəzləşdirilmiş qaydada uçota alınmaq üçün müvafiq vergi orqanına müraciət etməyə borcludurlar.',
        17, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '33'), '33.7.6',
        'Xüsusi vergi rejimində fəaliyyət göstərən müəssisələrin mərkəzləşdirilmiş qaydada yenidən uçota alınması və ya mərkəzləşdirilmiş uçotdan çıxarılması, xüsusi vergi rejimində fəaliyyətə başlaması və ya həmin fəaliyyəti dayandırması onların mərkəzləşdirilmiş qaydada uçotunu aparan müvafiq vergi orqanına ərizə ilə müraciət etdiyi gündən 15 gün müddətində həyata keçirilməlidir.',
        18, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '33'), '33.7.7',
        'Bu Məcəllənin 33.7.1.3-cü maddəsində göstərilən vergi ödəyicilərinə aid edilən müəssisələrin olduqları yer üzrə uçotdan çıxarılaraq mərkəzləşdirilmiş qaydada yenidən uçota alınması və ya mərkəzləşdirilmiş uçotdan çıxarılması barədə müvafiq icra hakimiyyəti orqanının müəyyən etdiyi orqan (qurum) tərəfindən hər il may ayının 15-dək qərar qəbul edilir.',
        19, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '33'), '33.7.8',
        'Bu Məcəllənin 33.7.1.3-cü maddəsində göstərilən vergi ödəyicilərinə aid edilən müəssisələrin mərkəzləşdirilmiş qaydada uçota alınması onların mərkəzləşdirilmiş qaydada uçota alınması barədə qərar qəbul edildiyi vergi ilindən sonrakı ilin yanvar ayında həyata keçirilir.',
        20, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '33'), '33.7.9',
        'Müvafiq icra hakimiyyəti orqanının müəyyən etdiyi orqan (qurum) hər il iyun ayının 15-dək olduqları yer üzrə uçotdan çıxarılaraq mərkəzləşdirilmiş qaydada yenidən uçota alınmış və ya mərkəzləşdirilmiş uçotdan çıxarılmış bu Məcəllənin 33.7.1.3-cü maddəsində göstərilən vergi ödəyiciləri və xüsusi vergi rejimli müəssisələr barədə məlumatı müvafiq icra hakimiyyəti orqanının müəyyən etdiyi orqan (qurum) ilə razılaşdırılmış forma üzrə müvafiq icra hakimiyyəti orqanının müəyyən etdiyi orqana (quruma) təqdim edir.',
        21, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '33'), '33.8',
        'Azərbaycan Respublikasının tərəfdar çıxdığı ikiqat vergitutmanın aradan qaldırılması haqqında beynəlxalq müqavilələrə əsasən xarici dövlətin rezidentinin Azərbaycan Respublikasında fəaliyyət göstərən və daimi nümayəndəlik yaratmayan bölmələrinin, habelə bu Məcəllənin 13.2.5.3-cü maddəsinə müvafiq olaraq idarəetmə yerinə görə rezident sayılan hüquqi şəxsin vergi orqanında uçota alınması aşağıdakı qaydada aparılır:',
        22, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '33'), '33.8.1',
        'Azərbaycan Respublikasında daimi nümayəndəlik yaratmayan bölmələr Azərbaycan Respublikasında fəaliyyətə başladıqdan 30 gün müddətində, idarəetmə yerinə görə rezident sayılan xarici hüquqi şəxslər isə Azərbaycan Respublikasının Vergi Məcəlləsinə və ya Azərbaycan Respublikasının tərəfdar çıxdığı ikiqat vergitutmanın aradan qaldırılması haqqında beynəlxalq müqavilələrin müddəalarına əsasən idarəetmə yerinə görə rezident sayıldıqları vaxtdan 30 gün müddətində olduqları yer üzrə vergi orqanına ərizə təqdim etməlidirlər.',
        23, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '33'), '33.8.2',
        'Azərbaycan Respublikasında daimi nümayəndəlik yaratmayan bölmələrin, habelə idarəetmə yerinə görə rezident sayılan xarici hüquqi şəxsin vergi uçotuna alınması üçün verilən ərizə xarici hüquqi şəxs və ya onun müvəkkil etdiyi şəxs tərəfindən imzalanmalıdır.',
        24, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '33'), '33.8.3',
        'Azərbaycan Respublikasında daimi nümayəndəlik yaratmayan bölmələrinin, habelə idarəetmə yerinə görə rezident sayılan xarici hüquqi şəxsin vergi orqanlarında uçota alınması üçün bu Məcəllənin 33.8-ci maddəsində göstərilənlərdən başqa digər sənəd və məlumatlar tələb olunmur.',
        25, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '33'), '33.8.4',
        'Xarici dövlətin rezidentinin Azərbaycan Respublikasında daimi nümayəndəlik yaratmayan bölmələrinin uçota alınması barədə verilən ərizəyə aşağıdakılar əlavə edilməlidir:',
        26, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '33'), '33.8.4.1',
        'xarici hüquqi şəxsin qeydiyyata alındığı dövlətdə qeydiyyat (inkorporasiya) sənədi və onun təsisçisi (təsisçiləri) olan xarici hüquqi şəxsin nizamnamə kapitalında birbaşa və ya dolayı yolla paya malik fiziki şəxslər barədə məlumatın da daxil olduğu ticarət reyestrindən çıxarış;',
        27, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '33'), '33.8.4.2',
        'xarici dövlətin rezidentinin səlahiyyətli orqanının Azərbaycan Respublikasında daimi nümayəndəlik yaratmayan bölməsinin yaradılması haqqında qərarı;',
        28, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '33'), '33.8.4.3',
        'təsis sənədləri;',
        29, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '33'), '33.8.4.4',
        'rezidentliyi barədə vergi orqanları tərəfindən təsdiq edilmiş sənəd;',
        30, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '33'), '33.8.4.5',
        'Azərbaycan Respublikasında hüquqi ünvanını təsdiq edən sənəd (icarə müqaviləsi, mülkiyyət hüququnu təsdiq edən və ya digər sənədlər);',
        31, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '33'), '33.8.4.6',
        'bölmənin rəhbərinin (təmsilçisinin) şəxsiyyətini təsdiq edən sənədin surəti;',
        32, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '33'), '33.8.4.7',
        'Azərbaycan Respublikasında daimi nümayəndəlik yaratmayan bölmələr və gəlir mənbələri barədə müvafiq icra hakimiyyəti orqanı tərəfindən müəyyən edilən forma üzrə məlumat.',
        33, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '33'), '33.8.5',
        'İdarəetmə yerinə görə rezident sayılan xarici hüquqi şəxs tərəfindən uçota alınma barədə verdiyi ərizəyə aşağıdakılar əlavə edilməlidir:',
        34, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '33'), '33.8.5.1',
        'qeydiyyata alındığı dövlətdə qeydiyyat (inkorporasiya) sənədi və onun təsisçisi (təsisçiləri) olan xarici hüquqi şəxsin nizamnamə kapitalında birbaşa və ya dolayı yolla paya malik fiziki şəxslər barədə məlumatın da daxil olduğu ticarət reyestrindən çıxarış;',
        35, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '33'), '33.8.5.2',
        'təsis sənədləri;',
        36, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '33'), '33.8.5.3',
        'Azərbaycan Respublikasında hüquqi ünvanını təsdiq edən sənəd (icarə müqaviləsi, mülkiyyət hüququnu təsdiq edən və ya digər sənədlər);',
        37, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '33'), '33.8.5.4',
        'hüquqi şəxsin rəhbərinin (təmsilçinin) şəxsiyyətini təsdiq edən sənədin surəti;',
        38, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '33'), '33.8.5.5',
        'Azərbaycan Respublikasında və digər ölkələrdə bilavasitə və ya dolayısı yolla nəzarətində olan qurumlar və gəlir mənbələri haqqında müvafiq icra hakimiyyəti orqanı tərəfindən müəyyən edilən forma üzrə məlumat.',
        39, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '33'), '33.8.6',
        'bu Məcəllənin 33.8.4.1-33.8.4.4-cü, 33.8.5.1-ci və 33.8.5.2-ci maddələrində göstərilən sənədlər müvafiq icra hakimiyyəti orqanı və ya Azərbaycan Respublikasının xarici dövlətlərdəki nümayəndəlikləri (Azərbaycan Respublikasının mənafeyini təmsil edən digər ölkənin konsulluq idarələri) tərəfindən leqallaşdırılır.',
        40, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '33'), '33.8.7',
        '33.8.4-cü və 33.8.5-ci maddələrdə göstərilən sənədlər Azərbaycan dilinə notariat qaydasında təsdiqlənən tərcümə ilə birgə ərizəyə əlavə edilir.',
        41, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '33'), '33.8.8',
        'Xarici dövlətin rezidentinin Azərbaycan Respublikasında fəaliyyət göstərən daimi nümayəndəlik yaratmayan bölməsinin vergi uçotundan çıxarılması və VÖEN-in ləğv edilməsi aşağıdakı hallarda həyata keçirilir:',
        42, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '33'), '33.8.8.1',
        'xarici dövlətin rezidenti olan şəxs və ya daimi nümayəndəlik yaratmayan bölmə ləğv edildikdə;',
        43, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '33'), '33.8.8.2',
        'daimi nümayəndəlik yaratmayan bölmənin fəaliyyəti daimi nümayəndəlik yaratdıqda.',
        44, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '33'), '33.8.9',
        'İdarəetmə yerinə görə rezident sayılan xarici hüquqi şəxsin vergi uçotundan çıxarılması və VÖEN-in ləğv edilməsi aşağıdakı hallarda həyata keçirilir:',
        45, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '33'), '33.8.9.1',
        'idarəetmə yerinə görə rezident sayılan xarici hüquqi şəxsin qeydiyyata alındığı (inkorporasiya) dövlətdə ləğv edildikdə;',
        46, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '33'), '33.8.9.2',
        'idarəetmə yerinə görə rezident sayılan xarici hüquqi şəxsin rezidentliyi dəyişildikdə.',
        47, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '33'), '33.8-1',
        'Rezidentlərə elektron ticarət qaydasında işlərin və xidmətlərin təqdim edilməsindən gəlir əldə edən internet informasiya ehtiyatı vasitəsilə elektron ticarəti həyata keçirən qeyri-rezidentin (bu Məcəllənin 19-cu maddəsi ilə nəzərdə tutulan daimi nümayəndəliklər istisna olmaqla) elektron qaydada vergi uçotuna alınması, yenidən uçota alınması və uçotdan çıxarılması, ƏDV-nin ödəyicisi kimi qeydiyyata alınması, ƏDV bəyannaməsinin təqdim edilməsi və ƏDV-nin ödənilməsi qaydası müvafiq icra hakimiyyəti orqanının müəyyən etdiyi orqan (qurum) tərəfindən müəyyən edilir. (33.8-1-ci maddəyə Azərbaycan Respublikasının 2026-cı il 13 fevral tarixli 355-VIIQD nömrəli Qanunu ilə edilmiş dəyişiklik 2026-cı il avqustun 23-dən qüvvəyə minir.)',
        48, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '33'), '33.9',
        'Yerli (bələdiyyə) vergilərinin ödəyicilərinin uçotu bələdiyyələrin vergi xidməti orqanı tərəfindən aparılır.',
        49, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '33'), '33.10',
        'Vergi orqanı bu Məcəlləyə uyğun olaraq vergi ödəyicilərini uçota aldıqdan sonra 1 iş günü müddətində bu barədə müvafiq icra hakimiyyəti orqanının müəyyən etdiyi orqana (quruma) elektron formada məlumat verir.',
        50, false, NOW(), NOW());

-- ============================
-- TAX ARTICLE (Maddə 34)
-- ============================
INSERT INTO tax_articles (article_number, title, chapter, active, created_at, updated_at)
VALUES ('34',
        'Uçota alınma, yenidən uçota alınma və uçotdan çıxarılma qaydaları',
        'IV fəsil. Vergi nəzarəti',
        true, NOW(), NOW());

INSERT INTO tax_sections (article_id, section_number, content, order_index, synced_to_vector_store, created_at,
                          updated_at)
VALUES ((SELECT id FROM tax_articles WHERE article_number = '34'), '34.1',
        'Vergi orqanında uçota alınmaq üçün vergi ödəyicisi (kommersiya hüquqi şəxsləri, publik hüquqi şəxslər, habelə xarici kommersiya hüquqi şəxsinin nümayəndəlik və filialları istisna olmaqla) tərəfindən ərizə verilir. Vergi ödəyicisi olan hüquqi şəxslər, onların filial və nümayəndəlikləri (kommersiya hüquqi şəxsləri, publik hüquqi şəxslər, habelə xarici kommersiya hüquqi şəxsinin nümayəndəlik və filialları istisna olmaqla) uçota alınmaq üçün ərizə ilə birgə vergi orqanına müraciət etdikdə, müəyyən edilmiş qaydada təsdiq edilmiş onların dövlət qeydiyyatına alınması haqqında şəhadətnamənin, nizamnaməsinin (və ya əsasnaməsinin), rəhbərin təyin olunmasını və hüquqi şəxsin ünvanını təsdiq edən sənədlərin, habelə rəhbərin şəxsiyyətini təsdiq edən sənədin bir nüsxədə surətlərini və olduğu yer (ünvanı) haqqında məlumat vergi orqanına təqdim etməlidirlər. Vergi ödəyiciləri olan hüquqi şəxslər (kommersiya hüquqi şəxsləri, publik hüquqi şəxslər, habelə xarici kommersiya hüquqi şəxsinin nümayəndəlik və filialları istisna olmaqla) onların yuxarı təşkilatlarına VÖEN verildikdən sonra uçota alınırlar. Ərizə vergi ödəyicisi və ya onun səlahiyyətli nümayəndəsi tərəfindən doldurulur. Ərizədə göstərilənlərin düzgünlüyünə vergi ödəyicisi (onun rəhbəri) cavabdehdir. Vergi ödəyicisi olan fərdi sahibkar uçota alınması üçün ərizə ilə birgə onun şəxsiyyətini təsdiq edən sənədin surətini və yaşadığı yer haqqında məlumat təqdim edir. Vergi ödəyiciləri olan fiziki şəxslər uçota alındıqda, onların şəxsi məlumatlarına, o cümlədən onların adı, doğulduğu tarix və yer, cinsi, yaşadığı ünvan, şəxsiyyətini təsdiq edən sənədin məlumatları, vətəndaşlığı haqqında məlumat daxil edilir. Uçota alınmaq üçün ərizənin forması müvafiq icra hakimiyyəti orqanı tərəfindən təsdiq olunur. Vergi orqanları tərəfindən fiziki şəxslərin vergi uçotuna alınması elektron və (və ya) kağız formada (uçota alınmaq üçün ərizənin poçt rabitəsi vasitəsilə göndərilməsi istisna olmaqla) aparılır. Onların uçota alınması, yenidən uçota alınması və uçotdan çıxarılması qaydaları müvafiq icra hakimiyyəti orqanı tərəfindən müəyyən edilir.',
        1, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '34'), '34.2',
        'Vergi orqanı vergi ödəyicisinin uçota alınmasını vergi uçotuna alınması haqqında ərizə və bu maddədə göstərilən digər vergi orqanına sənədlər daxil olduğu gündən sonrakı 1 gün müddətində (fiziki şəxslərin elektron formatda vergi uçotuna alınması istisna olmaqla) həyata keçirir və həmin müddətdə də vergi ödəyicisinə müvafiq şəhadətnaməni elektron formada göndərir. Fiziki şəxslərin elektron formatda vergi uçotuna alınması dərhal həyata keçirilir və müvafiq şəhadətnamə onlar üçün ayrıca yaradılmış elektron ünvana real vaxt rejimində göndərilir. Şəhadətnamə vergi ödəyicisinin uçotda olmasını təsdiq edən əsas sənəd olmaqla, vergi ödəyicisinə bir dəfə verilir və onda saxlanılır. Şəhadətnamə itirildikdə və ya yararsız hala düşdükdə vergi ödəyicisinin müraciəti əsasında şəhadətnamənin yeni nüsxəsi verilir. Bu zaman verilən nüsxənin üzərində şəhadətnamənin yeni nüsxə olması barədə müvafiq qeyd aparılır. Vergi ödəyicisinin uçota alınması haqqında şəhadətnamənin forması müvafiq icra hakimiyyəti orqanı tərəfindən təsdiq edilir.',
        2, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '34'), '34.2-1',
        'Vergi ödəyicisi tərəfindən şəhadətnamənin kağız daşıyıcıda da verilməsi ərizədə qeyd olunduğu halda müvafiq şəhadətnamə kağız daşıyıcıda da verilir.',
        3, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '34'), '34.3',
        'Vergi ödəyicisinin olduğu yer və ya yaşadığı yer dəyişdikdə, vergi orqanına bu cür dəyişiklik baş verdiyi gündən 15 gün müddətində ərizə verməlidir. Vergi ödəyicisinin vergi uçotunda olduğu vergi orqanına olduğu yer və ya yaşadığı yer dəyişdiyi barədə ərizə ilə müraciət etdiyi gündən sonra 15 gün müddətində həmin vergi orqanı vergi ödəyicisinin yenidən uçota alınmasını (yəni əvvəlki vergi orqanından uçotdan çıxarılması və yeni vergi orqanında uçota alınması) həyata keçirməlidir. Hüquqi şəxs yaratmadan sahibkarlıq fəaliyyəti ilə məşğul olan fiziki şəxs müflis elan olunduğu məqamdan və iflas prosesinə xitam verildiyi tarixdən 15 gün müddətində bu barədə vergi orqanına məlumat verməlidir. Vergi ödəyicisi vergi orqanında uçota alınmaq üçün verdiyi ərizə formasında olan məlumatlarda hər hansı dəyişiklik baş verdikdə, dəyişiklik baş verən gündən 15 gün müddətində vergi orqanına məlumat verməlidir.',
        4, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '34'), '34.3-1',
        'Vergi ödəyicisinin bir təsərrüfat subyekti (obyekti) olduqda və həmin təsərrüfat subyekti (obyekti) vergi ödəyicisinin olduğu yerdən kənarda olduqda vergi ödəyicisi həmin təsərrüfat subyektinin (obyektinin) olduğu ünvan üzrə yenidən uçota alınır. Vergi ödəyicisinin iki və daha çox təsərrüfat subyekti (obyekti) olduqda həmin vergi ödəyicisi iqtisadi maraqlar mərkəzinin yerləşdiyi ünvan üzrə yenidən uçota alınır. Vergi ödəyicisinin təsərrüfat subyekti (obyekti) üzrə yenidən uçota alınması qaydası müvafiq icra hakimiyyəti orqanının müəyyən etdiyi orqan (qurum) tərəfindən müəyyən edilir. Bu maddənin müddəaları mərkəzləşdirilmiş qaydada uçota alınan vergi ödəyicilərinə şamil edilmir.',
        5, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '34'), '34.4',
        'Hüquqi şəxsin ləğvi və ya yenidən təşkil edilməsi, hüquqi şəxs tərəfindən öz filialının və ya nümayəndəliyinin ləğv edilməsi, nümayəndəlik vasitəsi ilə fəaliyyətinin ləğvi, fərdi sahibkarın fəaliyyətinin ləğvi hallarında uçotdan çıxarılma, bu Məcəllənin 34.3-cü maddəsində göstərilən müddətlər nəzərə alınmaqla vergi ödəyicisinin müraciətinə əsasən həyata keçirilir. Vergi ödəyicisi olan fiziki şəxs uçotdan çıxarılması üçün forması müvafiq icra hakimiyyəti orqanının müəyyən etdiyi orqan (qurum) tərəfindən təsdiq edilən ərizəni elektron və (və ya) kağız formada (poçt rabitəsi vasitəsilə göndərilməsi istisna olmaqla) vergi orqanına təqdim edir. Bu Məcəllənin 33.2-ci maddəsi ilə nəzərdə tutulan hallarda hüquqi şəxs həm özünün olduğu yer üzrə, həm də onun filialının, nümayəndəliyinin və ya digər təsərrüfat subyektinin (obyektinin) olduğu yer üzrə uçota alındıqda, onun filialına, nümayəndəliyinə və ya digər təsərrüfat subyektinə (obyektinə) vergi ödəyicisinin eyniləşdirmə nömrəsi (VÖEN) verilə bilər.',
        6, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '34'), '34.5',
        'Uçota alınma, yenidən uçota alınma, uçotdan çıxarılma ödənişsiz həyata keçirilir.',
        7, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '34'), '34.6',
        'Hər bir vergi ödəyicisinə bütün vergilər üzrə, o cümlədən Azərbaycan Respublikasının gömrük sərhədindən malların keçirilməsi ilə bağlı ödənişlər üzrə Azərbaycan Respublikasının bütün ərazisində vahid olan vergi ödəyicisinin eyniləşdirmə nömrəsi (VÖEN) verilir. Vergi orqanı vergi ödəyicisinə göndərilən bütün bildirişlərdə onun eyniləşdirmə nömrəsini göstərir.',
        8, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '34'), '34.7',
        'Vergi ödəyiciləri maliyyə, statistika hesabatlarında, vergi haqq-hesablarında, bəyannamələrdə, təsərrüfat müqavilələrində, hesab-fakturalarda, qaimələrdə, nəzarət-kassa aparatlarının çeklərində, məktublarda, habelə gömrük, bank və bütün digər ödəniş sənədlərində VÖEN-i mütləq göstərməlidirlər.',
        9, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '34'), '34.7.1',
        'Vergi ödəyicilərinin hər hansı tədiyə, bank və digər ödəniş, gömrük sənədində VÖEN göstərilmədikdə, ödənişi aparan müvafiq ödəniş xidməti təchizatçıları, vergi və gömrük orqanları tərəfindən bu sənədlərin icra üçün qəbul edilməsinə yol verilmir.',
        10, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '34'), '34.7.2',
        'Vergi ödəyicilərinin uçot məlumatlarında dəyişikliklər onların müvafiq icra hakimiyyəti orqanı tərəfindən təsdiq edilmiş forma üzrə təqdim etdikləri ərizə əsasında aparılır. Vergi nəzarəti tədbiri zamanı vergi ödəyicisinin uçot məlumatlarından fərqli məlumatlar əldə olunarsa, bu barədə vergi ödəyicisinə bildiriş göndərilir. Bildiriş göndərildikdən 5 iş günü müddətində vergi ödəyicisi dəyişikliklərə dair ərizə təqdim etməzsə, uçot məlumatlarında dəyişikliklər vergi orqanı tərəfindən aparılır və bu barədə 3 iş günü müddətində vergi ödəyicisinə məlumat verilir.',
        11, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '34'), '34.7.3',
        'Vergi ödəyicisi olan fiziki şəxsin uçotdan çıxarılması aşağıdakı hallarda mümkündür:',
        12, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '34'), '34.7.3.1',
        'fəaliyyətinə xitam verildikdə;',
        13, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '34'), '34.7.3.2',
        'məhkəmə tərəfindən qanunvericiliklə müəyyən edilmiş qaydada ölmüş, itkin düşmüş və ya fəaliyyət qabiliyyətini itirmiş sayıldıqda;',
        14, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '34'), '34.7.3.3',
        'vəfat etdikdə.',
        15, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '34'), '34.7.4',
        'Vergi ödəyicisi uçotdan çıxarıldıqda, onun uçota alınmasını təsdiq edən şəhadətnamə vergi orqanına təhvil verilir. Vergi orqanı şəhadətnamə-dublikatın etibarsız hesab olunması barədə bank idarələrinə məlumat verməlidir.',
        16, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '34'), '34.8',
        'Uçot məlumatları əsasında müvafiq icra hakimiyyəti orqanı vergi ödəyicilərinin vahid dövlət reyestrini bu Məcəlləyə müvafiq olaraq aparır.',
        17, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '34'), '34.8.1',
        'Vergi ödəyiciləri vahid dövlət reyestrinə daxil edilərkən onların uçota alınması haqqında vergi orqanına təqdim etdikləri ərizədəki məlumatlardan istifadə olunur. Vahid dövlət reyestri kağız və (və ya) elektron yazıları formasında aparılmalıdır.',
        18, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '34'), '34.8.2',
        'Vergi ödəyicilərinin vahid dövlət reyestrinin aparılması aşağıdakılardan ibarətdir:',
        19, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '34'), '34.8.2.1',
        'xronoloji qaydada vergi ödəyicilərinin reyestr jurnalının aparılması;',
        20, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '34'), '34.8.2.2',
        'ləğv edilmiş vergi ödəyicilərinin reyestr jurnalının aparılması;',
        21, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '34'), '34.8.2.3',
        'uçota alınmış vergi ödəyicilərinin reyestr məlumatlarında dəyişikliklərlə bağlı dəqiqləşdirmələrin aparılması;',
        22, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '34'), '34.8.2.4',
        'uçota alınmış vergi ödəyicilərinə müvafiq məlumatın verilməsi.',
        23, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '34'), '34.8.3',
        'Müvafiq icra hakimiyyəti orqanının müəyyən etdiyi orqan (qurum) vergi ödəyicilərinin vahid dövlət reyestrinin məlumat bankının aparılmasını, onun bütövlüyünü və qorunmasını təmin edir, rəsmi sorğulara cavab olaraq bu Məcəllədə müəyyən edilmiş qaydada vahid dövlət reyestrindən çıxarışı (kommersiya hüquqi şəxslərin təsisçiləri (iştirakçıları) və onların nizamnamə kapitalındakı payları, habelə benefisiar mülkiyyətçiləri barədə məlumatlar istisna olmaqla) təqdim edir. Dövlət orqanları (qurumları), dövlət mülkiyyətində olan və paylarının (səhmlərinin) nəzarət zərfi dövlətə məxsus olan hüquqi şəxslər və dövlət adından yaradılan publik hüquqi şəxslər vergi orqanında uçota alındıqda, yenidən təşkil edildikdə və ya uçotdan çıxarıldıqda bu barədə məlumatlar (vergi ödəyicisinin adı, VÖEN-i, hesabları göstərilməklə) hər ay bitdikdən sonra növbəti ayın 15-dək həmin orqan tərəfindən elektron qaydada müvafiq icra hakimiyyəti orqanının müəyyən etdiyi orqana (quruma) təqdim olunur.',
        24, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '34'), '34.9',
        'Bu Məcəllə ilə başqa hallar nəzərdə tutulmamışdırsa, vergi ödəyicisi haqqında məlumatlar onun uçota alınması anından vergi sirrini təşkil edir.',
        25, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '34'), '34.10',
        'Vergi ödəyicisi kimi uçota alınmayan vergi agenti olan təşkilatlar bu fəsildə nəzərdə tutulmuş qaydada olduqları yer üzrə vergi orqanlarında uçota alınırlar.',
        26, false, NOW(), NOW());

-- ============================
-- TAX ARTICLE (Maddə 35)
-- ============================
INSERT INTO tax_articles (article_number, title, chapter, active, created_at, updated_at)
VALUES ('35',
        'Vergi ödəyicilərinə hesabların açılması',
        'IV fəsil. Vergi nəzarəti',
        true, NOW(), NOW());

INSERT INTO tax_sections (article_id, section_number, content, order_index, synced_to_vector_store, created_at,
                          updated_at)
VALUES ((SELECT id FROM tax_articles WHERE article_number = '35'), '35.1',
        'Vergi ödəyiciləri vergi uçotuna alındıqdan sonra hesab açmaq üçün bank və digər ödəniş hesablarını açmaq və aparmaq hüququ olan kredit və elektron pul təşkilatlarına və poçt rabitəsinin milli operatoruna (bundan sonra - bank əməliyyatları aparan şəxslərə) müraciət etdikdə bank əməliyyatları aparan şəxslər vergi ödəyicilərinə hesablar açır (qanunla hesabın açılmasından imtinaya əsas verən hallar nəzərə alınmaqla) və açılmış hesabların (qeyri-rezident üçün sahibkarlıq fəaliyyəti ilə bağlı olmayan açılmış hesablar istisna olmaqla) vergi orqanında qeydiyyata alınması üçün forması müvafiq icra hakimiyyəti orqanının müəyyən etdiyi orqan (qurum) tərəfindən təsdiq edilən məlumatı hesab açıldığı tarixdən 1 iş günü müddətində elektron qaydada vergi orqanına göndərir.',
        1, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '35'), '35.2',
        'Açılmış hesab daxil olmuş məlumat əsasında vergi orqanı tərəfindən real vaxt rejimində avtomatlaşdırılmış qaydada qeydiyyata alınır və bu barədə bank əməliyyatları aparan şəxslərə qeydiyyat bildirişi göndərilir. Qeydiyyat bildirişi daxil olanadək bank əməliyyatı aparan şəxslər tərəfindən hesab üzrə məxaric əməliyyatlarının aparılması qadağandır.',
        2, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '35'), '35.2-1',
        'Bu Məcəllənin 35.2-ci maddəsinə uyğun olaraq, qeydiyyata alınan hesab dövlət orqanlarına (qurumlarına), dövlət mülkiyyətində olan və paylarının (səhmlərinin) nəzarət zərfi dövlətə məxsus olan hüquqi şəxslərə və dövlət adından yaradılan publik hüquqi şəxslərə məxsus olduqda həmin hesablar barədə məlumatlar vergi orqanı tərəfindən müvafiq məlumat bank əməliyyatları aparan şəxslər tərəfindən vergi orqanına daxil olduğu gündən sonrakı 1 iş günü müddətində elektron qaydada müvafiq icra hakimiyyəti orqanının müəyyən etdiyi orqana (quruma) göndərilir.',
        3, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '35'), '35.3',
        'Adına hesab açılmış vergi ödəyicisinin dövlət büdcəsinə və büdcədənkənar fondlara vergilər, məcburi dövlət sosial sığorta, işsizlikdən sığorta və icbari tibbi sığorta haqları, faizlər və maliyyə sanksiyaları üzrə borcu olduğu və bu Məcəllənin 65.1-ci maddəsi ilə müəyyən edilən müddət bitdiyi halda vergi orqanı tərəfindən hesabın qeydiyyata alınmasına dair bildirişlə yanaşı eyni gündə həmin hesab üzrə bu Məcəllənin 65-ci maddəsinə uyğun olaraq sərəncam da göndərilir və bildirişdə bu barədə qeyd edilir.',
        4, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '35'), '35.4',
        'Hesab üzrə vergi orqanının sərəncamının göndəriləcəyi barədə qeyd olan hesab üzrə bank əməliyyatı aparan şəxslər tərəfindən həmin hesab üzrə vergi orqanının sərəncamı daxil olanadək sərəncamda göstərilən məbləğin 105 faizi həcmində məxaric əməliyyatlarının aparılması məhdudlaşdırılır. Bank əməliyyatlarını aparan şəxslər tərəfindən vergi orqanının sərəncamı daxil olanadək hesabdan məxarici məhdudlaşdırılan vəsaitdən artıq olan pul vəsaiti olduğu halda həmin artıq pul vəsaitinin hesabdan məxaric edilməsini nəzərdə tutan vergi ödəyicisinin ödəmə tapşırıqları icra edilir. Həmin hesaba vergi orqanının sərəncamı daxil olduqdan sonra hesab üzrə əməliyyatlar qanunla nəzərdə tutulmuş qaydalara və növbəliliyə riayət edilməklə icra edilir.',
        5, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '35'), '35.5',
        'Vergi ödəyicilərinə məxsus hesabların bank əməliyyatı aparan şəxslərin özü, filial və ya struktur bölmələri arasında köçürülməsi zamanı bank əməliyyatı aparan şəxslər köçürülən hesablar barədə müvafiq icra hakimiyyəti orqanının müəyyən etdiyi orqan (qurum) tərəfindən müəyyən edilmiş formada məlumatı hesabın köçürüldüyü tarixdən 1 iş günü müddətində elektron qaydada müvafiq icra hakimiyyəti orqanının müəyyən etdiyi orqana (quruma) göndərir.',
        6, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '35'), '35.6',
        'Vergi ödəyicilərinə məxsus hesablar bank əməliyyatı aparan şəxslər tərəfindən bağlandıqda həmin şəxslər bu barədə məlumatı hesabın bağlandığı tarixdən 1 iş günü müddətində elektron qaydada müvafiq icra hakimiyyəti orqanının müəyyən etdiyi orqana (quruma) göndərir.',
        7, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '35'), '35.7',
        'Bank əməliyyatlarını aparan şəxslər hüquqi və fiziki şəxslərə hesab açdıqda və ya maliyyə xidmətləri göstərdikdə Azərbaycan Respublikasının normativ hüquqi aktlarının, habelə vergi və maliyyə məlumatlarının mübadiləsini nəzərdə tutan Azərbaycan Respublikasının tərəfdar çıxdığı beynəlxalq müqavilələrin tələblərinə əməl edilməsini təmin edirlər.',
        8, false, NOW(), NOW());

-- ============================
-- TAX ARTICLE (Maddə 36)
-- QEYD: mənbə mətn 36.8-ci maddənin ortasında kəsilib ("...maliyyə sanksiyasının tətbiqi b").
-- Yalnız tam gələn 36.1-36.7 daxil edilib. 36.8 və sonrası ayrıca göndəriləndə əlavə olunmalıdır.
-- ============================
INSERT INTO tax_articles (article_number, title, chapter, active, created_at, updated_at)
VALUES ('36',
        'Vergi yoxlamaları, üfüqi monitorinq və maliyyə institutlarında vergi monitorinqi',
        'IV fəsil. Vergi nəzarəti',
        true, NOW(), NOW());

INSERT INTO tax_sections (article_id, section_number, content, order_index, synced_to_vector_store, created_at,
                          updated_at)
VALUES ((SELECT id FROM tax_articles WHERE article_number = '36'), '36.1',
        'Vergi orqanları tərəfindən keçirilən yoxlamalar kameral və ya səyyar ola bilər.',
        1, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '36'), '36.2',
        'Vergi yoxlamaları keçirildikdə, vergi orqanları və onların vəzifəli şəxsləri düzgün qərar qəbul edilməsi üçün əhəmiyyətli olan bütün halları, o cümlədən vergi ödəyicisi üçün əlverişli olan halları aydınlaşdırmalıdırlar.',
        2, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '36'), '36.3',
        'Bu Məcəllədə başqa hal müəyyən edilməmişdirsə, səyyar vergi yoxlaması mənfəət, gəlir, əmlak, yol və torpaq vergiləri üzrə vergi ödəyicisinin son 3 təqvim ilindən çox olmayan fəaliyyətini, digər vergilər üzrə həmin yoxlamanın keçirildiyi il də daxil olmaqla vergi ödəyicisinin son 3 ildən çox olmayan fəaliyyətini əhatə edə bilər. Vergi yoxlaması keçirildikdə, vergi orqanının vergi ödəyicisinin üçüncü şəxslərlə əlaqədar fəaliyyəti barədə vergi yoxlamasının predmetinə aid olan məlumat alması üçün sənədlərlə təsdiq edilmiş zərurət yarandığı halda, vergi orqanı həmin şəxslərdən yoxlanılan vergi ödəyicisinin fəaliyyətinə aid olan sənədlər ala bilər. Bu hərəkətlər üçün vergi orqanının əsaslandırılmış qərarı olmalıdır. Bu zaman tələb yönəldilən üçüncü şəxs və ya onun səlahiyyətli nümayəndəsi müvafiq sənədləri və ya məlumatları təsdiq edərək, tələbnaməni aldığı gündən 10 iş günü müddətində vergi orqanına təqdim etməyə borcludur.',
        3, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '36'), '36.3-1',
        'Vergi ödəyicisində keçirilən səyyar vergi yoxlaması zamanı bu maddə ilə müəyyən olunmuş müddətlər nəzərə alınmaqla yoxlamanın əhatə etdiyi dövr və (və ya) vergi növləri aşağıdakı hallarda artırıla bilər:',
        4, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '36'), '36.3-1.1',
        'vergi ödəyicisinin müraciəti əsasında;',
        5, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '36'), '36.3-1.2',
        'keçirilən səyyar vergi yoxlamasının əhatə etdiyi dövrdən sonrakı dövrdə vergidən yayınma hallarının olması barədə vergi orqanında mənbəyi bəlli məlumatlar olduqda;',
        6, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '36'), '36.3-1.3',
        'cinayət prosessual qanunvericiliyinə uyğun olaraq məhkəmənin və ya hüquq mühafizə orqanlarının vergi yoxlamalarının keçirilməsi barədə müvafiq qərarı olduqda;',
        7, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '36'), '36.3-1.4',
        'mənfəət, gəlir, əmlak və torpaq vergilərinin biri və ya bir neçəsi üzrə vergi hesabatının təqdim edilməsi müddəti səyyar vergi yoxlamasının davam etdiyi müddətdə başa çatdıqda.',
        8, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '36'), '36.4',
        'Vergi ödəyicisi olan hüquqi şəxslərin ləğvi və ya hüquqi şəxs yaratmadan sahibkarlıq fəaliyyəti göstərən fiziki şəxsin sahibkarlıq fəaliyyətinə xitam verilməsi barədə müraciəti ilə bağlı və bu Məcəllənin 38.3-cü maddəsində göstərilən hallarda keçirilən yoxlamalar istisna olmaqla, vergi orqanı tərəfindən yoxlanılmış vergi dövrü üçün vergi ödəyicisinin ödədiyi və ya ödəməli olduğu vergilər üzrə səyyar vergi yoxlamalarının keçirilməsi qadağandır.',
        9, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '36'), '36.5',
        'Vergi yoxlamasının nəticələri ilə razılaşmayan vergi ödəyiciləri növbədənkənar vergi yoxlamasının keçirilməsini tələb edə bilərlər. Bu halda növbədənkənar vergi yoxlaması vergi orqanlarının əvvəlki yoxlamanı keçirmiş vəzifəli şəxsləri tərəfindən keçirilə bilməz.',
        10, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '36'), '36.6',
        'Vergi ödəyicilərinin vergi orqanları tərəfindən həyata keçirilən vergi yoxlamaları üzrə məhkəməyə müraciət etmək hüququ vardır.',
        11, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '36'), '36.6-1',
        'Vergi orqanı üfüqi monitorinqə qəbul edilmiş vergi ödəyicilərinin fəaliyyəti üzrə bu Məcəllənin 38-1-ci maddəsində nəzərdə tutulan qaydada üfüqi monitorinq keçirir. Üfüqi monitorinqə qəbul edilən vergi ödəyicilərində monitorinqlə əhatə olunan hesabat dövrləri üzrə səyyar (bu Məcəllənin 38.3.2-ci, 38.3.5-ci, 38.3.6-cı və 38.3.10-cu maddələrində nəzərdə tutulan hallar istisna olmaqla) və kameral vergi yoxlamaları keçirilmir.',
        12, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '36'), '36.7',
        'Vergi orqanı vergi və maliyyə məlumatlarının mübadiləsini nəzərdə tutan Azərbaycan Respublikasının tərəfdar çıxdığı beynəlxalq müqavilələrin tələblərinə əməl edilməsini təmin etmək məqsədilə maliyyə institutlarında vergi monitorinqi apara bilər.',
        13, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '36'), '36.8',
        'Maliyyə institutlarında vergi monitorinqinin aparılması, nəticələrinin rəsmiləşdirilməsi, sənədlərin tələb edilməsi və materiallarına baxılmanın nəticələri üzrə qərarın çıxarılması, o cümlədən maliyyə sanksiyasının tətbiqi bu Məcəllənin 38-2-ci maddəsi ilə müəyyən edilir.',
        14, false, NOW(), NOW());

-- =========================================================
-- Maddə 37. Kameral vergi yoxlaması
-- =========================================================
INSERT INTO tax_articles (article_number, title, chapter, active, created_at, updated_at)
VALUES ('37',
        'Kameral vergi yoxlaması',
        'IV fəsil. Vergi nəzarəti',
        true, NOW(), NOW());

INSERT INTO tax_sections (article_id, section_number, content, order_index, synced_to_vector_store, created_at,
                          updated_at)
VALUES ((SELECT id FROM tax_articles WHERE article_number = '37'), '37.1',
        'Kameral vergi yoxlaması vergi orqanı tərəfindən yerlərə getmədən vergi orqanında olan, vergi ödəyicisi tərəfindən təqdim edilən vergi hesabatları, habelə vergilərin hesablanmasını və ödənilməsini özündə əks etdirən və vergi ödəyicisinin fəaliyyəti haqqında vergi orqanında olan digər sənədlər və mənbəyi məlum olan məlumatlar əsasında keçirilir.',
        1, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '37'), '37.2',
        'Kameral vergi yoxlaması vergi ödəyicisi tərəfindən bu Məcəllənin 72-ci maddəsində nəzərdə tutulmuş vergi bəyannaməsinin, habelə cari vergi ödəmələrinin hesablanması haqqında arayışın təqdim edildiyi tarixdən mənfəət və gəlir vergisi bəyannaməsinə (ödəmə mənbəyində tutulan gəlirlər üzrə bəyannamə, xüsusi notariusun və xüsusi icra məmurunun gəlir vergisi bəyannaməsi istisna olmaqla) münasibətdə 60 iş günü müddətində, digər bəyannamələrə, habelə cari vergi ödəmələrinin hesablanması haqqında arayışlara münasibətdə isə 30 iş günü müddətində keçirilir. Xaricdən əldə olunan gəlirlər üzrə xarici dövlətlərin səlahiyyətli orqanlarından müvafiq məlumatlar daxil olduğu halda kameral vergi yoxlaması bu Məcəllənin 85.4-cü maddəsində göstərilən dövr üzrə məlumatlar daxil olduğu tarixdən 90 iş günü müddətində keçirilir. Bu müddət başa çatdıqdan sonra bu maddənin birinci və ikinci cümləsində nəzərdə tutulmuş bəyannamə, cari vergi ödəmələrinin hesablanması haqqında arayış və ya xaricdən əldə olunan məlumatlar, habelə bu Məcəllənin 37.2-1-ci maddəsində göstərilən bildiriş üzrə verilmiş dəqiqləşdirilmiş bəyannamə üzrə yenidən kameral vergi yoxlaması keçirilə bilməz.',
        2, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '37'), '37.2-1',
        'Kameral vergi yoxlaması başa çatdıqdan sonra vergi orqanı verginin hesablanması üçün əlavə sənəd və ya mənbəyi məlum olan digər məlumat aşkar etdikdə, vergi ödəyicisinə 5 iş günü müddətində bu Məcəllənin 72.5-ci maddəsində nəzərdə tutulmuş dəqiqləşdirilmiş hesabatın 10 iş günü müddətində təqdim edilməsi barədə bildiriş göndərir.',
        3, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '37'), '37.3',
        'Kameral yoxlama aparmaq üçün vergi ödəyicisi tərəfindən təqdim olunmuş bəyannamə və cari vergi ödəmələrinin hesablanması haqqında arayışla bağlı sənədlərdə olan məlumatlar arasında ziddiyyət və ya səhv aşkar edildikdə, vergi orqanı vergi ödəyicisi tərəfindən əlavə məlumat, sənəd və izahat tələb edir.',
        4, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '37'), '37.4',
        'Kameral yoxlama nəticəsində vergi bəyannaməsində və ya cari vergi ödəmələrinin hesablanması haqqında arayışda vergilərin düzgün hesablanmaması (vergi məbləğinin az və ya artıq göstərilməsi) aşkar edildikdə, vergi ödəyicisinə 5 iş günü müddətində müvafiq icra hakimiyyəti orqanının müəyyən etdiyi formada vergi orqanı tərəfindən vergilərin hesablanmasına dair vergi orqanının qərarı göndərilir. Vergi orqanının qərarında hesablamanın səbəbləri və vergi ödəyicisinin bu Məcəllənin 62-ci maddəsinə uyğun olaraq şikayət etmək hüququ göstərilməlidir.

Bu maddənin birinci hissəsində göstərilən hallarda və (və ya) kameral yoxlama aparmaq üçün vergi bəyannaməsi, sənədlər və məlumatlar üzrlü əsas olmadan təqdim edilmədikdə, vergi orqanının bu Məcəllənin 67-ci maddəsinə müvafiq olaraq vergiləri hesablamaq hüququ vardır.',
        5, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '37'), '37.5',
        'Bu Məcəllənin 15.1.13-cü maddəsinə əsasən vergi ödəyicisindən xronometraj metodu ilə yeni müşahidə keçirilməsi barədə müraciət daxil olan dövrədək (vergi ödəyicisinin bu Məcəllədə nəzərdə tutulmuş qaydada fəaliyyətini dayandırdığı, xronometrajın keçirildiyi dövrü əhatə edən səyyar vergi yoxlamasının keçirildiyi hallar istisna olmaqla) xronometraj metodu ilə sonuncu müşahidənin nəticələri vergilərin hesablanması üçün əsas götürülə bilər.',
        6, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '37'), '37.6',
        'Kameral vergi yoxlaması zamanı vergi orqanı bu Məcəllənin 37.3-cü və 37.4-cü maddələrində müəyyən edilmiş qaydalara riayət etmədikdə, vergi ödəyicisinin səyyar vergi yoxlaması keçirilən zaman vergi orqanının təklifi əsasında həmin yoxlamanın keçirildiyi vaxta qədər yol verdiyi və kameral yoxlama zamanı müəyyən edilə bilən səhvləri (o cümlədən vergi məbləğlərinin düzgün hesablanmaması, vergi məbləğlərinin azaldılması və sair) 30 gün müddətində düzəltmək (aradan qaldırmaq) hüququ vardır və o, həmin müddət bitənədək, yol verdiyi vergi qanunvericiliyinin pozulmasına görə (faizlərin ödənilməsi istisna olmaqla) məsuliyyət daşımır.',
        7, false, NOW(), NOW());


-- =========================================================
-- Maddə 38. Səyyar vergi yoxlaması
-- =========================================================
INSERT INTO tax_articles (article_number, title, chapter, active, created_at, updated_at)
VALUES ('38',
        'Səyyar vergi yoxlaması',
        'IV fəsil. Vergi nəzarəti',
        true, NOW(), NOW());

INSERT INTO tax_sections (article_id, section_number, content, order_index, synced_to_vector_store, created_at,
                          updated_at)
VALUES ((SELECT id FROM tax_articles WHERE article_number = '38'), '38.1',
        'Səyyar vergi yoxlaması, o cümlədən elektron audit vergi orqanının qərarına əsasən həyata keçirilir.

Səyyar vergi yoxlaması növbəti və növbədənkənar ola bilər.

Növbəti səyyar vergi yoxlaması keçirildikdə, vergi orqanı tərəfindən vergi ödəyicisinə vergi yoxlamasının başlanmasından azı 15 gün əvvəl yazılı bildiriş göndərilir.',
        1, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '38'), '38.2',
        'Vergi ödəyicisinə göndərilən bildirişdə vergi yoxlamasının əsası və tarixi, habelə vergi ödəyicisinin və vergi orqanlarının hüquq və vəzifələri göstərilməlidir.

Növbəti səyyar vergi yoxlaması təqvim ili ərzində bir dəfədən çox olmayaraq keçirilir. Səyyar vergi yoxlaması 30 iş günündən artıq davam edə bilməz. Müstəsna hallarda, yuxarı vergi orqanının qərarına müvafiq olaraq səyyar vergi yoxlamasının keçirilməsi müddəti 90 iş gününə qədər artırıla bilər.

Aşağıda göstərilən hallarda yuxarı vergi orqanının əsaslandırılmış qərarına əsasən səyyar vergi yoxlamasının nəticələri üzrə aktın tərtibi müddəti 30 iş günündən çox olmayan müddətə uzadıla bilər:
- səyyar vergi yoxlamasının obyektiv və dolğun keçirilməsi üçün zəruri olan sənədlər, o cümlədən vergi orqanının sorğusuna cavab xarici ölkədən alındıqda;
- nümunə kimi götürülən əşyaların tədqiqi, səyyar vergi yoxlaması zamanı ekspertizanın keçirilməsi və ya mütəxəssis tərəfindən rəy verilmə üçün müxtəlif bilik sahələrindən istifadə etməklə aparıldıqda;
- səyyar vergi yoxlaması ilə əlaqədar vergi orqanları tərəfindən göndərilən sorğulara cavabların alınma müddətləri cavab göndərən şəxslər tərəfindən pozulduqda.',
        2, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '38'), '38.3',
        'Növbədənkənar vergi yoxlaması vergi orqanları tərəfindən aşağıda göstərilən hallarda keçirilə bilər:',
        3, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '38'), '38.3.1',
        'vergi ödəyicisində aparılan sonuncu vergi yoxlaması vergi ödəyicisi tərəfindən bilərəkdən hesabat sənədlərinin aparılmaması və ya qəbul edilmiş qaydalara uyğun olaraq aparılmaması, qanuni ödənilməli olan vergilərin 25 və daha çox faizinin vergidən yayındırılması hallarını aşkar etdikdə;',
        4, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '38'), '38.3.1',
        'verginin hesablanması və ödənilməsi üçün zəruri olan vergi hesabatı sənədləri müəyyən edilmiş müddətdə və bu barədə vergi orqanının xəbərdarlığından sonra da təqdim edilmədikdə;',
        5, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '38'), '38.3.2',
        'vergi yoxlamasının nəticələri üzrə tərtib edilmiş aktda dürüst olmayan və (və ya) təhrif olunmuş məlumatlar aşkar edildikdə.',
        6, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '38'), '38.3.3',
        'ƏDV üzrə artıq ödənilmiş vergi, faiz və maliyyə sanksiyası digər vergilərin, faizlərin və maliyyə sanksiyalarının ödənilməsi hesabına və ya sonrakı öhdəliklər üzrə ödəmələrin hesabına aid edildikdə. Bu halda növbədənkənar vergi yoxlaması yalnız vergi ödəyicisinin ƏDV-yə cəlb edilən əməliyyatları üzrə aparıla bilər;',
        7, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '38'), '38.3.4',
        'artıq ödənilmiş vergilərin, faizlərin və maliyyə sanksiyalarının qaytarılması barədə vergi ödəyicisinin ərizəsi daxil olduqda;',
        8, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '38'), '38.3.5',
        'vergi orqanının əldə etdiyi mənbəyi bəlli olan hər hansı məlumat əsasında vergi ödəyicisinin gəlirlərinin və ya vergitutma obyektinin gizlədilməsinin (azaldılmasının) əlamətləri müəyyən edildikdə, bu Məcəllənin 157.2-ci maddəsinə müvafiq olaraq ƏDV-nin məqsədləri üçün qeydiyyatdan keçmiş vergi ödəyicilərinin vergi hüquqpozmalarına yol verməsi barədə mənbəyi məlum olan məlumatlar olduqda;',
        9, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '38'), '38.3.6',
        'cinayət prosessual qanunvericiliyinə uyğun olaraq məhkəmənin və ya hüquq mühafizə orqanlarının vergi yoxlamalarının keçirilməsi barədə müvafiq qərarı olduqda;',
        10, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '38'), '38.3.7',
        'bu Məcəllənin 42.4-cü maddəsində göstərilən sənədlər həmin maddədə göstərilən müddətdə təqdim edilmədikdə və ya dürüst olmayan, yaxud təhrif olunmuş məlumatlar təqdim edildikdə.',
        11, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '38'), '38.3.8',
        'vergi ödəyicisi olan hüquqi şəxsin ləğv edilməsi, yenidən təşkil edilməsi və ya fiziki şəxsin hüquqi şəxs yaratmadan sahibkarlıq fəaliyyətinə xitam verilməsi barədə müraciəti olduqda;',
        12, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '38'), '38.3.8-1',
        'vergi ödəyicisi riskli vergi ödəyicisi olduğu halda;',
        13, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '38'), '38.3.9',
        'aşağıdakı hallarda bu Məcəllənin 85-ci maddəsində göstərilən müddətlərdən asılı olmayaraq, əvvəlki səyyar vergi yoxlaması ilə yoxlanılan dövr əhatə edilməklə yuxarı vergi orqanının qərarı əsasında:',
        14, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '38'), '38.3.9.1',
        'vergi yoxlamasının nəticələri ilə razılaşmayan vergi ödəyiciləri növbədənkənar səyyar vergi yoxlamasının keçirilməsini yazılı şəkildə tələb etdikdə;',
        15, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '38'), '38.3.9.2',
        'vergi ödəyicisi tərəfindən səyyar vergi yoxlaması zamanı sənədlər təqdim edilmədikdə və vergi yoxlamasının nəticələrinə görə vergi ödəyicisinin vergi qanunvericiliyinin pozulmasına görə məsuliyyətə cəlb edilməsi haqqında vergi orqanının qərarından vergi ödəyicisi tərəfindən sənədlər təqdim edilməklə yuxarı vergi orqanına şikayət verildikdə;',
        16, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '38'), '38.3.9.3',
        'vergi yoxlamasının nəticələrinə görə vergi ödəyicisinin vergi qanunvericiliyinin pozulmasına görə məsuliyyətə cəlb edilməsi haqqında vergi orqanının qərarından vergi ödəyicisi tərəfindən səyyar vergi yoxlamasının keçirilməsi zamanı təqdim edilən sənədlərdən fərqli sənədlər təqdim edilməklə yuxarı vergi orqanına şikayət verildikdə.

Vergi yoxlamasının nəticələri ilə razılaşmayan vergi ödəyiciləri növbədənkənar səyyar vergi yoxlamasının keçirilməsini yazılı şəkildə tələb etdikdə, vergi yoxlaması vergi orqanlarının əvvəlki yoxlamanı keçirmiş vəzifəli şəxsləri tərəfindən keçirilə bilməz.',
        17, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '38'), '38.3.10',
        'Üfüqi monitorinqə qəbul edilən vergi ödəyicisində transfer qiymətlərinin tətbiqi üzrə və xarici dövlətlərin səlahiyyətli orqanlarından sorğu və xaricdən əldə olunan gəlirlər üzrə müvafiq məlumatlar daxil olduğu halda vergilərin hesablanması zamanı. Bu halda növbədənkənar səyyar vergi yoxlaması yalnız transfer qiymətlərinin tətbiqi və xarici dövlətlərin səlahiyyətli orqanlarından daxil olmuş sorğu və ya xaricdə əldə olunan gəlirlər üzrə müvafiq məlumatlarla əhatə edilən əməliyyatlar üzrə aparıla bilər.',
        18, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '38'), '38.4',
        'Səyyar vergi yoxlaması iş günü və vergi ödəyicisinin iş vaxtı ərzində keçirilir.',
        19, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '38'), '38.5',
        'İnventarizasiya səyyar vergi yoxlaması zamanı aşağıda göstərilən hallarda vergi orqanının əsaslandırılmış qərarı ilə aparılır:',
        20, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '38'), '38.5.1',
        'vergi ödəyicisində sonuncu vergi yoxlaması zamanı vergi ödəyicisi tərəfindən bilərəkdən hesabat sənədlərinin aparılmaması aşkar edildikdə;',
        21, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '38'), '38.5.2',
        'vergi ödəyicisində sonuncu vergi yoxlaması zamanı vergi ödəyicisi tərəfindən qanunvericiliklə müəyyən edilmiş qaydalara uyğun olaraq hesabat sənədlərinin aparılmaması aşkar edildikdə və bununla əlaqədar vergi orqanının xəbərdarlığından sonra yol verilmiş dəqiqsizliklər aradan qaldırılmadıqda və hesabat müəyyən edilmiş qaydalara uyğun olaraq aparılmadıqda;',
        22, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '38'), '38.5.3',
        'vergi ödəyicisində səyyar vergi yoxlaması zamanı aksiz markaları ilə markalanmalı olan, ancaq markalanmamış, məcburi nişanlama ilə nişanlanmalı olan, ancaq nişanlanmamış mallar, habelə markalanmalı olan, lakin markalanmamış dini təyinatlı ədəbiyyat (kağız və elektron daşıyıcılarında), audio və videomateriallar, mal və məmulatlar və dini məzmunlu başqa məlumat materialları aşkar edildikdə;',
        23, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '38'), '38.5.4',
        'vergi ödəyicisində əmlak vergisinin hesablanmasının və ödənilməsinin düzgünlüyü yoxlanıldıqda.',
        24, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '38'), '38.6',
        'Səyyar vergi yoxlaması zamanı inventarizasiyanın aparılması qaydaları müvafiq icra hakimiyyəti orqanı tərəfindən müəyyən edilir.',
        25, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '38'), '38.7',
        'Yoxlama barədə qərar qəbul etmiş vergi orqanının əsaslandırılmış qərarına əsasən növbəti və ya növbədənkənar səyyar vergi yoxlaması aşağıda göstərilən hallarda və müddətlərdə, lakin 9 aydan çox olmamaqla dayandırılır (təxirə salınır):',
        26, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '38'), '38.7.1',
        'vergi ödəyicisində aparılan səyyar vergi yoxlaması zamanı şəxs vergi orqanında qeydiyyatda olan ünvanlarda olmadıqda və ya şəxsin olduğu yerin müəyyən edilməsi və digər səbəblərdən tapılması mümkün olmadıqda - həmin şəxsin olduğu yer müəyyən olunana qədər;',
        27, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '38'), '38.7.2',
        'səyyar vergi yoxlaması aparılan vergi ödəyicisinin rəhbəri (onu əvəz edən şəxs və ya vergi və ya maliyyə məsələləri üzrə məsul şəxs) və ya fərdi sahibkar müvəqqəti olaraq əmək qabiliyyətini itirdikdə - əmək qabiliyyəti bərpa olunanadək;',
        28, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '38'), '38.7.3',
        'vergi orqanının təşəbbüsü ilə mütəxəssis dəvət edildikdə və ya ekspertiza keçirildikdə - mütəxəssisin və ya ekspertin rəyi yoxlamaya təqdim edilənədək;',
        29, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '38'), '38.7.4',
        'səyyar vergi yoxlamasının obyektiv və dolğun keçirilməsi üçün zəruri olan sənədlər, o cümlədən vergi orqanının sorğusuna cavab xarici ölkədən alındıqda -xarici ölkədən cavab alınanadək;',
        30, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '38'), '38.7.4-1',
        'vergi ödəyicisində aparılan səyyar vergi yoxlaması ilə əlaqədar olaraq müvafiq məlumatın və ya sənədlərin əldə edilməsi məqsədilə, Azərbaycan Respublikasının tərəfdar çıxdığı beynəlxalq müqavilələr çərçivəsində vergi orqanının nümayəndəsinin xarici dövlətin ərazisində vergi yoxlamasında iştirak etməsilə bağlı xarici ölkənin səlahiyyətli orqanına müraciət edildikdə - xarici dövlətdə aparılan yoxlama yekunlaşanadək.',
        31, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '38'), '38.7.5',
        'bu Məcəllənin 43.11-ci maddəsi ilə müəyyən edilmiş hallarda - məhkəmənin qərarı qanuni qüvvəyə minənədək.',
        32, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '38'), '38.8',
        'Elektron auditin aparılması qaydaları müvafiq icra hakimiyyəti orqanı tərəfindən müəyyən edilir.',
        33, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '38'), '38.9',
        'Azərbaycan Respublikasının tərəfdar çıxdığı beynəlxalq müqavilələrdə nəzərdə tutulmuş hallarda xarici dövlətlərin (ərazilərin) səlahiyyətli orqanının nümayəndəsi Azərbaycanda və ya Azərbaycan Respublikasının vergi orqanının səlahiyyətli nümayəndəsi həmin xarici dövlətdə (ərazidə) fəaliyyət göstərən vergi ödəyicisində keçirilən səyyar vergi yoxlamalarında iştirak edə bilər.',
        34, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '38'), '38.10',
        'Xarici dövlətin (ərazinin) səlahiyyətli orqanının nümayəndələrinin Azərbaycan Respublikasının ərazisində səyyar vergi yoxlamasında iştirakının təşkili qaydası müvafiq icra hakimiyyəti orqanının müəyyən etdiyi orqan (qurum) tərəfindən təsdiq edilir.',
        35, false, NOW(), NOW());


-- =========================================================
-- Maddə 38-1. Üfüqi monitorinq
-- =========================================================
INSERT INTO tax_articles (article_number, title, chapter, active, created_at, updated_at)
VALUES ('38-1',
        'Üfüqi monitorinq',
        'IV fəsil. Vergi nəzarəti',
        true, NOW(), NOW());

INSERT INTO tax_sections (article_id, section_number, content, order_index, synced_to_vector_store, created_at,
                          updated_at)
VALUES ((SELECT id FROM tax_articles WHERE article_number = '38-1'), '38-1.1',
        'Üfüqi monitorinq bu Məcəllə və onun əsasında qəbul edilmiş digər normativ hüquqi aktlar üzrə həyata keçirilir. Üfüqi monitorinqin predmeti vergilərin bu Məcəlləyə uyğun olaraq düzgün hesablanmasına, tam və vaxtında ödənilməsinə nəzarətdən ibarətdir. Transfer qiymətlərinin tətbiqi və xarici dövlətlərin səlahiyyətli orqanlarından sorğu və xaricdən əldə olunan gəlirlər üzrə müvafiq məlumatların araşdırılması digər vergi nəzarəti tədbirləri ilə aparılır və üfüqi monitorinqlə əhatə edilmir.',
        1, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '38-1'), '38-1.2',
        'Üfüqi monitorinqin əhatə etdiyi dövr təqvim ili hesab olunur və başladığı tarixdən əvvəlki bir təqvim ilini əhatə edir. Üfüqi monitorinq bu Məcəllənin 38-1.7-ci maddəsində göstərilən vaxtda başlayır və 6 aydan gec olmayaraq başa çatır. Əlavə araşdırma tələb edildiyi halda üfüqi monitorinqin keçirilməsi müddəti vergi orqanının qərarına əsasən iki aya qədər uzadıla bilər.',
        2, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '38-1'), '38-1.3',
        'Bu Məcəllənin 38-1.4-cü maddəsinin müddəaları nəzərə alınmaqla üfüqi monitorinqə qəbul edilmək üçün ərizənin verildiyi tarixə aşağıdakı bütün şərtlərə cavab verən vergi ödəyiciləri üfüqi monitorinqə qəbul edilə bilərlər:',
        3, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '38-1'), '38-1.3.1',
        'vergi ödəyicisi orta və iri sahibkarlıq subyektidirsə;',
        4, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '38-1'), '38-1.3.2',
        'vergi ödəyicisi mühasibat və vergi uçotunu mühasibat və (və ya) vergi uçotunun avtomatlaşdırılması üçün nəzərdə tutulmuş proqram təminatından istifadə etməklə aparırsa;',
        5, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '38-1'), '38-1.3.3',
        'vergi ödəyicisi bu Məcəllənin 38-1.10.2-ci maddəsinin tələblərinə uyğun olaraq daxili nəzarət sistemini tətbiq edirsə.',
        6, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '38-1'), '38-1.4',
        'Barəsində riskli vergi ödəyicisi olmasına dair qərar qüvvədə olduqda, habelə vergi qanunvericiliyinin pozulması ilə bağlı cinayət işi qaldırıldıqda vergi ödəyicisi üfüqi monitorinqə qəbul edilə bilməz.',
        7, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '38-1'), '38-1.5',
        'Üfüqi monitorinqə qəbul edilmək üçün müraciət edən vergi ödəyicisi üfüqi monitorinqin aparılacağı dövrdən əvvəlki ilin sentyabr ayının 1-dən gec olmayaraq forması və doldurulma qaydası müvafiq icra hakimiyyəti orqanının müəyyən etdiyi orqan (qurum) tərəfindən təsdiq edilən ərizə və aşağıdakı sənədlərlə (məlumatlarla) birlikdə vergi orqanına müraciət edir:',
        8, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '38-1'), '38-1.5.1',
        'bu Məcəllənin 38-1.10.1-ci maddəsinə əsasən təsdiq edilmiş inzibati reqlamentə uyğun olaraq vergilərin hesablanması və ödənilməsi ilə bağlı sənədlər və məlumatlar;',
        9, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '38-1'), '38-1.5.2',
        'bu Məcəllənin 38-1.10.2-ci maddəsinə uyğun olaraq qurulmuş daxili nəzarət sistemi, mümkün vergi riskləri və həmin risklərə nəzarət proseduru barədə sənədlər.',
        10, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '38-1'), '38-1.6',
        'Üfüqi monitorinqə qəbul edilmə barədə ərizənin və ona əlavə edilmiş sənədlərin bu Məcəllənin 38-1.3-cü maddəsində nəzərdə tutulmuş şərtlərə uyğunluğuna vergi orqanı tərəfindən 2 ay müddətində baxılır və baxılmanın nəticəsi üzrə vergi ödəyicisinin üfüqi monitorinqə qəbul edilməsi və ya üfüqi monitorinqə qəbul edilməsindən imtina edilməsi barədə əsaslandırılmış qərar qəbul edilir. Vergi ödəyicisinin üfüqi monitorinqə qəbul edilməsi barədə qərar bir dəfə qəbul edilir və növbəti illər ərzində də qüvvədə qalır (vergi ödəyicisi bu Məcəllənin 38-1.12-ci maddəsinə uyğun olaraq üfüqi monitorinqdən çıxarılmadığı halda).',
        11, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '38-1'), '38-1.7',
        'Üfüqi monitorinqə qəbul edilməsi barədə qərar çıxarılmış vergi ödəyicisi bu Məcəllədə nəzərdə tutulmuş müddətdə mənfəət və gəlir vergisi bəyannaməsinin verilməsinin son tarixindən (hesabatın təqdim edilməsi müddətinin uzadılması nəzərə alınmaqla) 30 gün ərzində monitorinqin aparılması üçün tələb olunan sənədləri və məlumatları vergi orqanına təqdim edir. Bu maddədə nəzərdə tutulmuş müddət başa çatdıqdan sonra növbəti gün vergi orqanı tərəfindən üfüqi monitorinqin başlanması barədə qərar qəbul edilir.',
        12, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '38-1'), '38-1.8',
        'Bu Məcəllənin 38-1.5-ci maddəsində nəzərdə tutulmuş sənədlər və məlumatlar həmin maddədə müəyyən edilmiş müddətdə təqdim edilmədikdə və ya təqdim edilmiş sənədlərdə və məlumatlarda çatışmazlıqlar olduqda, vergi orqanı həmin sənədlərin və məlumatların, onlar vergi ödəyicisində olmadıqda isə bu barədə izahatın təqdim edilməsi üçün vergi ödəyicisinə 5 iş günü ərzində elektron qaydada sorğu göndərir. Sorğu göndərildikdən sonra 15 gün ərzində tələb edilən sənədlər və məlumatlar vergi orqanına təqdim edilməlidir.',
        13, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '38-1'), '38-1.9',
        'Üfüqi monitorinqin başlama tarixindən 15 gün ərzində vergi ödəyicisi dəqiqləşdirilmiş vergi bəyannamələrini təqdim edə bilər.',
        14, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '38-1'), '38-1.10',
        'Üfüqi monitorinqə qəbul edilən vergi ödəyicisinin aşağıdakı vəzifələri vardır:',
        15, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '38-1'), '38-1.10.1',
        'müvafiq icra hakimiyyəti orqanının müəyyən etdiyi orqanın (qurumun) təsdiq etdiyi inzibati reqlamentə uyğun olaraq vergilərin hesablanması və ödənilməsi ilə bağlı sənədləri və məlumatları bu məqsədlə yaratdığı məlumat mübadiləsi platformasında yerləşdirmək və vergi orqanının həmin platformaya çıxışını təmin etmək;',
        16, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '38-1'), '38-1.10.2',
        'müvafiq icra hakimiyyəti orqanının müəyyən etdiyi orqanın (qurumun) təsdiq etdiyi qaydalara uyğun daxili nəzarət sistemini qurmaq və mümkün vergi riskləri barədə məlumatı və həmin risklərə nəzarət prosedurunu vergi orqanına təqdim etmək.',
        17, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '38-1'), '38-1.11',
        'Üfüqi monitorinqin nəticələrinin rəsmiləşdirilməsi, üfüqi monitorinq zamanı vergi nəzarətini həyata keçirən vergi orqanının vəzifəli şəxsləri tərəfindən öz səlahiyyətləri çərçivəsində vergi ödəyicilərinin ərazilərinə və ya binalarına (yaşayış binaları (sahələri) istisna olmaqla) daxil olması, ərazilərinə, binalarına (yaşayış binaları (sahələri) istisna olmaqla), habelə sənədlərinə və əşyalarına baxış keçirilməsi, nümunə kimi əşyaların götürülməsi, ekspert cəlb edilməsi, mütəxəssis, tərcüməçi və müşahidəçi dəvət edilməsi və inventarizasiya aparılması bu Məcəllənin 38.5-ci, 38.6-cı, 39 - 41-ci və 43 - 48-ci maddələri ilə müəyyən edilmiş qaydada həyata keçirilir.',
        18, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '38-1'), '38-1.12',
        'Üfüqi monitorinqin keçirilməsi aşağıdakı hallarda dayandırılır və vergi ödəyicisi üfüqi monitorinqdən çıxarılır:',
        19, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '38-1'), '38-1.12.1',
        'vergi ödəyicisi tərəfindən üfüqi monitorinqdə iştirakın dayandırılması barədə ərizə təqdim edildikdə (bu halda vergi ödəyicisi 3 iş günü ərzində üfüqi monitorinqdən çıxarılır);',
        20, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '38-1'), '38-1.12.2',
        'sənədlərin və məlumatların təqdim edilməsinə dair vergi orqanının tələbləri ardıcıl iki dəfə pozulduqda;',
        21, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '38-1'), '38-1.12.3',
        'bu Məcəllənin 38.3.6-cı maddəsinə uyğun olaraq növbədənkənar səyyar vergi yoxlamasının keçirilməsi haqqında qərar çıxarıldıqda;',
        22, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '38-1'), '38-1.12.4',
        'vergi ödəyicisi bu Məcəllənin 38-1.10.2-ci maddəsinin tələblərinə uyğun olaraq mümkün vergi riskləri barədə məlumatı açıqlamamışdırsa vergi ödəyicisində üfüqi monitorinqlə əhatə olunan dövr üzrə bu Məcəllənin 38.3.5-ci maddəsinə uyğun olaraq növbədənkənar səyyar vergi yoxlamasının keçirilməsi haqqında qərar çıxarıldıqda və ya üfüqi monitorinqlə əhatə olunmayan dövr üzrə keçirilən səyyar vergi yoxlaması zamanı bu Məcəllənin 36.3-1.2-ci maddəsində göstərilən hal üzrə yoxlamanın əhatə etdiyi dövr artırıldıqda (üfüqi monitorinqlə əhatə olunan dövr daxil olmaqla);',
        23, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '38-1'), '38-1.12.5',
        'vergi ödəyicisinin riskli vergi ödəyicisi olması barədə qərar qəbul edildikdə, habelə vergi ödəyicisinə münasibətdə vergi qanunvericiliyinin pozulması ilə bağlı cinayət işi qaldırıldıqda.',
        24, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '38-1'), '38-1.13',
        'Üfüqi monitorinq başa çatdıqdan sonra onun nəticələri üzrə vergi orqanının rəhbəri (onun müavini) 10 gün müddətində aşağıda göstərilən qərarlardan birini çıxarır:',
        25, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '38-1'), '38-1.13.1',
        'vergi ödəyicisinin vergi qanunvericiliyinin pozulmasına görə məsuliyyətə cəlb edilməsi;',
        26, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '38-1'), '38-1.13.2',
        'vergi ödəyicisinin vergi qanunvericiliyinin pozulmasına görə məsuliyyətə cəlb edilməsindən imtina olunması.',
        27, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '38-1'), '38-1.14',
        'Bu Məcəllənin 38-1.15-ci maddəsində nəzərdə tutulan hal istisna olmaqla, üfüqi monitorinq aparılan vergi ödəyicisində vergitutma bazasının azaldılması və ya verginin düzgün hesablanmaması aşkar edildikdə, vergi orqanının qərarı ilə bu Məcəllənin 58.1-1-ci maddəsinə əsasən maliyyə sanksiyası tətbiq edilir.',
        28, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '38-1'), '38-1.15',
        'Vergi ödəyicisi üfüqi monitorinqlə aşkar olunmuş kənarlaşmalar barədə məlumatı üfüqi monitorinqin başlanmasına qədər bu Məcəllənin 38-1.10.2-ci maddəsinin tələblərinə uyğun olaraq daxili nəzarət sistemi tətbiq etməklə müvafiq formada açıqlamışdırsa üfüqi monitorinq keçirilən vergi ödəyicilərinə vergitutma bazasının azaldılması və ya verginin düzgün hesablanmamasına görə maliyyə sanksiyası tətbiq edilmir.',
        29, false, NOW(), NOW());


-- =========================================================
-- Maddə 39. Səyyar vergi yoxlamasının nəticələrinin rəsmiləşdirilməsi
-- =========================================================
INSERT INTO tax_articles (article_number, title, chapter, active, created_at, updated_at)
VALUES ('39',
        'Səyyar vergi yoxlamasının nəticələrinin rəsmiləşdirilməsi',
        'IV fəsil. Vergi nəzarəti',
        true, NOW(), NOW());

INSERT INTO tax_sections (article_id, section_number, content, order_index, synced_to_vector_store, created_at,
                          updated_at)
VALUES ((SELECT id FROM tax_articles WHERE article_number = '39'), '39.1',
        'Səyyar vergi yoxlamasının nəticələri üzrə vergi orqanlarının səlahiyyətli vəzifəli şəxsləri tərəfindən müəyyən edilmiş formada vergi yoxlaması aktı tərtib edilir və həmin şəxslər və yoxlanılan vergi ödəyicisinin rəhbəri (onu əvəz edən şəxs) və ya fərdi sahibkar tərəfindən imzalanır. Vergi ödəyicisi yoxlama aktında öz qeydlərini edə bilər, aktı imzalamaqdan imtina edə bilər və bu barədə həmin aktda müvafiq qeyd aparılır.',
        1, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '39'), '39.2',
        'Vergi yoxlaması aktında yoxlama zamanı aşkar olunmuş və sənədlərlə təsdiq edilmiş vergi qanunvericiliyinin pozulması halları və həmin pozuntulara görə məsuliyyət nəzərdə tutan bu Məcəllənin və digər qanunların konkret maddələri, yaxud vergi qanunvericiliyinin pozulması hallarının olmaması göstərilməlidir.',
        2, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '39'), '39.3',
        'Vergi yoxlaması aktının forması və onun tərtib edilməsinə dair tələblər müvafiq icra hakimiyyəti orqanı tərəfindən müəyyən edilir.',
        3, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '39'), '39.4',
        'Vergi yoxlaması aktının bir nüsxəsi vergi ödəyicisinə (onun səlahiyyətli nümayəndəsinə) verilmə tarixini təsdiq edən üsulla aktın tərtib edildiyi tarixdən sonra 5 gündən gec olmayaraq verilir və ya göndərilir.',
        4, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '39'), '39.5',
        'Vergi ödəyicisi vergi yoxlaması aktı ilə və ya onun hər hansı bir hissəsi ilə razılaşmadıqda, vergi yoxlaması aktının verilməsi günündən 30 gün müddətində müvafiq vergi orqanına aktı imzalamamasının səbəblərini izah edə, yaxud akta və ya onun ayrı-ayrı hissələrinə öz etirazını yazılı surətdə bildirə bilər. Bu halda vergi ödəyicisinin yoxlama aktını imzalamamasını və ya etirazını ona öz yazılı izahatını (etirazını) təsdiq edən sənədlərin surətini əlavə edərək vergi orqanına təqdim etməyə hüququ vardır.',
        5, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '39'), '39.6',
        'Bu Məcəllənin 39.5-ci maddəsində müəyyən edilən müddət bitdikdən sonra 15 gündən çox olmayan müddətdə vergi orqanının rəhbəri (onun müavini) vergi ödəyicisindən bu Məcəllə ilə müəyyən edilmiş qaydada götürülmüş, habelə vergi ödəyicisi tərəfindən təqdim edilmiş sənədlərə və vergi yoxlaması aktına, vergi qanunvericiliyinin pozulması hallarına və onların aradan qaldırılması və müvafiq sanksiyaların (cərimələrin) tətbiq edilməsi məsələsinə baxır.',
        6, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '39'), '39.7',
        'Vergi ödəyicisi tərəfindən vergi yoxlaması aktı üzrə yazılı izahatlar və ya etirazlar təqdim edildikdə, yoxlamanın materialları vergi ödəyicisinin vəzifəli şəxslərinin və ya fərdi sahibkarın və (və ya) onların nümayəndələrinin iştirakı ilə baxılır.

Vergi orqanı vergi yoxlamasının materiallarına baxılmanın yeri və vaxtı haqqında vergi ödəyicisinə əvvəlcədən məlumat verir. Vergi ödəyicisi ona əvvəlcədən məlumat verilməsinə baxmayaraq üzürlü səbəb olmadan gəlməyibsə, yoxlamanın materiallarına, vergi ödəyicisi tərəfindən təqdim edilən etirazlara, izahatlara, digər sənəd və materiallara onun iştirakı olmadan baxılır.',
        7, false, NOW(), NOW());


-- =========================================================
-- Maddə 40. Səyyar vergi yoxlamasının keçirilməsi üçün vergi orqanlarının
-- vəzifəli şəxslərinin ərazilərə və ya binalara daxil olması
-- =========================================================
INSERT INTO tax_articles (article_number, title, chapter, active, created_at, updated_at)
VALUES ('40',
        'Səyyar vergi yoxlamasının keçirilməsi üçün vergi orqanlarının vəzifəli şəxslərinin ərazilərə və ya binalara daxil olması',
        'IV fəsil. Vergi nəzarəti',
        true, NOW(), NOW());

INSERT INTO tax_sections (article_id, section_number, content, order_index, synced_to_vector_store, created_at,
                          updated_at)
VALUES ((SELECT id FROM tax_articles WHERE article_number = '40'), '40.1',
        'Səyyar vergi yoxlaması keçirən vergi orqanının vəzifəli şəxslərinin vergi ödəyicisinin sahibkarlıq fəaliyyətini həyata keçirmək üçün istifadə etdiyi ərazisinə və ya binasına (yaşayış binaları (sahələri) istisna olmaqla) bilavasitə daxil olması həmin şəxslər tərəfindən öz xidməti vəsiqələrini və vergi orqanının rəhbərinin (onun müavininin) həmin vergi ödəyicisində səyyar vergi yoxlamasının keçirilməsi haqqında qərarını və ya məhkəmənin qərarını təqdim etdikdən sonra həyata keçirilir.',
        1, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '40'), '40.2',
        'Vergi yoxlamasını bilavasitə həyata keçirən vergi orqanlarının vəzifəli şəxslərinin yaşayış binalarına (sahələrinə) orada yaşayan fiziki şəxslərin iradəsindən kənar və ya onların iradəsinə zidd olaraq daxil olmasına yol verilmir.',
        2, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '40'), '40.3',
        'Bilavasitə səyyar vergi yoxlamasını keçirən vergi orqanının vəzifəli şəxslərinə bu Məcəllənin 40.1-ci maddəsində göstərilən ərazilərə və ya binalara (yaşayış binaları (sahələri) istisna olmaqla) daxil olmağa icazə verilmədikdə, yoxlamanı keçirən vergi orqanının vəzifəli şəxsləri və vergi ödəyicisi tərəfindən imzalanan akt tərtib edilir. Həmin akta əsasən vergi orqanının ödənilməli olan vergi məbləğlərini bu Məcəllənin 67-ci maddəsi ilə nəzərdə tutulmuş qaydada müəyyən etmək hüququ vardır.

Vergi ödəyicisi həmin aktı imzalamaqdan imtina etdikdə, bu barədə aktda qeyd edilir. Tərtib olunmuş aktın surəti vergi ödəyicisinə verilir.',
        3, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '40'), '40.4',
        'Səyyar vergi yoxlamasını bilavasitə keçirən vergi orqanlarının vəzifəli şəxslərinin vergi ödəyicisinin sahibkarlıq fəaliyyətini həyata keçirmək üçün istifadə etdiyi ərazisinə və ya binasına (yaşayış binaları (sahələri) istisna olmaqla) daxil olmasına qeyri-qanuni maneçilik vergi qanunvericiliyinin pozulması hesab olunur və qanunla müəyyən edilmiş qaydada məsuliyyətə səbəb olur.',
        4, false, NOW(), NOW());


-- =========================================================
-- Maddə 41. Baxış protokolu
-- =========================================================
INSERT INTO tax_articles (article_number, title, chapter, active, created_at, updated_at)
VALUES ('41',
        'Baxış protokolu',
        'IV fəsil. Vergi nəzarəti',
        true, NOW(), NOW());

INSERT INTO tax_sections (article_id, section_number, content, order_index, synced_to_vector_store, created_at,
                          updated_at)
VALUES ((SELECT id FROM tax_articles WHERE article_number = '41'), '41.1',
        'Vergi nəzarəti tədbirləri ilə əlaqədar vergi ödəyicisinin ərazilərinə, binalarına, nəqliyyat vasitələrinə, habelə sənədlərinə və əşyalarına baxış keçirilərkən aşkar olunmuş pozuntular protokolla rəsmiləşdirilir və bu zaman foto və (və ya) video çəkilişdən istifadə olunur.',
        1, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '41'), '41.2',
        'Bu Məcəllənin 41.1-ci maddəsi ilə müəyyən edilmiş foto və (və ya) video çəkilişin nəticələri vergi ödəyicisi tərəfindən vergi qanunvericiliyinin pozulması hallarının sübut edilməsi məqsədilə məhkəmə və ya inzibati icraat çərçivəsində istifadə edilir. Foto və (və ya) video çəkilişin nəticələri üçüncü şəxslərə yalnız vergi ödəyicisinin yazılı razılığı əsasında açıqlana bilər.',
        2, false, NOW(), NOW());


-- =========================================================
-- Maddə 42. Sənədlərin tələb edilməsi
-- =========================================================
INSERT INTO tax_articles (article_number, title, chapter, active, created_at, updated_at)
VALUES ('42',
        'Sənədlərin tələb edilməsi',
        'IV fəsil. Vergi nəzarəti',
        true, NOW(), NOW());

INSERT INTO tax_sections (article_id, section_number, content, order_index, synced_to_vector_store, created_at,
                          updated_at)
VALUES ((SELECT id FROM tax_articles WHERE article_number = '42'), '42.1',
        'Səyyar vergi yoxlamasını keçirən vergi orqanının vəzifəli şəxsi bu Məcəllənin 38.1-ci maddəsinə uyğun olaraq vergi ödəyicisinə göndərdiyi bildirişlə birlikdə yoxlama üçün zəruri olan sənədləri, habelə elektron faylları vergi ödəyicisindən bu Məcəllə ilə müəyyən edilmiş qaydada tələb edə bilər. Sənədlərin və ya elektron faylların verilməsi barəsində tələb yönəldilən şəxs həmin sənədləri və ya elektron faylları 15 iş günü müddətində vergi orqanına təqdim etməlidir.

Vergi ödəyicisi tərəfindən vergilərin hesablanmasına təsir edən və yoxlama dövründə təqdim edilən sənədlərdən fərqli sənədlər əlavə vergi yoxlamasının təyin edildiyi tarixdən 30 iş günü müddətində təqdim edilməlidir.

Operativ vergi nəzarəti tədbirlərinin keçirilməsi zamanı sənədlərin və ya elektron faylların verilməsi barədə tələb yönəldilən şəxs həmin sənədləri və ya elektron faylları 1 iş günü ərzində təqdim etməlidir.

Sənədlərin lazımi qaydada təsdiq edilmiş surətləri təqdim edilir.',
        1, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '42'), '42.2',
        'Səyyar vergi yoxlamasını bilavasitə həyata keçirən vergi orqanının vəzifəli şəxsinə tələb olunan sənədlər vergi ödəyicisi tərəfindən bu Məcəllənin 42.1-ci maddəsinin ikinci və üçüncü hissəsində göstərilən müddətdə təqdim edilmədikdə və ya həmin sənədlərin və ya elektron faylların onda olmaması vergi ödəyicisi tərəfindən bildirildikdə, yoxlamanı həyata keçirən vergi orqanının vəzifəli şəxsləri və vergi ödəyicisi tərəfindən imzalanan akt tərtib edilir. Vergi ödəyicisi həmin aktı imzalamaqdan imtina etdikdə, bu barədə aktda qeyd edilir. Tərtib olunmuş aktın surəti vergi ödəyicisinə verilir. Tələb olunan sənədləri və ya surətlərini səyyar vergi yoxlamasının keçirildiyi müddətdə digər mənbələrdən əldə etmək mümkün olmadıqda, həmin akta əsasən vergi orqanının ödənilməli olan vergi məbləğlərini bu Məcəllənin 67-ci maddəsi ilə nəzərdə tutulmuş qaydada müəyyən etmək hüququ vardır.',
        2, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '42'), '42.3',
        'Səyyar vergi yoxlaması üçün zəruri olan vergi orqanı tərəfindən tələb edilən sənədlərin və ya elektron faylların vergi ödəyicisi tərəfindən vergi orqanına verilməsindən imtina edilməsi və ya bu Məcəllənin 42.1-ci maddəsində göstərilən müddətdə təqdim edilməməsi qanunla müəyyən edilmiş qaydada məsuliyyətə səbəb olur. Bu maddədə göstərilən qaydada sənədlərin və ya elektron faylların təqdim edilməsindən imtina edildikdə, səyyar vergi yoxlamasını həyata keçirən vergi orqanının vəzifəli şəxsi bu Məcəllənin 43-cü maddəsində nəzərdə tutulmuş qaydada sənədlərin götürülməsini həyata keçirə bilər.',
        3, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '42'), '42.4',
        'Vergi nəzarətinin həyata keçirilməsi və Azərbaycan Respublikasının tərəfdar çıxdığı beynəlxalq müqavilələrə əsasən daxil olmuş sorğuların icrası ilə bağlı zəruri olan sənədlər və ya onların lazımi qaydada təsdiq edilmiş surətləri vergi orqanının müraciətinə əsasən 10 iş günü müddətində təqdim edilməlidir.',
        4, false, NOW(), NOW());


-- =========================================================
-- Maddə 43. Sənədlərin və nümunə kimi əşyaların götürülməsi
-- =========================================================
INSERT INTO tax_articles (article_number, title, chapter, active, created_at, updated_at)
VALUES ('43',
        'Sənədlərin və nümunə kimi əşyaların götürülməsi',
        'IV fəsil. Vergi nəzarəti',
        true, NOW(), NOW());

INSERT INTO tax_sections (article_id, section_number, content, order_index, synced_to_vector_store, created_at,
                          updated_at)
VALUES ((SELECT id FROM tax_articles WHERE article_number = '43'), '43.1',
        'Sənədlərin və nümunə kimi əşyaların götürülməsinə səyyar vergi yoxlaması və operativ vergi nəzarəti keçirildikdə yol verilir.',
        1, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '43'), '43.2',
        'Səyyar vergi yoxlaması keçirildikdə yoxlamanın predmetinə aid olan və vergilərin hesablanması üçün tələb olunan vergi ödəyicisi tərəfindən təqdim olunan sənədlərin və əşyaların öyrənilməsinə əlavə vaxt tələb olunduğu halda, həmçinin təqdim olunmuş sənədlərdə vergi qanunvericiliyinin pozulması halları müəyyən edildikdə və ya bu pozuntular bilavasitə əşyalarla bağlı olduqda, səyyar vergi yoxlamasını bilavasitə həyata keçirən vergi orqanının vəzifəli şəxsi bu Məcəllənin 42-ci maddəsinə müvafiq olaraq ona təqdim edilmiş sənədləri və nümunə kimi əşyaları götürə bilər. Vergi ödəyicisi tərəfindən yoxlamanı bilavasitə həyata keçirən vəzifəli şəxsə verilən sənədlərin və nümunə kimi əşyaların götürülməsi vergi orqanının rəhbərinin (onun müavininin) əsaslandırılmış qərarı ilə həyata keçirilir.

Əşyaların nümunə kimi götürülmə həcmi, miqdarı, müddəti və onların tədqiq edilməsi qaydaları bu maddəyə uyğun müəyyən edilir.',
        2, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '43'), '43.2.1',
        'Səyyar vergi yoxlaması zamanı nümunə kimi əşyalar aşağıdakı məqsədlər üçün götürülür:',
        3, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '43'), '43.2.1.1',
        'gəlirdən çıxılan xərclərə aid edilən malların (işlərin, xidmətlərin) dəyərinin onların fiziki və keyfiyyət göstəriciləri, növü, mənşəyi və digər göstəriciləri ilə uyğunluğunun yoxlanılması;',
        4, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '43'), '43.2.1.2',
        'malların (işlərin, xidmətlərin) təqdim olunmasından əldə edilən və uçota alınan gəlirin həmin malların (işlərin, xidmətlərin) fiziki və keyfiyyət göstəriciləri, növü, mənşəyi və digər göstəricilərinə uyğunluğunun yoxlanılması;',
        5, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '43'), '43.2.1.3',
        'malların (işlərin, xidmətlərin) bazar qiymətlərinin müəyyənləşdirilməsi;',
        6, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '43'), '43.2.1.4',
        'vergi qanunvericiliyinin pozulmasının, o cümlədən aksiz markası ilə markalanmamış və ya saxta aksiz markası ilə markalanmış, məcburi nişanlama ilə nişanlanmamış və ya saxta məcburi nişanlama ilə nişanlanmış malların, habelə markalanmalı olan, lakin markalanmamış dini təyinatlı ədəbiyyatın (kağız və elektron daşıyıcılarında), audio və videomaterialların, mal və məmulatların və dini məzmunlu başqa məlumat materiallarının saxlanılmasının, satışının və idxal olunmasının sübut edilməsi;',
        7, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '43'), '43.2.1.5',
        'vergi qanunvericiliyinin pozulmasının sübut edilməsi məqsədi ilə əşyaların nümunə kimi götürülməsi zəruri olan digər hallarda.',
        8, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '43'), '43.2.2',
        'Səyyar vergi yoxlaması keçirildiyi zaman əşyaların nümunə kimi götürülməsinə bu Məcəllənin 43.2-ci maddəsində müəyyən edilmiş hallarda və məqsədlərlə yoxlamanı həyata keçirən vergi orqanının vəzifəli şəxsi həmin gün vergi orqanının rəhbərinə və ya onun müavininə yazılı məlumat verməlidir. Həmin məlumatda əşyaların nümunə kimi götürülməsi əsaslandırılmalıdır.',
        9, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '43'), '43.2.3',
        'Vergi orqanının səyyar vergi yoxlamasını həyata keçirən vəzifəli şəxsinin əşyaların nümunə kimi götürülməsini əsaslandıran məlumatı vergi orqanının rəhbəri (rəhbərin müavini) tərəfindən araşdırılır və yalnız bundan sonra həmin əşyaların nümunə kimi götürülməsi barədə qərar qəbul edilir.',
        10, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '43'), '43.2.4',
        'Səyyar vergi yoxlaması zamanı əşyaların nümunə kimi götürülməsi haqqında qərarın forması müvafiq icra hakimiyyəti orqanı tərəfindən təsdiq edilir.',
        11, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '43'), '43.2.5',
        'Vergi orqanının vəzifəli şəxsi tərəfindən səyyar vergi yoxlaması zamanı nümunə kimi götürülən əşyalar xüsusiyyətindən asılı olaraq qablaşdırılır, zəruri hallarda isə yoxlayıcı tərəfindən möhürlənir.',
        12, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '43'), '43.2.6',
        'Səyyar vergi yoxlaması keçirilərkən əşyaların nümunə kimi götürülməsinin miqdarı, həcmi və götürülmə ilə əlaqədar digər şərtlər Azərbaycan Respublikasının ərazisində qüvvədə olan standartlara və normativlərə əsasən müəyyən edilir.',
        13, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '43'), '43.2.7',
        'Nümunə kimi götürülmüş əşyalar, həmin əşyaların tədqiq edilməsi üçün zəruri olan vaxtı nəzərə almaqla 30 gündən artıq olmayan müddətə götürülə bilər.',
        14, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '43'), '43.2.8',
        'Nümunə kimi götürülmüş əşyaların saxlanılması və onların qorunması, qanunvericiliyə uyğun olaraq yaradılmış və fəaliyyət göstərən təşkilatlarda tədqiq edilməsi vergi orqanının hesabına həyata keçirilir.',
        15, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '43'), '43.2.9',
        'Nümunə kimi götürülmüş əşyalar istehlak xassələrini itirmədiyi halda, həmin əşyalar vergi ödəyicisinə qaytarılır. Nümunə kimi götürülmüş əşyalar istehlak xassələrini itirdikdə isə onların dəyəri vergi orqanı tərəfindən ödənilir.',
        16, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '43'), '43.3',
        'Sənədlərin vergi ödəyicisi tərəfindən təsdiq olunmuş surətləri götürülür.',
        17, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '43'), '43.4',
        'Sənədlər və nümunə kimi əşyalar vergi ödəyicisinin iş vaxtı (faktiki iş vaxtı) ərzində götürülür.',
        18, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '43'), '43.5',
        'Səyyar vergi yoxlaması zamanı vergilərin hesablanması üçün zəruri olmayan sənədlərin və nümunə kimi əşyaların götürülməsi qadağandır.',
        19, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '43'), '43.6',
        'Sənədlərin və nümunə kimi əşyaların götürülməsi sənədləri və əşyaları götürülən şəxslərin və (və ya) onların nümayəndələrinin, habelə müşahidəçilərin iştirakı ilə həyata keçirilir. Zəruri hallarda sənədlərin və nümunə kimi əşyaların götürülməsində iştirak etmək üçün mütəxəssis dəvət oluna bilər.',
        20, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '43'), '43.7',
        'Vergi orqanının vəzifəli şəxsi sənədlərin və nümunə kimi əşyaların götürülməsinə qədər götürülmə barədə vergi orqanının rəhbərinin (onun müavininin) əsaslandırılmış qərarını təqdim edir və iştirak edən şəxslərə onların hüquq və vəzifələrini izah edir.',
        21, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '43'), '43.8',
        'Sənədlərin və nümunə kimi əşyaların götürülməsi barədə bu Məcəllənin 48-ci maddəsinin tələblərinə riayət etməklə protokol tərtib edilir.',
        22, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '43'), '43.9',
        'Sənədlərin və nümunə kimi əşyaların götürülməsi haqqında protokolun surəti sənədləri və əşyaları götürülən şəxsə verilir. Bu barədə protokolda qeyd edilir, sənədləri və əşyaları götürülən şəxsin imzası ilə təsdiqlənir.',
        23, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '43'), '43.10',
        'Səyyar vergi yoxlaması zamanı vergi ödəyicisi sənədləri və nümunə kimi əşyaları vermədiyi halda, bu barədə müvafiq icra hakimiyyəti orqanı tərəfindən təsdiq edilmiş formada imtina aktı tərtib edilir və həmin akt vergi orqanının vəzifəli şəxsləri, yoxlamada iştirak edən digər şəxslər (müşahidəçilər, ekspertlər, mütəxəssislər), habelə vergi ödəyicisi və ya onun nümayəndəsi tərəfindən imzalanır.',
        24, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '43'), '43.11',
        'Vergi ödəyicisi bu Məcəllənin 43-cü maddəsində nəzərdə tutulmuş qaydada sənədləri və əşyaları təqdim etmədiyi, bu Məcəllənin 16.1.6-cı maddəsində göstərilən elektron daşıyıcıda, uçot bazalarında və sistemlərində olan məlumatlara birbaşa və ya məsafədən çıxış imkanı yaratmadığı və ya həmin sistemlərdə olan məlumatlar vergi orqanının tələbi ilə təqdim edilmədiyi halda həmin sənədlərin və nümunə kimi əşyaların götürülməsi və ya həmin məlumatlara birbaşa və ya məsafədən çıxış imkanının yaradılmasının təmin edilməsi səyyar vergi yoxlamasını bilavasitə həyata keçirən vergi orqanının əsaslandırılmış müraciətinə əsasən məhkəmənin qərarı ilə həyata keçirilir.',
        25, false, NOW(), NOW());


-- =========================================================
-- Maddə 44. Ekspertiza
-- =========================================================
INSERT INTO tax_articles (article_number, title, chapter, active, created_at, updated_at)
VALUES ('44',
        'Ekspertiza',
        'IV fəsil. Vergi nəzarəti',
        true, NOW(), NOW());

INSERT INTO tax_sections (article_id, section_number, content, order_index, synced_to_vector_store, created_at,
                          updated_at)
VALUES ((SELECT id FROM tax_articles WHERE article_number = '44'), '44.1',
        'Zəruri hallarda səyyar vergi yoxlamasına ekspert cəlb edilə bilər.

Ortaya çıxan məsələlərin izah olunması üçün xüsusi biliklər tələb olunduğu hallarda ekspertiza təyin edilir.',
        1, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '44'), '44.2',
        'Ekspert qarşısında qoyulan suallar və onun rəyi ekspertin xüsusi biliyindən kənara çıxa bilməz.

Ekspert müqavilə əsasında cəlb edilir. Müqavilədə tərəflərin hüquqları və vəzifələri, ekspert qarşısında qoyulan suallar, səhv və ya bilərəkdən yalan rəy verməsinə görə ekspertin məsuliyyəti və mülki qanunvericiliklə müəyyən edilmiş digər məsələlər nəzərdə tutula bilər.',
        2, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '44'), '44.3',
        'Ekspertiza səyyar vergi yoxlamasını bilavasitə həyata keçirən vergi orqanının qərarı ilə təyin edilir.

Qərarda ekspertizanın təyin edilməsi üçün əsaslar, ekspertin adı və ya ekspertiza keçirən təşkilatın adı, ekspert qarşısında qoyulan məsələlər və ekspertə təqdim olunan materiallar göstərilir.',
        3, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '44'), '44.4',
        'Ekspertin yoxlamanın predmetinə aid olan yoxlama materialları ilə tanış olmaq, ona əlavə materialların verilməsi barədə vəsatət qaldırmaq hüququ vardır.',
        4, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '44'), '44.5',
        'Ekspert qarşısında qoyulan suallar onun xüsusi biliyindən kənara çıxdıqda, yaxud təqdim olunan materiallar və sənədlər rəy verilməsi üçün yararsız olduqda və ya kifayət qədər olmadıqda, ekspert rəy verməkdən imtina edir.',
        5, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '44'), '44.6',
        'Ekspertiza keçirilməsi haqqında qərar çıxarmış vergi orqanı həmin qərarla yoxlanılması keçirilən vergi ödəyicisini bu qərarla tanış etməyə və həmin şəxsin bu Məcəllənin 44.7-ci maddəsində nəzərdə tutulan hüquqlarını ona izah etməyə borcludur.',
        6, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '44'), '44.7',
        'Ekspertizanın təyin edilməsi və keçirilməsi zamanı yoxlanılan şəxsin aşağıda göstərilən hüquqları vardır:',
        7, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '44'), '44.7.1',
        'ekspertə etiraz etmək;',
        8, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '44'), '44.7.2',
        'ekspertin onun tərəfindən göstərilən şəxslərdən təyin edilməsi barədə müraciət etmək;',
        9, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '44'), '44.7.3',
        'ekspertin rəyinin alınması üçün əlavə suallar təqdim etmək;',
        10, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '44'), '44.7.4',
        'ekspertiza keçirildikdə vergi yoxlaması keçirən vergi orqanının vəzifəli şəxsinə əvvəlcədən məlumat verməklə bilavasitə və ya nümayəndəsinin vasitəsi ilə ekspertiza keçirilməsində iştirak etmək;',
        11, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '44'), '44.7.5',
        'ekspertin rəyi ilə tanış olmaq.',
        12, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '44'), '44.8',
        'Ekspert rəyi öz adından verir və imzalayır. Ekspertin rəyində onun tərəfindən aparılan araşdırma, gəldiyi nəticələr və qoyulan suallara əsaslandırılmış cavablar əks etdirilir. Ekspertin, ekspertiza aparıldıqda, barəsində onlara dair suallar qoyulmamış, iş üçün əhəmiyyətli olan halları müəyyən etdikdə, həmin hallar haqqında özünün rəyinə nəticələr daxil etmək hüququ vardır.',
        13, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '44'), '44.9',
        'Ekspertin rəyinin surəti və ya onun rəy vermək imkanının olmaması barədə xəbər yoxlanılan şəxsə verilir. Həmin şəxsin izahat vermək, öz etirazlarını bəyan etmək, ekspertə əlavə sualların qoyulmasını, əlavə, yaxud təkrar ekspertizanın təyin edilməsini tələb etmək hüququ vardır.',
        14, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '44'), '44.10',
        'Əlavə ekspertiza ekspertin rəyi kifayət qədər aydın və dolğun olmadığı hallarda təyin edilir və bu ekspertiza həmin və ya başqa ekspertə həvalə edilir.

Təkrar ekspertiza ekspertin rəyi əsaslı olmadığı və onun düzgün olmasında şübhələrin olduğu hallarda təyin edilir və başqa ekspertə həvalə edilir.

Əlavə və təkrar ekspertiza bu maddə ilə nəzərdə tutulmuş qaydada təyin edilir.',
        15, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '44'), '44.11',
        'Yoxlanılan şəxsin bu Məcəllənin 44.7-ci və 44.9-cu maddələrində nəzərdə tutulmuş hüquqları ilə əlaqədar vəsatəti təmin edilmədikdə, vergi orqanının rəhbəri (onun müavini) vəsatətin rədd edilməsi səbəbləri göstərilməklə əsaslandırılmış qərar çıxarır və qərarın surətini yoxlanılan şəxsə təqdim edir.',
        16, false, NOW(), NOW());


-- =========================================================
-- Maddə 45. Vergi yoxlamasının keçirilməsinə kömək göstərilməsi üçün
-- mütəxəssisin dəvət edilməsi
-- =========================================================
INSERT INTO tax_articles (article_number, title, chapter, active, created_at, updated_at)
VALUES ('45',
        'Vergi yoxlamasının keçirilməsinə kömək göstərilməsi üçün mütəxəssisin dəvət edilməsi',
        'IV fəsil. Vergi nəzarəti',
        true, NOW(), NOW());

INSERT INTO tax_sections (article_id, section_number, content, order_index, synced_to_vector_store, created_at,
                          updated_at)
VALUES ((SELECT id FROM tax_articles WHERE article_number = '45'), '45.1',
        'Səyyar vergi yoxlamasının keçirilməsi zamanı bilavasitə vergi orqanlarının fəaliyyət dairəsinə aid olmayan sahələr üzrə xüsusi bilik və təcrübə tələb olunduqda, vergi orqanlarının rəhbərinin (onun müavininin) qərarına əsasən mütəxəssis dəvət oluna bilər.',
        1, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '45'), '45.2',
        'Mütəxəssisin xüsusi bilik və təcrübəsi olmalıdır və o, işin nəticələrində maraqlı olmamalıdır. Bu şərtlərə cavab verməyən mütəxəssisin rəyi vergi orqanları tərəfindən istifadə oluna bilməz.',
        2, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '45'), '45.3',
        'Mütəxəssis müqavilə əsasında dəvət olunur. Müqavilədə tərəflərin hüquq və vəzifələri, mütəxəssis qarşısında qoyulan suallar, səhv və ya bilərəkdən yalan rəy verməsinə görə mütəxəssisin məsuliyyəti və mülki qanunvericiliklə müəyyən edilmiş digər məsələlər nəzərdə tutula bilər.',
        3, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '45'), '45.4',
        'Bu Məcəllənin 45.1-ci maddəsinə müvafiq olaraq cəlb olunmuş mütəxəssis onun qarşısında qoyulmuş suallar barəsində öz rəyini bildirməlidir. Mütəxəssisin rəyi yazılı şəkildə tərtib olunur, onun tərəfindən imzalanır və səyyar vergi yoxlamasının aktına əlavə edilir.',
        4, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '45'), '45.5',
        'Vergi ödəyicisi vergi yoxlamasının aktına əlavə olunmuş mütəxəssisin rəyi ilə razılaşmadıqda, bu barədə yoxlama aktında müvafiq qeydlər edə bilər.',
        5, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '45'), '45.6',
        'Mütəxəssisin səhv və ya bilərəkdən yalan rəy verməsi nəticəsində vergi orqanlarına və ya vergi ödəyicisinə dəyən zərərin ödənilməsi mülki qanunvericiliyə müvafiq olaraq tələb oluna bilər.',
        6, false, NOW(), NOW());


-- =========================================================
-- Maddə 46. Tərcüməçinin iştirakı
-- =========================================================
INSERT INTO tax_articles (article_number, title, chapter, active, created_at, updated_at)
VALUES ('46',
        'Tərcüməçinin iştirakı',
        'IV fəsil. Vergi nəzarəti',
        true, NOW(), NOW());

INSERT INTO tax_sections (article_id, section_number, content, order_index, synced_to_vector_store, created_at,
                          updated_at)
VALUES ((SELECT id FROM tax_articles WHERE article_number = '46'), '46.1',
        'Səyyar vergi yoxlamasının keçirilməsi zamanı zəruri hallarda tərcüməçi dəvət oluna bilər. Tərcüməçinin dəvət olunması vergi orqanının rəhbərinin (onun müavininin) qərarı əsasında həyata keçirilir.',
        1, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '46'), '46.2',
        'Tərcüməçi tərcümə üçün lazım olan dili bilən, işin nəticələrində marağı olmayan şəxs olmalıdır.

Bu müddəalar, həmçinin eşitməyən və danışmayan fiziki şəxsin işarələrini başa düşən şəxsə də aiddir.',
        2, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '46'), '46.3',
        'Tərcüməçi müqavilə əsasında dəvət olunur. Müqavilədə tərəflərin hüquq və vəzifələri, bilərəkdən yalan tərcüməyə görə tərcüməçinin məsuliyyəti və mülki qanunvericiliyə müvafiq olaraq digər məsələlər müəyyən edilə bilər.',
        3, false, NOW(), NOW());


-- =========================================================
-- Maddə 47. Müşahidəçilərin iştirakı
-- =========================================================
INSERT INTO tax_articles (article_number, title, chapter, active, created_at, updated_at)
VALUES ('47',
        'Müşahidəçilərin iştirakı',
        'IV fəsil. Vergi nəzarəti',
        true, NOW(), NOW());

INSERT INTO tax_sections (article_id, section_number, content, order_index, synced_to_vector_store, created_at,
                          updated_at)
VALUES ((SELECT id FROM tax_articles WHERE article_number = '47'), '47.1',
        'Bu Məcəllə ilə nəzərdə tutulmuş hallarda səyyar vergi yoxlamasının keçirilməsi zamanı müşahidəçilər dəvət edilir.',
        1, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '47'), '47.2',
        'Müşahidəçilər iki nəfərdən az olmayaraq dəvət edilir.',
        2, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '47'), '47.3',
        'Müşahidəçilər qismində yoxlamanın nəticələrində maraqlı olmayan fiziki şəxslər dəvət edilə bilər.',
        3, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '47'), '47.4',
        'Müşahidəçi kimi vergi orqanlarının vəzifəli şəxslərinin iştirak etməsinə yol verilmir.

Müşahidəçilər onların iştirakı ilə keçirilən hərəkətlərin faktını, məzmununu və nəticələrini protokolda təsdiq etməyə borcludur.

Müşahidəçilərin həyata keçirilən hərəkətlərə dair öz qeydlərini protokola daxil etmək hüququ vardır.

Zərurət olduqda, müşahidəçilər həmin hərəkətlərə dair öz izahatlarını da verə bilər.

Eyni şəxs vergi orqanları tərəfindən eyni vergi ödəyicisi üzrə vergi ili ərzində bir dəfədən artıq müşahidəçi kimi dəvət oluna bilməz.',
        4, false, NOW(), NOW());


