        1, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '48'), '48.2',
        'Protokolda aşağıdakılar göstərilir:',
        2, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '48'), '48.2.1',
