       ((SELECT id FROM tax_articles WHERE article_number = '48'), '48.2.2',
        'konkret hərəkətlərin həyata keçirilməsinin yeri və tarixi;',
        4, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '48'), '48.2.3',
