       ((SELECT id FROM tax_articles WHERE article_number = '48'), '48.2.4',
        'protokolu tərtib etmiş şəxsin vəzifəsi, adı;',
        6, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '48'), '48.2.5',
        'hərəkətin həyata keçirilməsində iştirak edən və ya onun həyata keçirilməsini müşahidə edən şəxsin adı, lazım olduqda - onun ünvanı, vətəndaşlığı, Azərbaycan dilində danışa bilib-bilməməsi;',
        7, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '48'), '48.2.6',
        'hərəkətin məzmunu, onun həyata keçirilməsinin ardıcıllığı;',
        8, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '48'), '48.2.7',
        'hərəkətin həyata keçirilməsi zamanı aşkar olunan və iş üçün əhəmiyyətli olan faktlar və hallar;',
        9, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '48'), '48.2.8',
        'bu Məcəlləyə uyğun olaraq əşyalar nümunə kimi götürüldükdə protokolda əşyaların miqdarı, həcmi və digər xüsusi əlamətləri göstərilməlidir.',
        10, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '48'), '48.3',
        'Protokol hərəkətin həyata keçirilməsində iştirak edən bütün şəxslər tərəfindən oxunur. Həmin şəxslərin protokola daxil edilməli olan və ya işə tikilməli olan qeydlər etmək hüququ vardır.',
        11, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '48'), '48.4',
        'Protokol onu tərtib etmiş vergi orqanının vəzifəli şəxsi, habelə hərəkətin həyata keçirilməsində iştirak edən bütün şəxslər tərəfindən imzalanır.',
        12, false, NOW(), NOW());


