INSERT INTO tax_sections (article_id, section_number, content, order_index, synced_to_vector_store, created_at,
                          updated_at)
VALUES ((SELECT id FROM tax_articles WHERE article_number = '49'), '49.1',
        'Səyyar vergi yoxlamasının materiallarına baxılmanın nəticələri üzrə vergi orqanının rəhbəri (rəhbərin müavini) 10 gün müddətində aşağıda göstərilən qərarlardan birini çıxarır:',
        1, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '49'), '49.1.1',
        'vergi ödəyicisinin vergi qanunvericiliyinin pozulmasına görə məsuliyyətə cəlb edilməsi;',
        2, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '49'), '49.1.2',
        'vergi ödəyicisinin vergi qanunvericiliyinin pozulmasına görə məsuliyyətə cəlb edilməsindən imtina olunması;',
        3, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '49'), '49.1.3',
        'əlavə vergi yoxlaması tədbirlərinin keçirilməsi haqqında;',
        4, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '49'), '49.1.4',
        'əvvəlki vergi yoxlamasının nəticəsi üzrə qəbul edilmiş qərarın qüvvədə saxlanılması;',
        5, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '49'), '49.1.5',
        'əvvəlki vergi yoxlamasının nəticəsi üzrə qəbul edilmiş qərarın tam və ya qismən ləğv edilməsi və ya qərara dəyişikliklər edilməsi;',
        6, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '49'), '49.1.6',
        'yeni qərarın qəbul edilməsi.',
        7, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '49'), '49.1-1',
        'Bu Məcəllənin 49.1.4-cü – 49.1.6-cı maddələrinin müddəaları bu Məcəllənin 38.3-cü maddəsində nəzərdə tutulmuş əsas üzrə keçirilən səyyar vergi yoxlamasının materiallarına baxılmanın nəticələri üzrə qəbul olunan qərarlara münasibətdə tətbiq edilir.',
        8, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '49'), '49.1-2',
        'Bu Məcəllənin 49.1.3-cü maddəsinə müvafiq olaraq təyin edilən yoxlama əvvəlki səyyar vergi yoxlamasının davamı hesab edilir və yalnız 1 dəfə 60 iş günündən artıq olmamaqla keçirilə bilər. Əlavə vergi yoxlamasının keçirilməsinin nəticəsi üzrə yenidən əlavə vergi yoxlamasının keçirilməsi barədə qərar qəbul edilə bilməz.',
        9, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '49'), '49.2',
        'Vergi ödəyicisinin vergi qanunvericiliyinin pozulmasına görə məsuliyyətə cəlb edilməsi haqqında qərarda vergi yoxlaması ilə müəyyən olunan vergi qanunvericiliyinin pozulmasının şəraiti, həmin şəraiti təsdiq edən sənədlər və digər məlumatlar, vergi ödəyicisinin özünün müdafiəsi üçün gətirdiyi dəlillər və bu dəlillərin yoxlanılmasının nəticələri, vergi qanunvericiliyinin pozulmasına görə və tətbiq olunan məsuliyyət tədbirlərini nəzərdə tutan müvafiq qanunların maddələri göstərilməklə vergi ödəyicisinin vergi qanunvericiliyinin konkret hansı tələblərinin pozulmasına görə məsuliyyətə cəlb olunması ona izah olunur.',
        10, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '49'), '49.3',
        'Vergi ödəyicisinin vergi qanunvericiliyinin pozulmasına görə məsuliyyətə cəlb edilməsi barədə çıxarılmış qərar əsasında 10 gündən gec olmayaraq vergi ödəyicisinə vergi borcunun, faizlərin, maliyyə sanksiyalarının məbləğlərinin, inzibati cərimələrin, habelə aşkar edilmiş pozuntuların aradan qaldırılması barədə tələbnamə göndərilir.',
        11, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '49'), '49.4',
        'Vergi orqanının qərarının surəti və tələbnamə vergi ödəyicisinə və ya onun nümayəndəsinə verilmə tarixini təsdiq edən üsulla təqdim edilir. Vergi ödəyicisi və ya onun nümayəndəsinin bilərəkdən hərəkətləri nəticəsində vergi orqanının qərarının surəti və (və ya) tələbnaməsi ona təqdim oluna bilinmirsə, bu sənədlər (sənəd) onların (onun) sifarişli məktubla alınması günündən təqdim edilmiş hesab edilir.',
        12, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '49'), '49.5',
        'Vergi orqanının vəzifəli şəxsləri tərəfindən bu maddənin tələblərinin gözlənilməməsi vergi orqanının qərarının yuxarı vergi orqanı və məhkəmə tərəfindən ləğv edilməsi üçün əsasdır.',
        13, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '49'), '49.6',
        'Vergi orqanı tərəfindən aşkar edilmiş vergi qanunvericiliyinin pozulmasına görə vergi ödəyicisi inzibati məsuliyyətə cəlb edilməli olduqda, vergi yoxlamasını keçirən vergi orqanının səlahiyyətli vəzifəli şəxsi inzibati hüquq pozuntusu haqqında ayrıca protokol tərtib edir. Bu hüquq pozuntuları haqqında işlərə baxılma və inzibati tənbeh tədbirlərinin həmin pozuntuların edilməsində günahkar olan vergi ödəyicisinin vəzifəli şəxslərinə və vergi ödəyicisi – fərdi sahibkara münasibətdə tətbiq edilməsi vergi orqanları tərəfindən Azərbaycan Respublikasının İnzibati Xətalar Məcəlləsinə müvafiq olaraq həyata keçirilir.',
        14, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '49'), '49.7',
        'Bu maddənin müddəaları həmçinin vergi agentlərinə də şamil edilir.',
        15, false, NOW(), NOW());
