-- Maddə 50. Operativ vergi nəzarəti
-- =========================================================
INSERT INTO tax_articles (article_number, title, chapter, active, created_at, updated_at)
VALUES ('50',
        'Operativ vergi nəzarəti',
        'IV fəsil. Vergi nəzarəti',
        true, NOW(), NOW());

INSERT INTO tax_sections (article_id, section_number, content, order_index, synced_to_vector_store, created_at,
                          updated_at)
VALUES ((SELECT id FROM tax_articles WHERE article_number = '50'), '50.1',
        'Operativ vergi nəzarəti sahibkarlıq fəaliyyəti ilə məşğul olan hüquqi və fiziki şəxslərin gəlir götürmək üçün istifadə etdikləri, yaxud vergi tutulan obyektlərin və ya əmtəə-material ehtiyatlarının saxlanılması ilə bağlı olan anbar, ticarət və bu qəbildən olan digər binalarında (ərazilərində) (yaşayış binaları (sahələri) istisna olmaqla), nəqliyyat vasitələrində (sahibkarlıq fəaliyyəti üçün istifadə edilməyən şəxsi nəqliyyat vasitələri istisna olmaqla) həyata keçirilən və aşağıdakı məsələləri əhatə edən vergi nəzarəti formasıdır:',
        1, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '50'), '50.1.1',
        'bu Məcəllə ilə müəyyən edilmiş hallarda və qaydada vergi orqanlarında uçota durmayan, bu Məcəllənin 33.2-ci maddəsinə uyğun olaraq təsərrüfat subyekti (obyekti) vergi orqanlarında uçotda olmayan və ya bu Məcəllənin 221.4.7-ci maddəsinə əsasən "Fərqlənmə nişanı"nı almayan vergi ödəyicilərinin aşkar edilməsi;',
        2, false, NOW(), NOW()),
