INSERT INTO tax_articles (article_number, title, chapter, active, created_at, updated_at)
VALUES ('50-1',
        'Xronometraj metodu ilə müşahidə aparılması',
        'IV fəsil. Vergi nəzarəti',
        true, NOW(), NOW());

INSERT INTO tax_sections (article_id, section_number, content, order_index, synced_to_vector_store, created_at,
                          updated_at)
VALUES ((SELECT id FROM tax_articles WHERE article_number = '50-1'), '50-1.1',
        'Xronometraj metodu ilə müşahidə operativ vergi nəzarəti növü olmaqla istehsal həcminin və ya satış dövriyyəsinin müəyyənləşdirilməsi və dəqiqləşdirilməsi məqsədi ilə vergi ödəyicilərinin gəlir götürmək üçün istifadə etdikləri, yaxud vergi tutulan obyektlərin saxlanılması ilə bağlı olan istehsal, anbar, ticarət və digər binalarında (ərazilərində) aşağıdakı hallarda aparılır:',
        1, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '50-1'), '50-1.1.1',
        'vergi ödəyicisinin təqdim etdiyi vergi bəyannamələrində vergi tutulan dövriyyə əvvəlki hesabat dövriyyələri ilə müqayisədə 30 faizdən çox azaldıqda, yaxud dövriyyə məbləğlərinin vergi ödəyicisinin fəaliyyəti barədə iqtisadi göstəricilərinə, işçilərinin sayına, əmtəə-material ehtiyatlarının həcminə, satış qiymətlərinə və aktivlərinin dəyərinə uyğun olmaması barədə vergi orqanında mənbəyi bəlli məlumatlar olduqda;',
        2, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '50-1'), '50-1.1.2',
        'əhali ilə pul hesablaşmalarının aparılması qaydalarının təkrar pozulması faktları aşkar olunduqda;',
        3, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '50-1'), '50-1.1.3',
        'bu Məcəllənin 15.1.13-cü maddəsinə müvafiq olaraq vergi ödəyicisi yeni xronometraj metodu ilə müşahidə keçirilməsi haqqında vergi orqanına tələb irəli sürdükdə.',
        4, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '50-1'), '50-1.2',
        'Bu Məcəllənin 15.1.13-cü maddəsinə müvafiq olaraq yeni xronometraj metodu ilə müşahidə keçirilməsi haqqında tələbi vergi ödəyicisi istənilən vaxt, lakin sonuncu xronometraj metodu ilə müşahidədən ən azı 1 ay keçdikdən sonra, növbəti dəfə isə sonuncu müşahidədən ən azı 2 ay keçdikdən sonra təqdim edə bilər. Bu maddədə göstərilən müddətlərin axımına bu Məcəllənin 16.3-cü maddəsində nəzərdə tutulan müddət daxil edilmir.',
        5, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '50-1'), '50-1.3',
        'Xronometraj metodu ilə müşahidə obyektin normal fəaliyyətinə maneçilik törətməməklə və bu Məcəllənin 50.3-50.6-cı maddələrində nəzərdə tutulan qaydalar tətbiq edilməklə 15 iş günündən çox olmayan müddətdə aparılır.',
        6, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '50-1'), '50-1.4',
        'Müşahidəyə başlamazdan əvvəl xronometraj metodu ilə müşahidə aparılmalı olan obyektdə malın (işin, xidmətin) qiymətini müəyyən etmək məqsədi ilə vergi orqanının nəzarət qaydasında mal (iş, xidmət) alqısı həyata keçirmək hüququ vardır.',
        7, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '50-1'), '50-1.5',
        'Xronometraj metodu ilə müşahidə keçirilən zaman müxtəlif vergi ödəyicilərinin tətbiq etdikləri qiymətlərin nəzarət qaydasında mal alqısı zamanı rəsmiləşdirilmiş qiymətlərdən 30 faizdən çox (aşağı və ya yuxarı) fərqlənməsi faktları aşkar edildikdə, istehsal həcmi və ya satış dövriyyəsi nəzarət qaydasında mal alqısı zamanı rəsmiləşdirilmiş qiymətlər nəzərə alınmaqla hesablanır.',
        8, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '50-1'), '50-1.6',
        'Xronometraj metodu ilə müşahidə zamanı müəyyən edilmiş göstəricilər hər iş gününün sonunda müvafiq aktla rəsmiləşdirilir. Xronometraj metodu ilə müşahidənin son nəticəsi müşahidə ilə müəyyən edilmiş günlük göstəricilər əsasında orta günlük göstərici kimi ümumiləşdirilir və bu barədə müvafiq akt tərtib olunur.',
        9, false, NOW(), NOW());


