INSERT INTO tax_sections (article_id, section_number, content, order_index, synced_to_vector_store, created_at,
                          updated_at)
VALUES ((SELECT id FROM tax_articles WHERE article_number = '50-2'), '50-2.1',
        'Azərbaycan Respublikasında istehsal edilən, yaxud ölkəyə idxal olunan məcburi nişanlama ilə nişanlanmalı olan malların siyahısı, Azərbaycan Respublikasının ərazisində dövriyyəsinin tənzimlənməsi, məcburi nişanlamanın hazırlanması üçün sifarişin verilməsi, onun tətbiqi, satışı və uçotunun aparılması qaydası müvafiq icra hakimiyyəti orqanının müəyyən etdiyi orqan (qurum) tərəfindən müəyyən edilir.',
        1, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '50-2'), '50-2.2',
        'Məcburi nişanlamanın hazırlanması, onların vergi ödəyicilərinə verilməsi və uçotunun aparılması müvafiq icra hakimiyyəti orqanının müəyyən etdiyi orqan (qurum) tərəfindən təşkil edilir.',
        2, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '50-2'), '50-2.3',
        'Məcburi nişanlama ilə nişanlanmalı olan malları məcburi nişanlama ilə nişanlanmadan idxal etmək, saxlamaq (şəxsi məqsədlər üçün istisna olmaqla) və ya satmaq qadağandır.',
        3, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '50-2'), '50-2.3-1',
        'Bu Məcəllənin 50-2.1-ci maddəsində nəzərdə tutulan qaydaların tələblərini pozan şəxs bu Məcəllədə, Azərbaycan Respublikasının İnzibati Xətalar Məcəlləsində və Azərbaycan Respublikasının Cinayət Məcəlləsində nəzərdə tutulmuş hallarda məsuliyyət daşıyır.',
        4, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '50-2'), '50-2.4',
        'Məcburi nişanlamanın verilməsinə görə "Dövlət rüsumu haqqında" Azərbaycan Respublikasının Qanunu ilə müəyyən edilmiş məbləğdə dövlət rüsumu tutulur.',
        5, false, NOW(), NOW());


