INSERT INTO tax_sections (article_id, section_number, content, order_index, synced_to_vector_store, created_at,
                          updated_at)
VALUES ((SELECT id FROM tax_articles WHERE article_number = '51'), '51.1',
        'Vergi yoxlaması keçirildikdə, vergi ödəyicisinə və ya onun sahibliyində, istifadəsində və sərəncamında olan əmlaka qanunsuz olaraq zərər vurulmasına yol verilmir.',
        1, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '51'), '51.2',
        'Vergi orqanlarının və ya onların vəzifəli şəxslərinin qanunsuz hərəkətləri ilə vergi yoxlaması keçirildikdə, vurulan ziyan tam həcmdə, buraxılmış fayda (əldə edilməyən gəlir) da daxil olmaqla, vergi ödəyicisinə ödənilməlidir.',
        2, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '51'), '51.3',
        'Vergi orqanları və onların vəzifəli şəxsləri vergi ödəyicisinə qanunsuz hərəkətləri nəticəsində vurduqları ziyana görə qanunla müəyyən edilmiş qaydada məsuliyyət daşıyırlar.',
        3, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '51'), '51.4',
        'Vergi orqanlarının vəzifəli şəxslərinin qanuni hərəkətləri nəticəsində vergi ödəyicisinə vurulan ziyan qanunla müəyyən edilmiş hallar istisna olmaqla, ödənilmir.',
        4, false, NOW(), NOW());


