INSERT INTO tax_sections (article_id, section_number, content, order_index, synced_to_vector_store, created_at,
                          updated_at)
VALUES ((SELECT id FROM tax_articles WHERE article_number = '52'), '52.1',
        'Vergi qanunvericiliyinin pozulmasına görə vergi ödəyicisinin məsuliyyətə cəlb edilməsi haqqında qərarın çıxarılmasından sonra müvafiq vergi orqanı vergi qanunvericiliyinin pozulmasına görə məsuliyyətə cəlb edilən şəxsdən bu Məcəllə ilə müəyyən edilmiş maliyyə sanksiyalarını bu Məcəllənin 65-ci maddəsi ilə müəyyən edilən qaydada və ya məhkəmə qaydasında alır.',
        1, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '52'), '52.2',
        'Vergi orqanları tərəfindən maliyyə sanksiyalarının alınması barədə iddialarına Azərbaycan Respublikasının Mülki-Prosessual Məcəlləsinə müvafiq olaraq baxılır.',
        2, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '52'), '52.3',
        'Məhkəmənin maliyyə sanksiyalarının alınması haqqında qanuni qüvvəyə minmiş qərarının icrası qanunla müəyyən edilmiş qaydada həyata keçirilir.',
        3, false, NOW(), NOW());

-- =========================================================
-- Maddə 53. Vergi qanunvericiliyinin pozulmasına görə məsuliyyətin ümumi əsasları
-- =========================================================
INSERT INTO tax_articles (article_number, title, chapter, active, created_at, updated_at)
VALUES ('53',
        'Vergi qanunvericiliyinin pozulmasına görə məsuliyyətin ümumi əsasları',
        'V fəsil. Vergi qanunvericiliyinin pozulmasına görə məsuliyyət',
        true, NOW(), NOW());

INSERT INTO tax_sections (article_id, section_number, content, order_index, synced_to_vector_store, created_at,
                          updated_at)
VALUES ((SELECT id FROM tax_articles WHERE article_number = '53'), '53.1',
        'Bu Məcəllə ilə müəyyən edilmiş vergi ödəyiciləri, vergi agentləri və onların nümayəndələri, habelə vergi orqanlarının vəzifəli şəxsləri vergi qanunvericiliyinin pozulmasına görə bu Məcəllə, Azərbaycan Respublikasının İnzibati Xətalar Məcəlləsi, Azərbaycan Respublikasının Cinayət Məcəlləsi və Azərbaycan Respublikasının digər qanunları ilə müəyyən edilmiş qaydada məsuliyyət daşıyırlar.

Vergi qanunvericiliyinin pozulmasına görə vergi ödəyicilərinə və vergi agentlərinə bu Məcəllə ilə müəyyən edilmiş maliyyə sanksiyaları və faizlər tətbiq edilir.',
        1, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '53'), '53.2',
        'Heç bir kəs vergi qanunvericiliyinin pozuntusu olan eyni hərəkətə (hərəkətsizliyə) görə təkrarən məsuliyyətə cəlb oluna bilməz.',
        2, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '53'), '53.3',
        'Bu Məcəllə ilə müəyyən edilmiş qaydada və ya məhkəmənin qanuni qüvvəyə minmiş qərarı ilə təqsiri təsdiq edilməyənədək hər bir vergi ödəyicisi vergi qanunvericiliyinin pozulmasında təqsirsiz hesab edilir.

Vergi ödəyicisi vergi qanunvericiliyinin pozulmasında özünün təqsirsiz olmasını sübut etməyə borclu deyildir.

Vergi qanunvericiliyinin pozulması faktını təsdiq edən halların və vergi ödəyicisinin təqsirinin sübut edilməsi vergi orqanlarının üzərinə qoyulur.

Vergi qanunvericiliyinin pozulmasında vergi ödəyicisinin təqsirinin olmasında aradan qaldırılmaz şübhələr olduqda, onlar vergi ödəyicisinin xeyrinə şərh olunur.

Vergi ödəyicisinin, vergitutma obyektinin uçotunda, vergilərin hesablanmasında və ödənilməsində yol verdiyi səhvləri müstəqil düzəltmək hüququ vardır.

Bu maddədə nəzərdə tutulmuş müddəalar vergi agentlərinə də şamil edilir.',
        3, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '53'), '53.4',
        'Vergi qanunvericiliyinin pozulması halları nəzərdən keçirildikdə, onun bilərəkdən və ya ehtiyatsızlıq nəticəsində törədilməsi, inzibati məsuliyyətin tətbiq edilməsi üçün təqsirkar şəxsin müəyyən yaşa çatması, yüngülləşdirici və ya ağırlaşdırıcı hallar və bu Məcəllə, habelə Azərbaycan Respublikası İnzibati Xətalar Məcəlləsinin müddəaları müəyyən edilməlidir.',
        4, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '53'), '53.5',
        'Vergi qanunvericiliyinin pozulması malların Azərbaycan Respublikasının gömrük sərhədindən keçirilməsi ilə bağlı olduqda, həmin işlərə Azərbaycan Respublikasının Gömrük Məcəlləsi ilə müəyyən edilmiş qaydada baxılır.',
        5, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '53'), '53.6',
        'Vergi ödəyicisi tərəfindən vergi qanunvericiliyinin bir neçə pozuntusuna yol verildikdə, maliyyə sanksiyaları hər pozuntuya münasibətdə ayrıca tətbiq edilir. Vergi ödəyicisi tərəfindən eyni əməliyyat üzrə bu Məcəllənin 58.7-ci maddəsində nəzərdə tutulan hesablaşma qaydalarının pozulması hallarına eyni vaxtda yol verildikdə, həmin qanun pozuntularına bir pozuntu halı kimi baxılır və maliyyə sanksiyası bir dəfə tətbiq edilir.',
        6, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '53'), '53.7',
        'Vergi ödəyicisinin və ya vergi agentinin vergi qanunvericiliyinin pozulmasına görə məsuliyyətə cəlb edilməsi onları vergi öhdəliklərinin və vergi orqanlarının vəzifəli şəxslərinin qanuni tələblərininin yerinə yetirilməsindən azad etmir.',
        7, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '53'), '53.8',
        'Azərbaycan Respublikasının tərəfdar çıxdığı beynəlxalq müqavilələrdə, qanunla təsdiq olunmuş hasilatın pay bölgüsü haqqında, əsas ixrac boru kəməri haqqında və digər bu qəbildən olan sazişlərdə başqa qaydalar nəzərdə tutulmadığı hallarda bu sazişlər çərçivəsində fəaliyyət üzrə vergi hesabatının əsas olmadan müəyyən edilən müddətdə təqdim edilməməsinə görə vergi ödəyicisinin vəzifəli şəxsinin (şəxslərinin), habelə vergi və maliyyə məlumatlarının mübadiləsini nəzərdə tutan Azərbaycan Respublikasının tərəfdar çıxdığı beynəlxalq müqavilələr əsasında xarici dövlətlərdən daxil olmuş məlumat mübadiləsi üzrə sorğuların cavablandırılması üçün tələb olunan məlumat və sənədlərin müəyyən edilən müddətdə təqdim edilməməsinə və ya bilərəkdən təhrif olunmaqla təqdim edilməsinə görə vergi ödəyicisi kimi qeydiyyatda olmayan şəxslərin inzibati məsuliyyətə cəlb edilməsi Azərbaycan Respublikasının İnzibati Xətalar Məcəlləsinə müvafiq olaraq həyata keçirilir.',
        8, false, NOW(), NOW());


