INSERT INTO tax_sections (article_id, section_number, content, order_index, synced_to_vector_store, created_at,
                          updated_at)
VALUES ((SELECT id FROM tax_articles WHERE article_number = '56'), '56.1',
        'Azərbaycan Respublikası Vergi Məcəlləsinin tələblərinin (məcburi dövlət sosial sığorta, işsizlikdən sığorta və icbari tibbi sığorta haqları istisna olmaqla) pozulması anından 3 il (xaricdə əldə olunan gəlirlər üzrə xarici dövlətlərin səlahiyyətli orqanlarından müvafiq məlumatlar daxil olduğu hallarda həmin gəlirlər üzrə 5 il, həmçinin bu Məcəllənin 71.4-cü maddəsi ilə müəyyən edilmiş sənədlərin və məlumatların saxlanılması ilə bağlı ən azı 5 il, habelə, Azərbaycan Respublikasının Cinayət-Prosessual Məcəlləsinə uyğun olaraq təyin edilən vergi yoxlamalarında isə Azərbaycan Respublikasının Cinayət Məcəlləsinə müvafiq olaraq cinayət məsuliyyətinə cəlb etmə müddəti) keçmişdirsə, şəxs həmin hüquq pozuntusunun törədilməsinə görə məsuliyyətə cəlb edilə bilməz və vergi öhdəlikləri yarana bilməz. Bu maddə ilə müəyyən edilən müddət bu Məcəllənin 49.1-ci maddəsinə uyğun olaraq məsuliyyətə cəlb edilməsi barədə qərarın qəbul edilmə tarixindən asılı olmayaraq səyyar vergi yoxlamasının keçirilməsi barədə vergi orqanının qərar qəbul etdiyi tarixdən əvvəlki müvafiq dövrü əhatə edir.',
        1, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '56'), '56.2',
        'Çıxarılmışdır.',
        2, false, NOW(), NOW());


-- =========================================================
-- Maddə 57. Hesabatın və digər məlumatın təqdim edilməsi ilə bağlı
-- hüquqpozmalara görə maliyyə sanksiyaları
-- =========================================================
INSERT INTO tax_articles (article_number, title, chapter, active, created_at, updated_at)
VALUES ('57',
        'Hesabatın və digər məlumatın təqdim edilməsi ilə bağlı hüquqpozmalara görə maliyyə sanksiyaları',
        'V fəsil. Vergi qanunvericiliyinin pozulmasına görə məsuliyyət',
        true, NOW(), NOW());

INSERT INTO tax_sections (article_id, section_number, content, order_index, synced_to_vector_store, created_at,
                          updated_at)
VALUES ((SELECT id FROM tax_articles WHERE article_number = '57'), '57.1',
        'Hesabat dövrü üzrə vergi tutulan və ya vergidən azad edilən (vergiyə cəlb edilməyən) əməliyyatlar aparan, vergitutma obyektləri olan vergi ödəyicisi tərəfindən vergi hesabatının əsas olmadan müəyyən edilən müddətdə təqdim edilməməsinə görə vergi ödəyicisinə vergi orqanının rəhbərinin (onun müavininin) qərarına əsasən 40 manat məbləğində maliyyə sanksiyası tətbiq edilir.',
        1, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '57'), '57.1-1',
        'Mülkiyyətində olan kənd təsərrüfatına yararlı torpaqları istifadə edən fiziki şəxslərə və ailə kəndli təsərrüfatlarının əmək qabiliyyətli ailə üzvlərinə "Sosial sığorta haqqında" Azərbaycan Respublikası Qanununun 10-cu maddəsinin ikinci hissəsinin dördüncü və beşinci abzaslarında nəzərdə tutulan hesabatı və arayışı əsas olmadan müəyyən edilən müddətdə təqdim etməməyə görə – təqvim ili ərzində belə hallara birinci dəfə yol verdikdə minimum aylıq əməkhaqqının 3 faizi, iki və daha çox dəfə yol verdikdə 6 faizi miqdarında maliyyə sanksiyası tətbiq edilir.',
        2, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '57'), '57.1-2',
        'Bu Məcəllənin 16.9-cu maddəsində göstərilən hesabatın və (və ya) bildirişin müəyyən edilmiş müddətdə, formada və qaydada təqdim edilməməsinə görə vergi ödəyicisinə 10000 manat məbləğində maliyyə sanksiyası tətbiq edilir.',
        3, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '57'), '57.2',
        'Bu Məcəllənin 89.3-cü maddəsində nəzərdə tutulmuş məlumatı əsas olmadan müəyyən edilən müddətdə təqdim etməyən vergi ödəyicisinə vergi orqanının rəhbərinin (onun müavininin) qərarına əsasən 100 manat məbləğində maliyyə sanksiyası tətbiq edilir.',
        4, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '57'), '57.3',
        'Bu Məcəllənin 23.1.2-ci və 23.1.2-1-ci maddələrində göstərilən sənədlərin (o cümlədən elektron formatda məlumatların) müəyyən edilmiş müddətlərdə təqdim edilməməsinə və ya bilərəkdən təhrif olunmaqla təqdim edilməsinə, habelə bu Məcəllənin 16.1.4-2-ci maddəsində göstərilən məlumat formasının müəyyən edilmiş müddətdə təqdim edilməməsinə və ya təqdim edilmiş məlumat formasında təhrif olunmuş məlumatların göstərilməsinə, bu Məcəllənin 16.1.6-cı maddəsində nəzərdə tutulan halda vergi hesabatı təqdim edilərkən vergi orqanının tələbi ilə maliyyə hesabatlarının təqdim edilməməsinə, eləcə də bu Məcəllənin 16.1.11-17-ci maddəsində göstərilən məlumat formasının müəyyən edilmiş müddətdə təqdim edilməməsinə və ya təqdim edilmiş məlumat formasında təhrif olunmuş məlumatların göstərilməsinə, o cümlədən vergi orqanlarının bu Məcəllənin 42.4-cü maddəsinə əsasən edilmiş müraciətinin həmin maddədə göstərilən müddətdə icra edilməməsinə, habelə sənədlərin və ya məlumatların bu Məcəllənin 71.4-cü maddəsi ilə müəyyən edilmiş 5 ildən az olmayan müddətdə üzrlü səbəb olmadan saxlanılmamasına görə vergi ödəyicisinə 1000 manat məbləğində maliyyə sanksiyası tətbiq edilir.',
        5, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '57'), '57.4',
        'Bu Məcəllənin 16.1.4-cü və 16.1.4-3-cü maddələrində göstərilən arayışları müəyyən edilən müddətlərdə təqdim etməyən və ya arayışlarda düzgün olmayan məlumatlar göstərən və bu Məcəllənin 16.1.4-1-ci maddəsində göstərilən sənədləri və məlumatları vergi orqanının tələbi ilə 60 gün müddətində təqdim etməyən vergi ödəyicisinə vergi orqanının rəhbərinin (onun müavininin) qərarına əsasən 6000 manat məbləğində maliyyə sanksiyası tətbiq edilir.',
        6, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '57'), '57.5',
        'İdxal edilmiş mallar barədə bu Məcəllənin 16.1.11-11-ci maddəsində göstərilən məlumatları həmin maddədə nəzərdə tutulan formada və qaydada təqdim etməyən və ya təhrif olunmuş formada təqdim edən vergi ödəyicisinə müvafiq olaraq idxal edilmiş malların hesab-faktura (invoys) dəyərinin və ya onun təhrif olunmaqla təqdim edilmiş hissəsinin mikro sahibkarlıq subyektlərinə münasibətdə 2 faizi miqdarında, digər şəxslərə münasibətdə 5 faizi miqdarında maliyyə sanksiyası tətbiq edilir.',
        7, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '57'), '57.6',
        'Bu Məcəllənin 16.10-cu maddəsində nəzərdə tutulan kreditor və debitor borclar barədə məlumat formasının təqdim edilməməsinə görə vergi ödəyicisinə vergi orqanının rəhbərinin (onun müavininin) qərarına əsasən 100 manat məbləğində maliyyə sanksiyası tətbiq edilir.',
        8, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '57'), '57.7',
        'Bu Məcəllənin 16.11-ci maddəsində nəzərdə tutulan məlumatları ödəmə tapşırığında göstərməyən və ya təhrif edilməklə göstərən vergi ödəyicisinə vergi orqanının rəhbərinin (onun müavininin) qərarına əsasən hər belə ödəmə tapşırığına görə 100 manat məbləğində maliyyə sanksiyası tətbiq edilir.',
        9, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '57'), '57.8',
        'Bu Məcəllənin 16.1.11-13-cü maddəsində göstərilən məlumatları müəyyən edilən müddətdə təqdim etməyən və ya təhrif olunmuş məlumatları təqdim edən taksi sifarişi operatorlarına 1000 manat məbləğində maliyyə sanksiyası tətbiq edilir.',
        10, false, NOW(), NOW());



INSERT INTO tax_articles (article_number, title, chapter, active, created_at, updated_at)
VALUES ('58',
        'Vergilərin azaldılmasına və digər vergi hüquqpozmalarına görə maliyyə sanksiyaları',
        'V fəsil. Vergi qanunvericiliyinin pozulmasına görə məsuliyyət',
        true, NOW(), NOW());

INSERT INTO tax_sections (article_id, section_number, content, order_index, synced_to_vector_store, created_at,
                          updated_at)
VALUES ((SELECT id FROM tax_articles WHERE article_number = '58'), '58.1',
        'Verginin (o cümlədən ödəmə mənbəyində verginin) hesabatda göstərilən məbləği verginin hesabatda göstərilməli olan məbləğinə nisbətən azaldılmışdırsa, habelə büdcəyə çatası vergi məbləği hesabat təqdim etməməklə yayındırılmışdırsa vergi ödəyicisinə (bu Məcəllənin 58.1-1-ci maddəsində nəzərdə tutulan hal istisna olmaqla) azaldılmış və ya yayındırılmış vergi məbləğinin (kameral vergi yoxlaması nəticəsində hesablanmış əlavə vergi məbləği istisna olmaqla) 50 faizi miqdarında maliyyə sanksiyası tətbiq edilir.',
        1, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '58'), '58.1-1',
        'Verginin (o cümlədən ödəmə mənbəyində verginin) hesabatda göstərilən məbləğinin verginin hesabatda göstərilməli olan məbləğinə nisbətən azaldılması, habelə büdcəyə çatası vergi məbləğinin hesabat təqdim etməməklə yayındırılması üfüqi monitorinq zamanı aşkar edildikdə, həmin vergi ödəyicilərinə azaldılmış və ya yayındırılmış vergi məbləğinin (kameral vergi yoxlaması nəticəsində hesablanmış əlavə vergi məbləği istisna olmaqla) 25 faizi miqdarında maliyyə sanksiyası tətbiq edilir.',
        2, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '58'), '58.2',
        'Bu Məcəllənin 33.4-cü maddəsində göstərilən müddətdə vergi orqanında uçota alınmaq üçün ərizənin verilməməsinə görə 200 manat məbləğində, bu Məcəllənin 34.3-cü maddəsində göstərilən müddətdə olduğu yer, yaxud yaşadığı yerin dəyişməsi barədə ərizənin verilməməsinə, həmçinin digər uçot məlumatlarında (vergi ödəyicisinin vergi uçotuna alınma haqqında ərizədə qeyd olunan rekvizitlər) dəyişiklik haqqında məlumatın təqdim edilməməsinə görə, habelə bu Məcəllənin 221.4.7-ci maddəsində nəzərdə tutulmuş "Fərqlənmə nişanı" olmadan avtomobil nəqliyyatı vasitələri ilə sərnişin və ya yük daşınmasına görə 40 manat məbləğində maliyyə sanksiyası tətbiq edilir.',
        3, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '58'), '58.2-1',
        'Vergi ödəyicisinin bu Məcəllənin 33.2-ci maddəsinə uyğun olaraq təsərrüfat subyektinin (obyektinin) müvafiq icra hakimiyyəti orqanının müəyyən etdiyi orqan (qurum) tərəfindən müəyyən olunmuş qaydada vergi orqanlarında uçota alınmamasına və (və ya) təsərrüfat subyektinin (obyektinin) sahəsi barədə təhrif olunmuş məlumatın verilməsinə, habelə kənd təsərrüfatı məhsulları bazarları və kənd təsərrüfatı kooperativi bazarları istisna olmaqla, bazarlarda olan təsərrüfat subyektinin (obyektinin) girişində həmin təsərrüfat subyektinin (obyektinin) vergi orqanında uçota alınmasına dair (vergi ödəyicisinin adı və VÖEN-i göstərilməklə) məlumatın (arayışın) əks olunmamasına görə mikro sahibkarlıq subyektlərinə, qeyri-kommersiya təşkilatlarına və qeyri-sahibkarlıq fəaliyyəti ilə məşğul olan şəxslərə münasibətdə 40 manat məbləğində, digər şəxslərə münasibətdə 400 manat məbləğində maliyyə sanksiyası tətbiq edilir.',
        4, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '58'), '58.3',
        'Bu Məcəllənin 65-ci maddəsi ilə müəyyən edilmiş qaydada vergilər üzrə borcların və faizlərin, tətbiq edilmiş maliyyə sanksiyalarının dövlət büdcəsinə alınması üçün kredit və elektron pul təşkilatlarına və ya bank əməliyyatları aparan şəxslərə sərəncamın verildiyi tarixdən, kredit və elektron pul təşkilatlarında və ya bank əməliyyatları aparan şəxslərdə hesabları olmadığı halda bu Məcəllənin 65.1-ci maddəsi ilə müəyyən edilmiş bildirişdə göstərilən müddətin başa çatdığı tarixdən vergi ödəyicisi tərəfindən onun kassasından, Azərbaycan Respublikasının Mülki Məcəlləsində nəzərdə tutulmuş hesabdan pul vəsaitinin silinməsi növbəliliyi pozulmaqla, nağd qaydada məxaric əməliyyatları aparıldıqda - aparılmış məxaric əməliyyatlarının 50 faizi miqdarında maliyyə sanksiyası tətbiq edilir.',
        5, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '58'), '58.4',
        'Bu Məcəllənin 155-ci maddəsinə müvafiq olaraq vergi ödəyicisi tərəfindən ƏDV üzrə qeydiyyat məcburi olduğu halda, qeydiyyat olmadan fəaliyyət göstərilməsinə görə vergi ödəyicisinə ƏDV üzrə qeydiyyat olmadan fəaliyyət göstərdiyi bütün dövr ərzində büdcəyə ödənilməli olan ƏDV məbləğinin 50 faizi miqdarında maliyyə sanksiyası tətbiq edilir.',
        6, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '58'), '58.5',
        'Bu Məcəllənin 157-ci və 158-ci maddələrinə müvafiq olaraq ƏDV məqsədləri üçün qeydiyyat qüvvəyə minmədən və ya ləğv edildiyi halda ƏDV üzrə elektron vergi hesab-fakturasının təqdim edilməsinə görə vergi ödəyicisinə təqdim edilmiş elektron vergi hesab-fakturasında göstərilmiş vergi məbləğinin 100 faizi miqdarında maliyyə sanksiyası tətbiq edilir.',
        7, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '58'), '58.6',
        'Bu Məcəllənin 175.1.3-cü maddəsinə müvafiq olaraq bu Məcəllənin 175.8-ci maddəsində göstərilən vergi ödəyicisi tərəfindən malların (iş və xidmətlərin) dəyəri ödənilən gündən 1 iş günü müddətində ƏDV məbləğinin ödənilməməsinə görə (bu Məcəllənin 177.5-ci maddəsində nəzərdə tutulan halda ƏDV məbləğinin 1 iş günü müddətində ödənilməməsi istisna olmaqla) vergi ödəyicisinə vaxtında ödənilməmiş ƏDV məbləğinin 50 faizi miqdarında maliyyə sanksiyası tətbiq edilir.',
        8, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '58'), '58.7',
        'Bu Məcəllənin 13.2.63-cü maddəsində nəzərdə tutulmuş ticarət fəaliyyətinin həyata keçirilməsi halı istisna olmaqla, vergi ödəyicisi kimi vergi orqanında uçotda olmayan şəxslərlə (əhali ilə) pul hesablaşmalarının aparılması qaydalarının pozulmasına, yəni nəzarət-kassa aparatları və ya ciddi hesabat blankları tətbiq edilmədən (nəzarət-kassa aparatları quraşdırılmadan, qanunvericiliklə müəyyən edilmiş formalara uyğun ciddi hesabat blankları olmadan və ya nağd ödənilmiş məbləği mədaxil etmədən), vergi orqanlarında uçota alınmamış və ya texniki tələblərə cavab verməyən, o cümlədən bu Məcəllənin 50.8-ci maddəsində sadalanan tələblərə cavab verməyən çek təqdim edən nəzarət-kassa aparatlarından istifadə etməklə, qanunvericiliklə müəyyən olunmuş ciddi hesabat blanklarından istifadə etmədən və ya müəyyən olunmuş qaydada təsdiq olunmuş formalara uyğun olmayan ciddi hesabat blanklarından istifadə etməklə əhali ilə pul hesablaşmalarının aparılmasına, POS-terminalların quraşdırılması məcburi olan obyektlərdə POS-terminalların quraşdırılmaması və POS-terminallar quraşdırılmış obyektlərdə nağdsız ödənişlərin qəbulundan imtina edilməsinə və ya alıcıya təqdim edilməli olan çekin, bankların valyuta mübadilə şöbələri tərəfindən müştəriyə təqdim edilməli olan bank çıxarışlarının və ya digər ciddi hesabat blanklarının verilməsi barədə alıcının müraciətindən sonra da bunların verilməməsinə və ya ödənilmiş məbləğdən aşağı məbləğ göstərilməklə verilməsinə, nəzarət-kassa aparatlarından istifadə edilməsi dayandırıldıqda əhali ilə pul hesablaşmalarının qeydiyyatının aparılması qaydalarının pozulmasına görə vergi ödəyicisinə:',
        9, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '58'), '58.7.1',
        'təqvim ili ərzində belə hallara birinci dəfə yol verildikdə 1000 manat məbləğində;',
        10, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '58'), '58.7.2',
        'təqvim ili ərzində belə hallara ikinci dəfə yol verildikdə 3000 manat məbləğində;',
        11, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '58'), '58.7.3',
        'təqvim ili ərzində belə hallara üç və daha çox dəfə yol verildikdə 1200 manat, bu Məcəllənin 218.1.2-ci maddəsində göstərilən şəxslərə 6000 manat məbləğində maliyyə sanksiyası tətbiq edilir.',
        12, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '58'), '58.7-1',
        '"Nağdsız hesablaşmalar haqqında" Azərbaycan Respublikası Qanununun tələblərinin pozulmasına görə aşağıdakı vergi ödəyicilərinə Qanun pozulmaqla aparılan əməliyyatın ümumi məbləğinin təqvim ili ərzində belə hala birinci dəfə yol verdikdə 10 faizi, ikinci dəfə yol verdikdə 20 faizi, üç və daha çox dəfə yol verdikdə 40 faizi miqdarında maliyyə sanksiyası tətbiq edilir:',
        13, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '58'), '58.7-1.1',
        'həmin Qanunun 3.3-cü, 3.4.4-cü və 3.4.7-ci maddələrinin tələblərinin pozulmasına görə ödənişi həyata keçirən vergi ödəyicisinə;',
        14, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '58'), '58.7-1.2',
        'həmin Qanunun 3.4.1-ci maddəsinin tələblərini pozmaqla pul vəsaitlərini nağd qaydada qəbul edən lizinq verənə, kreditləri nağd qaydada verən kredit verənə; (58.7-1.2-ci maddəyə Azərbaycan Respublikasının 2026-cı il 26 may tarixli 413-VIIQD nömrəli Qanunu ilə edilmiş dəyişiklik 2026-cı il dekabr 25-dən qüvvəyə minir.)',
        15, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '58'), '58.7-1.3',
        'həmin Qanunun 3.4.2-ci maddəsinin tələblərini pozmaqla nağd qaydada sığorta ödənişlərini edən və sığorta haqlarını nağd qaydada qəbul edən sığortaçıya və ya təkrarsığortaçıya;',
        16, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '58'), '58.7-1.4',
        'həmin Qanunun 3.4.3-cü maddəsinin tələblərini pozmaqla xidmət haqlarını və digər yığımları nağd qaydada qəbul edən şəxsə;',
        17, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '58'), '58.7-1.5',
        'həmin Qanunun 3.4.5-ci maddəsinin tələblərini pozmaqla stasionar telefon və kommunal xidmətlərin haqqını nağd qaydada qəbul edən şəxsə;',
        18, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '58'), '58.7-1.6',
        'həmin Qanunun 3.4.6-cı maddəsinin tələblərini pozmaqla faizsiz pul vəsaitlərini (vergi ödəyicisi olmayan şəxslər tərəfindən pul vəsaitlərinin verilməsi halları istisna olmaqla), digər ayırmaları nağd qaydada ödəyən və qəbul edən şəxsə;',
        19, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '58'), '58.7-1.7',
        'həmin Qanunun 3.4.8-ci maddəsinin tələblərini pozmaqla təhsil haqlarını nağd qaydada qəbul edən şəxsə;',
        20, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '58'), '58.7-1.8',
        'həmin Qanunun 3.4.9-cu maddəsinin tələblərini pozmaqla nağd qaydada ödəmələri qəbul edən şəxsə;',
        21, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '58'), '58.7-1.9',
        'həmin Qanunun 3.4.10-cu, 3.4.11-ci, 3.4.15-ci və 3.4.16-cı maddələrinin tələblərini pozmaqla, ödənişi nağd qaydada qəbul edən şəxsə;',
        22, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '58'), '58.7-1.10',
        'həmin Qanunun 3.4.12-ci maddəsinin tələblərini pozmaqla, tibbi xidmətlərin dəyərini nağd qaydada qəbul edən tibb müəssisəsinə və özəl tibbi praktika ilə məşğul olan fiziki şəxslərə;',
        23, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '58'), '58.7-1.11',
        'həmin Qanunun 3.4.13-cü maddəsinin tələblərini pozmaqla, uduşları (mükafatları) nağd qaydada verən və ya oyunlarda iştirakla bağlı pul ödənişlərini (pul qoyuluşlarını) nağd qaydada qəbul edən şəxsə.',
        24, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '58'), '58.8',
        'Səyyar vergi yoxlaması və operativ vergi nəzarəti zamanı vergi ödəyicisinə məxsus pul vəsaitlərinin uçotdan yayındırılmasına görə, bu Məcəllədə nəzərdə tutulmuş qaydada gəlirlərin və xərclərin uçotu aparılmadıqda, habelə bu Məcəllənin 71-1.1-ci maddəsinin tələbləri nəzərə alınmaqla vergi ödəyicisinin sahibliyində olan mallara dair elektron qaimə-faktura, əvvəlcədən sifariş edilmədən təqdim edilən mallar üzrə malların təhvil-qəbul aktı, idxal gömrük bəyannaməsi və bu bəyannamə ilə bağlı hesab-faktura (invoys), alış aktları və ya bu Məcəllənin 71-2-ci maddəsində göstərilən elektron alış aktları, elektron qaimə-faktura təqdim edilənədək komissiyaya, emala və saxlamaya (məsuliyyətli mühafizəyə) götürülmüş mallara görə təhvil-qəbul aktı və qaytarılmış mallara dair malların qaytarılması aktı olmadıqda:',
        25, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '58'), '58.8.1',
        'pul vəsaitinin 1000 manatdan çox olan məbləğdə uçotdan gizlədilməsinə və ya uçota alınmamasına görə – 1000 manatdan çox olan hissəsinin 10 faizi, təqvim ili ərzində belə hala təkrar yol verdikdə 1000 manatdan çox olan hissəsinin 20 faizi miqdarında maliyyə sanksiyası tətbiq edilir;',
        26, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '58'), '58.8.2',
        'malların alışını və ya mədaxilini təsdiq edən bu Məcəllənin 58.8-ci maddəsində nəzərdə tutulan sənədlər olmadıqda – alıcıya təqvim ili ərzində belə hala birinci dəfə yol verdikdə alınmış malların dəyərinin 10 faizi, ikinci dəfə yol verdikdə 20 faizi, üç və daha çox dəfə yol verdikdə 40 faizi miqdarında. Bu maddənin müddəaları istehsal fəaliyyəti ilə məşğul olan vergi ödəyiciləri tərəfindən istehsal edilən hazır məhsullara münasibətdə tətbiq edilmir;',
        27, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '58'), '58.8.3',
        'bu Məcəllədə nəzərdə tutulmuş qaydada gəlirlərin və xərclərin uçotu aparılmadıqda – alıcıya rəsmiləşdirilməyən xərclərin 20 faizi miqdarında.',
        28, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '58'), '58.9',
        'Bu Məcəllənin 194.2-ci maddəsində nəzərdə tutulmuş plombların vurulması və açılması arasındakı müddətdə nəzarət-ölçü cihazlarının göstəricilərində dəyişikliklərin edilməsinə, texnoloji avadanlıqlardakı plombların zədələnməsinə, istehsal olunmuş məhsulların aksiz markası ilə markalanmamasına və ya məcburi nişanlama ilə nişanlanmamasına, tam uçota alınmamasına, aksiz markalarının və məcburi nişanlamanın inventarizasiyasında kənarlaşmalara yol verilməsinə, eləcə də bu Məcəllənin 191.2-ci maddəsinin tələblərini pozmaqla hazır məhsulun istehsal sahəsindən kənara çıxarılmasına görə vergi ödəyicisinə 5000 manat məbləğində maliyyə sanksiyası tətbiq edilir.',
        29, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '58'), '58.10',
        'Azərbaycan Respublikasının Əmək Məcəlləsində nəzərdə tutulmuş qaydada əmək müqaviləsi (kontraktı) hüquqi qüvvəyə minmədən işəgötürən tərəfindən fiziki şəxslərin hər hansı işlərin (xidmətlərin) yerinə yetirilməsinə cəlb edilməsi yolu ilə onların gəlirlərinin gizlədilməsinə (azaldılmasına) şərait yaradıldığına görə işəgötürənə, habelə bu Məcəllənin 220.10-cu maddəsinə uyğun olaraq aparıcılıq, çalğıçılıq, rəqqaslıq, aşıqlıq, məzhəkəçilik və digər oxşar fəaliyyətlə məşğul olan şəxslərin, foto, audio-video sahəsində məşğul olan şəxslərin və iaşə obyektlərində müştərilərə xidmət göstərən fiziki şəxslərin (ofisiantın) fəaliyyətə başlayanadək, "Sadələşdirilmiş vergi üzrə sabit məbləğin, məcburi dövlət sosial sığorta və icbari tibbi sığorta haqqının ödənilməsi haqqında qəbz" əldə edilmədən işlərin yerinə yetirilməsinə cəlb edilməsinə görə vergi orqanında uçotda olan sifarişçiyə hər bir belə şəxs üzrə təqvim ili ərzində belə hala birinci dəfə yol verdikdə 2000 manat, ikinci dəfə yol verdikdə 4000 manat, üç və daha çox dəfə yol verdikdə 6000 manat məbləğində maliyyə sanksiyası tətbiq edilir.',
        30, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '58'), '58.11',
        'Sahibkarlıq fəaliyyəti məqsədləri üçün qeyri-rezident ödəniş xidməti təchizatçılarında açılmış hesaba (rezident banklar tərəfindən qeyri-rezident banklarda açılmış müxbir hesablar istisna olmaqla) dair forması müvafiq icra hakimiyyəti orqanının müəyyən etdiyi orqan (qurum) tərəfindən təsdiq edilmiş məlumatın bu hesablar üzrə əməliyyatlar aparıldığı tarixədək vergi orqanına təqdim edilməməsinə görə həmin hesaba mədaxil edilmiş pul vəsaitinin 100 faizi miqdarında vergi ödəyicisinə maliyyə sanksiyası tətbiq edilir.',
        31, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '58'), '58.12',
        'Vergi orqanından bu Məcəllənin 221.8-ci maddəsinə əsasən "Sadələşdirilmiş vergi üzrə sabit məbləğin, məcburi dövlət sosial sığorta və icbari tibbi sığorta haqqının ödənilməsi haqqında qəbz" almadan sahibkarlıq fəaliyyətinin həyata keçirilməsinə, habelə "Sosial sığorta haqqında" Azərbaycan Respublikası Qanununun 14.6-1-ci maddəsinə əsasən həmin Qanunun 14.5.1-1.3-cü maddəsində göstərilən şəxslər tərəfindən "Sadələşdirilmiş vergi üzrə sabit məbləğin, məcburi dövlət sosial sığorta və icbari tibbi sığorta haqqının ödənilməsi haqqında qəbz" alınmamasına görə vergi ödəyicisinə:',
        32, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '58'), '58.12.1',
        'təqvim ili ərzində belə hallara birinci dəfə yol verildikdə həmin fəaliyyət növünə görə müəyyən olunmuş aylıq sabit vergi, məcburi dövlət sosial sığorta və icbari tibbi sığorta haqqı məbləğlərinin 40 faizi miqdarında;',
        33, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '58'), '58.12.2',
        'təqvim ili ərzində belə hallara iki və daha çox dəfə yol verildikdə həmin fəaliyyət növünə görə müəyyən olunmuş aylıq sabit vergi, məcburi dövlət sosial sığorta və icbari tibbi sığorta haqqı məbləğlərinin 100 faizi miqdarında maliyyə sanksiyası tətbiq edilir.',
        34, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '58'), '58.13',
        'Bu Məcəlləyə əsasən elektron qaimə-faktura təqdim edilməli olduğu halda malların elektron qaimə-faktura verilmədən təqdim edilməsinə, topdansatış ticarət və istehsal obyektlərindən, habelə anbarlardan malların pərakəndə satış qaydasında rəsmiləşdirməklə təqdim edilməsinə (elektron ticarət qaydasında satılan malların sifariş edilərək pərakəndə satış ticarət obyektlərinə məxsus anbarlardan təqdim edilməsi istisna olmaqla), habelə malların əvvəlcədən sifariş edilmədən təqdim edilməsi üçün malların təsərrüfat subyektindən (obyektindən) nəqliyyat vasitələrinə yüklənməsi üçün təsərrüfatdaxili yerdəyişmə qaimə-fakturasının tərtib edilmədən verilməsinə görə – malları təqdim edən şəxsə təqvim ili ərzində belə hala birinci dəfə yol verdikdə təqdim edilmiş malların satış qiymətinin 10 faizi, ikinci dəfə yol verdikdə 20 faizi, üç və daha çox dəfə yol verdikdə 40 faizi miqdarında maliyyə sanksiyası tətbiq edilir.',
        35, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '58'), '58.13-1',
        'Bu Məcəllənin 71-1.5.10-cu maddəsində nəzərdə tutulan növdə elektron qaimə-faktura tərtib edilmədən malların bir təsərrüfat subyektindən (obyektindən) digər təsərrüfat subyektinə (obyektinə) göndərilməsinə görə vergi ödəyicisinə elektron qaimə-faktura ilə rəsmiləşdirilməyən hər bir belə əməliyyat üçün 100 manat məbləğində maliyyə sanksiyası tətbiq edilir.',
        36, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '58'), '58.14',
        'Aksiz markası ilə markalanmalı olan malların belə marka olmadan, habelə məcburi nişanlama ilə nişanlanmalı malların məcburi nişanlama ilə nişanlanmadan satılmasına, satış məqsədi ilə saxlanılmasına, istehsal binasının hüdudlarından kənara buraxılmasına görə təqvim ili ərzində belə hallara birinci dəfə yol verildikdə həmin malların bazar qiyməti ilə dəyərinin 1 misli, təqvim ili ərzində belə hallara iki və daha çox dəfə yol verildikdə 2 misli məbləğində maliyyə sanksiyası tətbiq edilir.',
        37, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '58'), '58.15',
        'Bu Məcəllə ilə nəzərdə tutulmuş vergi güzəşt və azadolmalarını əldə edən şəxslər tərəfindən vergidən azad olunan gəlirlərin bəyan edilməməsinə və ya azaldılmasına görə vergi ödəyicisinə bəyan edilməmiş və ya azaldılmış gəlirin (xərclər çıxılmadan) 6 faizi miqdarında maliyyə sanksiyası tətbiq edilir.',
        38, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '58'), '58.15-1',
        'Vergi nəzarəti tədbirləri ilə əmtəəsiz əməliyyatlar çərçivəsində riskli vergi ödəyicisi olması barədə qərar qəbul edilmiş vergi ödəyicilərinə aşağıdakı maliyyə sanksiyaları tətbiq edilir:',
        39, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '58'), '58.15-1.1',
        'təqvim ili ərzində belə hallara birinci dəfə yol verildikdə aparılmış əmtəəsiz əməliyyatın məbləğinin 10 faizi miqdarında;',
        40, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '58'), '58.15-1.2',
        'təqvim ili ərzində belə hallara ikinci dəfə yol verildikdə aparılmış əmtəəsiz əməliyyatın məbləğinin 20 faizi miqdarında;',
        41, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '58'), '58.15-1.3',
        'təqvim ili ərzində belə hallara üç və daha çox dəfə yol verildikdə aparılmış əmtəəsiz əməliyyatın məbləğinin 40 faizi miqdarında.',
        42, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '58'), '58.15-2',
        'Bu Məcəllənin 16.1.11-15-ci maddəsinin tələblərinin pozulması baş verdikdə kənd təsərrüfatı məhsulları bazarları və kənd təsərrüfatı kooperativi bazarları istisna olmaqla, bazarların mülkiyyətçilərinə (bazarlar idarəetməyə verildikdə idarəedicilərinə) təqvim ili ərzində belə hal birinci dəfə aşkar edildikdə 2000 manat, ikinci dəfə aşkar edildikdə 4000 manat, üç və daha çox dəfə aşkar edildikdə 6000 manat məbləğində maliyyə sanksiyası tətbiq edilir.',
        43, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '58'), '58.16',
        'Bu Məcəllənin 58.8.2-ci maddəsinin məqsədləri üçün malların dəyəri dedikdə həmin malların alış qiyməti, malların alış qiymətini müəyyən etmək mümkün olmadığı halda isə topdansatış bazar qiyməti nəzərdə tutulur. Alışı bu Məcəllə ilə müəyyən edilmiş qaydada rəsmiləşdirilməyən malların təqdim edilməsinə dair tərtib edilmiş elektron qaimə-fakturalarda mallar barədə məlumatlar, o cümlədən malın adı dəqiq göstərilmədikdə, həmin malların alışı ilə bağlı çəkilən xərclərin dəyəri təqdim edilən malların dəyərinin 1,2-yə bölünməsi yolu ilə alınan dəyər kimi müəyyən edilir.',
        44, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '58'), '58.17',
        'Bu Məcəllənin 58.8.2-ci, 58.13-cü və 58.13-1-ci maddələrində sadalanan və bu Məcəllənin 71-1-ci və 71-2-ci maddələrində göstərilən sənədlər həmin maddədə nəzərdə tutulan müddətlər nəzərə alınmaqla, vergi nəzarəti tədbiri başlandıqdan sonra təqdim (tərtib) edildiyi halda həmin sənədlər nəzərə alınmır və bu Məcəllənin 58.8.2-ci, 58.13-cü və 58.13-1-ci maddələrində nəzərdə tutulan maliyyə sanksiyaları tətbiq edilir.',
        45, false, NOW(), NOW());

-- Maddə 59
INSERT INTO tax_articles (article_number, title, chapter, active, created_at, updated_at)
VALUES ('59',
        'Ödənilmə vaxtı keçmiş və artıq ödənilmiş vergilər üzrə faizlər',
        'V fəsil. Vergi qanunvericiliyinin pozulmasına görə məsuliyyət',
        true, NOW(), NOW());

INSERT INTO tax_sections (article_id, section_number, content, order_index, synced_to_vector_store, created_at,
                          updated_at)
VALUES ((SELECT id FROM tax_articles WHERE article_number = '59'), '59.1',
        'Vergi və ya cari vergi ödəməsi bu Məcəllə ilə müəyyən edilmiş müddətdə ödənilmədikdə, ödəmə müddətindən sonrakı hər bir ötmüş gün üçün vergi ödəyicisindən və ya vergi agentindən ödənilməmiş vergi və ya cari vergi ödəməsi məbləğinin 0,1 faizi məbləğində faiz tutulur.',
        1, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '59'), '59.2',
        'Bu Məcəllənin 59.1-ci maddəsində müəyyən edilmiş faiz yoxlama nəticəsində aşkar edilmiş vaxtında ödənilməmiş vergi məbləğlərinə və cari vergi ödənişlərinə münasibətdə bütün ötmüş müddətə, ancaq bir ildən çox olmamaq şərti ilə tətbiq edilir. Bu faiz səyyar vergi yoxlaması və üfüqi monitorinq nəticəsində aşkar edilmiş vaxtında ödənilməmiş vergi məbləğlərinə həmin vergi məbləğlərinin vergi ödəyicisinə hesablandığı gündən tətbiq edilir.',
        2, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '59'), '59.2-1',
        'Bu Məcəllənin 90.3-cü maddəsinin müddəaları nəzərə alınmaqla, məhkəmənin qanuni qüvvəyə minmiş qərarı ilə müflis elan olunmuş kredit təşkilatlarının ödəmə müddəti ötmüş vergi öhdəliklərinə faizlərin hesablanması kredit təşkilatının müflis elan olunması haqqında məhkəmə qərarının qəbul edildiyi gündən etibarən dayandırılır.',
        3, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '59'), '59.3',
        'Müəyyən edilmiş vergi məbləğindən artıq ödənilmiş məbləğ və ya düzgün tutulmayan vergi məbləği ödənildikdə, bu Məcəllə ilə başqa hallar nəzərdə tutulmamışdırsa, vergi ödəyicisinin ərizəsinin verildiyi tarixdən həmin məbləğlər geri qaytarılanadək gecikdirilən hər bir gün üçün (ödəmə günü də daxil olmaqla) vergi ödəyicisinə müvafiq məbləğlərin 0,1 faizi məbləğində faiz ödənilir. Vergi ödəyicisinin artıq ödənilmiş məbləğlərin qaytarılmasına dair ərizə verdiyi müddətdən 45 gün ərzində (bu Məcəllənin 179.1-ci maddəsi ilə müəyyən edilən halda 20 gün, 179.2-ci maddəsi ilə müəyyən edilən halda isə 4 ay ərzində) məbləğ qaytarılarsa, faizlər vergi ödəyicisinə qaytarılmır.',
        4, false, NOW(), NOW());

-- Maddə 60
INSERT INTO tax_articles (article_number, title, chapter, active, created_at, updated_at)
VALUES ('60',
        'Kredit təşkilatlarına, elektron pul təşkilatlarına, bank əməliyyatlarını aparan şəxslərə və maliyyə institutlarına tətbiq edilən maliyyə sanksiyaları',
        'V fəsil. Vergi qanunvericiliyinin pozulmasına görə məsuliyyət',
        true, NOW(), NOW());

INSERT INTO tax_sections (article_id, section_number, content, order_index, synced_to_vector_store, created_at,
                          updated_at)
VALUES ((SELECT id FROM tax_articles WHERE article_number = '60'), '60.1',
        'Kredit və elektron pul təşkilatları, bank əməliyyatlarını aparan şəxslərə aşağıdakı maliyyə sanksiyaları tətbiq edilir:',
        1, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '60'), '60.1.1',
        'vergi ödəyicisinə hesablar açdıqda həmin hesabların vergi orqanında qeydiyyata alınması üçün elektron məlumatın bu Məcəllənin 35.1-ci maddəsinə uyğun olaraq vergi orqanına təqdim edilməməsinə görə - hər açılmış hesab üzrə 400 manat məbləğində, habelə vergi orqanında qeydiyyata alınmamış hesablar üzrə və ya bu Məcəllənin 35.2-ci maddəsində müəyyənləşdirilən qeydiyyat bildirişi daxil olanadək məxaric əməliyyatları (dövlət büdcəsinə və məcburi dövlət sosial sığorta, işsizlikdən sığorta və icbari tibbi sığorta haqları üzrə büdcədənkənar fondlara məxaric əməliyyatları istisna olmaqla) aparıldığı halda aparılmış məxaric əməliyyatının 50 faizi miqdarında maliyyə sanksiyası tətbiq edilir.',
        2, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '60'), '60.1.2',
        'sahibkarlıq fəaliyyətini göstərən hüquqi və fiziki şəxslərin milli və ya xarici valyutada cari və ya digər hesablarında vəsait olduqda, onların vergilərin ödənilməsinə dair ödəmə tapşırıqlarının və vergi orqanının sərəncamlarının icra edilməməsinə görə:',
        3, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '60'), '60.1.2.1',
        'vergi ödəyicisinin vergilərin ödənilməsinə dair tapşırıqlarının vaxtında icra edilməməsinə, habelə Azərbaycan Respublikasının Mülki Məcəlləsində nəzərdə tutulmuş ödənişlərin növbəliyi pozulmaqla icra edilməsinə görə - vaxtında icra edilməyən ödəmə tapşırıqlarında göstərilən məbləğlərin və ya növbəliyi pozulmaqla aparılan əməliyyatların məbləğlərinin 50 faizi;',
        4, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '60'), '60.1.2.2',
        'vergilər üzrə borcların, faizlərin və maliyyə sanksiyalarının vergi ödəyicisinin hesabından tutulması haqqında vergi orqanının sərəncamlarının daxil olduğu gündən 3 iş günü müddətində icra edilməməsinə, habelə Azərbaycan Respublikasının Mülki Məcəlləsində nəzərdə tutulmuş ödənişlərin növbəliyi pozulmaqla icra edilməsinə görə - vergi orqanının icra edilməyən sərəncamlarında göstərilən məbləğlərin və ya növbəliyi pozulmaqla aparılan əməliyyatların məbləğlərinin 50 faizi;',
        5, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '60'), '60.1.2.3',
        'bu Məcəllənin 65.2-ci maddəsi ilə müəyyən edilən həcmdə pul vəsaitinin məxaric əməliyyatları üzrə dondurulması haqqında vergi orqanlarının sərəncamlarının daxil olduğu vaxt icra edilməməsinə görə - vergi orqanının icra edilməyən sərəncamında göstərilən məbləğlərin 50 faizi;',
        6, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '60'), '60.1.2.4',
        'bu Məcəllənin 65.7-1-ci maddəsinin tələblərinin pozulmasına görə - vergi orqanının sərəncamında göstərilən məbləğlərin 50 faizi. Bu Məcəllənin 60.1.2.1-ci və 60.1.2.2-ci maddələrində növbəliyi pozulmaqla aparılan əməliyyatların məbləğlərinə əsasən tətbiq edilən maliyyə sanksiyasının məbləği həmin ödəmə tapşırıqlarında və ya vergi orqanının sərəncamlarında göstərilən məbləğin 50 faizindən çox olmamalıdır.',
        7, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '60'), '60.1.3',
        'Çıxarılmışdır.',
        8, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '60'), '60.1.4',
        'Bu Məcəllənin 76.2-1-ci maddəsinin tələblərini icra etməməyə görə - aparılmış əməliyyatın ümumi məbləğinin 30 faizi miqdarında, bu hesablar üzrə əməliyyat aparılmadıqda isə hər belə hesab üçün 400 manat məbləğində.',
        9, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '60'), '60.2',
        'Bu Məcəllənin 60.1.2-ci maddəsində müəyyən edilən hallarda vergi ödəyicisindən banka və ya bank əməliyyatlarının ayrı-ayrı növlərini həyata keçirən digər kredit təşkilatına, habelə elektron pul təşkilatına müvafiq tapşırıq və ya sərəncam daxil olduğu gündən həmin günlər üçün vergi ödəyicisinə faiz hesablanmır.',
        10, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '60'), '60.3',
        'Maliyyə institutlarına aşağıdakı maliyyə sanksiyaları tətbiq edilir:',
        11, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '60'), '60.3.1',
        'maliyyə institutları tərəfindən hüquqi və fiziki şəxslərə hesab açıldıqda və ya maliyyə xidmətləri göstərildikdə, Azərbaycan Respublikasının normativ hüquqi aktlarının, habelə vergi və maliyyə məlumatlarının mübadiləsini nəzərdə tutan Azərbaycan Respublikasının tərəfdar çıxdığı beynəlxalq müqavilələrin tələblərinə əməl edilməməsinə görə – hər belə hesab və ya əməliyyat üçün 500 manat məbləğində;',
        12, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '60'), '60.3.2',
        'bu Məcəllənin 16.1.11-4-cü maddəsində göstərilən elektron hesabatın müəyyən edilmiş qaydada və müddətdə təqdim edilməməsinə görə – 10000 manat məbləğində;',
        13, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '60'), '60.3.3',
        'bu Məcəllənin 76-1.1-ci maddəsinin tələblərini icra etməməyə görə – hesaba mədaxil olunmuş vəsaitin ümumi məbləğinin 30 faizi miqdarında, bu hesablar üzrə mədaxil əməliyyatı aparılmadıqda isə, hər belə hesab üçün 400 manat məbləğində;',
        14, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '60'), '60.3.4',
        'vergi və maliyyə məlumatlarının mübadiləsini nəzərdə tutan Azərbaycan Respublikasının tərəfdar çıxdığı beynəlxalq müqavilələrin tələblərinin pozulması həmin müqavilələrin tərəfi olan digər dövlətin səlahiyyətli orqanının bildirişinə əsasən aşkar olunduqda – hər belə hesab üçün 1000 manat məbləğində.',
        15, false, NOW(), NOW());

-- Maddə 61
INSERT INTO tax_articles (article_number, title, chapter, active, created_at, updated_at)
VALUES ('61',
        'Vergi orqanlarının və onların vəzifəli şəxslərinin məsuliyyəti',
        'V fəsil. Vergi qanunvericiliyinin pozulmasına görə məsuliyyət',
        true, NOW(), NOW());

INSERT INTO tax_sections (article_id, section_number, content, order_index, synced_to_vector_store, created_at,
                          updated_at)
VALUES ((SELECT id FROM tax_articles WHERE article_number = '61'), '61.1',
        'Vergi orqanlarının hüquqa zidd hərəkətləri (qərarları) və ya hərəkətsizliyi, habelə vergi orqanlarının vəzifəli şəxslərinin və digər işçilərinin öz vəzifələrini icra etdikdə, onların hüquqa zidd hərəkətləri (qərarları) və ya hərəkətsizliyinə, həmçinin bunların nəticəsində vergi ödəyicilərinə dəymiş zərərə görə vergi orqanları və vergi orqanlarının vəzifəli şəxsləri qanunvericiliklə müəyyən edilmiş qaydada məsuliyyət daşıyırlar.',
        1, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '61'), '61.2',
        'Vergi ödəyicilərinə bu Məcəllənin 61.1-ci maddəsində göstərilən hərəkətlər (qərarlar) və ya hərəkətsizlik nəticəsində dəymiş zərər məhkəmənin qərarına əsasən ödənilir. Vergi orqanları tərəfindən düzgün tutulmayan vergi, maliyyə sanksiyaları, faizlər və inzibati cərimələrin məbləğləri, vergilər üzrə borclar olmadıqda, bu Məcəllədə başqa hallar nəzərdə tutulmadıqda vergi ödəyicisinin müraciətinə əsasən 45 gün müddətində geri qaytarılmalıdır və ya gələcək ödənişlərin hesabına aid edilə bilər.',
        2, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '61'), '61.3',
        'Vergi orqanlarının vəzifəli şəxsləri və digər işçiləri özlərinin hüquqa zidd hərəkətlərinə (qərarlarına) və ya hərəkətsizliyinə, o cümlədən öz xidməti vəzifələrini yerinə yetirmədiyinə və ya lazımınca yerinə yetirmədiyinə görə qanunvericiliklə müəyyən edilmiş qaydada məsuliyyət daşıyırlar.',
        3, false, NOW(), NOW());


-- Maddə 62
INSERT INTO tax_articles (article_number, title, chapter, active, created_at, updated_at)
VALUES ('62',
        'Şikayət verilməsi qaydası',
        'VI fəsil. Vergi orqanlarının qərarlarından (aktlarından) və onların vəzifəli şəxslərinin hərəkətlərindən (hərəkətsizliyindən) şikayət verilməsi',
        true, NOW(), NOW());

INSERT INTO tax_sections (article_id, section_number, content, order_index, synced_to_vector_store, created_at,
                          updated_at)
VALUES ((SELECT id FROM tax_articles WHERE article_number = '62'), '62.1',
        'Hər bir vergi ödəyicisinin və ya başqa vəzifəli şəxsin vergi orqanlarının qərarlarından (aktlarından), habelə vergi orqanlarının vəzifəli şəxslərinin hərəkətlərindən (hərəkətsizliyindən) şikayət etmək hüququ vardır.',
        1, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '62'), '62.2',
        'Vergi orqanlarının qərarlarından (aktlarından), habelə vergi orqanlarının vəzifəli şəxslərinin hərəkətlərindən (hərəkətsizliyindən) şikayət qanunla müəyyən edilmiş qaydada yuxarı vergi orqanına (yuxarı vəzifəli şəxsə) və (və ya) məhkəməyə verilir. Şikayətin yuxarı vergi orqanına (yuxarı vəzifəli şəxsə) verilməsi həmin şikayətin eyni zamanda və ya sonradan məhkəməyə verilməsini istisna etmir.',
        2, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '62'), '62.3',
        'Vergi orqanlarının qərarlarından (aktlarından), habelə vergi orqanlarının vəzifəli şəxslərinin hərəkətlərindən (hərəkətsizliyindən) şikayət yuxarı vergi orqanına (yuxarı vəzifəli şəxsə) vergi ödəyicisi və ya başqa borclu şəxs tərəfindən öz hüquqlarının pozulduğunu bildiyi və ya bilməli olduğu gündən 3 ay müddətində verilir. Vergi ödəyicisi və ya başqa borclu şəxs üzürlü səbəbdən bu maddənin birinci abzasında göstərilən müddəti buraxmışdırsa, yuxarı vergi orqanı və ya yuxarı vergi orqanının vəzifəli şəxsi tərəfindən şikayəti verən şəxsin ərizəsinə əsasən həmin müddət bərpa edilə bilər.',
        3, false, NOW(), NOW());

-- Maddə 63
INSERT INTO tax_articles (article_number, title, chapter, active, created_at, updated_at)
VALUES ('63',
        'Vergi orqanında şikayətə baxılma',
        'VI fəsil. Vergi orqanlarının qərarlarından (aktlarından) və onların vəzifəli şəxslərinin hərəkətlərindən (hərəkətsizliyindən) şikayət verilməsi',
        true, NOW(), NOW());

INSERT INTO tax_sections (article_id, section_number, content, order_index, synced_to_vector_store, created_at,
                          updated_at)
VALUES ((SELECT id FROM tax_articles WHERE article_number = '63'), '63.1',
        'Vergi ödəyicisinin və ya başqa borclu şəxsin vergi orqanının qərarlarından (aktlarından), vergi orqanının vəzifəli şəxslərinin hərəkətlərindən (hərəkətsizliyindən) şikayətinə yuxarı vergi orqanı və ya onun vəzifəli şəxsi tərəfindən həmin şikayət alındığı gündən 30 iş günü müddətində baxılır və şikayət vermiş şəxsə yazılı cavab verilir. Şikayət üzrə əhəmiyyət kəsb edən halların müəyyən olunması üçün 30 iş günündən artıq müddət tələb olunduğu hallarda şikayətə baxılması müddəti vergi orqanı tərəfindən bir dəfə 30 iş günü müddətində uzadıla bilər. Müddətin uzadılması barədə şikayət vermiş şəxsə 3 iş günü ərzində məlumat verilir. Qəbul edilmiş qərar barəsində şikayət vermiş şəxsə 10 gün müddətində yazılı cavab verilməlidir.',
        1, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '63'), '63.2',
        'Vergi ödəyicisi ona hesablanmış verginin məbləği ilə razı olmadığı halda, verginin ödənilməsini dayandırmadan bilavasitə vergi nəzarətini həyata keçirən müvafiq icra hakimiyyəti orqanına və ya məhkəməyə şikayət verə bilər. Vergi ödəyicisinin şikayətə baxılan müddət ərzində maliyyə sanksiyasını ödəməmək hüququ vardır.',
        2, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '63'), '63.3',
        'Vergi ödəyicisi və ya başqa borclu şəxs tərəfindən vergi orqanına (vəzifəli şəxsə) verilən şikayət, bu Məcəllənin 63.2-ci maddəsinin ikinci abzasında müəyyən edilən hallar istisna olunmaqla, şikayət edilən qərarın (aktın) və ya hərəkətin icrasını dayandırmır. Şikayət edilən qərar (akt) və ya hərəkət Azərbaycan Respublikasının qanunvericiliyinə uyğun olmadıqda, şikayətə baxan vergi orqanı (vəzifəli şəxsi) onun icrasını tam və ya qismən dayandırır. Qərarın (aktın) və ya hərəkətin icrasının tam və ya qismən dayandırmaq barədə qərarı həmin aktı qəbul etmiş vergi orqanının rəhbəri və ya yuxarı vergi orqanı qəbul edir.',
        3, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '63'), '63.4',
        'Hesablanmasından və ya tətbiq edilməsindən şikayət edilən verginin, faizlərin və ya maliyyə sanksiyasının məbləği hesablanmaya (tətbiq edilməyə) uyğun şəkildə ödənildiyi və bu şikayətin təmin edilməsi nəticəsində vergi, faizlər və ya maliyyə sanksiyası tamamilə və ya qismən ləğv edildiyi halda, vergi ödəyicisinin aşağıdakılara hüququ vardır:',
        4, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '63'), '63.4.1',
        'səhv tutulan məbləğlərə görə bu Məcəllənin 61.2-ci maddəsinə uyğun olaraq kompensasiya almaq;',
        5, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '63'), '63.4.2',
        'bu Məcəlləyə müvafiq olaraq həmin məbləğlərdən faizlər almaq.',
        6, false, NOW(), NOW());

-- Maddə 64
INSERT INTO tax_articles (article_number, title, chapter, active, created_at, updated_at)
VALUES ('64',
        'Məhkəməyə verilmiş şikayətlərə baxılma',
