        true, NOW(), NOW());

INSERT INTO tax_sections (article_id, section_number, content, order_index, synced_to_vector_store, created_at,
                          updated_at)
VALUES ((SELECT id FROM tax_articles WHERE article_number = '64'), '64',
        'Vergi orqanlarının qərarları (aktları), onların vəzifəli şəxslərinin hərəkətləri (hərəkətsizliyi) barəsində məhkəməyə verilmiş şikayətlərə (iddia ərizələrinə) Azərbaycan Respublikasının İnzibati Prosessual Məcəlləsi ilə müəyyən edilmiş qaydada baxılır.',
        1, false, NOW(), NOW());

-- Maddə 65
INSERT INTO tax_articles (article_number, title, chapter, active, created_at, updated_at)
VALUES ('65',
        'Vergilər üzrə borcların alınması qaydası',
        'VII fəsil. Vergilərin ödənilməsi üzrə ümumi qaydalar',
        true, NOW(), NOW());

INSERT INTO tax_sections (article_id, section_number, content, order_index, synced_to_vector_store, created_at,
                          updated_at)
VALUES ((SELECT id FROM tax_articles WHERE article_number = '65'), '65.1',
        'Vergi ödəyicisi vergi öhdəliyini bu Məcəllə ilə müəyyən edilmiş müddətdə yerinə yetirmədikdə vergi orqanı bu Məcəlləyə müvafiq olaraq hesablanmış və ya yenidən hesablanmış vergilərin, faizlərin və tətbiq edilmiş maliyyə sanksiyalarının 5 gün müddətində ödənilməsinə dair vergi ödəyicisinə bildiriş göndərir.',
        1, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '65'), '65.2',
        'Bu Məcəllənin 65.2.1.1-ci və 65.2.1.4-cü maddələrində nəzərdə tutulan hallar istisna olmaqla digər hallarda vergi orqanının hesabladığı və ya yenidən hesabladığı vergilər, faizlər və ya tətbiq etdiyi maliyyə sanksiyaları üzrə vergi orqanı vergi ödəyicisinin milli və ya xarici valyutada cari və ya digər hesablarında borc məbləğinin 105 faizi həcmində pul vəsaitinin məxaric əməliyyatları üzrə dondurulması haqqında kredit və ya elektron pul təşkilatına və ya bank əməliyyatları aparan şəxsə icra sənədi olan sərəncam verir. Bu zaman kredit və ya elektron pul təşkilatları və ya bank əməliyyatlarını aparan şəxslər tərəfindən hesablarda dondurulmuş vəsaitdən artıq olan pul vəsaitinə dair hesabdan məxaric edilməsini nəzərdə tutan vergi ödəyicisinin ödəmə tapşırıqları icra edilir.',
        2, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '65'), '65.2.1',
        'Vergi orqanı aşağıdakı hallarda vergilər, faizlər və maliyyə sanksiyaları üzrə borcların vergi ödəyicisinin milli və ya xarici valyutada cari və ya digər hesablarından dövlət büdcəsinə alınması haqqında kredit və ya elektron pul təşkilatına və ya bank əməliyyatları aparan şəxsə icra (ödəniş) sənədi olan sərəncam verir:',
        3, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '65'), '65.2.1.1',
        'vergi ödəyicisi tərəfindən hesablanmış və bəyan edilmiş vergilər bu Məcəllənin 65.1-ci maddəsi nəzərə alınmaqla müəyyən edilmiş müddətdə ödənilmədikdə;',
        4, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '65'), '65.2.1.2',
        'vergi orqanının hesabladığı vergilər, faizlər və tətbiq etdiyi maliyyə sanksiyaları üzrə vergi ödəyicisi tərəfindən bu Məcəllənin 65.1-ci maddəsində göstərilən bildirişin alındığı tarixdən 30 təqvim günü müddətində məhkəməyə və ya müvafiq icra hakimiyyəti orqanının müəyyən etdiyi orqana (quruma) şikayət verilmədikdə;',
        5, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '65'), '65.2.1.3',
        'məhkəmənin müvafiq qərarı və ya müvafiq icra hakimiyyəti orqanının müəyyən etdiyi orqanın (qurumun) qərarı olduqda həmin qərara uyğun olaraq;',
        6, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '65'), '65.2.1.4',
        'vergi ödəyicisinin yazılı razılığı olduqda.',
        7, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '65'), '65.2.2',
        'Vergi orqanının hesablamaları üzrə vergi ödəyicisi tərəfindən bu Məcəllənin 65.1-ci maddəsində göstərilən bildirişin alındığı tarixdən 30 təqvim günü müddətində məhkəməyə və ya müvafiq icra hakimiyyəti orqanının müəyyən etdiyi orqana (quruma) şikayət verildikdə kredit və ya elektron pul təşkilatı və ya bank əməliyyatları aparan şəxs məhkəmənin qanuni qüvvəyə minmiş qərarına və ya müvafiq icra hakimiyyəti orqanının müəyyən etdiyi orqanın (qurumun) qərarına uyğun olaraq və bu Məcəllənin 65.2.1.3-cü maddəsinə əsasən verilmiş sərəncamın icrasını təmin edir.',
        8, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '65'), '65.2.3',
        'Vergi orqanı vergi ödəyicisinin ƏDV depoziti hesabından yalnız ƏDV üzrə vergi borclarının dövlət büdcəsinə alınmasını təmin edir. ƏDV üzrə vergi borclarının ödənilməsi üçün ƏDV depoziti hesabında vergi ödəyicisinin kifayət qədər vəsaiti olmadıqda, ƏDV üzrə vergi borclarının dövlət büdcəsinə alınması üçün həmin şəxsin digər hesablarına bu Məcəllədə nəzərdə tutulmuş qaydada sərəncam verilə bilər.',
        9, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '65'), '65.2.3-1',
        'Bu Məcəllənin 65.2.1.1-ci və 65.2.1.4-cü maddələrində nəzərdə tutulan hallar istisna olmaqla digər hallarda vergi orqanının hesabladığı və ya yenidən hesabladığı ƏDV üzrə vergi, faiz və ya tətbiq etdiyi maliyyə sanksiyası üzrə borc məbləğinin 105 faizi həcmində pul vəsaitinin vergi ödəyicisinin ƏDV depozit hesabında dondurulması barədə vergi orqanı tərəfindən qərar qəbul edilir.',
        10, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '65'), '65.2.3-2',
        'Vergi orqanının hesablamaları üzrə vergi ödəyicisi tərəfindən bu Məcəllənin 65.1-ci maddəsində göstərilən bildirişin alındığı tarixdən 30 təqvim günü müddətində məhkəməyə və ya müvafiq icra hakimiyyəti orqanının müəyyən etdiyi orqana (quruma) şikayət verilmədikdə vergi orqanı tərəfindən ƏDV depozit hesabından ƏDV üzrə vergi borcunun, faizlərin və tətbiq edilmiş maliyyə sanksiyalarının dövlət büdcəsinə alınması həyata keçirilir.',
        11, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '65'), '65.2.3-3',
        'Vergi orqanının hesablamaları üzrə vergi ödəyicisi tərəfindən bu Məcəllənin 65.1-ci maddəsində göstərilən bildirişin alındığı tarixdən 30 təqvim günü müddətində məhkəməyə və ya müvafiq icra hakimiyyəti orqanının müəyyən etdiyi orqana (quruma) şikayət verildikdə bu Məcəllənin 65.2.3-1-ci maddəsinə uyğun olaraq dondurulmuş ƏDV depozit hesabından ƏDV üzrə vergi, faiz və tətbiq edilmiş maliyyə sanksiyası üzrə borcların alınması məhkəmənin qanuni qüvvəyə minmiş qərarına və ya müvafiq icra hakimiyyəti orqanının müəyyən etdiyi orqan (qurum) tərəfindən "İnzibati icraat haqqında" Azərbaycan Respublikasının Qanununa uyğun olaraq qəbul edilmiş qərara uyğun həyata keçirilir.',
        12, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '65'), '65.3',
        'Vergi ödəyicisinin milli və ya xarici valyutada cari və ya digər hesablarında vəsait olduqda vergi orqanının sərəncamı kredit və ya elektron pul təşkilatı tərəfindən həmin sərancamın daxil olduğu gün icra edilir.',
        13, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '65'), '65.4',
        'Vergi ödəyicisinin milli və ya xarici valyutada cari və ya digər hesablarında vəsait olmadıqda və ya o, vergilər üzrə borcların və faizlərin, tətbiq edilmiş maliyyə sanksiyalarının ödənilməsinə, yaxud bu Məcəllə ilə müəyyən edilən həcmdə vəsaitin dondurulmasına kifayət etmədikdə vergi orqanının sərancamı kredit və ya elektron pul təşkilatında saxlanılır və vergi ödəyicisinin hesablarına vəsait daxil olduqca icra edilir.',
        14, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '65'), '65.5',
        'Çıxarılmışdır.',
        15, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '65'), '65.6',
        'Bu Məcəllənin 79.3-cü maddəsinin müddəaları nəzərə alınmaqla, vergi orqanlarının vergilər üzrə borcların və faizlərin, tətbiq edilmiş maliyyə sanksiyalarının dövlət büdcəsinə alınması haqqında sərəncamları kredit və elektron pul təşkilatı tərəfindən Azərbaycan Respublikasının Mülki Məcəlləsində nəzərdə tutulmuş ödənişlərin növbəliliyi ardıcıllığına uyğun olaraq icra edilir.',
        16, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '65'), '65.7',
        'Vergi orqanlarının vergilər üzrə borcların və faizlərin, tətbiq edilmiş maliyyə sanksiyalarının dövlət büdcəsinə alınması haqqında sərəncamı vergi ödəyicisinin xarici valyutada olan hesabına yönəldildikdə, kredit və elektron pul təşkilatı və ya poçt rabitəsinin milli operatoru həmin gün Azərbaycan Respublikası Mərkəzi Bankının müəyyən etdiyi rəsmi məzənnə ilə sərəncamda göstərilən məbləğin 105 faizinədək hesabdakı valyuta vəsaitini dondurur və dərhal bu barədə vergi ödəyicisinə məlumat göndərir. Vergi ödəyicisi tərəfindən konvertasiya əməliyyatı aparıldıqdan sonra kredit və elektron pul təşkilatı vergi orqanının sərəncamını icra edir.',
        17, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '65'), '65.7-1',
        'Vergi ödəyicisi tərəfindən onun bank və digər ödəniş hesabında xarici valyutada olan pul vəsaiti hesaba vergi orqanının sərəncamı daxil olduğu gündən 10 əməliyyat günü ərzində konvertasiya edilmədikdə, növbəti iş günü ərzində Azərbaycan Respublikası Mərkəzi Bankının elan etdiyi məzənnə ilə xarici valyutada olan dondurulmuş pul vəsaiti kredit və ya elektron pul təşkilatı tərəfindən konvertasiya edilməklə sərəncam icra edilir. Bu maddə ilə müəyyən edilmiş 10 əməliyyat günü müddətində vergi orqanı tərəfindən yeni sərəncam göndərildiyi halda həmin sərəncamda göstərilən vergi borcunun məbləği vergi orqanının əvvəlki sərəncamına münasibətdə azalmışdırsa, 10 əməliyyat günü müddəti əvvəlki sərəncamın tarixindən hesablanır. Bu maddə ilə müəyyən edilmiş 10 əməliyyat günü müddətində vergi orqanı tərəfindən yeni sərəncam göndərildiyi halda həmin sərəncamda göstərilən vergi borcunun məbləği vergi orqanının əvvəlki sərəncamına münasibətdə artmışdırsa, 10 əməliyyat günü müddəti əvvəlki sərəncamda göstərilən vergi borcu üzrə həmin sərəncamın tarixindən, artan vergi borcu məbləğinə münasibətdə isə yeni sərəncamın daxil olduğu tarixdən hesablanır. Kredit və ya elektron pul təşkilatının xarici valyutanın konvertasiya edilməsinə kifayət edəcək məbləğdə milli valyutası olmadıqda konvertasiya əməliyyatı mövcud olan milli valyutaya uyğun həyata keçirilməklə sərəncam icra edilir və hər dəfə kredit və ya elektron pul təşkilatının hesabına milli valyuta daxil olduqca icra edilir.',
        18, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '65'), '65.7-2',
        'Vergi orqanının vergi ödəyicisinin milli və ya xarici valyutada cari və ya digər hesablarında vergilər, faizlər və ya maliyyə sanksiyaları üzrə borc məbləğinin 105 faizi həcmində pul vəsaitinin məxaric əməliyyatları üzrə dondurulması haqqında sərəncamı vergi ödəyicisinin bir neçə kredit və ya elektron pul təşkilatında olan hesablarına verildikdə və bu zaman borc məbləği vergi ödəyicisinin milli və ya xarici valyutada cari və ya digər hesablarından hər hansı biri üzrə dondurulduqda, həmin vəsaitin dondurulmasını təmin edən kredit və ya elektron pul təşkilatı vergi ödəyicisinin müraciəti əsasında bu barədə məlumatı vergi orqanına elektron qaydada təqdim edir. Vergi orqanı təqdim olunan məlumat əsasında digər kredit və ya elektron pul təşkilatlarına verilən sərəncamların 1 iş günü müddətində geri qaytarılmasını təmin edir.',
        19, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '65'), '65.7-3',
        'Vergi orqanının vergi ödəyicisinin eyni kredit və ya elektron pul təşkilatında olan bir neçə hesablarına verilmiş vergilər, faizlər və ya maliyyə sanksiyaları üzrə borc məbləğinin 105 faizi həcmində pul vəsaitinin məxaric əməliyyatları üzrə dondurulması haqqında sərəncamları olduqda və bu zaman borc məbləği vergi ödəyicisinin milli və ya xarici valyutada cari və ya digər hesablarından hər hansı biri üzrə dondurulduqda, vergi orqanı həmin kredit və ya elektron pul təşkilatının elektron müraciəti əsasında digər hesablar üzrə sərəncamların 1 iş günü müddətində geri qaytarılmasını təmin edir.',
        20, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '65'), '65.8',
        'Vergi orqanının vergilər üzrə borcların, faizlərin və maliyyə sanksiyalarının dövlət büdcəsinə alınması haqqında sərəncamı bir neçə kredit və ya elektron pul təşkilatına verildikdə və bu zaman vergilər üzrə borclar, faizlər və maliyyə sanksiyaları vergi ödəyicisinin hər hansı milli və ya xarici valyutada cari və ya digər hesablarından dövlət büdcəsinə alındıqda və ya dondurulduqda, vergi orqanı digər kredit və ya elektron pul təşkilatlarına verilən sərəncamların dərhal geri qaytarılmasını təmin edir. Vergi orqanının sərəncamı geri qaytarılana qədər kredit və elektron pul təşkilatları və ya bank əməliyyatları aparan şəxslər vergilər üzrə borcların, faizlərin və maliyyə sanksiyalarının dövlət büdcəsinə alınmasını (ödənilməsini) təsdiq edən sənəd əsasında alınmış (ödənilmiş) həmin məbləğ həcmində vergi ödəyicisinin vəsaitini hesabda dondurmaqla, belə vəsaitlər üzrə sərəncamın icrasını dayandırır.',
        21, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '65'), '65.8-1',
        'Bu Məcəllənin 65.2-ci maddəsinə uyğun olaraq vergi ödəyicisinin milli və ya xarici valyutada cari və ya digər hesablarında borc məbləğinin 105 faizi həcmində pul vəsaitinin məxaric əməliyyatları üzrə dondurulması haqqında sərəncam olduqda, vergi ödəyicisi dondurulmuş pul vəsaitinin dövlət büdcəsinə köçürülməsi ilə bağlı kredit və ya elektron pul təşkilatları və ya bank əməliyyatları aparan şəxslərə ödəniş tapşırığı təqdim edə bilər və həmin şəxslər vergi ödəyicisinin ödəniş tapşırığında göstərilən məbləğdə pul vəsaitinin dövlət büdcəsinə köçürülməsini təmin edir.',
        22, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '65'), '65.9',
        'Vergi ödəyicisinin milli və ya xarici valyutada cari və ya digər hesablarından dövlət büdcəsinə artıq alınmış vəsaitin geri qaytarılması bu Məcəllənin 87-ci maddəsi ilə müəyyən edilmiş qaydada həyata keçirilir.',
        23, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '65'), '65.10',
        'Vergi orqanları Azərbaycan Respublikasının tərəfdar çıxdığı beynəlxalq müqavilələrin tələblərinin yerinə yetirilməsi məqsədilə xarici dövlətlərin vergi orqanlarının müraciətinə əsasən həmin xarici dövlətdə yaranmış vergi borcunun alınması ilə bağlı bu Məcəllənin 65.1 – 65.9-cu maddələrində nəzərdə tutulmuş tədbirləri həyata keçirirlər.',
        24, false, NOW(), NOW());

