-- Maddə 67
INSERT INTO tax_articles (article_number, title, chapter, active, created_at, updated_at)
VALUES ('67',
        'Vergitutma obyektinin ayrı-ayrı hallarda müəyyən edilməsi qaydaları',
        'VII fəsil. Vergilərin ödənilməsi üzrə ümumi qaydalar',
        true, NOW(), NOW());

INSERT INTO tax_sections (article_id, section_number, content, order_index, synced_to_vector_store, created_at,
                          updated_at)
VALUES ((SELECT id FROM tax_articles WHERE article_number = '67'), '67.1',
        'Bu Məcəllənin 37.4-cü və 50.1.1-ci maddələrində göstərilən hallarda, habelə səyyar vergi yoxlamasının aparılması zamanı sənədlər təqdim edilmədikdə, ərazi və ya binalara (yaşayış binası (sahəsi) istisna olmaqla) daxil olmağa icazə verilmədikdə, mühasibat uçotunu aparmadıqda və ya mühasibat uçotunu müəyyən edilmiş qaydada aparmadıqda, mühasibat uçotu və hesabat sənədləri məhv olunduqda (itirildikdə), həmçinin vergitutma obyektinin müəyyənləşdirilməsi hər hansı başqa səbəblərdən mümkün olmadıqda, vergi orqanlarının ödənilməli olan verginin məbləğini aşağıda göstərilən əlaqəli məlumatlardan istifadə etməklə hesablamaq hüququ vardır:',
        1, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '67'), '67.1.1',
        'vergi ödəyicisi tərəfindən vergi orqanına əvvəlki hesabat dövrləri üçün təqdim edilmiş vergi bəyannamələri;',
        2, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '67'), '67.1.2',
        'vergi ödəyicisinin gəlirləri, o cümlədən satışdankənar gəlirləri barədə rəsmi məlumatlar;',
        3, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '67'), '67.1.3',
        'vergi ödəyicisinin xərcləri, o cümlədən fərdi istehlakı üçün malların (daşınar və daşınmaz əmlakın), işlərin və xidmətlərin alınmasına çəkilən xərcləri barədə rəsmi məlumatlar;',
        4, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '67'), '67.1.4',
        'vergi ödəyicisinin mülkiyyətində və ya istifadəsində olan maddi və qeyri-maddi əmlak barədə rəsmi məlumatlar;',
        5, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '67'), '67.1.5',
        'vergi ödəyicisi tərəfindən istehsal olunmuş və (və ya) təqdim edilmiş malların (işlərin, xidmətlərin) fiziki həcmi barədə rəsmi məlumatlar;',
        6, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '67'), '67.1.6',
        'vergi ödəyicisinin idxal-ixrac əməliyyatları barədə rəsmi məlumatlar;',
        7, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '67'), '67.1.7',
        'vergi ödəyicisinin bank və digər ödəniş hesablarındakı vəsaitlər, o cümlədən bank və digər ödəniş hesablarındakı vəsaitlərin hərəkəti barədə alınan rəsmi məlumatlar;',
        8, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '67'), '67.1.8',
        'vergi ödəyicisində aparılmış xronometraj müşahidələrin nəticələri;',
        9, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '67'), '67.1.9',
        'vergi orqanının əldə etdiyi mənbəyi bəlli olan hər hansı digər məlumatlar, o cümlədən vergi orqanı tərəfindən həyata keçirilən vergi nəzarəti tədbirləri zamanı əldə edilmiş vergi ödəyicisinin sahibkarlıq fəaliyyəti ilə bağlı qanunla nəzərdə tutulmuş qaydada rəsmiləşdirilməyən əməliyyatlar üzrə məlumatlar.',
        10, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '67'), '67.2',
        'Vergi ödəyicisi tərəfindən ödənilməli olan verginin (mənfəət və gəlir vergisi istisna olmaqla) əlaqəli məlumatlara əsasən müəyyənləşdirilməsi üçün aşağıda göstərilən meyarlar nəzərə alınmaqla vergi ödəyicisinin fəaliyyətinə analoji fəaliyyətlə məşğul olan vergi ödəyicisinin vergi orqanında olan məlumatlarından istifadə edilir:',
        11, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '67'), '67.2.1',
        'eyni xüsusiyyətli və ya eyni cinsli malların istehsalı;',
        12, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '67'), '67.2.2',
        'eyni xüsusiyyətli və ya eyni cinsli malların təqdim edilməsi, işlərin görülməsi və xidmətlərin göstərilməsi;',
        13, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '67'), '67.2.3',
        'fəaliyyət göstərilən ərazi.',
        14, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '67'), '67.3',
        'Vergilər əlaqəli məlumatlar və analoji vergi ödəyicisi barədə məlumatlar əsasında hesablandıqda, verginin məbləği vergi ödəyicisinin müvafiq olaraq gəlirinin, yaxud gəlirdən çıxılan xərclərinin məbləğini analoji fəaliyyətlə məşğul olan vergi ödəyicisinin həmin hesabat dövründə gəlirində, yaxud gəlirdən çıxılan xərclərində verginin xüsusi çəkisini göstərən əmsala vurmaqla müəyyənləşdirilir.',
        15, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '67'), '67.3-1',
        'Vergi ödəyicisi tərəfindən vergiyə cəlb edilən gəlirlər rəsmiləşdirilmədikdə, lakin gəlirdən çıxılan xərclərə dair əlaqəli məlumatlar mövcud olduqda vergi tutulan mənfəət (gəlir) 50 faiz həcmində rentabellik nəzərə alınmaqla hesablanır.',
        16, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '67'), '67.4',
        'Vergi ödəyicisi barədə əlaqəli məlumatları əldə etmək mümkün olmadıqda, vergilər analoji fəaliyyətlə məşğul olan vergi ödəyicilərinin uçot və hesabat məlumatları əsasında hesablanır.',
        17, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '67'), '67.5',
        'Muzdla işləyən fiziki şəxslərin gəlir vergisini əlaqəli məlumata əsasən hesablamaq qeyrı-mümkün olduqda və ya fiziki şəxslərin işləməsi rəsmiləşdirilmədikdə vergi orqanı gəlir vergisinin məbləğini ötən ilin ölkə üzrə orta aylıq əmək haqqı əsasında hesablayır.',
        18, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '67'), '67.6',
        'Verginin hesablanması üçün vergi ödəyicisi barədə vergi orqanında bir neçə əlaqəli məlumat olduqda, ən yuxarı məbləğdə verginin hesablanmasına əsas verən əlaqəli məlumata əsasən vergi hesablanır.',
        19, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '67'), '67.7',
        'Əlaqəli məlumata əsasən vergi hesablanarkən, vergi ödəyicisinin artıq ödənilmiş vergiləri, faizləri və maliyyə sanksiyaları nəzərə alınır.',
        20, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '67'), '67.8',
        'Bu Məcəllənin 16.2-ci maddəsinə uyğun olaraq sahibkarlıq fəaliyyəti, əmlakının, torpağının və vergi tutulan əməliyyatının olmaması barədə vergi orqanına arayış təqdim etmiş vergi ödəyicilərinə əlaqəli məlumatlar əsasında vergilər hesablanmır.',
        21, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '67'), '67.9',
        'Əlaqəli məlumatlara əsasən hesablanmış vergilərə dair bəyannamələr vergi orqanına təqdim edildikdən sonra, hesablanmış vergilər bəyannamələr nəzərə alınmaqla yenidən hesablanır.',
        22, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '67'), '67.10',
        'Əlaqəli məlumatlara əsasən hesablanmış vergilərin alınması bu Məcəllənin 65-ci maddəsinə uyğun olaraq həyata keçirilir.',
        23, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '67'), '67.11',
        'Qarşılıqlı surətdə asılı olan şəxslər arasında hər hansı əməliyyat aparıldıqda, vergi orqanı müstəqil şəxslər arasındakı əməliyyatlar zamanı əldə edilə bilən vergi tutulan gəliri müəyyənləşdirmək üçün gəlirləri və ya xərcləri həmin şəxslər arasında bölə bilər.',
        24, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '67'), '67.12',
        'Şəxs fərdi istehlakına, o cümlədən əmlak alınmasına çəkilən xərclərin ödənilməsi üçün kifayət olmayan məbləğdə gəlir əldə etdiyini bildirirsə, vergi orqanı gəliri və vergiləri həmin şəxsin əvvəlki dövrlərdəki gəlirlərini, habelə kredit və borclarını nəzərə almaqla çəkdiyi xərclərə əsasən müəyyənləşdirir.',
        25, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '67'), '67.13',
        'Verginin məqsədləri üçün barter əməliyyatları malların (işlərin, xidmətlərin) bazar qiymətləri ilə satışı kimi qiymətləndirilir. Barter əməliyyatının elektron qaimə-fakturada göstərilən məbləği azaldılmışdırsa, vergi orqanı vergitutma obyektlərini bazar qiymətləri nəzərə alınmaqla dəqiqləşdirir, verginin məbləğini yenidən hesablayır və Azərbaycan Respublikasının vergi qanunvericiliyinin pozulmasına görə nəzərdə tutulan sanksiyaları tətbiq edir.',
        26, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '67'), '67.14',
        'Bu Məcəllənin 67.1-ci maddəsində göstərilən hallarda vergi ödəyicisinin gəlirlərini və ya xərclərini müəyyən etmək mümkün olduqda mənfəət (gəlir) vergisi bu Məcəllənin 83.9-cu maddəsinə əsasən hesablanır.',
        27, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '67'), '67.15',
        'Vergi orqanı tərəfindən keçirilən vergi nəzarəti (o cümlədən üfüqi monitorinq) zamanı vergi ödəyicisinin uçot məlumatlarında (mühasibat uçotu və ilkin uçot sənədlərində) göstərilən malların faktiki olaraq onun sahibliyində olmadığı aşkar edildikdə vergilər həmin halın aşkar edildiyi hesabat dövrü üzrə, səyyar vergi yoxlaması zamanı isə yoxlama ilə əhatə edilən sonuncu hesabat dövrü üzrə hesablanır. Bu maddənin məqsədləri üçün təqdim edilən mallar bir əqd və ya müqavilə üzrə təqdim edilmiş hesab edilir.',
        28, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '67'), '67.16',
        'Bina tikintisi fəaliyyəti ilə məşğul olan şəxslərdə keçirilən səyyar vergi yoxlaması zamanı yaşayış və qeyri-yaşayış sahələrinin təqdim edilməsi aşkar edildikdə, vergitutma məqsədləri üçün aşağıdakı hallarda yaşayış və qeyri-yaşayış sahələri yoxlamanın əhatə etdiyi sonuncu hesabat dövründə təqdim edilmiş sayılır:',
        29, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '67'), '67.16.1',
        'bu Məcəllənin 16.8-ci maddəsində nəzərdə tutulan məlumat səyyar vergi yoxlamasının başlandığı günədək təqdim edilmədikdə;',
        30, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '67'), '67.16.2',
        'bu Məcəllənin 16.8-ci maddəsində nəzərdə tutulan məlumatı təqdim edən, lakin təqdim edilən məlumatda yaşayış və qeyri-yaşayış sahələrinin təqdim edilmədiyi göstərildikdə.',
        31, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '67'), '67.17',
        'Bu Məcəllənin 67-ci maddəsində sadalanan vergitutma obyektinin müəyyən edilməsi ilə bağlı ayrı-ayrı halları tənzimləyən maddələr bu maddədə sıra üzrə ardıcıllıq gözlənilmədən tətbiq edilir.',
        32, false, NOW(), NOW());

-- Maddə 67-1
INSERT INTO tax_articles (article_number, title, chapter, active, created_at, updated_at)
VALUES ('67-1',
        'Sənaye, yaxud texnologiyalar parklarında vergitutma',
        'VII fəsil. Vergilərin ödənilməsi üzrə ümumi qaydalar',
        true, NOW(), NOW());

INSERT INTO tax_sections (article_id, section_number, content, order_index, synced_to_vector_store, created_at,
                          updated_at)
VALUES ((SELECT id FROM tax_articles WHERE article_number = '67-1'), '67-1.1',
        'Sənaye, yaxud texnologiyalar parklarının rezidenti sənaye, yaxud texnologiyalar parklarında yerləşən təsərrüfat və digər vergitutma obyektlərini bu Məcəllə ilə müəyyən edilmiş güzəşt müddəti bitənədək təqdim etdikdə:',
        1, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '67-1'), '67-1.1.1',
        'əvvəlki rezidentin mövcud investisiya layihəsinə uyğun olaraq mal (iş, xidmət) istehsalına başlamağı və ya davam etdirməyi öhdəsinə götürən təsərrüfat və digər vergitutma obyektlərini əldə edən yeni rezidentə vergi güzəştləri həmin müddətin qalan hissəsi ərzində verilir;',
        2, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '67-1'), '67-1.1.2',
        'yeni investisiya layihəsinə uyğun olaraq digər növ mal (iş, xidmət) istehsalını təşkil etməyi və müvafiq icra hakimiyyəti orqanının müəyyən etdiyi məbləğdən az olmayan sərmayə qoyuluşunu öhdəsinə götürən təsərrüfat və digər vergitutma obyektlərini əldə edən yeni rezidentə vergi güzəştləri bu Məcəllə ilə nəzərdə tutulmuş tam müddət ərzində verilir.',
        3, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '67-1'), '67-1.2',
        'Sənaye, yaxud texnologiyalar parklarının rezidenti sənaye, yaxud texnologiyalar parklarında yerləşən təsərrüfat və digər vergitutma obyektlərini bu Məcəllə ilə müəyyən edilmiş güzəşt müddəti bitəndən sonra təqdim etdikdə:',
        4, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '67-1'), '67-1.2.1',
        'əvvəlki rezidentin mövcud investisiya layihəsinə uyğun olaraq mal (iş, xidmət) istehsalını davam etdirən təsərrüfat və digər vergitutma obyektlərini əldə edən yeni rezidentə vergi güzəştləri verilmir;',
        5, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '67-1'), '67-1.2.2',
        'yeni investisiya layihəsinə uyğun olaraq digər növ mal (iş, xidmət) istehsalını təşkil etməyi və müvafiq icra hakimiyyəti orqanının müəyyən etdiyi məbləğdən az olmayan sərmayə qoyuluşunu öhdəsinə götürən təsərrüfat və digər vergitutma obyektlərini əldə edən yeni rezidentə vergi güzəştləri bu Məcəllə ilə nəzərdə tutulmuş tam müddət ərzində verilir.',
        6, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '67-1'), '67-1.3',
        'Sənaye, yaxud texnologiyalar parklarının rezidenti yeni investisiya layihəsinə əsasən sənaye, yaxud texnologiyalar parklarında digər istehsal sahəsi qurduqda, bu Məcəllə ilə müəyyən edilmiş vergi güzəştləri rezidentin sənaye, yaxud texnologiyalar parklarında müvafiq icra hakimiyyəti orqanı tərəfindən müəyyən edilmiş qaydada yeni investisiya layihəsi üzrə qeydiyyata alındığı tarixdən hesablanır. Bu halda bu Məcəllə ilə müəyyən edilmiş vergi güzəştləri yeni investisiya layihəsi üzrə fəaliyyətə şamil olunur.',
        7, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '67-1'), '67-1.4',
        'Sənaye, yaxud texnologiyalar parklarının rezidenti vergi güzəştlərinin tətbiq olunduğu dövrdə sənaye, yaxud texnologiyalar parklarından kənarda fəaliyyət göstərdikdə həmin fəaliyyətlə bağlı gəlirlərin və xərclərin uçotunu ayrıca aparmalıdır. Bu zaman sənaye, yaxud texnologiyalar parklarının rezidenti bu parklardan kənarda göstərdiyi fəaliyyətə görə əldə etdiyi gəlirlərdən vergiləri Vergi Məcəlləsi ilə müəyyən edilmiş ümumi qaydada ödəyir.',
        8, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '67-1'), '67-1.5',
        'Bu Məcəllənin 67-1.3-cü maddəsində nəzərdə tutulan halda sənaye, yaxud texnologiyalar parklarının rezidenti yeni investisiya layihəsinə əsasən sənaye, yaxud texnologiyalar parklarında qurduğu digər istehsal sahəsinin fəaliyyəti ilə bağlı gəlirlərin və xərclərin uçotunu vergi güzəştlərinin tətbiq olunduğu dövrdə ayrıca aparmalıdır.',
        9, false, NOW(), NOW());

-- Maddə 67-2
INSERT INTO tax_articles (article_number, title, chapter, active, created_at, updated_at)
VALUES ('67-2',
        'İnvestisiya təşviqi sənədini almış hüquqi şəxslərdən və fərdi sahibkarlardan vergitutma',
        'VII fəsil. Vergilərin ödənilməsi üzrə ümumi qaydalar',
        true, NOW(), NOW());

INSERT INTO tax_sections (article_id, section_number, content, order_index, synced_to_vector_store, created_at,
                          updated_at)
VALUES ((SELECT id FROM tax_articles WHERE article_number = '67-2'), '67-2.1',
        'İnvestisiya təşviqi sənədini almış şəxs təsərrüfat və digər vergitutma obyektlərini bu Məcəllə ilə müəyyən edilmiş güzəşt müddəti bitənədək təqdim etdikdə, mövcud investisiya layihəsinə uyğun olaraq mal (iş, xidmət) istehsalına başlamağı və ya davam etdirməyi öhdəsinə götürən təsərrüfat və digər vergitutma obyektlərini əldə edən yeni şəxsə vergi güzəştləri həmin müddətin qalan hissəsi ərzində verilir.',
        1, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '67-2'), '67-2.2',
        'İnvestisiya təşviqi sənədini əvvəllər almış şəxs yeni investisiya layihəsinə əsasən istehsal sahəsi qurduqda, bu Məcəllə ilə müəyyən edilmiş vergi güzəştləri şəxsin yeni investisiya layihəsi üzrə investisiya təşviqi sənədinin alındığı tarixdən hesablanır.',
        2, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '67-2'), '67-2.3',
        'İnvestisiya təşviqi sənədini almış şəxs vergi güzəştlərinin tətbiq olunduğu dövrdə investisiya layihəsinə aid olmayan fəaliyyət göstərdikdə, həmin fəaliyyətlə bağlı gəlirlərin və xərclərin uçotunu ayrıca aparır və bu fəaliyyətə görə əldə etdiyi gəlirlərdən vergiləri bu Məcəllə ilə müəyyən edilmiş ümumi qaydada ödəyir.',
        3, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '67-2'), '67-2.4',
        'İnvestisiya layihəsinin həcmi ilə bağlı minimal məbləğ investisiya edilmədikdə, habelə müvafiq icra hakimiyyəti orqanının müəyyən etdiyi orqan (qurum) tərəfindən müəyyən edilmiş qaydada nəzərdə tutulan hallarda investisiya təşviqi sənədi ləğv edildikdə, vergilər üzrə faizlərin ödənilməsi istisna olmaqla, investisiya layihəsinin icrasına başlandığı tarixdən etibarən bu Məcəllə ilə müəyyən edilmiş vergi azadolmaları tətbiq edilən gəlirlər və əməliyyatlar üzrə vergilərin hesablanması və dövlət büdcəsinə ödənilməsi investisiya təşviqi sənədi verilmiş şəxslər tərəfindən yerinə yetirilir. Bu zaman yenidən hesablanmalı vergilərin məbləği investisiya təşviqi sənədinin ləğv edildiyi hesabat dövründə və ya vergi nəzarəti zamanı bu hal aşkar edildiyi halda yoxlama ilə əhatə edilən sonuncu hesabat dövründə həyata keçirilir.',
        4, false, NOW(), NOW());

-- Maddə 68
INSERT INTO tax_articles (article_number, title, chapter, active, created_at, updated_at)
VALUES ('68',
        'Müddətlərin müəyyən edilməsi qaydası',
