        true, NOW(), NOW());

INSERT INTO tax_sections (article_id, section_number, content, order_index, synced_to_vector_store, created_at,
                          updated_at)
VALUES ((SELECT id FROM tax_articles WHERE article_number = '68'), '68.1',
        'Bu Məcəllədə müəyyən edilən hər hansı müddətin axımı onun hesablanmasını şərtləndirən hüquqi hərəkətin və ya faktiki hadisənin həyata keçirildiyi sonrakı gündən başlanır.',
        1, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '68'), '68.2',
        'Hər hansı müddət bu Məcəllədə göstərilən dövrün sonuncu gününün axırında bitir. Bu Məcəllədə nəzərdə tutulan hər hansı müddət qeyri-iş gününə təsadüf edərsə, həmin müddət onun ardınca gələn ən yaxın növbəti iş gününə keçir.',
        2, false, NOW(), NOW());

-- Maddə 69
INSERT INTO tax_articles (article_number, title, chapter, active, created_at, updated_at)
VALUES ('69',
        'Xarici valyutanın manatla hesablanması',
        'VII fəsil. Vergilərin ödənilməsi üzrə ümumi qaydalar',
        true, NOW(), NOW());

INSERT INTO tax_sections (article_id, section_number, content, order_index, synced_to_vector_store, created_at,
                          updated_at)
VALUES ((SELECT id FROM tax_articles WHERE article_number = '69'), '69.1',
        'Xarici valyuta ilə aparılan və vergiyə cəlb etməyə aid olan hər hansı əməliyyat onun həyata keçirildiyi gün Azərbaycan Respublikasının Mərkəzi Bankının rəsmi mübadilə məzənnəsi ilə manatla hesablanır.',
        1, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '69'), '69.2',
        'Xarici valyuta ilə aparılan və vergiyə cəlb etməyə aid olan əməliyyatlar üzrə yaranan məzənnə fərqi əməliyyatın həyata keçirildiyi günlə malların (işlərin, xidmətlərin) dəyərinin ödənildiyi günə olan məzənnə arasındakı fərqlə müəyyən edilir. Hesabat ilinin sonuna xarici valyutada alınmış və təqdim edilmiş mallar (işlər və xidmətlər) üzrə yaranan debitor və kreditor borcları üzrə məzənnə fərqi Azərbaycan Respublikasının Mərkəzi Bankının elan etdiyi məzənnə ilə qiymətləndirilməklə gəlirə və ya zərərə aid edilir. Vergi ödəyicisinin xarici valyutada olan pul vəsaitləri təqvim ilinin sonu vəziyyətinə Azərbaycan Respublikası Mərkəzi Bankının elan etdiyi rəsmi məzənnə ilə hesablanmaqla müəyyən edilir.',
        2, false, NOW(), NOW());

