INSERT INTO tax_articles (article_number, title, chapter, active, created_at, updated_at)
VALUES ('70',
        'Vergi ödəyiciləri ilə yazışma',
        'VII fəsil. Vergilərin ödənilməsi üzrə ümumi qaydalar',
        true, NOW(), NOW());

INSERT INTO tax_sections (article_id, section_number, content, order_index, synced_to_vector_store, created_at,
                          updated_at)
VALUES ((SELECT id FROM tax_articles WHERE article_number = '70'), '70.1',
        'Vergi orqanının vergi ödəyicisinə və ya vergi ödəyicisinin vergi orqanına tələbi yazılı şəkildə və ya elektron formada tərtib edilməmişdirsə və bir tərəf onu digər tərəfə verməmişdirsə, belə tələblərin heç biri vergi orqanı və ya vergi ödəyicisi üçün hüquqi qüvvəyə malik deyildir.',
        1, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '70'), '70.1-1',
        'Dövlət informasiya ehtiyatlarının, sistemlərinin və elektron xidmətlərin vahid reyestrinə daxil edilmiş elektron xidmətlərlə bağlı vergi ödəyiciləri tərəfindən vergi orqanlarına göndərilən sənədlər yalnız elektron kabinet vasitəsilə elektron qaydada təqdim olunur.',
        2, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '70'), '70.2',
        'Vergi orqanının vergi ödəyicisinə göndərdiyi hər hansı qərar, akt, bildiriş, tələbnamə, məktub və ya digər sənədlər (onların surətləri) adı göstərilməklə vergi orqanının rəhbəri (onun müavini) tərəfindən imzalanmalı və möhürlə təsdiq edilməlidir. Elektron üsulla göndərilən sənədlərin möhürlə təsdiq edilməsi tələb olunmur.',
        3, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '70'), '70.2-1',
        'Sənədlər (onların surətləri) vergi orqanı tərəfindən vergi ödəyicisinə aşağıdakı formalardan birinə uyğun göndərildikdə (verildikdə), lazımi qaydada çatdırılmış sayılır:',
        4, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '70'), '70.2-1.1',
        'vergi ödəyicisinə (onun səlahiyyətli nümayəndəsinə) şəxsən verildikdə – şəxsən verildiyi gün;',
        5, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '70'), '70.2-1.2',
        'poçt rabitəsi vasitəsilə vergi ödəyicisi olan hüquqi şəxsin dövlət qeydiyyatı haqqında sənədlərində və ya vergi ödəyicisi olan fiziki şəxsin uçot sənədlərində sonuncu ünvan kimi qeyd olunmuş ünvanına göndərildikdə – poçta təqdim edildiyi gündən 5 iş günü keçdikdən sonra;',
        6, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '70'), '70.2-1.3',
        'elektron üsulla elektron kabinetinə göndərildikdə – elektron üsulla göndərildiyi gündən 3 iş günü keçdikdən sonra.',
        7, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '70'), '70.2-2',
        'Sənədlər (onların surətləri) bu Məcəllənin 70.2-1.1-ci maddəsinə əsasən şəxsən verildikdə, vergi ödəyicisinə (onun səlahiyyətli nümayəndəsinə) verilmə tarixini təsdiq edən üsulla təqdim edilir.',
        8, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '70'), '70.2-3',
        'Bu Məcəllənin 70.2-1.2-ci və 70.2-1.3-cü maddələrində nəzərdə tutulmuş qayda vergi ödəyicisinin (onun səlahiyyətli nümayəndəsinin) inzibati aktı almadığı və ya gec aldığı hallara şamil olunmur.',
        9, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '70'), '70.2-4',
        'Vergi ödəyicilərinin müraciətlərinə vergi orqanının cavabları elektron üsulla vergi ödəyicisinin elektron kabinetinə göndərilir. Vergi ödəyicisinin müraciəti əsasında həmin cavabların kağız daşıyıcıda olan surəti ona verilir.',
        10, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '70'), '70.3',
        'Vergi hesablamalarına dair sənədlərin və ya vergi qanunvericiliyinə əsasən tərtib edilən digər sənədlərin heç biri, aşağıdakılara əməl edildiyi halda, etibarsız və ya prosessual pozuntularla tərtib edilmiş sayıla bilməz:',
        11, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '70'), '70.3.1',
        'onlar öz məzmununa və mahiyyətinə görə vergi qanunvericiliyinə uyğun gəlirsə; və',
        12, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '70'), '70.3.2',
        'vergi hesablanılan və ya bu sənədlərin aid olduğu şəxs hamı üçün aydın şəkildə göstərilmişdirsə.',
        13, false, NOW(), NOW());

