INSERT INTO tax_sections (article_id, section_number, content, order_index, synced_to_vector_store, created_at,
                          updated_at)
VALUES ((SELECT id FROM tax_articles WHERE article_number = '71-1'), '71-1.1',
        'Bu Məcəllə ilə müəyyən edilən hallarda malları təqdim edən (göndərən), işləri görən və xidmətləri göstərən, habelə malların təsərrüfatdaxili yerdəyişməsini həyata keçirən vergi orqanında uçotda olan şəxs elektron qaimə-fakturanı aşağıdakı müddətlərdə təqdim (tərtib) etməlidir:',
        1, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '71-1'), '71-1.1.1',
        'bu Məcəllənin 71-1.5.1-ci, 71-1.5.4-cü, 71-1.5.5-ci, 71-1.5.7-ci və 71-1.5.8-ci maddələrində nəzərdə tutulmuş hallarda – mallar göndərilən (verilən) vaxt;',
        2, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '71-1'), '71-1.1.2',
        'əvvəlcədən sifariş edilməyən malların təqdim edilməsi üzrə – malların təhvil verilməsini təsdiq edən sənədin verildiyi tarixdən 5 gün müddətində;',
        3, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '71-1'), '71-1.1.3',
        'işlərin görülməsi və xidmətlərin (beynəlxalq daşıma xidmətləri, habelə müntəzəm və daimi əsaslarda göstərilən xidmətlər istisna olmaqla) göstərilməsi üzrə – işlərin görüldüyü və xidmətlərin göstərildiyi tarixdən 5 gün müddətində;',
        4, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '71-1'), '71-1.1.3-1',
        'beynəlxalq daşıma xidmətlərinin göstərilməsi üzrə – daşıma xidmətlərinin başlanıldığı vaxtadək;',
        5, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '71-1'), '71-1.1.3-2',
        'müntəzəm və daimi əsaslarda göstərilən xidmətlər üzrə – hər təqvim ayı üçün xidmətlərin göstərilməsinə başlanıldığı vaxt;',
        6, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '71-1'), '71-1.1.4',
        'bu Məcəllənin 71-1.5.2-ci, 71-1.5.3-cü və 71-1.5.6-cı maddələrində nəzərdə tutulmuş hallarda – malların qaytarıldığı və vergi tutulan dövriyyənin dəqiqləşdirildiyi vaxtdan 3 gün müddətində;',
        7, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '71-1'), '71-1.1.5',
        'bu Məcəllənin 71-1.5.12-ci maddəsində nəzərdə tutulmuş halda – avansın alındığı vaxtadək.',
        8, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '71-1'), '71-1.2',
        'Elektron qaimə-fakturanın forması, tətbiqi, uçotu və istifadəsi qaydaları müvafiq icra hakimiyyəti orqanı tərəfindən müəyyən edilir.',
        9, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '71-1'), '71-1.3',
        'Əcnəbilər və vətəndaşlığı olmayan şəxslər tərəfindən Azərbaycan Respublikasının ərazisində alınmış, istehsal, yaxud kommersiya məqsədləri üçün nəzərdə tutulmayan mallara, habelə tibb müəssisələri və özəl tibbi praktika ilə məşğul olan fiziki şəxslər tərəfindən əcnəbilər və vətəndaşlığı olmayan şəxslərə göstərilən tibbi xidmətlərə görə ödənilmiş əlavə dəyər vergisinin qaytarılması üçün elektron qaimə-fakturanın vahid forması müvafiq icra hakimiyyəti orqanının müəyyən etdiyi orqan (qurum) tərəfindən təsdiq edilir.',
        10, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '71-1'), '71-1.3-1',
        'Fiziki şəxs olan istehlakçılar tərəfindən Azərbaycan Respublikasının ərazisində bina tikintisi fəaliyyəti ilə məşğul olan şəxslərdən nağdsız qaydada alınmış yaşayış və qeyri-yaşayış sahələrinə görə ödənilmiş ƏDV-nin qaytarılması üçün elektron qaimə-fakturanın vahid forması müvafiq icra hakimiyyəti orqanının müəyyən etdiyi orqan (qurum) tərəfindən təsdiq edilir.',
        11, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '71-1'), '71-1.4',
        'Ticarət festivalları dövründə fiziki şəxslər tərəfindən Azərbaycan Respublikasının ərazisində alınmış, istehsal, yaxud kommersiya məqsədləri üçün nəzərdə tutulmayan mallara görə ödənilmiş əlavə dəyər vergisinin qaytarılması üçün elektron qaimə-fakturanın vahid forması müvafiq icra hakimiyyəti orqanının müəyyən etdiyi orqan (qurum) tərəfindən təsdiq edilir.',
        12, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '71-1'), '71-1.5',
        'Vergi ödəyicisi tərəfindən aparılan əməliyyatlar zamanı əməliyyatın xarakterindən asılı olaraq aşağıdakı növdə elektron qaimə-faktura verilir:',
        13, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '71-1'), '71-1.5.1',
        'malların, işlərin və xidmətlərin təqdim edilməsi barədə;',
        14, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '71-1'), '71-1.5.2',
        'malların qaytarılması barədə;',
        15, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '71-1'), '71-1.5.3',
        'malların qaytarılması istisna olmaqla, bu Məcəllənin 163-cü maddəsinə əsasən verilən;',
        16, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '71-1'), '71-1.5.4',
        'malların (işlərin, xidmətlərin) vəkalət verən (komitent) tərəfindən agentə (komisyonçuya) verilməsi barədə;',
        17, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '71-1'), '71-1.5.5',
        'agent (komisyonçu) tərəfindən malların (işlərin, xidmətlərin) alıcısına (subagentə) təqdim edilən;',
        18, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '71-1'), '71-1.5.6',
        'agent (komisyonçu) tərəfindən malların (işlərin, xidmətlərin) vəkalət verənə (komitentə) qaytarılması barədə;',
        19, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '71-1'), '71-1.5.7',
        'malların emala, yaxud saxlamaya verilməsi barədə;',
        20, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '71-1'), '71-1.5.8',
        'emal prosesi keçmiş, yaxud saxlamaya verilmiş malların qaytarılması barədə;',
        21, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '71-1'), '71-1.5.9',
        'bu Məcəllənin 177.5-ci maddəsinə əsasən verilən;',
        22, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '71-1'), '71-1.5.10',
        'aksizli malların (neft məhsulları istisna olmaqla) təsərrüfatdaxili yerdəyişməsi barədə;',
        23, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '71-1'), '71-1.5.11',
        'ixrac qeydi ilə satış barədə.',
        24, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '71-1'), '71-1.5.12',
        'alınmış avans ödənişləri barədə.',
        25, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '71-1'), '71-1.6',
        'Bu Məcəllənin 71-1.5.10-cu maddəsində nəzərdə tutulan növdə elektron qaimə-faktura aksizli malların istehsalçıları və ya idxalçıları tərəfindən tərtib edilir.',
        26, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '71-1'), '71-1.7',
        'Agent (komisyonçu) tərəfindən malların (işlərin, xidmətlərin) subagentə verilməsi, habelə subagent tərəfindən malların (işlərin, xidmətlərin) alıcıya təqdim edilməsi zamanı bu Məcəllənin 71-1.5.5-ci maddəsinə uyğun olaraq elektron qaimə-faktura tərtib edilir və müvafiq olaraq əməliyyatın subagentə ötürülməsi və subagent tərəfindən aparılması ilə bağlı qeyd aparılır.',
        27, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '71-1'), '71-1.8',
        'Aksizli malların istehsalçısı tərəfindən aksizli malların istehsal binasının hüdudlarından ona məxsus digər təsərrüfat subyektlərinə (obyektlərinə), yaxud əvvəlcədən sifariş edilməyən əməliyyatlar üzrə nəqliyyat vasitələrinə buraxılışı bu Məcəllənin 71-1.5.10-cu maddəsində nəzərdə tutulmuş növdə elektron qaimə-faktura ilə rəsmiləşdirilir.',
        28, false, NOW(), NOW());


