INSERT INTO tax_sections (article_id, section_number, content, order_index, synced_to_vector_store, created_at,
                          updated_at)
VALUES ((SELECT id FROM tax_articles WHERE article_number = '71-3'), '71-3.1',
        '"Avtomobil nəqliyyatı haqqında" Azərbaycan Respublikasının Qanununa uyğun olaraq əmtəə təyinatlı yüklərin daşınmasına görə elektron əmtəə-nəqliyyat qaiməsi və yük avtonəqliyyatı üçün elektron yol vərəqi tərtib edilir.',
        1, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '71-3'), '71-3.2',
        'Elektron əmtəə-nəqliyyat qaiməsinin və yük avtonəqliyyatı üçün elektron yol vərəqinin forması, tətbiqi, uçotu və istifadəsi qaydası müvafiq icra hakimiyyəti orqanının müəyyən etdiyi orqan (qurum) tərəfindən təsdiq edilir.',
        2, false, NOW(), NOW());


-- =========================================================
-- Maddə 72. Vergi hesabatının tərtib edilməsi və verilməsi qaydası
-- =========================================================
INSERT INTO tax_articles (article_number, title, chapter, active, created_at, updated_at)
VALUES ('72',
        'Vergi hesabatının tərtib edilməsi və verilməsi qaydası',
        'VII fəsil. Vergilərin ödənilməsi üzrə ümumi qaydalar',
        true, NOW(), NOW());

INSERT INTO tax_sections (article_id, section_number, content, order_index, synced_to_vector_store, created_at,
                          updated_at)
VALUES ((SELECT id FROM tax_articles WHERE article_number = '72'), '72.1',
        'Bu Məcəllənin məqsədləri üçün vergi hesabatı vergi bəyannaməsindən ibarətdir.',
        1, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '72'), '72.2',
        'Bu Məcəlləyə və ona müvafiq olaraq qəbul edilmiş qanunlara uyğun olaraq vergi hesabatını verməyə borclu olan vergi ödəyiciləri vergi hesabatını bu Məcəllədə göstərilən müddətlərdə müvafiq icra hakimiyyəti orqanının müəyyənləşdirdiyi formada və yerdə vergi orqanına verməlidirlər.

Vergi hesabatları vergi ödəyicisi tərəfindən şəxsən və ya hesabatın təqdim edilməsi təsdiq oluna bilən hər hansı digər üsulla (rabitə təşkilatına təhvil verilməsi və ya müvafiq qanunvericiliyə uyğun olaraq elektron sənəd formasında göndərilməsi də daxil olmaqla) təqdim edilə bilər.

Vergi hesabatının elektron sənəd formasında göndərilməsi müvafiq icra hakimiyyəti orqanının müəyyən etdiyi qaydada həyata keçirilir. Vergi hesabatını elektron sənəd formasında təqdim edən vergi ödəyicilərinə bu Məcəllənin 72.3-cü, 72.4-cü 72.6.3-cü və 72.6.4-cü maddələrinin müddəaları şamil edilmir.',
        2, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '72'), '72.3',
        'Vergi hesabatını vergi ödəyicisi, yaxud onun müəyyən edilmiş qaydada vəkil edilmiş nümayəndəsi imzalamalıdır.',
        3, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '72'), '72.4',
        'Qanunvericiliyə müvafiq olaraq vergi ödəyicisinin vergi hesabatının tərtib edilməsində müstəqil auditor iştirak edirsə o, vergi hesabatını imzalamalı, möhür vurmalı və öz vergi ödəyicisinin eyniləşdirmə nömrəsini göstərməlidir. Hesabatı bir nəfərdən çox tərtibatçı hazırlayırsa, onu ancaq baş tərtibatçı imzalayır.',
        4, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '72'), '72.4-1',
        'Bu Məcəllənin 163-cü maddəsində nəzərdə tutulan hallarda vergilərin dəqiqləşdirilməsi qiymətləndirmə bazasında dəyişikliyin baş verdiyi hesabat dövründə aparılır və hesabat dövrü üzrə vergi ödəyicisi tərəfindən təqdim edilmiş bəyannamədə dəqiqləşdirilir.',
        5, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '72'), '72.5',
        'Bu Məcəllənin 163-cü maddəsində nəzərdə tutulan hallar istisna olmaqla əvvəlki hesabat dövrləri üzrə təqdim edilmiş hesabatlardakı məlumatlar ilkin uçot sənədləri üzrə məlumatlara uyğun olmadığı hallarda vergi ödəyiciləri tərəfindən həmin hesabat dövrü üçün dəqiqləşdirilmiş hesabat təqdim edilməlidir. Dəqiqləşdirilmiş hesabat üzrə büdcəyə ödənilməli vergi məbləği əvvəl təqdim edilmiş hesabat üzrə büdcəyə ödənilməli vergi məbləğindən çox olduqda, əlavə hesablanmış vergi məbləği faizlərlə birlikdə büdcəyə ödənilir, az olduqda isə hesablanmış vergi və faiz məbləğləri azaldılır. Vergi ödəyicisi tərəfindən dəqiqləşdirilmiş və ya vaxtında təqdim edilməmiş hesabatlar vergi ödəyicisində səyyar vergi yoxlamasının başlandığı günədək təqdim edilə bilər.',
        6, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '72'), '72.5-1',
        'Vergi ödəyiciləri tərəfindən könüllü açıqlama edildiyi halda bu barədə vergi orqanına forması müvafiq icra hakimiyyəti orqanı tərəfindən müəyyən edilən hesabat təqdim edilir.',
        7, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '72'), '72.5-2',
        'Könüllü açıqlama edildiyi halda təqdim edilmiş hesabat üzrə vergi ödəyicisi tərəfindən yalnız hesablanmış vergi məbləği, məcburi dövlət sosial sığorta, işsizlikdən sığorta və icbari tibbi sığorta haqları ödənilir.',
        8, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '72'), '72.6',
        'Vergi orqanı tərəfindən vergi hesabatının onun barəsində kameral vergi yoxlaması aparıldıqdan sonra və ya hər hansı digər hərəkətlərin həyata keçirilməsi ilə qəbul edilməsinin şərtləndirilməsi yolverilməzdir və qanunla müəyyən edilmiş məsuliyyətə səbəb olur. Vergi orqanı tərəfindən vergi hesabatı yalnız aşağıdakı hallardan biri olduqda qəbul edilmir:',
        9, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '72'), '72.6.1',
        'vergi ödəyicisinin eyniləşdirmə nömrəsi göstərilmədikdə və ya səhv göstərildikdə;',
        10, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '72'), '72.6.2',
        'vergi dövrü əks olunmadıqda;',
        11, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '72'), '72.6.3',
        'vergi ödəyicisi olan hüquqi şəxs tərəfindən kağız daşıyıcı vasitəsi ilə verilən vergi hesabatı imzalanmadıqda və möhürlə təsdiq olunmadıqda;',
        12, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '72'), '72.6.4',
        'vergi ödəyicisi olan fiziki şəxs tərəfindən vergi hesabatı imzalanmadıqda.',
        13, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '72'), '72.6.5',
        'Vergi ödəyicisi olan hüquqi və fiziki şəxslər tərəfindən elektron sənəd formasında göndərilən vergi hesabatı müvafiq qanunvericiliyin və ya qaydaların tələlərinə uyğun olmadıqda.',
        14, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '72'), '72.7',
        'Bu Məcəlləyə və ya digər qanunvericilik aktlarına müvafiq olaraq vergi orqanına təqdim edilmiş vergi hesabatı bu Məcəllənin 72.6.1-72.6.5-ci maddələrində müəyyən edilmiş hallarda qəbul edilmədikdə, hesabatın vergi orqanına daxil olduğu gündən 3 iş günü ərzində vergi ödəyicisinə bu barədə, habelə aşkar edilmiş dəqiqsizliklər aradan qaldırılaraq vergi orqanına təqdim edilməsi barədə bildiriş göndərilir.',
        15, false, NOW(), NOW());


