INSERT INTO tax_sections (article_id, section_number, content, order_index, synced_to_vector_store, created_at,
                          updated_at)
VALUES ((SELECT id FROM tax_articles WHERE article_number = '74'), '74.1',
        'Hesabatın verilmə müddəti başa çatanadək vergi ödəyicisi gəlir vergisinin və ya mənfəət vergisinin hesabatının verilməsi müddətinin uzadılması barədə müraciət edirsə və bu zaman ödənilməli olan verginin məbləğini tamamilə ödəyirsə, hesabatın verilməsi müddəti üç ayadək uzadılmış hesab olunur.

Bu maddəyə uyğun olaraq müddətin uzadılması verginin ödənilməsi müddətini dəyişdirmir.',
        1, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '74'), '74.2',
        'Hesabat üzrə hesablanmış verginin məbləği ödənilmiş məbləğdən artıq olduqda yaranan fərq verginin ödənilməsinin son müddəti günündən hesablanan faizlər nəzərə alınmaqla büdcəyə keçirilməlidir.',
        2, false, NOW(), NOW());


