-- =========================================================
INSERT INTO tax_articles (article_number, title, chapter, active, created_at, updated_at)
VALUES ('75',
        'Vergi ödəyiciləri ilə münasibətdə bankların və bank əməliyyatlarının ayrı-ayrı növlərini həyata keçirən digər kredit təşkilatlarının, habelə elektron pul təşkilatlarının vəzifələri',
        'VII fəsil. Vergilərin ödənilməsi üzrə ümumi qaydalar',
        true, NOW(), NOW());

INSERT INTO tax_sections (article_id, section_number, content, order_index, synced_to_vector_store, created_at,
                          updated_at)
VALUES ((SELECT id FROM tax_articles WHERE article_number = '75'), '75.0',
        'Banklar və bank əməliyyatlarının ayrı-ayrı növlərini həyata keçirən digər kredit təşkilatları, habelə elektron pul təşkilatları borcludurlar:',
        1, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '75'), '75.0.1',
        'yalnız vergi orqanları tərəfindən vergi ödəyicisinin eyniləşdirmə nömrəsi verildiyini təsdiq edən sənədlər verildikdən sonra hüquqi şəxslərə və sahibkarlıq fəaliyyətini hüquqi şəxs yaratmadan həyata keçirən fiziki şəxslərə milli və ya xarici valyutada cari və ya digər hesablar açmağa, bank və digər ödəniş sənədlərində vergi ödəyicisinin eyniləşdirmə nömrəsi göstərilmədikdə hesablar üzrə əməliyyatlar aparmamağa;',
        2, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '75'), '75.0.2',
        'hüquqi şəxslərin və sahibkarlıq fəaliyyətini hüquqi şəxs yaratmadan həyata keçirən fiziki şəxslərin öz milli və ya xarici valyutada cari və ya digər hesablarından vergilərin ödənilməsi haqqında ödəmə tapşırıqlarını icra etməyə;',
        3, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '75'), '75.0.3',
        'hüquqi şəxslərin və sahibkarlıq fəaliyyətini hüquqi şəxs yaratmadan həyata keçirən fiziki şəxslərin milli və ya xarici valyutada cari və ya digər hesablarından vəsaitin tutulması üzrə əməliyyatların aparıldığı gün vergi məbləğlərini müvafiq büdcəyə keçirməyə (banka və ya büdcəyə kassa xidməti göstərən digər maliyyə idarəsinə köçürməyə).',
        4, false, NOW(), NOW());


-- =========================================================
-- Maddə 76. Banklar və bank əməliyyatlarının ayrı-ayrı növlərini həyata
-- keçirən kredit təşkilatları, habelə elektron pul təşkilatları tərəfindən
-- məlumatların verilməsi
-- =========================================================
INSERT INTO tax_articles (article_number, title, chapter, active, created_at, updated_at)
VALUES ('76',
        'Banklar və bank əməliyyatlarının ayrı-ayrı növlərini həyata keçirən kredit təşkilatları, habelə elektron pul təşkilatları tərəfindən məlumatların verilməsi',
        'VII fəsil. Vergilərin ödənilməsi üzrə ümumi qaydalar',
        true, NOW(), NOW());

INSERT INTO tax_sections (article_id, section_number, content, order_index, synced_to_vector_store, created_at,
                          updated_at)
VALUES ((SELECT id FROM tax_articles WHERE article_number = '76'), '76.1',
        'Vergi orqanları vergi nəzarəti zamanı və ya Azərbaycan Respublikasının tərəfdar çıxdığı beynəlxalq müqavilələr çərçivəsində digər dövlətin səlahiyyətli orqanları ilə məlumat mübadiləsinin həyata keçirilməsi məqsədilə kredit və ya elektron pul təşkilatlarına və ya bank əməliyyatları aparan şəxslərə yazılı bildiriş göndərməklə, həmin kredit və ya elektron pul təşkilatının xidmət etdiyi vergi ödəyicisinin (şəxsin) eyniləşdirmə məlumatını, onun hesabları və hesab əməliyyatları barədə məlumat, həmçinin bu məlumatı təsdiq edən sənədləri almaq hüququna malikdir.',
        1, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '76'), '76.1-1',
        'Bu Məcəllənin 76.1-ci maddəsinin müddəalarından asılı olmayaraq, vergi ödəyicisinin vergi öhdəliklərinin müəyyən edilməsi məqsədilə ƏDV qeydiyyatında olan vergi ödəyicilərinin sahibkarlıq fəaliyyəti məqsədləri üçün açılmış hesabları üzrə aparılmış əməliyyatlar barədə aylıq məlumatlar kredit və ya elektron pul təşkilatları tərəfindən elektron qaydada hər ay bitdikdən sonra növbəti ayın 10-dək müvafiq icra hakimiyyəti orqanının müəyyən etdiyi orqan (qurum) tərəfindən təsdiq edilmiş formada müvafiq icra hakimiyyəti orqanının müəyyən etdiyi orqana (quruma) təqdim edilir.',
        2, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '76'), '76.2',
        'Kredit və ya elektron pul təşkilatı və ya bank əməliyyatları aparan şəxs müvafiq icra hakimiyyəti orqanının təsdiq etdiyi formada bu Məcəllənin 76.1-ci maddəsi ilə müəyyən edilmiş qaydada göndərilən bildirişi aldıqdan sonra həmin bildirişdə göstərilən məlumatların vergi orqanına veriləcəyi barədə 5 iş günü müddətində hesab sahibinə rəsmi məlumat göndərməlidir (verməlidir) və 15 gün müddətində tələb olunan məlumatları vergi orqanına təqdim etməlidir.

Bu maddənin digər müddəalarından asılı olmayaraq, Azərbaycan Respublikasının tərəfdar çıxdığı beynəlxalq müqavilələrin tələblərindən irəli gəldiyi halda xarici dövlətin səlahiyyətli orqanından daxil olan müraciətdə (sorğuda) hesab sahibinə müvafiq məlumatın verilməməsi qeyd edildiyi təqdirdə, hesab sahibinə rəsmi məlumat göndərilmir.',
        3, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '76'), '76.2-1',
        'Banklar və bank əməliyyatlarının ayrı-ayrı növlərini həyata keçirən kredit təşkilatları Azərbaycan Respublikası ilə digər dövlətlər arasında bağlanmış beynəlxalq müqavilələrə uyğun olaraq, bu dövlətlərin hüquqi və fiziki şəxslərinin Azərbaycan Respublikası ərazisində həyata keçirdikləri maliyyə əməliyyatları barədə məlumatları müvafiq icra hakimiyyəti orqanının müəyyən etdiyi hədlərdə və qaydada müvafiq icra hakimiyyəti orqanı vasitəsilə həmin xarici dövlətlərin səlahiyyətli orqanlarına təqdim etməlidir.',
        4, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '76'), '76.3',
        'Bu maddə ilə müəyyən edilmiş qaydada bank və digər ödəniş hesabları və ya əməliyyatlar barədə alınmış məlumatlar müvafiq beynəlxalq müqavilənin müddəaları əsasında digər dövlətin aidiyyəti orqanlarına verilə bilər. Digər hallarda bank və digər ödəniş hesabları və əməliyyatlar barədə alınmış məlumatların digər orqanlara və ya vətəndaşlara verilməsi qadağandır.',
        5, false, NOW(), NOW());


-- =========================================================
-- Maddə 76-1. Maliyyə institutları və digər şəxslər tərəfindən məlumatların
-- və sənədlərin verilməsi
-- =========================================================
INSERT INTO tax_articles (article_number, title, chapter, active, created_at, updated_at)
VALUES ('76-1',
        'Maliyyə institutları və digər şəxslər tərəfindən məlumatların və sənədlərin verilməsi',
        'VII fəsil. Vergilərin ödənilməsi üzrə ümumi qaydalar',
        true, NOW(), NOW());

INSERT INTO tax_sections (article_id, section_number, content, order_index, synced_to_vector_store, created_at,
                          updated_at)
VALUES ((SELECT id FROM tax_articles WHERE article_number = '76-1'), '76-1.1',
        'Maliyyə institutları qeyri-rezidentlərin Azərbaycan Respublikası ərazisində həyata keçirdikləri maliyyə əməliyyatları barədə məlumatları müvafiq icra hakimiyyəti orqanının müəyyən etdiyi hədlərdə və qaydada müvafiq icra hakimiyyəti orqanına təqdim etməlidir.',
        1, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '76-1'), '76-1.2',
        'Maliyyə institutları tərəfindən fiziki və hüquqi şəxslərə hesab açıldıqda və ya maliyyə xidmətləri göstərildikdə vergi və maliyyə məlumatlarının mübadiləsini nəzərdə tutan Azərbaycan Respublikasının tərəfdar çıxdığı beynəlxalq müqavilələrin icrası məqsədilə şəxsin rezidentliyinin müəyyən edilməsi üçün zəruri məlumatlar və sənədlər, həmçinin həmin məlumatlarda və sənədlərdə şəxsin rezidentlik statusunun dəyişdirilməsinə səbəb olan dəyişiklik baş verdiyi halda, bu barədə məlumatlar və sənədlər dəyişiklik baş verdiyi gündən 30 gün müddətində şəxs tərəfindən maliyyə institutuna təqdim edilməlidir.',
        2, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '76-1'), '76-1.3',
        'Maliyyə institutuna dürüst olmayan və (və ya) təhrif olunmuş məlumatların və sənədlərin təqdim edilməsinə və ya rezidentlik statusunun dəyişdirilməsinə səbəb olan dəyişiklik üzrə məlumatların və sənədlərin bu Məcəllənin 76-1.2-ci maddəsi ilə müəyyən edilmiş müddətdə təqdim edilməməsinə görə şəxslərin inzibati məsuliyyətə cəlb edilməsi Azərbaycan Respublikasının İnzibati Xətalar Məcəlləsinə müvafiq olaraq həyata keçirilir.',
        3, false, NOW(), NOW());


-- =========================================================
-- Maddə 77. Vergi öhdəliyi
-- =========================================================
INSERT INTO tax_articles (article_number, title, chapter, active, created_at, updated_at)
VALUES ('77',
        'Vergi öhdəliyi',
        'VII fəsil. Vergilərin ödənilməsi üzrə ümumi qaydalar',
        true, NOW(), NOW());

INSERT INTO tax_sections (article_id, section_number, content, order_index, synced_to_vector_store, created_at,
                          updated_at)
VALUES ((SELECT id FROM tax_articles WHERE article_number = '77'), '77.1',
        'Vergi ödəyicisinin bu Məcəllədə göstərilən hallarda və qaydada müəyyən edilən vergini (o cümlədən cari vergi ödəmələrini), hesablanmış faizləri və tətbiq edilmiş maliyyə sanksiyalarını ödəmək vəzifəsi onun vergi öhdəliyi hesab olunur.',
        1, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '77'), '77.2',
        'Vergi öhdəliyinin yaranması, dəyişdirilməsi və ya ləğv edilməsi üçün əsaslar, həmçinin vergi öhdəliyinin yerinə yetirilməsi qaydası və şərtləri yalnız bu Məcəllə ilə müəyyən edilir.',
        2, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '77'), '77.3',
        'Vergi ödəyicisi vergi qanunvericiliyinin tələblərinə uyğun olaraq verginin ödənilməsini nəzərdə tutan şəraitin yarandığı andan vergi öhdəliklərinin yerinə yetirilməsi üçün cavabdehdir.',
        3, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '77'), '77.4',
        'Vergi öhdəliyinə aşağıdakı hallarda xitam verilmiş hesab olunur:',
        4, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '77'), '77.4.1',
        'verginin ödənilməsi;',
        5, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '77'), '77.4.2',
        'verginin ödənilməsi öhdəliyinin xitam verilməsi vergilər haqqında qanunvericiliyə müvafiq olaraq ortaya çıxan hallarda, habelə qanun əsasında vergilər, faizlər və maliyyə sanksiyaları üzrə borclar silindikdə;',
        6, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '77'), '77.4.3',
        'vergi ödəyicisi vəfat etmiş və ya Azərbaycan Respublikasının mülki qanunvericiliyi ilə müəyyən edilmiş qaydada ölmüş hesab edildikdə. Vəfat etmiş və ya ölmüş hesab edilmiş şəxsin əmlak vergiləri üzrə borcları vərəsəlik əmlakının dəyəri hədlərində ödənilir;',
        7, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '77'), '77.4.4',
        'bu Məcəlləyə müvafiq olaraq ləğvetmə komissiyası (təsviyəçi, ləğvedici) tərəfindən büdcə ilə (büdcədənkənar fondlarla) bütün hesablaşmalar aparıldıqdan sonra vergi ödəyicisi olan hüquqi şəxs ləğv edildikdə.',
        8, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '77'), '77.4.5',
        'Azərbaycan Respublikasının qanunvericiliyi ilə müəyyən edilmiş qaydada müflis olması nəticəsində ləğv edilmiş borclu vergi ödəyicisinin məhkəmənin qərarı ilə ödənilməsindən imtina edilmiş tələblər ləğv edilmiş sayıldıqda.',
        9, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '77'), '77.5',
        'Müvafiq icra hakimiyyəti orqanının müəyyən etdiyi orqan (qurum) tərəfindən təsdiq edilən meyarlara cavab verən və müvafiq icra hakimiyyəti orqanının müəyyən etdiyi orqanın (qurumun) elektron informasiya sisteminə real vaxt rejimində qoşulmuş nəzarət-kassa aparatını quraşdıran vergi ödəyicisi tərəfindən hər bir nəzarət-kassa aparatının quraşdırılmasına çəkilən xərclərin (nəzarət-kassa aparatının dəyəri daxil olmaqla) dəyəri müvafiq icra hakimiyyəti orqanının müəyyən etdiyi orqan (qurum) tərəfindən təsdiq edilən həddə nəzarət-kassa aparatı quraşdırıldıqdan sonra yaranan vergi öhdəlikləri ilə əvəzləşdirilir.',
        10, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '77'), '77.6',
        'Bu Məcəllənin 77.5-ci maddəsi 2019-cu il yanvarın 1-dək istismar edilən nəzarət-kassa aparatını müvafiq icra hakimiyyəti orqanının müəyyən etdiyi orqan (qurum) tərəfindən təsdiq edilən meyarlara cavab verən və müvafiq icra hakimiyyəti orqanının müəyyən etdiyi orqanın (qurumun) elektron informasiya sisteminə real vaxt rejimində qoşulmuş nəzarət-kassa aparatı ilə əvəz edən vergi ödəyicilərinə şamil edilir və müvafiq icra hakimiyyəti orqanının müəyyən etdiyi orqan (qurum) tərəfindən təsdiq edilən həddən artıq olan məbləğ vergi ödəyicisi tərəfindən ödənilir.',
        11, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '77'), '77.7',
        'Aşağıdakı hallarda nəzarət-kassa aparatının quraşdırılmasına çəkilən xərclər bu maddə ilə müəyyənləşdirilmiş qaydada vergi öhdəlikləri ilə əvəzləşdirilmir:',
        12, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '77'), '77.7.1',
        'nəzarət-kassa aparatı 2019-cu il 1 yanvar tarixinədək quraşdırıldıqda;',
        13, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '77'), '77.7.2',
        'nəzarət-kassa aparatı 2019-cu il 1 yanvar tarixindən sonra quraşdırıldıqda, lakin müvafiq icra hakimiyyəti orqanının müəyyən etdiyi orqan (qurum) tərəfindən müəyyən edilən meyarlara cavab vermədikdə;',
        14, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '77'), '77.7.3',
        'nəzarət-kassa aparatı 2019-cu il 1 yanvar tarixindən sonra quraşdırıldıqda, müvafiq icra hakimiyyəti orqanının müəyyən etdiyi orqan (qurum) tərəfindən təsdiq edilən meyarlara cavab verdikdə, lakin əvvəllər istifadədə olan nəzarət-kassa aparatını əvəzləmədikdə.',
        15, false, NOW(), NOW());


-- =========================================================
-- Maddə 77-1. Vergi öhdəliyinin əvvəlcədən müəyyənləşdirilməsi barədə qərar
-- =========================================================
INSERT INTO tax_articles (article_number, title, chapter, active, created_at, updated_at)
VALUES ('77-1',
        'Vergi öhdəliyinin əvvəlcədən müəyyənləşdirilməsi barədə qərar',
        'VII fəsil. Vergilərin ödənilməsi üzrə ümumi qaydalar',
        true, NOW(), NOW());

INSERT INTO tax_sections (article_id, section_number, content, order_index, synced_to_vector_store, created_at,
                          updated_at)
VALUES ((SELECT id FROM tax_articles WHERE article_number = '77-1'), '77-1.1',
        'Vergi ödəyicisi vergi öhdəliyinin əvvəlcədən müəyyənləşdirilməsi barədə qərarın (bundan sonra bu maddənin məqsədləri üçün – qərar) qəbul edilməsi məqsədilə vergi orqanına "İnzibati icraat haqqında" Azərbaycan Respublikası Qanununun 29-cu və 30-cu maddələrində nəzərdə tutulmuş qaydada ərizə təqdim edir.',
        1, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '77-1'), '77-1.2',
        'Ərizəyə aşağıdakılar əlavə olunur:',
        2, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '77-1'), '77-1.2.1',
        'barəsində qərarın qəbul edilməsi tələb edilən vergi tutulan əməliyyata aid sənədlər;',
        3, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '77-1'), '77-1.2.2',
        'vergi tutulan əməliyyatlar üzrə vergi öhdəliklərinin və vergi qanunvericiliyinin tətbiq edilməsinin doğuracağı hüquqi nəticələrə dair vergi ödəyicisinin qeydləri;',
        4, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '77-1'), '77-1.2.3',
        'qərarın qəbulu üçün zəruri hesab edilən digər məlumatlar.',
        5, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '77-1'), '77-1.3',
        'Ərizəyə əlavə olunmuş sənədlər dövlət dilində olmalıdır. Xarici dildə tərtib olunmuş sənədlərin əsli dövlət dilinə rəsmi təsdiq edilmiş tərcümə ilə müşayiət olunmalıdır.',
        6, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '77-1'), '77-1.4',
        'Qərar bu Məcəllənin 77-1.2-ci və 77-1.3-cü maddələrində nəzərdə tutulan sənədlər və məlumatlar təqdim edildikdən sonra 30 iş günü müddətində qəbul edilir.',
        7, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '77-1'), '77-1.5',
        'Vergi orqanı ərizənin və ona əlavə edilmiş sənədlərin 77-1.1 - 77-1.3-cü maddələrinin tələblərinə uyğunluğunu yoxlayır. Ərizədə və ona əlavə edilmiş sənədlərdə aradan qaldırılması mümkün olan və qərarın qəbul edilməsi üçün imtinaya səbəb olmayan çatışmazlıqlar aşkar edildikdə, ərizənin qeydiyyata alındığı tarixdən 10 iş günündən gec olmayaraq vergi orqanı onların aradan qaldırılması barədə məlumatı vergi ödəyicisinə bildirməlidir.',
        8, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '77-1'), '77-1.6',
        'Vergi ödəyicisi həmin çatışmazlıqları məlumatı aldığı vaxtdan ən geci 10 iş günü ərzində aradan qaldırmalıdır. Bu zaman qərarın qəbul edilməsi ilə bağlı müddətin axımı dayandırılır və dayandırılmış müddət qərarın qəbul edilməsi müddətinə daxil edilmir. Çatışmazlıqların aradan qaldırılması barədə vergi ödəyicisinin müraciətindən sonra müddətin axımı bərpa olunur.',
        9, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '77-1'), '77-1.7',
        'Qərar vergi orqanı tərəfindən hər bir vergi ödəyicisinə və hər bir vergi tutulan əməliyyata münasibətdə ayrılıqda qəbul olunur, vergi orqanının rəhbərinin imzası və möhürlə təsdiq olunur və barəsində qərar qəbul edilən əməliyyatla bağlı münasibətləri tənzimləyən normativ hüquqi aktlarda əməliyyat baş tutanadək dəyişiklik baş verdiyi hallar istisna olmaqla 3 il müddətində məcburi hüquqi qüvvəyə malik olur.',
        10, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '77-1'), '77-1.8',
        'Vergi ödəyicisi tərəfindən təqdim olunmuş ərizə və ona əlavə edilmiş sənədlərdə çatışmazlıqlar olmadıqda və ya aşkar edilmiş çatışmazlıqlar bu Məcəllənin 77-1.6-cı maddəsində müəyyən olunmuş vaxtda aradan qaldırıldıqda, vergi orqanı "Dövlət rüsumu haqqında" Azərbaycan Respublikasının Qanunu ilə müəyyən edilmiş dövlət rüsumunu ödəmək vəzifəsi barədə vergi ödəyicisinə şifahi və ya məktub vasitəsilə yazılı məlumat verir.',
        11, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '77-1'), '77-1.9',
        'Qərarın qəbul edilməsi üçün dövlət rüsumu bu Məcəllənin 77-1.8-ci maddəsinə uyğun olaraq, vergi orqanının verdiyi məlumat alındığı tarixdən 3 iş günü ərzində vergi ödəyicisi tərəfindən ödənilir və ödənişi təsdiq edən sənəd vergi orqanına təqdim olunur.',
        12, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '77-1'), '77-1.10',
        'Dövlət rüsumunun ödənilməsi faktını təsdiq edən sənəd vergi orqanına təqdim edildikdən sonra bu Məcəllə ilə müəyyən edilmiş müddətdə qərar qəbul edilərək vergi ödəyicisinə təqdim edilir və ya sifarişli poçt göndərişi vasitəsilə göndərilir.',
        13, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '77-1'), '77-1.11',
        'Qərarın icrası yalnız ərizədə qeyd olunan əməliyyat üzrə vergi orqanı və qərarda qeyd olunan əməliyyatı həyata keçirəcək vergi ödəyicisi üçün məcburi hüquqi qüvvəyə malikdir, bir şərtlə ki, vergi ödəyicisi tərəfindən həmin əməliyyat həyata keçirilmiş olsun.',
        14, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '77-1'), '77-1.12',
        'Barəsində qərar qəbul edilmiş əməliyyatın icrası vergi ödəyicisi üçün məcburi xarakter daşımır.',
        15, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '77-1'), '77-1.13',
        'Aşağıdakı hallarda vergi orqanı tərəfindən qərarın qəbul edilməsindən imtina edilir:',
        16, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '77-1'), '77-1.13.1',
        'ərizədə və ona əlavə olunmuş sənədlərdə qanuna uyğun olmayan məlumatlar olduqda (bu Məcəllənin 77-1.5-ci maddəsinin ikinci cümləsində nəzərdə tutulmuş hal istisna olmaqla);',
        17, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '77-1'), '77-1.13.2',
        'ərizədə qeyd olunan əməliyyat üzrə bu Məcəlləyə uyğun olaraq vergi öhdəliyinin müəyyən edilməsinə dair vergi orqanının qərarı olduqda və bu əməliyyat üzrə göstəricilərdə hər hansı dəyişiklik baş vermədikdə;',
        18, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '77-1'), '77-1.13.3',
        'ərizədə qeyd olunan əməliyyat artıq baş tutmuş olduqda və ya bu əməliyyatla bağlı vergi orqanının qərarı və ya məhkəmənin qanuni qüvvəyə minmiş qərarı olduqda;',
        19, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '77-1'), '77-1.13.4',
        'barəsində qərar qəbul edilməsi üçün müraciət edilmiş əməliyyat üzrə vergi ödəyicisinin vergidən yayınma sxemi yaratmaqla, vergi üstünlüyü əldə etmək məqsədi daşıdığı vergi orqanı tərəfindən müəyyən edildikdə;',
        20, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '77-1'), '77-1.13.5',
        'barəsində qərar qəbul edilməsi nəzərdə tutulan əməliyyatın dəyəri 10.000.000 (on milyon) manatdan aşağı olduqda;',
        21, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '77-1'), '77-1.13.6',
        'dövlət rüsumunun ödənilməsini təsdiq edən sənəd bu Məcəllənin 77-1.9-cu maddəsində göstərilən müddətdə vergi orqanına təqdim edilmədikdə;',
        22, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '77-1'), '77-1.13.7',
        'vergi ödəyicisi tərəfindən qərarın qəbul olunması üçün müraciət zamanı bu Məcəllə ilə müəyyən olunmuş tələblərə əməl edilmədikdə, o cümlədən vergi öhdəliyinin və vergi qanunvericiliyinin tətbiq edilməsinin doğuracağı hüquqi nəticələrin müəyyən edilməsi ilə bağlı tələb olunan sənədlər və məlumatlar müraciətə əlavə olunmadıqda və ya əlavə olunmuş sənədlər və məlumatlar vergi öhdəliyinin və vergi qanunvericiliyinin tətbiq edilməsinin doğuracağı hüquqi nəticələrin müəyyən edilməsi üçün kifayət etmədikdə;',
        23, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '77-1'), '77-1.13.8',
        'barəsində qərar qəbul edilməsi nəzərdə tutulan əməliyyat üzrə vergi öhdəliyinin və vergi qanunvericiliyinin tətbiq edilməsinin doğuracağı hüquqi nəticələrin müəyyən edilməsi vergi orqanının səlahiyyətlərinə aid olmadıqda.',
        24, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '77-1'), '77-1.14',
        'Barəsində qərar qəbul edilən əməliyyatla bağlı münasibətləri tənzimləyən normativ hüquqi aktlarda əməliyyat baş tutanadək dəyişiklik baş verərsə, vergi öhdəliklərinin əvvəlcədən müəyyən edilməsi haqqında vergi orqanının qərarının hüquqi qüvvəsi olmur.',
        25, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '77-1'), '77-1.15',
        'Vergi ödəyicisi vergi orqanı tərəfindən bu maddəyə uyğun olaraq qəbul edilmiş qərardan, habelə həmin qərarın qəbul edilməsi ilə bağlı imtinadan inzibati qaydada və məhkəməyə şikayət verə bilər.',
        26, false, NOW(), NOW());


