        true, NOW(), NOW());

INSERT INTO tax_sections (article_id, section_number, content, order_index, synced_to_vector_store, created_at,
                          updated_at)
VALUES ((SELECT id FROM tax_articles WHERE article_number = '78'), '78.1',
        'Vergi öhdəliklərinin yerinə yetirilməsi ödənilməli olan vergilərin (o cümlədən cari vergi ödəmələrinin), hesablanmış faizlərin və tətbiq edilmiş maliyyə sanksiyalarının müəyyən edilmiş müddətlərdə və qaydada ödənilməsidir. Vergi ödəyicisinin hesablarında və ya kassasında vəsaitin, habelə onun əmlakının olub-olmamasından asılı olmayaraq vergi öhdəliklərinin yerinə yetirilməsi məcburidir.',
        1, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '78'), '78.2',
        'Vergi öhdəliklərinin yerinə yetirilməsi Mülki Məcəllədə nəzərdə tutulmuş ardıcıllıqla həyata keçirilir.',
        2, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '78'), '78.3',
        'Vergi öhdəliklərinin yerinə yetirilməsi bu Məcəllədə başqa hallar nəzərdə tutulmamışdırsa, bilavasitə vergi ödəyicisi tərəfindən həyata keçirilir.',
        3, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '78'), '78.4',
        'Vergi öhdəliklərinin yerinə yetirilməsi əmtəəsiz əməliyyat üzrə faydalanan şəxs istisna olmaqla, digər şəxsin üzərinə qoyula bilməz. Bu maddənin məqsədləri üçün faydalanan şəxs əmtəəsiz əməliyyat aparmaqla mənfəət əldə etmək məqsədilə həyata keçirilən fəaliyyət üzrə faktiki olaraq gəlir əldə edən, o cümlədən əmtəəsiz əməliyyat aparmaqla mənfəət (gəlir) əldə edən hüquqi şəxsin faktiki sahibi və ya əmtəəsiz əməliyyat aparmaqla gəlir əldə edən vergi ödəyicisinə nəzarəti həyata keçirən fiziki şəxsdir.

Bu Məcəllənin 85.9-1.2-ci maddəsinə uyğun olaraq zamin duran vergi ödəyicisi tərəfindən vergi borcunun ödənilməsinə möhlət verilmiş vergi ödəyicisinin vergi öhdəliyinin yerinə yetirilməsi vergi öhdəliyinin digər şəxsin üzərinə qoyulması hesab edilmir və zamin tərəfindən vergi borcu olan şəxsin vergi öhdəliyinin yerinə yetirilməsi zamin vergi ödəyicisinin vergi öhdəlikləri ilə bağlı ödəmələrinə aid edilmir.',
        4, false, NOW(), NOW());


-- =========================================================
-- Maddə 79. Müəssisə (təşkilat) ləğv edildikdə vergi öhdəliklərinin yerinə
-- yetirilməsi
-- =========================================================
INSERT INTO tax_articles (article_number, title, chapter, active, created_at, updated_at)
VALUES ('79',
        'Müəssisə (təşkilat) ləğv edildikdə vergi öhdəliklərinin yerinə yetirilməsi',
        'VII fəsil. Vergilərin ödənilməsi üzrə ümumi qaydalar',
        true, NOW(), NOW());

INSERT INTO tax_sections (article_id, section_number, content, order_index, synced_to_vector_store, created_at,
                          updated_at)
VALUES ((SELECT id FROM tax_articles WHERE article_number = '79'), '79.1',
        'Ləğv edilən müəssisənin (təşkilatın) vergi öhdəliklərini onun pul vəsaitləri, o cümlədən müəssisənin (təşkilatın) əmlakının satışından əldə edilən gəlir hesabına ləğvetmə komissiyası (təsviyəçi, ləğvedici) yerinə yetirir. Bu maddədə başqa hallar nəzərdə tutulmamışdırsa, ləğvetmə komissiyası (təsviyəçi, ləğvedici) müəssisənin (təşkilatın) filiallarının digər struktur bölmələrinin və daimi nümayəndəliyinin vergi öhdəliklərini də yerinə yetirməlidir. Ləğv edilən müəssisənin (təşkilatın) filialının və ya digər ayrıca bölməsinin öhdəliklərini bilavasitə həmin ayrıca bölmənin daxil olduğu müəssisə (təşkilat), bu müəssisə (təşkilat) ləğv edildikdə isə həmin müəssisənin (təşkilatın) ləğvetmə komissiyası (təsviyəçi, ləğvedici) yerinə yetirir.',
        1, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '79'), '79.2',
        'Ləğv edilən müəssisənin (təşkilatın) pul vəsaiti, o cümlədən vergi öhdəliklərinin yerinə yetirilməsindən ötrü əmlakın satışından əldə edilən vəsait onun vergi öhdəliklərinin tam həcmdə yerinə yetirilməsi üçün kifayət etmədiyi halda, vergi öhdəlikləri üzrə qalan borc qanuna, nizamnaməyə və ya digər təsis sənədinə uyğun olaraq müəssisənin (təşkilatın) öhdəlikləri üçün onun iştirakçıları (təsisçiləri) birgə məsuliyyət daşıyırlarsa, həmin iştirakçılar (təsisçilər) tərəfindən ödənilməlidir.',
        2, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '79'), '79.3',
        'Müəssisənin iflas prosesinə məruz qaldığı hallarda vergi öhdəlikləri qanunla müəyyən edilmiş növbəlilik qaydasında yerinə yetirilir. Müflis elan olunmuş bankların və sığorta (təkrarsığorta) təşkilatlarının vergi öhdəlikləri müvafiq olaraq "Banklar haqqında" və "Sığorta fəaliyyəti haqqında" Azərbaycan Respublikasının qanunlarında nəzərdə tutulmuş ödənişlərin növbəliliyi ardıcıllığına uyğun olaraq yerinə yetirilir.',
        3, false, NOW(), NOW());


-- =========================================================
