INSERT INTO tax_articles (article_number, title, chapter, active, created_at, updated_at)
VALUES ('80',
        'Müəssisə (təşkilat) yenidən təşkil edildikdə vergi öhdəliklərinin yerinə yetirilməsi',
        'VII fəsil. Vergilərin ödənilməsi üzrə ümumi qaydalar',
        true, NOW(), NOW());

INSERT INTO tax_sections (article_id, section_number, content, order_index, synced_to_vector_store, created_at,
                          updated_at)
VALUES ((SELECT id FROM tax_articles WHERE article_number = '80'), '80.1',
        'Yenidən təşkil edilən hüquqi şəxsin vergi öhdəliklərini onun hüquqi varisi (hüquqi varisləri) bu maddədə müəyyən edilmiş qaydada yerinə yetirir.',
        1, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '80'), '80.2',
        'Yenidən təşkil edilən hüquqi şəxsin vergi öhdəliklərinin yerinə yetirməməsinin, yaxud lazımi qaydada yerinə yetirməməsinin yenidən təşkili başa çatanadək hüquqi varisə (hüquqi varislərə) məlum olub-olmamasından asılı olmayaraq yenidən təşkil edilən hüquqi şəxsin vergi öhdəliklərini onun hüquqi varisi (hüquqi varisləri) yerinə yetirməlidir.',
        2, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '80'), '80.3',
        'Hüquqi şəxsin yenidən təşkil edilməsi onun vergi öhdəliklərinin bu hüquqi şəxsin hüquqi varisi (hüquqi varisləri) tərəfindən yerinə yetirilməsi müddətlərini dəyişdirmir.',
        3, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '80'), '80.4',
        'Bir neçə hüquqi şəxs birləşdikdə, onların vergilərin ödənilməsinə dair öhdəliklərinin yerinə yetirilməsi üzrə hüquqi varisi bu cür birləşmə nəticəsində yaranan hüquqi şəxs sayılır.',
        4, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '80'), '80.5',
        'Bir hüquqi şəxs digər hüquqi şəxsə birləşdirildikdə, onun birləşdiyi hüquqi şəxs birləşdirilmiş hüquqi şəxsin vergilərin ödənilməsinə dair öhdəliklərinin yerinə yetirilməsi üzrə hüquqi varisi sayılır.',
        5, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '80'), '80.6',
        'Hüquqi şəxs bölündükdə, bu cür bölünmə nəticəsində əmələ gələn hüquqi şəxslər bölünmüş hüquqi şəxsin vergilərin ödənilməsinə dair öhdəliklərinin yerinə yetirilməsi üzrə hüquqi varisləri sayılırlar.',
        6, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '80'), '80.7',
        'Bir neçə hüquqi varis olduqda, onların hər birinin yenidən təşkil edilən və ya bölünən hüquqi şəxsin vergi öhdəliklərinin yerinə yetirilməsində iştirak payı bölüşdürücü balansa və ya digər təhvil aktına uyğun olaraq müəyyənləşdirilir. Bölüşdürücü balans və ya digər təhvil aktı yenidən təşkil edilən və ya bölünən hüquqi şəxsin hər bir hüquqi varisinin payını müəyyənləşdirməyə imkan vermirsə və ya hər hansı hüquqi varis tərəfindən vergi öhdəliklərinin tam həcmdə yerinə yetirilməsi imkanını aradan qaldırırsa, yeni yaranan hüquqi şəxslər yenidən təşkil edilən və ya bölünən hüquqi şəxsin vergi öhdəliklərini və ya bu öhdəliklərin müvafiq hissəsini yerinə yetirmək üçün birgə məsuliyyət daşıyırlar.',
        7, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '80'), '80.8',
        'Bir hüquqi şəxs təşkilati-hüquqi formasının dəyişdirilməsi yolu ilə digər hüquqi şəxsə çevrildikdə, onun vergilərin ödənilməsinə dair öhdəliklərinin yerinə yetirilməsi üzrə hüquqi varisi yeni yaranan hüquqi şəxs sayılır.',
        8, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '80'), '80.9',
        'Hüquqi şəxsin tərkibindən bir və ya bir neçə hüquqi şəxs çıxdıqda, çıxmış hüquqi şəxslərin yenidən təşkil edilən hüquqi şəxsin vergi öhdəliklərini yerinə yetirməsi üzrə hüquqi varisliyi yaranmır, bu şərtlə ki, bu cür yenidən təşkil hüquqi şəxsin vergi öhdəliklərinin yerinə yetirilməməsinə yönəldilməmiş olsun.',
        9, false, NOW(), NOW());
