INSERT INTO tax_articles (article_number, title, chapter, active, created_at, updated_at)
VALUES ('81',
        'Vəfat etmiş, fəaliyyət qabiliyyətini itirmiş və ya itkin düşmüş fiziki şəxslərin vergi öhdəliklərinin yerinə yetirilməsi',
        'VII fəsil. Vergilərin ödənilməsi üzrə ümumi qaydalar',
        true, NOW(), NOW());

INSERT INTO tax_sections (article_id, section_number, content, order_index, synced_to_vector_store, created_at,
                          updated_at)
VALUES ((SELECT id FROM tax_articles WHERE article_number = '81'), '81.1',
        'Vəfat etmiş və ya Azərbaycan Respublikasının mülki qanunvericiliyi ilə müəyyən edilmiş qaydada ölmüş hesab edilmiş fiziki şəxsin əmlak vergiləri üzrə vergi öhdəliklərini onun varisi (varisləri) miras qalan əmlakın dəyəri hüdudlarında və mirasın alındığı tarixdəki payına mütənasib şəkildə ödəyirlər.',
        1, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '81'), '81.2',
        'Varis (varislər) olmadıqda vəfat etmiş fiziki şəxsin vergi öhdəlikləri silinir (ləğv edilir).',
        2, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '81'), '81.3',
        'Məhkəmə tərəfindən qanunvericiliklə müəyyən edilmiş qaydada itkin düşmüş və ya fəaliyyət qabiliyyətini itirmiş sayılan fiziki şəxsin vergi öhdəliklərini itkin düşmüş və ya fəaliyyət qabiliyyətini itirmiş şəxsin əmlak sərəncamçısı kimi səlahiyyətləndirilən şəxs həmin əmlakın hesabına ödəyir.',
        3, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '81'), '81.4',
        'Qanunvericiliklə müəyyən olunmuş qaydada itkin düşmüş və ya fəaliyyət qabiliyyətini itirmiş kimi tanınan fiziki şəxsin əmlakı onun vergi öhdəliklərini ödəmək üçün kifayət deyilsə, vergilərin əmlakın çatışmaması ilə əlaqədar ödənilməyən hissəsi, bu Məcəllənin 93-cü maddəsində göstərilən qaydada silinir.',
        4, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '81'), '81.5',
        'Fiziki şəxsin itkin düşmüş və ya fəaliyyət qabiliyyətini itirmiş kimi tanınmasının ləğv olunmasına dair məhkəmə tərəfindən qanunvericiliklə müəyyən edilmiş qaydada qərar qəbul edildikdə, əvvəllər silinmiş vergi öhdəlikləri bərpa edilir, lakin fiziki şəxsin itkin düşmüş və ya fəaliyyət qabiliyyətini itirmiş sayıldığı vaxtdan bu cür tanınmanın ləğv olunduğuna dair qərar qəbul edildiyi vaxtadək olan dövr ərzində faizlər hesablanmır və maliyyə sanksiyaları tətbiq edilmir.',
        5, false, NOW(), NOW());

