INSERT INTO tax_articles (article_number, title, chapter, active, created_at, updated_at)
VALUES ('82',
        'Vergi ödəyicisi tərəfindən vergilərin hesablanması və ödənilməsi qaydası',
        'VII fəsil. Vergilərin ödənilməsi üzrə ümumi qaydalar',
        true, NOW(), NOW());

INSERT INTO tax_sections (article_id, section_number, content, order_index, synced_to_vector_store, created_at,
                          updated_at)
VALUES ((SELECT id FROM tax_articles WHERE article_number = '82'), '82.1',
        'Bu Məcəllədə başqa hallar nəzərdə tutulmamışdırsa, vergi ödəyicisi vergi bazasını, vergi dərəcəsini və vergi güzəştlərini əsas götürərək, hesabat dövrü üçün ödənilməli olan verginin məbləğini sərbəst surətdə özü hesablayır.',
        1, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '82'), '82.2',
        'Bu Məcəllədə müəyyən edilən hallarda ödənilməli olan vergi məbləğini hesablamaq vəzifəsi vergi agentinə həvalə edilə bilər.',
        2, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '82'), '82.3',
        'Verginin məbləği bu Məcəllədə və ya ona müvafiq olaraq qəbul edilmiş qanunvericilik aktında müvafiq vergi üçün müəyyən edilmiş qaydada hesablanır.',
        3, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '82'), '82.4',
        'Müəyyən edilmiş müddətlərdə ödənilməli olan verginin məbləği vergi ödəyicisi və ya qanunla müəyyən edilmiş hallarda digər şəxs tərəfindən ödənilir (köçürülür).',
        4, false, NOW(), NOW());

