-- TAX ARTICLE (Maddə 83)
-- ============================
INSERT INTO tax_articles (article_number, title, chapter, active, created_at, updated_at)
VALUES ('83',
        'Vergi orqanları tərəfindən vergilərin hesablanması',
        'VII fəsil. Vergilərin ödənilməsi üzrə ümumi qaydalar',
        true, NOW(), NOW());

INSERT INTO tax_sections (article_id, section_number, content, order_index, synced_to_vector_store, created_at,
                          updated_at)
VALUES ((SELECT id FROM tax_articles WHERE article_number = '83'), '83.1',
        'Bu Məcəllədə vergi məbləğinin hesablanması konkret hesabat dövrü üçün vergi ödəyicisinin ödəməli olduğu vergi məbləğinin vergi orqanının uçot sənədlərində qeyd edilməsi deməkdir. Hesablanmış vergi məbləğlərinin vergi orqanları tərəfindən bu Məcəllə ilə müəyyən edilmiş hallarda yenidən hesablanaraq uçot sənədlərində qeyd edilməsi də vergilərin hesablanması deməkdir. Bu Məcəllənin 85.4-cü maddəsində göstərilən müddətlər nəzərə alınmaqla, vergi ödəyicisinin vergi orqanında uçota alındığı tarixədək əldə etdiyi gəlirləri, o cümlədən xaricdən əldə etdiyi gəlirləri üzrə vergilər həmin gəlirlərin aid olduğu hesabat dövrləri üzrə ayrılıqda hesablanaraq vergi orqanı tərəfindən vergi orqanının uçot sənədlərində qeyd edilir. Vergi ödəyicisinin xaricdən əldə etdiyi gəlirləri üzrə vergilər hesablanarkən bu Məcəllənin 127-ci maddəsinin müddəaları nəzərə alınır.',
        1, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '83'), '83.2',
        'Vergi orqanının bu Məcəlləyə uyğun olaraq vergi ödəyicisinin vergi öhdəliklərini aşağıdakı məlumat mənbələrindən birinə və ya bir neçəsinə əsaslanaraq hesablamaq hüququ vardır:',
        2, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '83'), '83.2.1',
        'vergi ödəyicilərinin vergi bəyannamələrində olan məlumata;',
        3, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '83'), '83.2.2',
        'bu Məcəllənin 73-cü maddəsinə müvafiq ödəmələr haqqında məlumata;',
        4, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '83'), '83.2.3',
        'vergi yoxlaması materiallarına;',
        5, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '83'), '83.2.4',
        'vergi orqanının əldə etdiyi mənbəyi bəlli olan hər hansı digər məlumata, o cümlədən bu Məcəllənin 67-ci maddəsi ilə nəzərdə tutulmuş əlaqəli məlumatlara.',
        6, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '83'), '83.3',
        'Vergi orqanının səyyar və kameral (bu Məcəllənin 37.2-ci maddəsində göstərilən hal üzrə kameral vergi yoxlaması ilə hesablama istisna olmaqla) vergi yoxlamasının nəticələrinə görə hesablanmış vergiləri, faizləri və maliyyə sanksiyalarını bu Məcəllənin 85.4-cü maddəsinə müvafiq olaraq hesabat dövrü qurtardıqdan sonra 3 il ərzində yenidən hesablamaq hüququ vardır.',
        7, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '83'), '83.4',
        'Bu Məcəlləyə müvafiq olaraq verginin vergi bəyannaməsini vermək şərti ilə ödənilməsində, yaxud əvvəllər verginin hesablanmasında səhv olunduğunu müəyyən edildiyi hallarda, vergi orqanı qanunvericiliyə uyğun vergiləri hesablayır və sonra bu Məcəllənin 84-cü maddəsinə uyğun olaraq verginin hesablanmasına dair bildirişi 5 iş günü müddətində vergi ödəyicisinə göndərir. Vergi orqanı bu Məcəllənin 85-ci maddəsində göstərilən müddət başa çatanadək vergi məbləğini qanunvericiliklə müəyyən edilmiş qaydada hesablaya və ya əvvəllər hesablanmış vergi məbləğinə düzəliş edə bilər.',
        8, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '83'), '83.5',
        'Bu Məcəlləyə müvafiq olaraq verginin vergi bəyannaməsini vermək şərti ilə ödənilməsi müəyyən edildiyi halda, verginin ödənilməsinə dair öhdəliyin əks etdirildiyi bəyannamənin tərtib edilməsi bu cür verginin hesablanması və onun ödənilməsinə dair bildirişdir.',
        9, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '83'), '83.6',
        'Vergilər bu Məcəllənin 5.0.1-ci, 212.4-cü və ya 221.4.1-ci maddələrinə uyğun olaraq alındıqda və vergi ödəyicisi vergi bəyannaməsini vermədiyi, vergi orqanı isə vergi ödəyicisinin ödəməli olduğu verginin məbləğini bu Məcəllə ilə müəyyən edilmiş qaydada digər məlumata əsasən hesablamadığı halda, hesab olunur ki, vergi orqanı vergi ödəyicisinin illik vergi öhdəliyini vergi ödəyicisinin il ərzində vergitutma bazasından tutulmuş və ya ödənilmiş vergi məbləğində hesablamış və verginin hesablanması barədə vergi ödəyicisinə bildiriş vermişdir.',
        10, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '83'), '83.7',
        'Vergi orqanlarında vergi ödəyicisinin vergini ödəməkdən yayınmaq niyyətində olduğunu təsdiq edən əsaslandırılmış konkret məlumat varsa və verginin tutulmasının təmin edilməsi zəruridirsə, habelə vergi ödəyicisi riskli vergi ödəyicisidirsə, vergi orqanının vergini onun ödənildiyi tarixədək hesablamaq hüququ vardır. Vergi orqanı bu barədə əsaslandırılmış qərar çıxarmalıdır.',
        11, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '83'), '83.8',
        'Vergi ödəyicisinin bu Məcəllənin 83.7-ci maddəsinə uyğun olaraq verginin hesablanması barəsində vergi orqanının qərarından aşağıdakıları əsas tutaraq məhkəməyə müraciət etmək hüququ vardır:',
        12, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '83'), '83.8.1',
        'vergi məbləğinin ödənilməli olan miqdarından çox olduğunu;',
        13, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '83'), '83.8.2',
        'verginin vaxtından əvvəl hesablanmasına əsas vermiş amilin və ya vəziyyətin olmadığını.',
        14, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '83'), '83.9',
        'Vergi ödəyicisinin əldə etdiyi mənfəəti (gəliri) birbaşa müəyyən etmək mümkün olmadığı halda, həmin mənfəət (gəlir) müvafiq icra hakimiyyəti orqanı tərəfindən müəyyən edilmiş qaydalar əsasında hesablanır.',
        15, false, NOW(), NOW());

