-- ============================
INSERT INTO tax_articles (article_number, title, chapter, active, created_at, updated_at)
VALUES ('85',
        'Vergi öhdəliyinin yerinə yetirilməsi müddətləri və həmin müddətlərin dəyişdirilməsi',
        'VII fəsil. Vergilərin ödənilməsi üzrə ümumi qaydalar',
        true, NOW(), NOW());

INSERT INTO tax_sections (article_id, section_number, content, order_index, synced_to_vector_store, created_at,
                          updated_at)
VALUES ((SELECT id FROM tax_articles WHERE article_number = '85'), '85.1',
        'Hər bir vergiyə dair ödənilmə müddətləri müəyyən edilir. Vergilərin müəyyən edilmiş ödənilmə müddətinin dəyişdirilməsi yalnız bu Məcəllə ilə müəyyən edilmiş qaydada həyata keçirilə bilər.',
        1, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '85'), '85.2',
        'Vergilərin (o cümlədən cari vergi ödəmələrinin) ödənilmə müddətlərinin pozulmasına görə vergi ödəyicisi bu Məcəllə ilə müəyyən edilmiş qaydada və şərtlərlə faiz ödəyir.',
        2, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '85'), '85.3',
        'Vergilərin ödənilməsi müddəti təqvim tarixi ilə və ya illərlə, rüblərlə, aylarla, dekadalarla, həftələrlə və günlərlə hesablanan dövrün qurtarması ilə, habelə baş verməli hadisə və yaxud edilməli olan hərəkət göstərilməklə müəyyən olunur.',
        3, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '85'), '85.4',
        'Vergi orqanları vergiyə cəlb edilən hesabat dövrü qurtardıqdan sonra 3 il ərzində vergi ödəyicisinin vergisini, faizləri və maliyyə sanksiyasını hesablamaq və hesablanmış məbləği yenidən hesablamaq, verginin, faizlərin və maliyyə sanksiyalarının hesablanmış (yenidən hesablanmış) məbləğini vergiyə cəlb edilən hesabat dövrü qurtardıqdan sonra (səyyar vergi yoxlaması zamanı əlavə hesablanmış vergilər, faizlər və maliyyə sanksiyaları üzrə səyyar vergi yoxlamasının materiallarına baxılmanın nəticələri üzrə çıxarılmış qərarın tarixindən etibarən) 5 il ərzində tutmaq hüququna malikdirlər. Bu maddə ilə müəyyən edilən 3 illik müddət (məcburi dövlət sosial sığorta, işsizlikdən sığorta və icbari tibbi sığorta haqları istisna olmaqla) səyyar vergi yoxlamasının keçirilməsi barədə vergi orqanının qərar qəbul etdiyi tarixdən əvvəlki 3 illik dövrü əhatə edir. Vergi ödəyicisi tərəfindən bu maddədə göstərilən müddətdə təqdim edilən vergi bəyannaməsi üzrə vergi orqanı tərəfindən vergilərin hesablanması bu Məcəllənin 37.2-ci maddəsində göstərilən müddətdə həyata keçirilir. Bu maddənin digər müddəalarından asılı olmayaraq, xarici dövlətlərin səlahiyyətli orqanlarından sorğu və ya xaricdə əldə olunan gəlirlər üzrə müvafiq məlumatlar daxil olduğu hallarda, kameral vergi yoxlamaları sorğu və ya məlumat daxil olduğu tarixdən, səyyar vergi yoxlamaları isə yoxlamanın keçirilməsi haqqında vergi orqanının qərar qəbul etdiyi tarixdən əvvəlki 5 illik dövrü, Azərbaycan Respublikasının Cinayət-Prosessual Məcəlləsinə uyğun olaraq təyin edilən vergi yoxlamaları üzrə Azərbaycan Respublikasının Cinayət Məcəlləsinə müvafiq olaraq cinayət məsuliyyətinə cəlbetmə müddəti ilə müəyyən edilən dövrü əhatə edir.',
        4, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '85'), '85.5',
        'Vergi ödəyicisi vergi hesabatı dövrü qurtardıqdan sonra 3 il ərzində ondan düzgün tutulmamış vergilərin, faizlərin və maliyyə sanksiyalarının hesablanmasını və hesablanmış məbləğin yenidən hesablanmasını, artıq ödənilmiş vergilərin, faizlərin və maliyyə sanksiyalarının məbləğinin qaytarılmasını və ya əvəzləşdirilməsini vergiyə cəlb edilən hesabat dövrü qurtardıqdan sonra (bu Məcəllənin 38.3.3-cü və 38.3.4-cü maddələrinə uyğun olaraq həyata keçirilən səyyar vergi yoxlamasının nəticələri üzrə çıxarılmış qərarın tarixindən etibarən) 5 il ərzində tələb etmək hüququna malikdir.',
        5, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '85'), '85.5-1',
        'Bu Məcəllənin 85.4-cü və 85.5-ci maddələrində müddətlə bağlı müəyyən edilmiş məhdudiyyətlər məcburi dövlət sosial sığorta haqqına, işsizlikdən sığorta haqqına və icbari tibbi sığorta haqlarına (bu sığorta haqları ilə bağlı tətbiq edilmiş maliyyə sanksiyaları və hesablanmış faizlər istisna olmaqla), habelə bu Məcəllənin 38.3.9-cu maddəsində nəzərdə tutulan hallara münasibətdə tətbiq edilmir.',
        6, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '85'), '85.5-2',
        'Vergi ödəyicisi vergi orqanı tərəfindən hesablanmış vergilər, faizlər və tətbiq edilmiş maliyyə sanksiyalarından məhkəməyə şikayət verdikdə həmin şikayətin verildiyi tarixdən məhkəmənin qanuni qüvvəyə minmiş qərarı qəbul olunan tarixədək keçən müddət, habelə bu Məcəllənin 38.7.1-ci, 38.7.2-ci, 38.7.4-cü, 38.7.4-1-ci və 38.7.5-ci maddələri ilə müəyyən olunan müddətlər bu Məcəllənin 85.4-cü və 85.5-ci maddələri ilə müəyyən olunmuş müddətə daxil edilmir.',
        7, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '85'), '85.6',
        'Bu Məcəllənin 85.8-ci maddəsinin müddəaları nəzərə alınmaqla vergi öhdəliklərinin yerinə yetirilməsi müddətləri aşağıda göstərilən halların biri olduqda bu Məcəllə ilə müəyyən edilmiş müddətdən daha gec müddətə dəyişdirilə bilər:',
        8, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '85'), '85.6.1',
        'təbii fəlakət, təhlükə potensiallı obyektlərdə baş verən qəzalar və ya digər qarşısı alınmaz qüvvə nəticəsində vergi ödəyicisinə zərər dəydikdə. Bu halda vergi ödəyicisi hadisənin baş verməsi barədə və onun nəticəsində dəymiş zərərin məbləği barədə müvafiq dövlət orqanlarının arayışlarını təqdim etməlidir;',
        9, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '85'), '85.6.2',
        'vergi borcunu birdəfəyə ödədiyi təqdirdə vergi ödəyicisinin iflasa uğramaq təhlükəsi olduqda və ya vergi ödəyicisinin vergi borcunu birdəfəyə ödəmə qabiliyyəti olmadıqda. Vergi ödəyicisinin vergi borcunu ödəmə qabiliyyətinin müəyyənləşdirilməsi qaydası müvafiq icra hakimiyyəti orqanının müəyyən etdiyi orqan (qurum) tərəfindən müəyyən edilir;',
        10, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '85'), '85.6.3',
        '"Dövlət satınalmaları haqqında" Azərbaycan Respublikasının Qanununa uyğun olaraq dövlət sifarişlərinin yerinə yetirilməsi ilə əlaqədar olaraq vergi ödəyicisi tərəfindən yerinə yetirilmiş dövlət sifarişi üzrə müvafiq icra hakimiyyəti orqanının müəyyən etdiyi orqan (qurum) tərəfindən verilmiş sifarişçinin borclu olduğunu təsdiq edən arayış təqdim edildikdə;',
        11, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '85'), '85.6.4',
        'vergi ödəyicisi tərəfindən yalnız mövsümi xarakterli malların təqdim edilməsi, işlər görülməsi və ya xidmətlər göstərilməsi həyata keçirildikdə.',
        12, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '85'), '85.6-1',
        'Bu Məcəllənin 85.6.2 - 85.6.4-cü maddələri məcburi dövlət sosial sığorta, işsizlikdən sığorta və icbari tibbi sığorta haqlarına münasibətdə tətbiq edilmir.',
        13, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '85'), '85.7',
        'Vergilərin ödənilmə müddətinin dəyişdirilməsi mövcud olan öhdəliyi ləğv etmir və yeni vergi öhdəliyi yaratmır.',
        14, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '85'), '85.8',
        'Aşağıdakı hallarda vergi öhdəliyinin yerinə yetirilməsi müddəti uzadıla bilməz:',
        15, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '85'), '85.8.1',
        'vergi ödəyicisinə münasibətdə vergi qanunvericiliyinin pozulması ilə bağlı cinayət işi qaldırıldıqda;',
        16, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '85'), '85.8.2',
        'vergi ödəyicisi riskli vergi ödəyicisi olduqda;',
        17, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '85'), '85.8.3',
        'vergi öhdəliyinin məbləği vergi ödəyicisi tərəfindən məhkəmə və ya inzibati qaydada mübahisələndirildikdə;',
        18, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '85'), '85.8.4',
        'vergi öhdəliyinin məbləği sahibkarlıq subyektlərinin kateqoriyası üzrə müvafiq olaraq bu Məcəllənin 85.9-cu maddəsində müəyyən edilmiş məbləğlərin aşağı həddindən az olduqda;',
        19, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '85'), '85.8.5',
        'bu Məcəllənin 85.6.3-cü və 85.6.4-cü maddələrinə münasibətdə müraciət edən vergi ödəyicisinin vergi orqanında uçotda olduğu müddət 2 ildən az olduqda;',
        20, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '85'), '85.8.6',
        'vergi ödəyicisi tərəfindən son bir il ərzində müddəti uzadılmış vergi öhdəliyi vaxtında yerinə yetirilmədikdə;',
        21, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '85'), '85.8.7',
        'vergi ödəyicisi bu Məcəllənin 85.9-3-cü maddəsində nəzərdə tutulan ödənişi etmədikdə.',
        22, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '85'), '85.9',
        'Vergi öhdəliyinin yerinə yetirilməsi müddətinin uzadılması üçün vergi ödəyicisi tərəfindən vergi növü (növləri) üzrə vergi orqanına yazılı müraciət təqdim edilməlidir. Vergi ödəyicisinin borcu 500 manatdan 300 000 manatadək olduqda, vergi ödəyicisi tərəfindən müraciətə aşağıda göstərilən məlumatları əks etdirən sənədlər əlavə edilir:',
        23, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '85'), '85.9.1',
        'bu Məcəllənin 85.6-cı maddəsində nəzərdə tutulan hər bir hala münasibətdə müraciət edilmə tarixinə vergi ödəyicisinin kassasında, milli və ya xarici valyutada cari və ya digər hesablarında vəsaitlərin qalığı, debitorların və kreditorların VÖEN-i göstərilməklə adı və borcun məbləği, habelə son bir il ərzində bank və digər ödəniş hesabları üzrə aparılmış əməliyyatlar barədə arayışlar;',
        24, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '85'), '85.9.2',
        'bu Məcəllənin 85.6.1-ci maddəsində nəzərdə tutulan hala münasibətdə hadisənin baş verməsi barədə və onun nəticəsində dəymiş zərərin məbləği barədə müvafiq dövlət orqanlarının arayışları.',
        25, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '85'), '85.9-1',
        'Vergi öhdəliyinin məbləği sahibkarlıq subyektlərinin kateqoriyası üzrə müvafiq olaraq bu Məcəllənin 85.9-cu maddəsində müəyyən edilmiş məbləğlərin yuxarı həddindən çox olduqda - bu Məcəllənin 85.6.3-cü maddəsində nəzərdə tutulan hal istisna olmaqla, digər hallarda vergi ödəyiciləri tərəfindən müraciətə 85.9-cu maddədə göstərilən sənədlərlə yanaşı, aşağıdakı sənədlərdən hər hansı biri əlavə edilir:',
        26, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '85'), '85.9-1.1',
        'bank zəmanəti;',
        27, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '85'), '85.9-1.2',
        'zaminlik müqaviləsi. Həmin müqaviləyə əsasən zamin duran şəxs ən azı bir il müddətinə vergi orqanında qeydiyyata alınmış, vergilər, məcburi dövlət sosial sığorta, işsizlikdən sığorta və icbari tibbi sığorta haqları, faizlər və maliyyə sanksiyaları üzrə borcu olmayan, riskli vergi ödəyicisi olmayan şəxs olmalıdır və həmin şəxsin müraciət edən vergi ödəyicisinin vergi öhdəliyini yerinə yetirmək imkanına malik olması ilə bağlı qanunla nəzərdə tutulmuş qaydada yüklü edilməmiş aktivləri barədə məlumat vergi orqanına təqdim edilməlidir;',
        28, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '85'), '85.9-1.3',
        'girov müqaviləsi. Müqavilədə qanunla nəzərdə tutulmuş qaydada vergi öhdəliyinin təminatı kimi girov qoyulacaq əmlak barədə zəruri məlumatlar qeyd edilməlidir. Girov qoyulacaq əmlakın ümumi bazar dəyərinin 50 faizi borcun məbləğindən çox olmalıdır. Girov müqaviləsinin qanunla nəzərdə tutulmuş qaydada etibarsız hesab edilməsi vergi ödəyicisinin vergi öhdəliyini ləğv etmir. Girov müqaviləsinin qeydiyyatı ilə bağlı xərclər vergi ödəyicisi tərəfindən ödənilir.',
        29, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '85'), '85.9-1.4',
        'vergi ödəyicisinin mülkiyyətində olan və satış üçün yararlı daşınar və daşınmaz əmlakının siyahıya alınmasına dair yazılı razılıq. Razılıq sənədində həmin əmlak barədə zəruri məlumatlar qeyd edilməli, əmlakın ümumi bazar dəyərinin 50 faizi borcun məbləğindən çox olmalıdır. Vergi ödəyicisinin müraciəti təmin edildiyi halda, vergi öhdəliyinin yerinə yetirilməsi müddətinin uzadıldığı dövr ərzində razılıq sənədində qeyd edilən əmlaklar vergi ödəyicisinin istifadə hüququ saxlanılmaqla vergi orqanı tərəfindən siyahıya alınır. Vergi öhdəliyinin yerinə yetirilməsi müddətinin uzadıldığı dövr ərzində həmin əmlakların hərrac vasitəsilə satışı ilə bağlı vergi orqanı tərəfindən məhkəməyə müraciət edilmir və vergi ödəyicisi tərəfindən həmin əmlakların təqdim edilməsi vergi orqanının razılığı ilə həyata keçirilir.',
        30, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '85'), '85.9-2',
        'Vergi ödəyicisi tərəfindən bu Məcəllənin 85.6.3-cü maddəsində nəzərdə tutulan halla əlaqədar müraciət edildikdə, borcun məbləğindən asılı olmayaraq, yalnız bu Məcəllənin 85.9.1-ci maddəsində nəzərdə tutulan sənədlər əlavə olunur.',
        31, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '85'), '85.9-3',
        'Bu Məcəllənin 85.6-cı maddəsində nəzərdə tutulmuş əsaslar olduğu halda vergi ödəyicisi vergi öhdəliyinin yerinə yetirilməsi müddətinin uzadılması məqsədilə müraciətdə göstərilən vergi borcunun 10 faizini ödəməlidir.',
        32, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '85'), '85.10',
        'Bu Məcəllənin 85.6-cı maddəsində nəzərdə tutulmuş əsaslar olduqda, vergi öhdəliyinin yerinə yetirilməsi müddəti vergi orqanının qərarı ilə vergi ödəyicisinin seçimindən asılı olaraq aşağıdakı qaydada uzadıla bilər. Həmin müddət ərzində vergi ödəyicisinə faizlər hesablanmır.',
        33, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '85'), '85.10.1',
        'borcun ödənilməsinə 6 aydan çox olmayan müddətə möhlət verilməsi;',
        34, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '85'), '85.10.2',
        'cari vergi ödəmələri üzrə borcun ödənilməsinə təqvim ili ərzində 6 aydan çox olmayan müddətə möhlət verilməsi;',
        35, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '85'), '85.10.3',
        'vergi öhdəliyinin razılaşdırılmış qrafik əsasında hissə-hissə icrası şərtilə borcun ödənilməsinə 1 ildən çox olmayan müddətə möhlət verilməsi. Bu zaman ödəniş qrafiki vergi orqanı ilə vergi ödəyicisi arasında imzalanmış müvafiq aktla rəsmiləşdirilir.',
        36, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '85'), '85.10-1',
        'Vergi ödəyicisi tərəfindən möhlət verilən dövr ərzində möhlət verilmiş borcun 75 faizi ödənildiyi halda vergi ödəyicisinin müraciəti əsasında bu Məcəllənin 85.10.1-ci maddəsində müəyyən edilən müddət 1 ildən, 85.10.3-cü maddəsində müəyyən edilən müddət isə 2 ildən çox olmayan müddətə yuxarı vergi orqanının qərarı ilə artırıla bilər.',
        37, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '85'), '85.10-2',
        'Vergi orqanının qərarı ilə vergi öhdəliyinin yerinə yetirilməsi müddəti uzadıldığı halda həmin borca müraciət edilmə tarixindən etibarən müddətin uzadıldığı dövr ərzində bu Məcəllənin 85.9-1.4-cü maddəsində nəzərdə tutulan hal istisna olmaqla, borcun alınması ilə bağlı tədbirlər həyata keçirilmir və faizlər hesablanmır.',
        38, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '85'), '85.10-3',
        'Vergi orqanının qərarı ilə vergi borcunun ödənilməsinə möhlət verilən dövr ərzində vergi ödəyicisinin yeni vergi borcu yarandığı halda həmin vergi borcu bu Məcəllə ilə müəyyən edilmiş ümumi qaydada dövlət büdcəsinə ödənilir.',
        39, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '85'), '85.11',
        'Müvafiq icra hakimiyyəti orqanının müəyyən etdiyi orqan (qurum) müraciətin və digər sənədlərin daxil olduğu tarixdən 30 iş günü müddətində vergi ödəyicisinin müraciətinə baxır və bu Məcəllənin 85.6-cı maddəsində nəzərdə tutulmuş əsaslar olduğu halda vergi öhdəliyinin yerinə yetirilməsi müddətinin uzadılması barədə qərar qəbul edir. Qərarın qəbul edilməsi məqsədilə vergi orqanı bu Məcəllənin 85.9-3-cü maddəsində nəzərdə tutulan ödənişin edilməsi vəzifəsi barədə vergi ödəyicisinə yazılı məlumat verir. Qərarın qəbul edilməsi üçün müvafiq ödəniş vergi orqanının verdiyi məlumat alındığı tarixdən 3 iş günü ərzində vergi ödəyicisi tərəfindən həyata keçirilməlidir. Müvafiq icra hakimiyyəti orqanının müəyyən etdiyi orqanın (qurumun) vergi öhdəliyinin yerinə yetirilməsi müddətinin uzadılması haqqında qərarında müddətin uzadılması səbəbi, vergi üzrə borcun məbləği, ödənilməsi müddəti uzadılan verginin növü (növləri), ödənilmə müddəti və qaydası, habelə girov, bank zəmanəti, vergi ödəyicisinin mülkiyyətində olan siyahıya alınmış daşınar və daşınmaz əmlaklar və zamin haqqında qeydlər göstərilməlidir. Bu Məcəllənin 85.6-cı maddəsində nəzərdə tutulmuş əsaslar olmadığı halda vergi orqanı öhdəliyinin yerinə yetirilməsi müddətinin uzadılmasından imtina edilməsi barədə qərar qəbul edir və həmin qərarda imtinanın səbəbləri göstərilir.',
        40, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '85'), '85.12',
        'Vergi öhdəliyinin yerinə yetirilməsi müddətinin uzadılması haqqında qərar bu qərarda müəyyən edilmiş tarixdən qüvvəyə minir. Vergi orqanının qərarı əsasında vergi öhdəliyinin yerinə yetirilməsinin uzadıldığı müddət bu Məcəllənin 85.4-cü maddəsində nəzərdə tutulan vergi borcunun tələb edilməsi ilə bağlı 5 illik müddətə daxil edilmir.',
        41, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '85'), '85.13',
        'Girov müqaviləsinin qanunvericilikdə nəzərdə tutulmuş qaydada etibarsız hesab edilməsi vergi ödəyicisinin vergi öhdəliyini ləğv etmir. Girov müqaviləsinin qeydiyyatı ilə bağlı xərclər vergi ödəyicisi tərəfindən ödənilir.',
        42, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '85'), '85.14',
        'Vergi öhdəliyinin yerinə yetirilməsinin uzadılmış müddətinə aşağıdakı hallarda vaxtından əvvəl xitam verilir:',
        43, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '85'), '85.14.1',
        'vergi ödəyicisi vergi öhdəliyini vaxtından əvvəl yerinə yetirdikdə;',
        44, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '85'), '85.14.2',
        'bu Məcəllənin 85.8.1-85.8.3-cü maddələrində nəzərdə tutulmuş hallarda;',
        45, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '85'), '85.14.3',
        'vergi orqanının vergi öhdəliyinin yerinə yetirilməsi müddətinin uzadılması barədə qərarının şərtlərinə əməl edilmədikdə.',
        46, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '85'), '85.15',
        'Bu Məcəllənin 85.14.2-ci və 85.14.3-cü maddələrində nəzərdə tutulmuş hallarda vergi öhdəliyinin yerinə yetirilməsinin uzadılmış müddətinə vaxtından əvvəl xitam verilməsi haqqında vergi orqanı tərəfindən qərar verilməklə, bu Məcəllənin 85.9-1-ci maddəsində nəzərdə tutulan təminatlar hesabına vergi borcunun alınması təmin edilir və 5 gün müddətində vergi ödəyicisinə bu barədə məlumat verilir.',
        47, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '85'), '85.16',
        'Müvafiq icra hakimiyyəti orqanı rüblər üzrə (dövri olaraq) müddəti uzadılan vergi öhdəliklərinin məbləği barədə müvafiq icra hakimiyyəti orqanına məlumat verir.',
        48, false, NOW(), NOW());

