        true, NOW(), NOW());

INSERT INTO tax_sections (article_id, section_number, content, order_index, synced_to_vector_store, created_at,
                          updated_at)
VALUES ((SELECT id FROM tax_articles WHERE article_number = '86'), '86.0',
        'Vergi aşağıdakı yerlərdə ödənilir:',
        1, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '86'), '86.0.1',
        'bildirişdə göstərilən yerdə;',
        2, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '86'), '86.0.2',
        'Bu Məcəllədə başqa hallar nəzərdə tutulmamışdırsa, vergi ödəyicisinin uçotda olduğu yer üzrə;',
        3, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '86'), '86.0.3',
        'vergi agentləri ödəmə mənbəyində tutulmuş vergiləri özlərinin uçotda olduqları yer üzrə;',
        4, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '86'), '86.0.4',
        'bu Məcəllədə verginin ödənildiyi yer müəyyən edilməmişdirsə, vergi ödəyicisi fiziki şəxsin yaşadığı yer üzrə, yaxud vergi ödəyicisi hüquqi şəxsin idarə olunduğu yer üzrə.',
        5, false, NOW(), NOW());

