-- TAX ARTICLE (Maddə 87)
-- ============================
INSERT INTO tax_articles (article_number, title, chapter, active, created_at, updated_at)
VALUES ('87',
        'Artıq ödənilmiş vergilərin, faizlərin və maliyyə sanksiyalarının məbləğlərinin qaytarılması',
        'VII fəsil. Vergilərin ödənilməsi üzrə ümumi qaydalar',
        true, NOW(), NOW());

INSERT INTO tax_sections (article_id, section_number, content, order_index, synced_to_vector_store, created_at,
                          updated_at)
VALUES ((SELECT id FROM tax_articles WHERE article_number = '87'), '87.1',
        'Vergilərin, faizlərin və maliyyə sanksiyalarının ödənilmiş məbləğləri onların hesablanmış məbləğlərindən artıq olduqda, inzibati cərimələr üzrə borclar istisna olmaq şərti ilə, artıq ödənilmiş məbləğlər:',
        1, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '87'), '87.1.1',
        'digər vergilərin, faizlərin, maliyyə sanksiyalarının və inzibati cərimələr üzrə borcların ödənilməsi hesabına aid edilir;',
        2, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '87'), '87.1.2',
        'vergi ödəyicisinin razılığı ilə sonrakı öhdəliklər üzrə ödəmələrin hesabına aid edilir.',
        3, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '87'), '87.2',
        'Vergi ödəyicisinin ödədiyi vergilərin, faizlərin və maliyyə sanksiyalarının artıq məbləğləri digər vergilərin, faizlərin və maliyyə sanksiyalarının ödənilməsi hesabına aid edildiyi halda, vergi ödəyicisinin tələbi ilə ona şəxsi vərəqədən çıxarış və üzləşmə aktı verilir, habelə rübdə bir dəfə rüb başa çatdıqdan sonra 20 gün ərzində ona bildiriş göndərilir. Azərbaycan Respublikasının Cinayət Prosessual Məcəlləsinə müvafiq olaraq Azərbaycan Respublikası Cinayət Məcəlləsinin 213-cü və 213-1-ci maddələrində nəzərdə tutulmuş cinayətlərə dair işlər üzrə müvafiq icra hakimiyyəti orqanı tərəfindən ibtidai istintaq aparıldığı zaman vergi yoxlaması ilə əhatə olunmamış dövr üzrə şəxsi vərəqədən çıxarış və üzləşmə aktı verilmir.',
        4, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '87'), '87.3',
        'Bu Məcəllədə başqa hallar müəyyən edilməmişdirsə, artıq ödənilmiş vergilərin, faizlərin və maliyyə sanksiyalarının qalan məbləğləri vergi ödəyicisinin yazılı ərizəsinə əsasən 45 gün ərzində vergi ödəyicisinə qaytarılır.',
        5, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '87'), '87.3-1',
        'Riskli vergi ödəyiciləri tərəfindən artıq ödəmənin qaytarılması ilə bağlı müraciət edildikdə bu maddə ilə müəyyən edilən müddətlər onların fəaliyyəti üzrə kameral və ya səyyar vergi yoxlamaları və operativ vergi nəzarəti tədbirləri tam başa çatdıqdan sonra tətbiq edilir.',
        6, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '87'), '87.4',
        'Artıq ödənilmiş vergilərin, faizlərin və maliyyə sanksiyalarının məbləğlərinin vergi ödəyicisinə qaytarılması qaydaları müvafiq icra hakimiyyəti orqanı tərəfindən müəyyən edilir.',
        7, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '87'), '87.5',
        'Bu maddənin digər müddəalarından və bu Məcəllənin 179-cu maddəsindən asılı olmayaraq, rekvizitlərin səhv göstərilməsi və (və ya) ödəniş əməliyyatlarının səhv icra olunması nəticəsində səhv ödənilmiş məbləğlər vergi ödəyicisinin borcu olmadığı halda bu Məcəllənin 87.4-cü maddəsinə müvafiq olaraq 20 gün ərzində (məcburi dövlət sosial sığorta, işsizlikdən sığorta və icbari tibbi sığorta haqlarına münasibətdə 45 gün ərzində) qaytarılır.',
        8, false, NOW(), NOW());

