INSERT INTO tax_articles (article_number, title, chapter, active, created_at, updated_at)
VALUES ('88',
        'Vergilər üzrə borcların ödənilməsi qaydası',
        'VII fəsil. Vergilərin ödənilməsi üzrə ümumi qaydalar',
        true, NOW(), NOW());

INSERT INTO tax_sections (article_id, section_number, content, order_index, synced_to_vector_store, created_at,
                          updated_at)
VALUES ((SELECT id FROM tax_articles WHERE article_number = '88'), '88.1',
        'Məhkəmənin qanuni qüvvəyə minmiş qərarı ilə təmin edilmiş borc məbləğləri istisna olmaqla, vergilər üzrə yaranmış borc bu Məcəllənin 85.4-cü maddəsinin müddəaları nəzərə alınmaqla aşağıdakı sıra qaydası ilə ödənilir:',
        1, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '88'), '88.1.1',
        'yaranma tarixi ardıcıllığı ilə hesablanmış verginin məbləği;',
        2, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '88'), '88.1.2',
        'hesablanmış faizlərin məbləği;',
        3, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '88'), '88.1.3',
        'tətbiq edilmiş maliyyə sanksiyalarının məbləği.',
        4, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '88'), '88.2',
        'Məhkəmənin qanuni qüvvəyə minmiş qərarı ilə təmin edilmiş borc məbləğləri istisna olmaqla, məcburi dövlət sosial sığorta üzrə yaranmış borc aşağıdakı sıra qaydası ilə ödənilir:',
        5, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '88'), '88.2.1',
        'cari rüb üzrə borc;',
        6, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '88'), '88.2.2',
        'cari rübdən geriyə doğru (daha əvvəl yaranan borclar üzrə) yaranan borclar ardıcıl olaraq;',
        7, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '88'), '88.2.3',
        'yaranma tarixi ardıcıllığı ilə hesablanmış faizlərin məbləği;',
        8, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '88'), '88.2.4',
        'yaranma tarixi ardıcıllığı ilə tətbiq edilmiş maliyyə sanksiyalarının məbləği.',
        9, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '88'), '88.2-1',
        'Məhkəmənin qanuni qüvvəyə minmiş qərarı ilə təmin edilmiş borc məbləğləri bu Məcəllənin 88.1-ci və 88.2-ci maddələrində göstərilən sıra qaydasından asılı olmayaraq, hər bir qətnamə üzrə ayrılıqda ödənilir.',
        10, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '88'), '88.3',
        'Cari rüb üzrə borc ödənildikdən sonra sığortaedənin artıq vəsaiti qaldığı təqdirdə, həmin vəsait bu Məcəllənin 88.2.2 – 88.2.4-cü maddələrində göstərilən qaydada əvvəlki borcların ödənilməsinə aid edilir.',
        11, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '88'), '88.4',
        'Bu Məcəllənin 88.1.1-ci maddəsinin müddəaları bu Məcəllənin 221.4.7-ci və 221.8.6-cı maddələrində nəzərdə tutulan hallara şamil edilmir.',
        12, false, NOW(), NOW());

