-- TAX ARTICLE (Maddə 89)
-- ============================
INSERT INTO tax_articles (article_number, title, chapter, active, created_at, updated_at)
VALUES ('89',
        'Əmlakın siyahıya alınması',
        'VII fəsil. Vergilərin ödənilməsi üzrə ümumi qaydalar',
        true, NOW(), NOW());

INSERT INTO tax_sections (article_id, section_number, content, order_index, synced_to_vector_store, created_at,
                          updated_at)
VALUES ((SELECT id FROM tax_articles WHERE article_number = '89'), '89.1',
        'Vergi ödəyicisi vergi öhdəliyini bu Məcəllə ilə müəyyən edilmiş müddətdə yerinə yetirmədikdə yaranmış vergi borclarının, habelə həmin öhdəliyin yerinə yetirilməməsi ilə əlaqədar vergi borcu üzrə hesablanmış faizlərin və tətbiq edilmiş maliyyə sanksiyalarının ödənilməsini təmin etmək üsulu kimi onun əmlakı siyahıya alına bilər.',
        1, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '89'), '89.2',
        'Əmlakın siyahıya alınması vergi ödəyicisinin öz əmlakı barəsində hüquqlarının elə məhdudlaşdırılmasıdır ki, bu zaman vergi ödəyicisi siyahıya alınmış əmlaka və ya onun bir hissəsinə sərəncam vermək hüququna malik olmur, həmin əmlaka sahiblik və ondan istifadə edilməsi vergi orqanının nəzarəti ilə həyata keçirilir.',
        2, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '89'), '89.3',
        'Vergi ödəyicisi vergilər, faizlər və maliyyə sanksiyaları üzrə borclarını bu Məcəllənin 65.1-ci maddəsində qeyd olunan bildirişdə göstərilən müddət ərzində ödəmədikdə vergi orqanı müvafiq icra hakimiyyəti orqanı tərəfindən müəyyən edilmiş formada aktivləri barədə məlumatın 10 gün ərzində vergi orqanına təqdim edilməsini vergi ödəyicisindən tələb edə bilər. Məlumatın vaxtında verilməməsinə görə vergi ödəyicisi bu Məcəllənin tələblərinə uyğun olaraq məsuliyyət daşıyır. Vergi ödəyicisinin vergi öhdəliyini yerinə yetirməkdən boyun qaçırması barədə vergi orqanının kifayət qədər əsası olduqda, habelə vergi ödəyicisi riskli vergi ödəyicisi olduğu halda vergi orqanı vergi ödəyicisinə yazılı bildiriş göndərməklə eyni zamanda ondan vergi öhdəliyini dərhal ödəməyi tələb edə bilər. Vergi ödəyicisi bu maddənin ikinci abzasında nəzərdə tutulmuş hallarda vergi öhdəliyini yerinə yetirmədikdə, vergi orqanı özünün əsaslandırılmış qərarı əsasında vergi ödəyicisinin əmlakının siyahıya alınmasını həyata keçirə bilər. Təxirəsalınmaz hallar istisna olunmaqla, gecə vaxtı (axşam saat 20.00-dan səhər saat 8.00-qədər) əmlakın siyahıya alınmasına yol verilmir.',
        3, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '89'), '89.4',
        'Vergi ödəyicisi olan hüquqi şəxsin bütün əmlakı, vergi ödəyicisi olan fiziki şəxsin isə Azərbaycan Respublikasının qanunvericiliyinə əsasən tələb yönəldilə bilməyən əmlakından başqa digər əmlakı siyahıya alına bilər.',
        4, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '89'), '89.5',
        'Yalnız vergi öhdəliyinin yerinə yetirilməsi, həmin öhdəliyin yerinə yetirilməməsi ilə əlaqədar vergi borcu üzrə hesablanmış faizlərin və tətbiq edilmiş maliyyə sanksiyalarının, habelə əmlakın satışı üzrə xərclərin ödənilməsi üçün zəruri və kifayət olan, satış üçün yararlı və öz əmtəə xassəsini itirməmiş əmlak siyahıya alınır.',
        5, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '89'), '89.6',
        'Əmlakın siyahıya alınması bu Məcəllənin 89.5-ci maddəsinin müddəaları nəzərə alınmaqla aşağıdakı ardıcıllıqla həyata keçirilir: nağd pul vəsaitləri; bilavasitə məhsulların (malların) istehsalında iştirak etməyən əmlak (qiymətli kağızlar, valyuta dəyərliləri, qeyri-istehsal binaları, minik avtonəqliyyatı, xidmət otaqlarının dizayn əşyaları və sair); hazır məhsullar (mallar), habelə istehsalda iştirak etməyən və (və ya) bilavasitə istehsalda iştirakı nəzərdə tutulmayan digər maddi qiymətlilər; istehsalda bilavasitə iştirakı nəzərdə tutulmuş xammal və materiallar, habelə dəzgahlar, avadanlıqlar, binalar, qurğular və digər əsas vəsaitlər; inventarizasiya aparılmaqla digər əmlak.',
        6, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '89'), '89.7',
        'Əmlakın siyahıya alınması vergi orqanının rəhbərinin qərarına əsasən həyata keçirilir. Qərarda vergi ödəyicisinin adı və əmlakın yerləşdiyi ünvan göstərilməlidir.',
        7, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '89'), '89.8',
        'Əmlakın siyahıya alınması vergi ödəyicisinin, habelə müşahidəçilərin və zəruri hallarda mütəxəssislərin iştirakı ilə vergi orqanı tərəfindən həyata keçirilir. Əmlakın siyahıya alınmasını həyata keçirən vergi orqanı vergi ödəyicisinin (onun qanuni və (və ya) səlahiyyətli nümayəndəsinin) əmlakın siyahıya alınması prosesində iştirak etməsinə icazə verməməyə səlahiyyətli deyildir. Əmlakın siyahıya alınması prosesində müşahidəçilərə, mütəxəssis kimi iştirak edən şəxslərə, həmçinin vergi ödəyicisinə (onun nümayəndəsinə) onların hüquq və vəzifələri izah edilməlidir.',
        8, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '89'), '89.8-1',
        'Dövlət reyestri aparılan daşınmaz və daşınar əmlakı mövcud olan borclu vergi ödəyicisinin həmin əmlakının siyahıya alınmaya təqdim edilməsi məqsədilə, vergi orqanı tərəfindən əmlakın siyahıya alınması haqqında çıxarılmış qərarla birlikdə vergi ödəyicisinə müvafiq yazılı xəbərdarlıq da göndərilir. Vergi ödəyicisi dövlət reyestri aparılan daşınmaz və daşınar əmlakı vergi orqanı tərəfindən müvafiq yazılı xəbərdarlıq edildikdən sonra da həmin xəbərdarlıqda müəyyən edilmiş müddətdə və yerdə siyahıya alınmaya təqdim etməkdən yayınarsa, həmin əmlak reyestr məlumatlarına əsasən vergi ödəyicisinin (onun qanuni və (və ya) səlahiyyətli nümayəndəsinin) və müşahidəçilərin iştirakı olmadan vergi orqanı tərəfindən siyahıya alınır. Əmlakın siyahıya alınmasının vaxtı və yeri barədə yazılı qaydada xəbərdar edilmiş vergi ödəyicisi (onun qanuni və (və ya) səlahiyyətli nümayəndəsi) əmlakın siyahıya alınması prosesində iştirak etmədiyi halda, əmlakın siyahıya alınmasını həyata keçirən vergi orqanının vəzifəli şəxsləri 1 iş günü müddətində vergi ödəyicisinə (onun qanuni və (və ya) səlahiyyətli nümayəndəsinə) əmlakın siyahıya alınması haqqında protokolun surətini əlavələri ilə birlikdə göndərir. Vergi orqanı dövlət reyestri aparılan daşınar və daşınmaz əmlakın bu Məcəlləyə uyğun olaraq siyahıya alınmasını apardıqdan sonra 1 iş günü müddətində həmin əmlakın yüklü edilməsi barədə məlumatı bu əmlakın dövlət reyestrini aparan səlahiyyətli dövlət orqanına (qurumuna) elektron və ya kağız daşıyıcıda verir.',
        9, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '89'), '89.9',
        'Əmlakın siyahıya alınmasını həyata keçirən vergi orqanının vəzifəli şəxsləri vergi ödəyicisinə (onun nümayəndəsinə) siyahıya alınma haqqında vergi orqanının rəhbərinin qərarını və özlərinin səlahiyyətlərini təsdiq edən sənədi təqdim etməlidirlər.',
        10, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '89'), '89.10',
        'Siyahıya alınma zamanı vergi orqanının vəzifəli şəxsləri tərəfindən əmlakın siyahıya alınması haqqında protokol tərtib edilir, əmlak siyahıya alınır və bu siyahı əmlakın fotoşəkli ilə birlikdə (dövlət reyestri aparılan daşınar və daşınmaz əmlakın reyestr məlumatlarına əsasən siyahıya alınması halı istisna olmaqla) protokola əlavə edilir. Siyahıda əmlakın dəqiq adı, sayı, fərdi əlamətləri, mümkün olduqda qiymətləri göstərilməklə əmlak tam təsvir edilir. Siyahıya alınan bütün əmlak müşahidəçilərə və vergi ödəyicisinə (onun nümayəndəsinə) baxış üçün təqdim edilir. Vergi ödəyicisi siyahıya alınmış əmlakı barəsində bu Məcəllənin 89.2-ci və 89.11-ci maddələrində müəyyən edilmiş məhdudiyyətlərin pozulmasına görə Azərbaycan Respublikasının qanunvericiliyinə uyğun olaraq məsuliyyət daşıdığı barədə vergi orqanı tərəfindən xəbərdar edilir.',
        11, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '89'), '89.11',
        'Vergi ödəyicisinin bu maddənin müəyyənləşdirdiyi qaydanı pozaraq siyahıya alınmış əmlaka dair bağladığı əqdlər etibarsız sayılır.',
        12, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '89'), '89.12',
        'Əmlakın siyahıya alınması haqqında qərar qanunla müəyyən edilmiş qaydada ləğv edildiyi andan, yaxud vergi öhdəliyinin yerinə yetirildiyi andan öz qüvvəsini itirir.',
        13, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '89'), '89.13',
        'Aksiz markası ilə markalanmalı olan markalanmamış və ya saxta aksiz markası ilə markalanmış, habelə məcburi nişanlama ilə nişanlanmalı olan, ancaq nişanlanmamış və ya saxta məcburi nişanlama ilə nişanlanmış malların siyahıya alınması aşağıdakı qaydada həyata keçirilir:',
        14, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '89'), '89.13.1',
        'Aksiz markası ilə markalanmalı olan markalanmamış və ya saxta aksiz markası ilə markalanmış, habelə məcburi nişanlama ilə nişanlanmalı olan, ancaq nişanlanmamış və ya saxta məcburi nişanlama ilə nişanlanmış malların siyahıya alınması vergi ödəyicisinin həmin mallar barəsində hüquqlarının elə məhdudlaşdırılmasıdır ki, bu zaman vergi ödəyicisi siyahıya alınmış aksiz markası ilə markalanmalı olan markalanmamış və ya saxta aksiz markası ilə markalanmış, habelə məcburi nişanlama ilə nişanlanmalı olan, ancaq nişanlanmamış və ya saxta məcburi nişanlama ilə nişanlanmış mallara sahiblik, onlardan istifadə etmək və sərəncam vermək hüququna malik deyildir.',
        15, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '89'), '89.13.2',
        'Aksiz markaları ilə markalanmalı olan malların həmin markalarla markalanmadan və ya saxta aksiz markaları ilə markalanmaqla, habelə məcburi nişanlama ilə nişanlanmalı olan malların məcburi nişanlama ilə nişanlanmadan və ya saxta məcburi nişanlama ilə nişanlanmaqla satışı və ya saxlanılması aşkar edildikdə (içməli spirtin, pivənin, spirtli içkilərin bütün növlərinin və tütün məmulatlarının) ümumi miqdarı, aksiz markaları ilə markalanmalı olan markalanmamış və ya saxta aksiz markaları ilə markalanmış malların (içməli spirtin, pivənin, spirtli içkilərin bütün növlərinin və tütün məmulatlarının), habelə məcburi nişanlama ilə nişanlanmalı olan, ancaq nişanlanmamış və ya saxta məcburi nişanlama ilə nişanlanmış malların miqdarı müvafiq icra hakimiyyəti orqanı tərəfindən təsdiq edilmiş formaya uyğun olan aktla, hüquqi şəxslərin və sahibkarlıq fəaliyyətini hüquqi şəxs yaratmadan həyata keçirən fiziki şəxsin rekvizitləri və onların səlahiyyətli nümayəndəsinin adı və soyadı göstərilməklə rəsmiləşdirilir, akt vergi orqanının nümayəndələrinin, habelə obyektin məsul şəxsinin və müşahidəçilərin imzaları ilə təsdiqlənir. Vergi ödəyicisi və ya onun səlahiyyətli nümayəndəsi aktda öz qeydlərini edə bilər, aktı imzalamaqdan imtina edə bilər və bu barədə həmin aktda müvafiq qeyd aparılır.',
        16, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '89'), '89.13.3',
        'Aksiz markaları ilə markalanmalı olan markalanmamış və ya saxta aksiz markası ilə markalanmış malların (içməli spirtin, pivənin, spirtli içkilərin bütün növlərinin və tütün məmulatlarının), habelə məcburi nişanlama ilə nişanlanmalı olan, ancaq nişanlanmamış və ya saxta məcburi nişanlama ilə nişanlanmış malların müvafiq icra hakimiyyəti orqanı tərəfindən təsdiq edilmiş formaya uyğun olan siyahısı tərtib edilir. Siyahıda həmin malların adı, fərqləndirici əlamətləri, mənşə mənbəyi, alış və satış qiymətləri, vergi orqanının adı, siyahıya almanı həyata keçirən vəzifəli şəxslərin adı, soyadı və atasının adı, siyahıya almanın həyata keçirildiyi tarix və yer, vergi ödəyicisi və onun nümayəndəsi haqqında məlumat, müşahidəçilər və dəvət olunmuş mütəxəssislər haqqında məlumatlar əks etdirilir.',
        17, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '89'), '89.13.4',
        'Aksiz markaları ilə markalanmalı olan markalanmamış və ya saxta aksiz markaları ilə markalanmış malların (içməli spirtin, pivənin, spirtli içkilərin bütün növlərinin və tütün məmulatlarının), habelə məcburi nişanlama ilə nişanlanmalı olan, ancaq nişanlanmamış və ya saxta məcburi nişanlama ilə nişanlanmış malların mənşə mənbəyi, alış və satış qiymətləri ilkin sənədlərlə və ya vəzifəli şəxsdən (vəzifəli şəxs olmadıqda satıcıdan) alınmış izahatla müəyyənləşdirilir.',
        18, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '89'), '89.13.5',
        'Azərbaycan Respublikasının İnzibati Xətalar Məcəlləsində göstərilən inzibati xətalara yol vermiş vəzifəli şəxs (şəxslər) barəsində həmin Məcəlləyə müvafiq olaraq protokol tərtib olunur.',
        19, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '89'), '89.13.6',
        'Tərtib olunmuş aktın və siyahının surətləri vəzifəli şəxsə verilir.',
        20, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '89'), '89.13.7',
        'Aksiz markası ilə markalanmalı olan markalanmamış və ya saxta aksiz markası ilə markalanmış, habelə məcburi nişanlama ilə nişanlanmalı olan, ancaq nişanlanmamış və ya saxta məcburi nişanlama ilə nişanlanmış malların siyahıya alınmasını həyata keçirən vergi orqanının nümayəndəsi həmin malların siyahıya alınması prosesində vergi ödəyicisinin və ya onun nümayəndəsinin iştirak etməsinə icazə verməməyə səlahiyyətli deyildir.',
        21, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '89'), '89.13.8',
        'Aksiz markası ilə markalanmalı olan markalanmamış və ya saxta aksiz markası ilə markalanmış, habelə məcburi nişanlama ilə nişanlanmalı olan, ancaq nişanlanmamış və ya saxta məcburi nişanlama ilə nişanlanmış malların siyahıya alınması prosesində vergi orqanının nümayəndəsi vergi ödəyicisinə və ya onun nümayəndəsinə hüquq və vəzifələrini izah etməlidir.',
        22, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '89'), '89.14',
        'Siyahıya alınmış malların vergi ödəyicisində məsul saxlamaya qoyulması aşağıdakı qaydada həyata keçirilir:',
        23, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '89'), '89.14.1',
        'Siyahıya alınmış mallar vergi ödəyicisində və ya onun razılığı ilə vergi orqanının vəzifəli şəxsləri tərəfindən müəyyən edilən yerlərdə məsul saxlamaya qoyulur.',
        24, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '89'), '89.14.2',
        'Vergi ödəyicisinin bu qaydaları pozaraq siyahıya alınmış mallara dair bağladığı əqdlər qanunvericiliklə müəyyən edilmiş qaydada etibarsız hesab edilir.',
        25, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '89'), '89.14.3',
        'Vergi ödəyicisi siyahıya alınmış malları məsul saxlamaya qoymaq üçün qəbul etməkdən imtina etdikdə və ya vergi ödəyicisinin malları saxlamaq üçün müvafiq şəraiti olmadıqda, vergi orqanının vəzifəli şəxslərinin (şəxsinin), vergi ödəyicisinin (və ya onun nümayəndəsinin), iki müşahidəçinin və obyektin məsul şəxsinin iştirakı ilə edilən hərəkətlər protokolla rəsmiləşdirilərək mallar yerindəcə qablaşdırılır, möhürlənir və obyektdən vergi orqanının müəyyən etdiyi digər vergi ödəyicisində və ya vəzifəli şəxsdə məsul saxlamaya qoyulmaq ücün götürülür.',
        26, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '89'), '89.14.4',
        'Malların obyektdən götürülməsi haqqında protokolda aşağıdakılar göstərilir:',
        27, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '89'), '89.14.4.1',
        'protokolu tərtib edən şəxsin vəzifəsi, soyadı, adı, atasının adı;',
        28, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '89'), '89.14.4.2',
        'protokolun tərtib edildiyi tarix və yer;',
        29, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '89'), '89.14.4.3',
        'malları götürülən şəxs barədə məlumat;',
        30, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '89'), '89.14.4.4',
        'protokolun tərtibində iştirak edən müşahidəçilər barədə məlumat;',
        31, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '89'), '89.14.4.5',
        'götürülən malların siyahısı və miqdarı barədə məlumat.',
        32, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '89'), '89.14.5',
        'Malların götürülməsi haqqında protokol vergi orqanının vəzifəli şəxsləri, habelə vergi ödəyicisi (və ya onun nümayəndəsi), obyektin məsul şəxsi və müşahidəçilər tərəfindən imzalanır. Vergi ödəyicisi və ya onun səlahiyyətli nümayəndəsi protokolu imzalamaqdan imtina etdikdə həmin protokolda bu barədə müvafiq qeyd aparılır.',
        33, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '89'), '89.14.6',
        'Götürülən mallar inzibati xəta haqqında işə baxılanadək, vergi orqanının müəyyən etdiyi yerdə digər vergi ödəyicisinə və ya vəzifəli şəxsə məsul saxlamaya qoyulmaq üçün təhvil verilir.',
        34, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '89'), '89.14.7',
        'Siyahıya alınmış mallar məsul saxlamaya qoyulmaq üçün vergi ödəyicisinə təhvil verildikdə, o, siyahıya alınmış malların özgəninkiləşdirilməsinə, israf edilməsinə, gizlədilməsinə, dəyişdirilməsinə yol verdiyi təqdirdə qanunvericiliklə müəyyən edilmiş qaydada məsuliyyət daşıdığı barədə xəbərdar olunmalıdır.',
        35, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '89'), '89.14.8',
        'Tərtib olunmuş aktlara və protokollara bu Məcəlləyə uyğun olaraq baxılır.',
        36, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '89'), '89.15',
        'Azərbaycan Respublikasının qanunvericiliyi ilə özəlləşdirilməsi qadağan olunan dövlət əmlakının, habelə özəlləşdirilməsi müvafiq icra hakimiyyəti orqanının qərarı ilə həyata keçirilən, lakin özəlləşdirilməsi barədə qərar qəbul edilməmiş və ya özəlləşdirilməsi başa çatmamış vergi ödəyicilərinin əmlakının siyahıya alınması yalnız müvafiq icra hakimiyyəti orqanının razılığı ilə həyata keçirilir. Vergilər üzrə borcların, faizlərin və tətbiq edilmiş maliyyə sanksiyalarının dövlət büdcəsinə alınması haqqında kredit və ya elektron pul təşkilatına sərəncam verilən gündən 15 gün müddətində vergi orqanı, bu maddədə göstərilən əmlakın siyahıya alınmasına razılıq bildirilməsi məqsədi ilə müvafiq icra hakimiyyəti orqanına rəsmi müraciət edir. Əmlakın siyahıya alınmasına bir ay müddətində razılıq verildikdə, siyahıya alınma vergi orqanı tərəfindən bu Məcəllə ilə müəyyən edilmiş qaydada həyata keçirilir.',
        37, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '89'), '89.15-1',
        'Məhkəmənin qanuni qüvvəyə minmiş qərarı ilə müflis elan olunmuş kredit təşkilatlarının əmlakı siyahıya alınmır.',
        38, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '89'), '89.16',
        'Vergi ödəyicisinin pul vəsaitləri siyahıya alınarkən siyahıya alındığı gündən sonrakı iş günündən gec olmayaraq müvafiq büdcə hesabına depozitə qoyulur. Vergi orqanı vergi ödəyicisinin pul vəsaitlərinin depozitə qoyulmasını təsdiq edən sənədin surətini ona təqdim edir. Qızıldan, gümüşdən, platindən və platin qrupundan olan materiallardan, qiymətli daşlardan və mirvaridən hazırlanmış zərgərlik məmulatları siyahıya alınarkən qablaşdırılır, möhürlənir və məsul saxlanması üçün vergi ödəyicisinə (onun qanuni və (və ya) səlahiyyətli nümayəndəsinə) və ya vergi orqanının müəyyən etdiyi digər şəxsə təhvil verilir.',
        39, false, NOW(), NOW());

