-- TAX ARTICLE (Maddə 90)
-- ============================
INSERT INTO tax_articles (article_number, title, chapter, active, created_at, updated_at)
VALUES ('90',
        'Vergi ödəyicisinin əmlakı hesabına verginin tutulması qaydası',
        'VII fəsil. Vergilərin ödənilməsi üzrə ümumi qaydalar',
        true, NOW(), NOW());

INSERT INTO tax_sections (article_id, section_number, content, order_index, synced_to_vector_store, created_at,
                          updated_at)
VALUES ((SELECT id FROM tax_articles WHERE article_number = '90'), '90.1',
        'Vergi ödəyicisinin əmlakı siyahıya alındıqdan sonra 30 gün müddətində vergi öhdəliyi yerinə yetirilmədikdə, vergi orqanı vergilər, faizlər və maliyyə sanksiyaları üzrə dövlət büdcəsinə yaranmış borclarının ödənilməsinin təmin olunması məqsədi ilə siyahıya alınmış əmlakın zəruri və kifayət olan həcmdə müvafiq icra hakimiyyəti orqanının müəyyən etdiyi orqan (qurum) vasitəsilə, habelə dəyəri 5000 manatdan artıq olmayan daşınar əmlakların isə ticarət şəbəkələrində satılması haqqında qərar qəbul olunması üçün məhkəməyə müraciət edə bilər. Siyahıya alınmış əmlakın yararlıq müddəti bu maddədə göstərilən müddət başa çatanadək bitirsə, vergi orqanı dərhal məhkəməyə müraciət edə bilər.',
        1, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '90'), '90.2',
        'Məhkəmə bu Məcəllənin 90.1-ci maddəsində göstərilən vergi orqanının müraciətinə Azərbaycan Respublikasının Mülki Prosessual Məcəlləsində müəyyən edilmiş qaydada baxır.',
        2, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '90'), '90.3',
        'Vergi ödəyicisinin siyahıya alınmış əmlakının müvafiq icra hakimiyyəti orqanının müəyyən etdiyi orqan (qurum) vasitəsilə, habelə dəyəri 5000 manatdan artıq olmayan daşınar əmlakların isə ticarət şəbəkələrində satılması haqqında məhkəmənin qərarı qanuni qüvvəyə mindikdən sonra qətnamə ilə təmin edilmiş borca faizin hesablanması dayandırılır və bu Məcəllənin 90.4-cü maddəsinin müddəaları nəzərə alınmaqla vergi borcunun dövlət büdcəsinə ödənilməsi vergi orqanı tərəfindən təmin edilir. Vergi ödəyicisinin siyahıya alınmış əmlakı vergi orqanının sifarişinə əsasən elektron hərrac vasitəsi ilə də satıla bilər. Elektron hərracın təşkili və keçirilməsi qaydaları müvafiq icra hakimiyyəti orqanı tərəfindən təsdiq olunur. Müvafiq icra hakimiyyəti orqanı vergi ödəyicisinin siyahıya alınmış əmlakının satışından əldə olunan vəsait barədə, habelə siyahıya alınmış əmlakın hərracda (o cümlədən elektron hərracda) və ya ticarət şəbəkələrində (o cümlədən satışını elektron şəkildə həyata keçirən ticarət şəbəkələrində) satılması üçün icra məmurları tərəfindən edilmiş sifarişlər barədə rüblük məlumatı müvafiq icra hakimiyyəti orqanı tərəfindən müəyyən edilmiş formada hər rüb başa çatdıqdan sonra növbəti ayın 20-dən gec olmayaraq müvafiq icra hakimiyyəti orqanına elektron şəkildə təqdim edir. Vergi ödəyicisinin siyahıya alınmış əmlakının qiymətinin məhkəmə qərarı ilə müəyyən edildiyi, habelə tənzimlənən qiymətlərin tətbiq olunduğu hallar istisna olmaqla, vergi ödəyicisinin siyahıya alınmış əmlakının qiymətləndirilməsi "Qiymətləndirmə fəaliyyəti haqqında" Azərbaycan Respublikasının Qanununa uyğun olaraq qiymətləndirici tərəfindən həyata keçirilir. Məhkəmə qərarlarına əsasən verilən icra vərəqələri daxil olduqdan 10 (on) gün müddətində qiymətləndirici "Qiymətləndirmə fəaliyyəti haqqında" Azərbaycan Respublikasının Qanunu ilə müəyyən edilmiş qaydada seçilərək dəvət olunur. Vergi orqanı qiymətləndirmə sahəsində ixtisaslaşmış və 5 ildən az olmayaraq fəaliyyət göstərən, ağır və ya xüsusilə ağır cinayətlərə, habelə korrupsiya cinayətləri və qulluq mənafeyi əleyhinə olan cinayətlərə və ya iqtisadi sahədə olan cinayətlərə görə məhkum edilməyən qiymətləndiricini dəvət etməlidir. Qiymətləndirməyə görə xidmət haqqı vergi ödəyicisi tərəfindən ödənilir. Həmin əmlak aşağıdakı qaydada satılır:',
        3, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '90'), '90.3.1',
        'Əmlakın hərracda satışı - məhkəmənin qanuni qüvvəyə minmiş qərarı əsasında əmlakın, ona dair heç bir şərt qoyulmadan satışıdır. Bu zaman ən yüksək qiymət təklif etmiş alıcı həmin əmlak üzərində mülkiyyət hüququnu əldə edir.',
        4, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '90'), '90.3.2',
        'Hərracın təşkilatçısı kimi müvafiq icra hakimiyyəti orqanının müəyyən etdiyi orqan (qurum) çıxış edir. Müvafiq icra hakimiyyəti orqanının müəyyən etdiyi orqan (qurum) hərracı vergi orqanının sifarişi əsasında həyata kecirir.',
        5, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '90'), '90.3.3',
        'Vergi orqanının sifarişinə aşağıdakı sənədlər əlavə edilməlidir:',
        6, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '90'), '90.3.3.1',
        'vergi ödəyicisinin əmlakının hərracda satışı barədə Azərbaycan Respublikasının Mülki Prosessual Məcəlləsinə uyğun olaraq məhkəmənin qanuni qüvvəyə minmiş qərarının surəti;',
        7, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '90'), '90.3.3.2',
        'icraata başlanılması barədə məhkəmə qərarına əsasən verilən icra sənədinin surəti;',
        8, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '90'), '90.3.3.2-1',
        'əmlakın fotoşəkli, yerləşdiyi ünvan barədə məlumat;',
        9, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '90'), '90.3.3.3',
        'əmlakın ilkin satış qiyməti barədə məlumat;',
        10, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '90'), '90.3.3.4',
        'əmlakın satışından əldə olunan vəsaitin köçürüləcəyi bank və digər ödəniş hesabının nömrəsi;',
        11, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '90'), '90.3.3.5',
        'əmlakın siyahıya alınması barədə vergi orqanının aktı və tərtib edilmiş siyahı;',
        12, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '90'), '90.3.3.6',
        'daşınmaz əmlak satıldıqda, həmin əmlaka dair qanunvericiliyə müvafiq olaraq zəruri olan sənədlərin surəti;',
        13, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '90'), '90.3.3.7',
        'ayrıca tikili satıldıqda, həmin tikilinin yerləşdiyi torpaq sahəsindən istifadə hüququnu və ya həmin torpaq sahəsi üzərində mülkiyyət hüququnu təsdiq edən sənədlərin surəti;',
        14, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '90'), '90.3.3.8',
        'uzunmüddətli icarə hüququ satıldıqda, müqavilənin surəti və qanunvericiliklə nəzərdə tutulmuş hallarda belə müqavilənin dövlət qeydiyyatını təsdiq edən sənədin surəti;',
        15, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '90'), '90.3.3.9',
        'tikintisi başa çatmamış obyekt üzərində hüquq satıldıqda əlavə olaraq torpaq sahəsi üzərində mülkiyyət, icarə və ya istifadə hüququnu təsdiq edən sənədin surəti və tikintiyə icazə. Məhkəmənin qərarı qüvvəyə mindiyi gün siyahıya alınmış əmlakın yararlılıq müddəti 60 gündən tez başa çatdıqda və ya qida məhsulu olduqda vergi orqanı hərracın təşkilatçısına sənədləri 3 gün müddətində təqdim etməlidir.',
        16, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '90'), '90.3.4',
        'Hərracın təşkilatçısı bu məcəllənin 90.3.3-cü maddəsində göstərilən sənədləri aldıqdan sonra hərracın keçiriləcəyi tarixə ən azı 20 gün, yararlılıq müddəti başa çatmaqda, habelə yararsız hala düşmək təhlükəsi olan qida və qeyri-qida məhsulu olan əmlak satıldıqda isə ən azı 5 gün qalmış mediada, o cümlədən internet saytlarında və sosial şəbəkələrdə hərraca çıxarılacaq əmlak barəsində elan dərc etdirir.',
        17, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '90'), '90.3.5',
        'Elanda aşağıdakı məlumatlar əks olunmalıdır:',
        18, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '90'), '90.3.5.1',
        'hər bir lot üzrə ayrı-ayrılıqda satışa çıxarılan əmlakın siyahısı, fotoşəkli, yerləşdiyi ünvan;',
        19, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '90'), '90.3.5.2',
        'siyahı üzrə əmlakın ayrı-ayrılıqda ilkin satış qiyməti;',
        20, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '90'), '90.3.5.3',
        'hərracda iştirak etmək üçün sifariş və digər sənədlərin qəbulu günü, son müddəti və yeri;',
        21, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '90'), '90.3.5.4',
        'əmlakın sahibi barədə məlumat;',
        22, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '90'), '90.3.5.5',
        'ilkin satış qiymətinin daşınmaz əmlakın 5 faizi, daşınan əmlakın 10 faizi həcmində hesablanan behin məbləği və həmin məbləğin köçürüləcəyi bank və digər ödəniş hesabı;',
        23, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '90'), '90.3.5.6',
        'əmlakın satışından əldə olunan vəsaitin köçürüləcəyi bank və digər ödəniş hesabları və bu hesablara köçürüləcək vəsaitin miqdarı;',
        24, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '90'), '90.3.5.7',
        'hərracın keçirilmə tarixi, vaxtı və yeri, əlaqə telefonunun nömrəsi;',
        25, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '90'), '90.3.5.8',
        'hərracın təşkilatçısının adı, ünvanı, əlaqə telefonu və sair rekvizitləri.',
        26, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '90'), '90.3.6',
        'Məlumatın dərc edildiyi andan qanunvericiliyə uyğun olaraq hərracda iştirak etmək hüququnu əldə etmiş şəxslərə satışa çıxarılan əmlakla tanış olmaq imkanı yaradılır. Satışa çıxarılan əmlakla tanış olduqdan sonra hərracın keçirilməsinə 5 gün qalmış hərraca buraxılmış şəxslər hərracın təşkilatçısına hərracda iştirak edib-etməyəcəkləri barədə öz qərarlarını yazılı surətdə bildirməlidirlər.',
        27, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '90'), '90.3.7',
        'Hərracda iştirak etmək üçün müraciət etmiş və müvafiq qaydada sənədləri tərtib edib, elanda göstərilən müddətdə təqdim etmiş, habelə elanda göstərilən bank və digər ödəniş hesabına behin köçürülməsi barədə bildiriş təqdim etmiş şəxslər hərracda iştirak edə bilərlər.',
        28, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '90'), '90.3.8',
        'Hərracda iştirak etmək üçün şəxs və ya onun səlahiyyətli nümayəndəsi tərəfindən imzalanmış (hüquqi şəxs tərəfindən əlavə olaraq möhürlə təsdiq edilmiş) ərizə sifariş verən tərəfindən müəyyən olunmuş nümunəyə müvafiq olaraq hərracın təşkilatçısına verilir və ərizəyə aşağıdakı sənədlər əlavə edilir:',
        29, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '90'), '90.3.8.1',
        'elanda göstərilmiş bank və digər ödəniş hesabına behin köçürüldüyünü təsdiq edən sənəd;',
        30, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '90'), '90.3.8.2',
        'fiziki şəxslər tərəfindən şəxsiyyəti təsdiq edən sənədin notariat qaydasında təsdiq edilmiş surəti;',
        31, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '90'), '90.3.8.3',
        'hüquqi şəxslər və (və ya) fərdi sahibkarlar tərəfindən vergi ödəyicisinin uçota alınması haqqında şəhadətnamənin notariat qaydasında təsdiq edilmiş surəti.',
        32, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '90'), '90.3.9',
        'Hərracın təşkilatçısı tərəfindən aşağıdakı hallar müəyyən edildikdə, şəxslər hərracda iştirak etmək üçün buraxılmırlar:',
        33, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '90'), '90.3.9.1',
        'hüquqi şəxs yenidən təşkil olunma, ləğv olunma yaxud müflis vəziyyətində olduqda;',
        34, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '90'), '90.3.9.2',
        'şəxs özü haqqında dəqiq olmayan məlumat verdikdə;',
        35, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '90'), '90.3.9.3',
        'sənədlər sifarişlərin qəbulu müddəti qurtardıqdan sonra təqdim edildikdə;',
        36, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '90'), '90.3.9.4',
        'ərizə müvafiq səlahiyyəti olmayan şəxs tərəfindən təqdim edildikdə;',
        37, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '90'), '90.3.9.5',
        'məlumatda göstərilən siyahıya uyğun bütün sənədlər təqdim edilmədikdə, yaxud təqdim olunmuş sənədlər müvafiq qaydada tərtib olunmadıqda.',
        38, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '90'), '90.3.10',
        'Sənədlərin qəbulundan imtina hərracın təşkilatçısı tərəfindən əsasları göstərilməklə edilir. Ərizəni və sənədləri qəbul edilməyən şəxslərin sənədləri, imtinanın əsasları yazılı surətdə bildirilməklə, növbəti iş günü ərzində qaytarılır.',
        39, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '90'), '90.3.11',
        'Hərracda iştirak etmək üçün şəxslər ərizəni və ona əlavə olunmuş sənədləri, habelə təqdim olunan sənədlərin 2 nüsxədən ibarət siyahısını hərracın təşkilatçısına təqdim edirlər. Hərracın təşkilatçısı hər bir ərizəni və ona əlavə olunmuş sənədləri verilmə tarixi və vaxtını göstərməklə xüsusi jurnalda ardıcıllıqla qeyd edir. Hərracın təşkilatçısı təqdim olunan sənədlərin siyahısının bir nüsxəsində ərizənin verilmə tarixini və vaxtını, habelə qeydiyyat jurnalındakı nömrəsini göstərməklə ərizəçiyə qaytarır.',
        40, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '90'), '90.3.12',
        'Hərrac iştirakçılarına onların hərracda iştirak etmək nömrəsini əks etdirən bilet verilir.',
        41, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '90'), '90.3.13',
        'Şəxs hərracda iştirak etmək üçün ərizələrin qəbulu başa çatanadək öz ərizəsini geri götürə bilər. Bunun üçün şəxs hərracın təşkilatçısına yazılı müraciət etməlidir. Sənədlərin qəbulu jurnalında hərracda iştirak etmək üçün ərizələrin geri götürülməsi barədə müvafiq qeyd aparılmalıdır. Hərracın şərtlərinə uyğun olaraq hərracda iştirak etmək üçün ərizələrini geri götürmüş şəxslərin ödədiyi beh geri qaytarılır.',
        42, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '90'), '90.3.14',
        'Hərracda iştirak etmək üçün müraciət edən şəxslərin hərraca buraxılıb-buraxılmaması barədə hərracın təşkilatçısının qərarı protokolla rəsmiləşdirilir. Bu protokolda müraciətləri (ərizələri) qəbul edilən və rədd edilən şəxslərin adları qeyd edilir. Müraciətlərinin (ərizələrinin) rədd edilməsinin əsasları şəxslərə yazılı surətdə bildirilir. Müraciətlərin (ərizələrin) qəbuluna dair protokol imzalandıqdan sonra müvafiq şəxslər hərracın iştirakçısı statusunu əldə edir.',
        43, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '90'), '90.3.15',
        'Hərracın təşkilatçısı təqdim olunmuş ərizələrin və onlara əlavə olunmuş sənədlərin müvafiq qaydada saxlanılması üçün zəruri tədbirlər görür.',
        44, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '90'), '90.3.16',
        'Çıxarılmışdır.',
        45, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '90'), '90.3.17',
        'Çıxarılmışdır.',
        46, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '90'), '90.3.18',
        'Çıxarılmışdır.',
        47, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '90'), '90.3.19',
        'Hərracın təşkilatçısı:',
        48, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '90'), '90.3.19.1',
        'hərracın təşkil olunmasını və keçirilməsini təmin edir;',
        49, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '90'), '90.3.19.2',
        'satışın baş tutub-tutmadığını təsdiq edir;',
        50, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '90'), '90.3.19.3',
        'hərracın gedişində mübahisəli vəziyyət yarandıqda mübahisənin səbəbləri aradan qaldırılanadək hərracı dayandırır. Mübahisənin səbəblərini aradan qaldırmaq mümkün olmadıqda hərracı baş tutmamış elan edir;',
        51, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '90'), '90.3.19.4',
        'hərracın yekunu barədə protokol tərtib edir və onu təsdiq etmək üçün sifariş verənə təqdim edir.',
        52, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '90'), '90.3.20',
        'Hərrac aşağıdakı qaydada keçirilir:',
        53, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '90'), '90.3.20.1',
        'satışa çıxarılan əmlakın ilkin satış qiyməti elan olunur. İlkin satış qiyməti və ya əlavələr edilməklə artırılan satış qiyməti elan olunduqda, hərrəcda iştirak edən şəxslər öz biletlərini qaldırmaqla elan olunmuş qiymətə əmlakı almağa razı olduqlarını bildirirlər;',
        54, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '90'), '90.3.20.2',
        'hərracı aparan hər yeni elan olunmuş qiyməti üç dəfə təkrar edir. Elan olunmuş satış qiymətinə əmlakı almağa razı olan hərracda iştirakçılarının sayı iki və daha çox olduqda həmin qiymət iştirakçılar tərəfindən əlavəetmə yolu ilə artırılır. Elan olunmuş satış qiymətinə əmlakı almağa yalnız bir iştirakçı razılıq verdiyi halda həmin şəxs hərracın qalibi hesab olunur. Bu vaxt hərracı aparan şəxs əmlakın satıldığını, satış qiymətini və qalib gəlmiş şəxsin biletinin nömrəsini bildirir;',
        55, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '90'), '90.3.20.3',
        'ilkin qiymət və ya əmlakın növbəti hərracda aşağı salınmış qiyməti 3 dəfə elan olunduqdan sonra iştirakçıların heç biri biletini qaldırmazsa, hərrac baş tutmamış hesab olunur;',
        56, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '90'), '90.3.20.4',
        'birinci hərrac baş tutmadıqda və ya siyahı üzrə ayrı-ayrılıqda əmlakın satışı baş tutmadıqda, hər növbəti hərraca 10 gün qalmış mediada, o cümlədən internet saytlarında və sosial şəbəkələrdə hərracla bağlı 90.3.5-ci maddədə qeyd olunan elan verilir. İkinci hərracda qiymət birinci hərracda satılmayan əmlakın və ya onun ayrılıqda siyahı üzrə satılmayan hissəsinin ilkin satış qiymətinin 20 faizi, üçüncü hərracda isə 40 faizinədək aşağı salına bilər;',
        57, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '90'), '90.3.20.5',
        'bu zaman ikinci və sonrakı hərraclar arasındakı müddət 10 gündən, yararlılıq müddəti başa çatan (yaxud, bu müddət ərzində qurtaran) əmlakın növbəti hərracları arasındakı müddət isə 3 gündən çox olmamalıdır;',
        58, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '90'), '90.3.20.6',
        'yararlılıq müddəti başa çatmış qida məhsullarının hərraca yenidən qida məhsulları qismində çıxarılması qadağandır. Bu əmlak qanunvericiliyə uyğun olaraq heyvanların yemləndirilməsi üçün istifadəyə yararlı olduqda 5 gün müddətində qanunvericiliklə müəyyən edilmiş qaydada yenidən qiymətləndirilərək hərracda satılmalıdır;',
        59, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '90'), '90.3.20.7',
        'hərrac başa çatdıqdan sonra hərracın təşkilatçısı hərracın yekunları üzrə iki nüsxədə protokol tərtib edir və qanunvericiliyə uyğun olaraq komissiyanın sədri, sifarişçi və alıcı arasında alqı-satqı müqaviləsi imzalanır;',
        60, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '90'), '90.3.20.8',
        'protokol qalib gəlmiş şəxs və ya onun nümayəndəsi, komissiyanın sədri və üzvləri tərəfindən 2 nüsxədə imzalanır. Protokolda sifarişçi və qalib gəlmiş şəxs barədə qısa məlumatlar, satılan əmlakın siyahısı və satış qiyməti, satış qiymətinin ödəniləcəyi bank və digər ödəniş hesabları, hərracda qalib gəlmiş şəxsin verdiyi beh məbləğinin imzalanmış protokol üzrə öhdəliklərin icrası hesabına daxil edilməsi, habelə tərəflərin digər hüquq və vəzifələri əks olunur. Protokolun bir nüsxəsi qalib gəlmiş şəxsə verilir. Hərracın qalibi və hərracın təşkilatçısı hərrac başa çatdığı gün protokolu imzalamalıdır. İmzalanmış protokol üç gündən gec olmayaraq satıcıya təqdim olunmalıdır. Alqı-satqı müqaviləsində satılmış obyektin adı (siyahısı), onun alınma qiyməti, sifarişçi və qalib gəlmiş şəxs barədə və qanunvericiliyə müvafiq olaraq digər məlumatlar göstərilir. Müqavilə protokol imzalandığı gündən 5 gün müddətində imzalanmalıdır;',
        61, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '90'), '90.3.20.9',
        'qalib gəlmiş şəxs qanunvericiliyə uyğun tərtib edilmiş protokolu imzalamaqdan imtina etdikdə, verdiyi beh geri qaytarılmır. Həmin protokolu imzalamaqdan imtina edən sifarişçi qalib gəlmiş şəxsə behi ikiqat məbləğdə geri qaytarmalı, habelə hərracda iştirak etmək nəticəsində dəyən zərərin əvəzini ödəməlidir. Ziyanın məbləği sifarişçinin və qalib gəlmiş şəxsin razılığı əsasında müəyyən edilir. Tərəflər razılığa gəlmədikdə zərərin məbləği onların birinin ərizəsi əsasında məhkəmə qaydasında müəyyən edilir;',
        62, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '90'), '90.3.20.10',
        'hərrac baş tutmadıqda beh geri qaytarılmalıdır. Hərracda iştirak edən, lakin onu udmayan şəxslərin behi 5 əməliyyat günü müddətində geri qaytarılır;',
        63, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '90'), '90.3.20.11',
        'hərrac baş tutmadığı hallarda hərracın təşkilatçısı tərəfindən protokol tərtib edilir.',
        64, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '90'), '90.3.21',
        'Hərracın yekunları haqqında məlumat hərracın keçirildiyi gündən 15 təqvim günü müddətində hərracın təşkilatçısı tərəfindən hərracın keçirilməsi haqqında elanın verildiyi media subyektlərində verilir.',
        65, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '90'), '90.3.22',
        'Hərracın qalibi ilə sifarişçi arasında müqavilə imzalandığı andan ən geci beş əməliyyat günü müddətində hərracın qalibi ödəməli olduğu pul vəsaitini satıcının müəyyən etdiyi bank və digər ödəniş hesabına köçürür. Hərracın təşkilatçısı hərracın keçirilməsi ilə bağlı çəkdiyi xərcləri təsdiq edən sənədləri sifarişçi təqdim edir.',
        66, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '90'), '90.3.23',
        'Əmlakın (və ya müəyyən lotun) qiymətinin tam ödənildiyini təsdiq edən ödəniş sənədi (sənədləri) təqdim edildikdən sonra əmlaka (lota) mülkiyyət hüququ hərracın qalibinə keçir.',
        67, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '90'), '90.3.24',
        'Siyahıya alınmış əmlakın açıq hərracda satışında ədliyyə orqanlarının, o cümlədən icra məmurlarının, vergi orqanlarının və hərracın təşkilatçısının vəzifəli şəxslərinin bir-başa və ya dolayısı ilə alıcı kimi iştirak etməsinə yol verilmir.',
        68, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '90'), '90.3-1',
        'Dövlət əmlakı istisna olmaqla, vergi ödəyicisinin siyahıya alınmış dəyəri 5000 manatadək olan daşınar əmlakları müvafiq icra hakimiyyəti orqanının müəyyən etdiyi orqanının (qurumun) müəyyən etdiyi qaydada vergi orqanının müəyyən etdiyi ticarət şəbəkələrində (o cümlədən satışını elektron şəkildə həyata keçirən ticarət şəbəkələrində) satıla bilər.',
        69, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '90'), '90.3-2',
        'Hərracın təşkilatçısının rəsmi internet saytı olmalı, hərracın keçirilməsi barədə elan, habelə hərraca çıxarılan əmlak barəsində məlumatlar ətraflı şəkildə həmin internet saytında yerləşdirilməlidir.',
        70, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '90'), '90.3-3',
        'Hərracın təşkilatçısı (o cümlədən elektron hərracın təşkilatçısı) keçirilmiş hərraclar, başa çatmış və ya baş tutmamış hərraclar, habelə siyahıya alınmış əmlakın satışından əldə olunan vəsaitlər barədə aylıq məlumatı müvafiq icra hakimiyyəti orqanı tərəfindən müəyyən edilmiş formada hər ay başa çatdıqdan sonra növbəti ayın 20-dən gec olmayaraq müvafiq icra hakimiyyəti orqanına təqdim edir.',
        71, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '90'), '90.3-4',
        'Ticarət şəbəkələri (o cümlədən satışını elektron şəkildə həyata keçirən ticarət şəbəkələri) satışa çıxarılmış əmlaklar, satışı təmin edilmiş və ya satışı mümkün olmadığı üçün geri qaytarılmış əmlaklar, habelə siyahıya alınmış əmlakın satışından əldə olunan vəsaitlər barədə aylıq məlumatı müvafiq icra hakimiyyəti orqanı tərəfindən müəyyən edilmiş formada hər ay başa çatdıqdan sonra növbəti ayın 20-dən gec olmayaraq müvafiq icra hakimiyyəti orqanına təqdim edir.',
        72, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '90'), '90.4',
        'Əmlakın satılmasından əldə edilən məbləğlər əvvəlcə tənbeh tədbirinin yönəldilməsi və əmlakın satışı üzrə xərclərin, sonra isə vergilər, faizlər və maliyyə sanksiyaları üzrə dövlət büdcəsinə yaranmış borcların ödənilməsinə yönəldilir. Vəsaitin qalan hissəsi vergi ödəyicisinin yeni borcu yaranmadıqda 3 əməliyyat günü ərzində vergi ödəyicisinə qaytarılır. Əmlakın satışından daxil olan pul vəsaiti vergilər, faizlər və maliyyə sanksiyaları üzrə dövlət büdcəsinə yaranmış borcların ödənilməsi üçün kifayət etmədikdə və ya əmlak qanunvericilikdə nəzərdə tutulmuş qaydada hərracda satılmadıqda, borcların dövlət büdcəsinə ödənilməsini təmin etmək məqsədilə vergi orqanı tərəfindən vergi ödəyicisinin həmin borclarının qalan məbləği həcmində digər əmlakı qanunvericilikdə nəzərdə tutulmuş qaydada siyahıya alına bilər.',
        73, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '90'), '90.5',
        'Bu maddənin müddəaları vergi agentinə də şamil edilir.',
        74, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '90'), '90.6',
        'Siyahıya alınmış əmlakın ixtisaslaşdırılmış açıq hərracda satışında hərracın təşkilatçısının, vergi orqanlarının vəzifəli şəxslərinin və ya digər işçilərinin bilavasitə və ya dolayısı ilə alıcı kimi iştirak etməsinə yol verilmir. Vergi orqanının sorğusuna əsasən hərracın təşkilatçısı tərəfindən əmlakı hərraca çıxarılmış şəxslərin əmlakının hərraca çıxarılması və satışı barədə vergi orqanına müvafiq icra hakimiyyəti orqanı tərəfindən müəyyən edilmiş formada məlumat verilir.',
        75, false, NOW(), NOW());


