INSERT INTO tax_articles (article_number, title, chapter, active, created_at, updated_at)
VALUES ('93',
        'Ümidsiz borcların silinməsi',
        'VII fəsil. Vergilərin ödənilməsi üzrə ümumi qaydalar',
        true, NOW(), NOW());

INSERT INTO tax_sections (article_id, section_number, content, order_index, synced_to_vector_store, created_at,
                          updated_at)
VALUES ((SELECT id FROM tax_articles WHERE article_number = '93'), '93.1',
        'Vergilər, faizlər və maliyyə sanksiyaları üzrə ümidsiz borclar vergi orqanları tərəfindən aşağıdakı hallarda silinir:',
        1, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '93'), '93.1.1',
        'bu Məcəllədə müəyyən edilmiş vergi öhdəliyinin yerinə yetirilməsi müddəti qurtardıqda;',
        2, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '93'), '93.1.2',
        'bu Məcəllədə müəyyən edilmiş əsaslar üzrə vergi öhdəlikləri qüvvədən düşdükdə.',
        3, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '93'), '93.1.3',
        'qanuni qüvvəyə minmiş məhkəmə qərarı ilə təmin edilmiş vergilər üzrə borcların və faizlərin, tətbiq edilmiş maliyyə sanksiyalarının (məcburi dövlət sosial sığorta, işsizlikdən sığorta və icbari tibbi sığorta haqları istisna olmaqla) dövlət büdcəsinə alınması barədə məhkəmə qərarının qüvvəyə mindiyi tarixdən 5 illik müddət keçdikdə.',
        4, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '93'), '93.2',
        'Digər hallarda vergilər, faizlər və maliyyə sanksiyaları üzrə borclar məhkəmə qərarı ilə ümidsiz borc hesab edildikdə qanunla müəyyən edilmiş qaydada silinə bilər.',
        5, false, NOW(), NOW());


