-- ============================
-- TAX ARTICLE (Maddə 96)
-- ============================
INSERT INTO tax_articles (article_number, title, chapter, active, created_at, updated_at)
VALUES ('96',
        'Vergitutma obyekti',
        'VIII fəsil. Fiziki şəxslərin gəlir vergisi',
        true, NOW(), NOW());

INSERT INTO tax_sections (article_id, section_number, content, order_index, synced_to_vector_store, created_at,
                          updated_at)
VALUES ((SELECT id FROM tax_articles WHERE article_number = '96'), '96.1',
        'Rezidentlərin gəlirləri üzrə vergitutma obyekti vergi ili üçün rezidentlərin bütün gəliri ilə həmin dövr üçün bu Məcəllə ilə müəyyənləşdirilən gəlirdən çıxılan məbləğ arasındakı fərqdən ibarət olan vergiyə cəlb edilən gəlirdir. Xüsusi notarius tərəfindən bir ay ərzində aparılan notariat hərəkətlərinə, habelə notariat hərəkətləri ilə əlaqədar göstərilən xidmətlərə görə alınan haqlar (xərclər nəzərə alınmadan) vergitutma obyektidir. "Xüsusi icra məmurları haqqında" Azərbaycan Respublikasının Qanununa əsasən xüsusi icra məmurunun fəaliyyətinə görə bir ay ərzində alınan standart və əlavə icra haqları (xərclər nəzərə alınmadan) vergitutma obyektidir. Ödəmə mənbəyində vergi tutulduğu halda, vergitutma obyekti vergiyə cəlb olunan gəlirdir.',
        1, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '96'), '96.2',
        'Azərbaycan Respublikasında daimi nümayəndəlik vasitəsilə fəaliyyət göstərən qeyri-rezident vergi ödəyicisi daimi nümayəndəliyi ilə əlaqədar olan vergiyə cəlb edilən gəlirləri üzrə gəlir vergisinin ödəyicisidir. Vergiyə cəlb olunan gəlir, konkret dövrdə Azərbaycan mənbələrindən daimi nümayəndəliklə bağlı əldə edilən ümumi gəlirlə həmin dövrdə bu gəlirlərin əldə edilməsi ilə əlaqədar çəkilən və gəlirdən çıxılan məbləğ arasındakı fərqdir.',
        2, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '96'), '96.3',
        'Qeyri-rezidentin bu Məcəllənin 96.2-ci maddəsində göstərilməyən, lakin vergiyə cəlb edilməsi bu Məcəllənin 125-ci maddəsində nəzərdə tutulan ümumi gəliri, gəlirdən çıxılan məbləğ nəzərə alınmadan ödəniş yerində vergitutma obyektidir.',
        3, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '96'), '96.4',
        'Məşğulluqdan və ya əmlakın təqdim edilməsindən gəlir əldə edən qeyri-rezident fiziki şəxs Azərbaycan mənbəyindən təqvim ili ərzində əldə etdiyi bu növ ümumi gəlirin bu Məcəllədə müəyyənləşdirilən, həmin dövrdə bu gəlirə aid olan və ondan çıxılan xərclər qədər azaldılan məbləği üzrə gəlir vergisinin ödəyicisidir.',
        4, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '96'), '96.5',
        'Kütləvi təklif edilmiş və tənzimlənən bazarda ticarətə buraxılmış səhmlərin Azərbaycan Respublikasının ərazisində, habelə ölkə hüdudlarından kənarda fond birjasında təqdim edilməsi istisna olmaqla, hüquqi şəxsin nizamnamə kapitalındakı iştirak payı və ya səhmlər xalis aktivlərin iştirak payı və ya səhmlərə mütənasib dəyərindən yuxarı qiymətə təqdim edildikdə faktiki təqdimetmə qiyməti ilə nizamnamə kapitalındakı iştirak payının və ya səhmin nominal dəyəri arasındakı fərq, iştirak payı və ya səhmlər xalis aktivlərin iştirak payı və ya səhmlərə mütənasib dəyərindən aşağı qiymətə (güzəştli qiymətlə) təqdim edildikdə isə alqı-satqı müqaviləsinin bağlandığı tarixə xalis aktivlərin mütənasib dəyəri ilə nizamnamə kapitalındakı iştirak payının nominal dəyəri arasındakı fərq vergiyə cəlb edilən gəlirdir. İştirak payları və ya səhmlər nominal qiymətdən yuxarı qiymətə alınmışdırsa, həmin iştirak paylarının və ya səhmlərin təqdim edilməsi zamanı gəlirdən çıxılan xərclər bu aktivlərin faktiki satınalma qiyməti ilə nəzərə alınır. Bu zaman iştirak payı və ya səhmlərin təqdim edilməsi əməliyyatı ilə bağlı əldə olunan gəlirdən həmin gəlirin əldə olunması ilə bağlı çəkilən digər xərclər də çıxılır.',
        5, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '96'), '96.6',
        'Kütləvi təklif edilmiş və tənzimlənən bazarda ticarətə buraxılmış səhmlərin Azərbaycan Respublikasının ərazisində, habelə ölkə hüdudlarından kənarda fond birjasında təqdim edilməsi üzrə səhmin satış dəyəri ilə alış dəyəri və çəkilən digər xərclər arasındakı fərq vergitutma obyektidir.',
        6, false, NOW(), NOW());


