INSERT INTO tax_articles (article_number, title, chapter, active, created_at, updated_at)
VALUES ('98',
        'Muzdlu işlə əlaqədar alınan gəlir',
        'VIII fəsil. Fiziki şəxslərin gəlir vergisi',
        true, NOW(), NOW());

INSERT INTO tax_sections (article_id, section_number, content, order_index, synced_to_vector_store, created_at,
                          updated_at)
VALUES ((SELECT id FROM tax_articles WHERE article_number = '98'), '98.1',
        'Fiziki şəxs tərəfindən muzdlu işlə əlaqədar alınan gəlir - əmək haqqı, bu işdən alınan hər hansı ödəmə və ya fayda, o cümlədən əvvəlki iş yerindən, yaxud gələcək muzdlu işdən alınan gəlirdir.',
        1, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '98'), '98.2',
        'Bu Məcəllənin 98.1-ci maddəsinin məqsədləri üçün gəlirin məbləği, aşağıda göstərilən məbləğdən işçinin əldə etdiyi gəlirə görə ödədiyi hər hansı xərc çıxıldıqdan sonra qalan məbləğə bərabərdir:',
        2, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '98'), '98.2.1',
        'fiziki şəxsə banklararası kredit hərracında olan faiz dərəcəsindən aşağı faiz dərəcəsi ilə ssuda verildiyi halda - bu tipli ssudalar üzrə banklararası kredit hərracında olan faiz dərəcəsinə uyğun faizlə ödənməli olan məbləğlə aşağı faiz dərəcəsinə uyğun ödənməli olan məbləğ arasındakı fərq;',
        3, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '98'), '98.2.2',
        'işəgötürənin öz işçisinə malı, işi və ya xidməti təqdim etdiyi, yaxud hədiyyə verdiyi halda - bu cür malların, işlərin və xidmətlərin bazar qiyməti ilə dəyəri;',
        4, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '98'), '98.2.3',
        'bu Məcəllənin 119.2-ci maddəsində nəzərdə tutulmuş xərclər istisna olmaqla, işçinin xərclərinin əvəzi ödənildiyi halda - ödənən vəsaitin məbləği;',
        5, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '98'), '98.2.4',
        'işçinin işə götürənə olan borcunun və ya öhdəliyinin bağışlanıldığı halda - həmin borcun və ya öhdəliyin məbləği;',
        6, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '98'), '98.2.5',
        'İşəgötürən tərəfindən ödənilən sığorta haqları.',
        7, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '98'), '98.2.6',
        'hər hansı digər halda - normativ hüquqi aktlarda başqa qiymətləndirmə metodu göstərilmirsə, bu Məcəllənin 14-cü maddəsinə uyğun olaraq müəyyən edilən dəyər;',
        8, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '98'), '98.2.7',
        'işəgötürən tərəfindən işçiyə (təhtəlhesab şəxsə) verilmiş təhtəlhesab vəsait müvafiq icra hakimiyyəti orqanının müəyyən etdiyi orqan (qurum) tərəfindən müəyyən edilmiş qaydada geri qaytarılmadıqda – həmin vəsaitin məbləği.',
        9, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '98'), '98.3',
        'Faktiki ezamiyyə xərclərinin, habelə müvafiq icra hakimiyyəti orqanı tərəfindən müəyyən edilmiş dəniz nəqliyyatında ezamiyyə xərcləri əvəzinə üzücü heyətin üzvlərinə sutkalıq ödənişlərin və ya digər işgüzar xərclərin əvəzinin ödənilməsi gəlirə daxil deyildir.',
        10, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '98'), '98.4',
        'Bu Məcəllənin 98.2-ci maddəsində göstərilən məbləğlərə və xərclərə aksizlər, əlavə dəyər vergisi və qiymətləndirilən əqdlə əlaqədar işə götürənin ödəməli olduğu hər hansı digər vergi daxildir.',
        11, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '98'), '98.5',
        'İşə götürən tərəfindən bu Məcəllənin 109.3-cü və 119.2-ci maddələrində nəzərdə tutulmuş xərclərin çəkilməsinin nəticəsi kimi əldə edilən gəlir vergi tutulan gəlirə aid deyildir.',
        12, false, NOW(), NOW());


