INSERT INTO tax_articles (article_number, title, chapter, active, created_at, updated_at)
VALUES ('101',
        'Gəlir vergisinin dərəcəsi',
        'VIII fəsil. Fiziki şəxslərin gəlir vergisi',
        true, NOW(), NOW());

INSERT INTO tax_sections (article_id, section_number, content, order_index, synced_to_vector_store, created_at,
                          updated_at)
VALUES ((SELECT id FROM tax_articles WHERE article_number = '101'), '101.1',
        'Bu Məcəllənin 101.1-1-ci maddəsinin müddəaları nəzərə alınmaqla, fiziki şəxslərin muzdlu işdən aylıq gəlirlərindən vergi aşağıdakı cədvələ uyğun tutulur (1-ci cədvəl): vergi tutulan aylıq gəlirin məbləği 2500 manatadək olduqda - 14 faiz; 2500 manatdan çox olduqda - 350 manat + 2500 manatdan çox olan məbləğin 25 faizi. İki və ya daha çox yerdə muzdla işləyən fiziki şəxslərin gəlirlərindən gəlir vergisi hər bir iş yerində ödənilən məbləğdən ayrıca hesablanır və dövlət büdcəsinə ödənilir. Fiziki şəxslərin bu Məcəllənin 150.1.1-ci, 150.1.2-ci, 150.1.3-cü və 150.1.7-ci maddələrinə əsasən ödəmə mənbəyində vergiyə cəlb olunan gəlirlərindən vergi bu maddədə nəzərdə tutulan 1-ci cədvələ uyğun olaraq hesablanır və dövlət büdcəsinə ödənilir.',
        1, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '101'), '101.1-1',
        'Neft-qaz sahəsində fəaliyyəti olmayan və qeyri-dövlət sektoruna aid edilən vergi ödəyicilərində işləyən fiziki şəxslərin muzdlu işdən aylıq gəlirlərindən vergi aşağıdakı dərəcələrlə tutulur:',
        2, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '101'), '101.1-1.1',
        '2026-cı il yanvarın 1-dən 2027-ci il yanvarın 1-dək aşağıdakı cədvələ uyğun olaraq (2-ci cədvəl): vergi tutulan aylıq gəlirin məbləği 2500 manatadək olduqda - 3 faiz; 2500 manatdan 8000 manatadək olduqda - 75 manat + 2500 manatdan 8000 manatadək olan məbləğin 10 faizi; 8000 manatdan çox olduqda - 625 manat + 8000 manatdan çox olan məbləğin 14 faizi.',
        3, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '101'), '101.1-1.2',
        '2027-ci il yanvarın 1-dən 2028-ci il yanvarın 1-dək aşağıdakı cədvələ uyğun olaraq (3-cü cədvəl): vergi tutulan aylıq gəlirin məbləği 2500 manatadək olduqda - 5 faiz; 2500 manatdan 8000 manatadək olduqda - 125 manat + 2500 manatdan 8000 manatadək olan məbləğin 10 faizi; 8000 manatdan çox olduqda - 675 manat + 8000 manatdan çox olan məbləğin 14 faizi.',
        4, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '101'), '101.1-1.3',
        '2028-ci il yanvarın 1-dən aşağıdakı cədvələ uyğun olaraq (4-cü cədvəl): vergi tutulan aylıq gəlirin məbləği 2500 manatadək olduqda - 7 faiz; 2500 manatdan 8000 manatadək olduqda - 175 manat + 2500 manatdan 8000 manatadək olan məbləğin 10 faizi; 8000 manatdan çox olduqda - 725 manat + 8000 manatdan çox olan məbləğin 14 faizi.',
        5, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '101'), '101.1-2',
        'İki və ya daha çox yerdə muzdla işləyən fiziki şəxslərin gəlirlərindən gəlir vergisi hər bir iş yerində ödənilən məbləğdən ayrıca hesablanır və dövlət büdcəsinə ödənilir.',
        6, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '101'), '101.1-3',
        'Fiziki şəxslərin bu Məcəllənin 150.1.1-ci və 150.1.2-ci maddələrinə əsasən ödəmə mənbəyində vergiyə cəlb olunan gəlirlərindən vergi bu Məcəllənin 101.1-ci və 101.1-1-ci maddələrində nəzərdə tutulan dərəcələrə uyğun olaraq hesablanır və aidiyyəti üzrə ödənilir. Bu Məcəllənin 150.1.3-cü və 150.1.7-ci (vergi orqanlarında uçota alınmayan fiziki şəxslərin göstərdiyi xidmətlərə (işlərə) münasibətdə) maddələri tətbiq edilərkən gəlir vergisi bu Məcəllənin 101.1-ci maddəsində nəzərdə tutulan verginin dərəcəsi müvafiq olaraq pensiya alan və xidməti göstərən şəxsin gəlirlərinə tətbiq edilməklə hesablanır.',
        7, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '101'), '101.1-4',
        'Bu Məcəllənin məqsədləri üçün neft-qaz sahəsində fəaliyyətin və qeyri-dövlət sektorunun meyarları müvafiq icra hakimiyyəti orqanının müəyyən etdiyi orqan (qurum) tərəfindən müəyyən edilir.',
        8, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '101'), '101.2',
        'Qeyri-sahibkarlıq fəaliyyəti üzrə illik gəlirdən 14 faiz dərəcə ilə vergi tutulur. Muzdlu işçi kimi cəlb etmədiyi fiziki şəxslərə hüquqi şəxslər, fərdi sahibkarlar və ya vergi orqanında uçotda olan qeyri-sahibkarlıq fəaliyyətindən gəlir əldə edən fiziki şəxslər tərəfindən ödənilən maddi yardım, mükafat və təqaüdlərdən, mediatorlara mediasiya təşkilatları tərəfindən mülki-hüquqi müqavilələr əsasında ödənilən xidmət haqlarından habelə vəkil qurumlarının tərkibində fəaliyyət göstərən vəkillərin həmin qurum tərəfindən ödənilən gəlirlərindən vergi bu Məcəllənin 150.1.7-ci, 150.1.17-ci və 150.1.18-ci maddələrinə uyğun olaraq bu maddənin birinci abzasında göstərilən dərəcə ilə tutulur. Qeyri-rezident müəssisə tərəfindən ödənilən dividenddən 5 faiz dərəcə ilə vergi tutulur.',
        9, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '101'), '101.3',
        'Hüquqi şəxs yaratmadan sahibkarlıq fəaliyyətini həyata keçirən fiziki şəxslərin vergiyə cəlb edilən gəlirlərindən 20 faiz dərəcə ilə vergi tutulur.',
        10, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '101'), '101.4',
        'Xüsusi notarius üçün bu Məcəllənin 96.1-ci maddəsinin ikinci abzasının birinci cümləsi ilə müəyyən edilmiş vergitutma obyektindən 10 faiz dərəcə ilə vergi tutulur.',
        11, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '101'), '101.4-1',
        'Xüsusi icra məmuru üçün bu Məcəllənin 96.1-ci maddəsinin ikinci abzasının ikinci cümləsi ilə müəyyən edilmiş vergitutma obyektindən 10 faiz dərəcə ilə vergi tutulur.',
        12, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '101'), '101.5',
        'İdman mərc oyunlarından, lotereyalardan, habelə digər yarışlardan və müsabiqələrdən pul şəklində əldə edilən uduşlardan (mükafatlardan) iştirakla bağlı ödənilən pul vəsaiti (pul qoyuluşu) çıxılmaqla qalan məbləğdən (Azərbaycan Respublikasının hüdudlarından kənarda təşkil edilən mərc oyunlarından, lotereyalardan, yarışlardan və müsabiqələrdən əldə edilən nağd pul vəsaiti istisna olmaqla) 10 faiz dərəcə ilə vergi tutulur.',
        13, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '101'), '101.6',
        'Vergi ödəyicisi kimi vergi orqanında uçotda olmayan fiziki şəxslərin "Nağdsız hesablaşmalar haqqında" Azərbaycan Respublikasının Qanununun 3.5-ci maddəsində göstərilən malların təqdim edilməsindən əldə edilən gəlirlərindən (bu Məcəllə ilə vergidən azad olunan gəlirlər istisna olmaqla) xərclər çıxılmadan 5 faiz dərəcə ilə vergi tutulur.',
        14, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '101'), '101.6-1',
        'Əlilliyi olan şəxslərin müvafiq icra hakimiyyəti orqanının müəyyən etdiyi orqanın (qurumun) rəsmi internet saytı vasitəsilə elektron ticarət qaydasında əl işlərinin satışından əldə edilən gəlirlərindən xərclər çıxılmadan 2 faiz dərəcə ilə vergi tutulur.',
        15, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '101'), '101.7',
        'Bu maddənin digər müddəalarından asılı olmayaraq, texnologiyalar parkının rezidenti kimi texnologiyalar parkından kənar fəaliyyət göstərən sistem inteqrasiyası, proqram təminatının hazırlanması və inkişaf etdirilməsi fəaliyyətini həyata keçirən vergi ödəyicilərində bu sahə üzrə işləyən mütəxəssislərin muzdlu işdən əldə edilən aylıq gəlirlərindən gəlir vergisi aşağıdakı qaydada tutulur:',
        16, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '101'), '101.7.1',
        '2023-cü il yanvarın 1-dən 3 il müddətində aylıq gəlir 8000 manatadək olduqda 0 faiz, 8000 manatdan çox olan məbləğin 5 faizi;',
        17, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '101'), '101.7.2',
        '2026-cı il yanvarın 1-dən 7 il müddətində aylıq gəlirin 5 faizi.',
        18, false, NOW(), NOW());


