INSERT INTO tax_articles (article_number, title, chapter, active, created_at, updated_at)
VALUES ('102',
        'Gəlir vergisindən azadolmalar və güzəştlər',
        'VIII fəsil. Fiziki şəxslərin gəlir vergisi',
        true, NOW(), NOW());

INSERT INTO tax_sections (article_id, section_number, content, order_index, synced_to_vector_store, created_at,
                          updated_at)
VALUES ((SELECT id FROM tax_articles WHERE article_number = '102'), '102.1',
        'Fiziki şəxslərin aşağıdakı gəlirləri gəlir vergisindən azaddır:',
        1, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '102'), '102.1.1',
        'Azərbaycan Respublikasının diplomatik nümayəndəliyində və ya konsulluğunda xidmət keçən diplomatik xidmət orqanı əməkdaşlarına, habelə "Diplomatik xidmət haqqında" Azərbaycan Respublikası Qanununun 13.15-ci və 13.16-cı maddələrində nəzərdə tutulan şəxslərə həmin Qanunun 12.5-ci və 13-cü maddələrinə uyğun olaraq ödənilən müavinətlər, kompensasiyalar və aylıq əlavə, müvafiq icra hakimiyyəti orqanının müəyyən etdiyi orqanın (qurumun) xarici dövlətlərdə və beynəlxalq təşkilatlarda nümayəndələrinə dövlət məvacibi istisna olmaqla, müvafiq icra hakimiyyəti orqanının müəyyən etdiyi orqanın (qurumun) müəyyən etdiyi qaydaya uyğun olaraq ödənilən bütün növ ödənişlər, Azərbaycan Respublikasının diplomatik nümayəndəliyində və ya konsulluğunda işləyən və Azərbaycan Respublikasının vətəndaşı olmayan işçinin əməkhaqqı.',
        2, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '102'), '102.1.2',
        'Azərbaycan Respublikasının rezidenti olmayan şəxsin iş yerindən gəlir - əgər bu gəlir Azərbaycan Respublikasının rezidenti olmayan işə götürən tərəfindən, yaxud onun adından ödənilirsə və qeyri-rezidentin daimi nümayəndəliyi tərəfindən və ya onun adından, yaxud daimi nümayəndəlikdə fəaliyyəti ilə əlaqədar ödənilmirsə;',
        3, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '102'), '102.1.3',
        'təqvim ili ərzində alınan hədiyyə, maddi yardım, birdəfəlik müavinət və miraslar:',
        4, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '102'), '102.1.3.1',
        'hədiyyələrin və təhsil haqlarını ödəmək üçün maddi yardımın, birdəfəlik müavinətin dəyərinin 2500 manatadək olan hissəsi, mirasların dəyərinin 20000 manatadək olan hissəsi; Ölkə daxilində müalicə haqlarını, o cümlədən cərrahiyyə əməliyyatının haqqını ödəmək üçün maddi yardımın, birdəfəlik müavinətin dəyərinin 10000 manatadək olan hissəsi, xaricdə müalicə haqlarını, o cümlədən cərrahiyyə əməliyyatının haqqını ödəmək üçün maddi yardımın, birdəfəlik müavinətin dəyərinin 50000 manatadək olan hissəsi. Təhsil və ya müalicə (o cümlədən cərrahiyyə əməliyyatı üçün) haqlarını ödəmək üçün maddi yardım, birdəfəlik müavinət almış şəxslərə bu güzəşt o halda verilir ki, həmin məbləğlərin təyinatı üzrə ödənildiyini təsdiq edən müvafiq sənədlər təqdim edilmiş olsun.',
        5, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '102'), '102.1.3.2',
        'hədiyyə, maddi yardım və miras vergi ödəyicisinin ailə üzvlərindən alındığı halda, onun tam dəyəri;',
        6, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '102'), '102.1.3.3',
        'şəhid olmuş şəxslərin ailə üzvlərinin əldə etdiyi maddi yardımın 20000 manatadək olan hissəsi;',
        7, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '102'), '102.1.3.4',
        'Azərbaycan Respublikasının azadlığı, suverenliyi və ərazi bütövlüyü uğrunda aparılan hərbi əməliyyatlar nəticəsində əlilliyi müəyyən edilmiş hərbi qulluqçuların və mülki şəxslərin əldə etdiyi maddi yardımın 20000 manatadək olan hissəsi. Maddi yardım almış mülki şəxslərə bu güzəşt o halda verilir ki, müvafiq icra hakimiyyəti orqanının müəyyən etdiyi orqan (qurum) tərəfindən şəxsin hərbi əməliyyatlar nəticəsində əlilliyi müəyyən edildiyini təsdiq edən arayış təqdim edilmiş olsun.',
        8, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '102'), '102.1.4',
        'Əmək qabiliyyətinin müvəqqəti itirilməsinə görə ödənilən müavinətlər istisna olmaqla, dövlət müavinətləri, əvəzsiz dövlət köçürmələri, dövlət pensiyaları, dövlət təqaüdləri, müəssisənin ləğv edilməsi və ya fiziki şəxs olan işəgötürənin fəaliyyətinə xitam verilməsi və işçilərin sayının və ştatların ixtisar edilməsi ilə əlaqədar olaraq əmək müqaviləsinə xitam verildikdə işçilərə, habelə işçinin vəfatı ilə əlaqədar əmək müqaviləsinə xitam verildikdə isə vəfat edənin vərəsələrinə Azərbaycan Respublikasının Əmək Məcəlləsinə müvafiq ödənilən təminatlar, habelə Azərbaycan Respublikasının qanunları və müvafiq icra hakimiyyəti orqanlarının qərarları əsasında dövlət büdcəsinin vəsaiti hesabına fərdi birdəfəlik ödəmələr və ya maddi yardımlar;',
        9, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '102'), '102.1.5',
        'alimentlər;',
        10, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '102'), '102.1.6',
        'Fiziki şəxsin əsas iş yerində (əmək kitabçasının olduğu yerdə) hər hansı muzdlu işlə əlaqədar əldə edilən aylıq gəliri 2500 manatadək olduqda, 200 manat, illik gəliri 30000 manatadək olduqda, 2400 manat məbləğində olan hissəsi;',
        11, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '102'), '102.1.7',
        'qiymətli daşlardan və metallardan, qiymətli daşlar və metalların məmulatlarından, incəsənət əsərlərindən, əntiq əşyalardan və vergi ödəyicisinin sahibkarlıq fəaliyyətində istifadə edilən və ya istifadə edilmiş əmlakdan, habelə "Nağdsız hesablaşmalar haqqında" Azərbaycan Respublikası Qanununun 3.5-ci maddəsində göstərilən malların vergi ödəyicilərinə təqdim edilməsindən (kənd təsərrüfatı məhsullarının istehsalçıları tərəfindən istehsal olunan kənd təsərrüfatı məhsullarının təqdim edilməsi istisna olmaqla) başqa, daşınan maddi əmlakın təqdim edilməsindən gəlir;',
        12, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '102'), '102.1.8',
        'Sığorta hadisəsi baş verdikdə sığorta olunanın və faydalanan şəxsin həyatına, habelə onun əmlakına və ya əmlak mənafelərinə dəymiş zərərin əvəzini ödəmək üçün pul və ya natura şəklində ödənilmiş vəsait, həmçinin işəgötürən tərəfindən ödənilən bütün növ icbari sığorta və könüllü tibbi sığorta haqları, 3 ildən az olmayan müddətə bağlanan müqavilə ilə həyatın yığım sığortası və pensiya sığortası üzrə qeyri-dövlət sektoruna aid edilən işəgötürənin sığortaolunanın vergiyə cəlb olunan gəlirlərinin 50 faizindən çox olmayan hissəsindən Azərbaycan Respublikasının sığortaçılarına ödədikləri sığorta haqları, həyatın yığım sığortası və pensiya sığortası üzrə müqavilənin qüvvəyə mindiyi andan etibarən 3 illik müddət keçdikdən sonra sığorta olunana və faydalanan şəxsə ödənilən hər hansı məbləğlər;',
        13, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '102'), '102.1.9',
        'vergi ödəyicisinin azı 3 il ərzində əsas yaşayış yeri olduğu daşınmaz əmlakının təqdim edilməsindən gəlir;',
        14, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '102'), '102.1.10',
        'dəymiş zərərlərin ödənilməsi ilə bağlı alınan kompensasiya ödənişləri;',
        15, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '102'), '102.1.11',
        'bilavasitə kənd təsərrüfatı məhsullarının istehsalından (o cümlədən sənaye üsulu ilə) alınan gəlirlər, o cümlədən kənd təsərrüfatı məhsullarının istehsalı ilə məşğul olan fiziki şəxslərin bu fəaliyyət üzrə satışdankənar gəlirləri, habelə kənd təsərrüfatı məhsullarının istehsalı ilə əlaqədar fiziki şəxslərə dövlət büdcəsinin vəsaiti hesabına verilən subsidiyalar;',
        16, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '102'), '102.1.11-1',
        'kənd təsərrüfatı məhsullarının istehsalı ilə məşğul olan (o cümlədən sənaye üsulu ilə) rezident hüquqi şəxslərin iştirakçıları olan fiziki şəxslərin bu sahə üzrə dividend gəlirləri - 2023-cü il yanvarın 1-dən 4 il müddətinə;',
        17, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '102'), '102.1.12',
        'sənətkarlığın misgərlik, qalayçılıq və saxsı məmulatlarının, təsərrüfat müxəlləfatının, bağçılıq-bostançılıq alətlərinin, xalq musiqi alətlərinin, oyuncaqların, suvenirlərin, qamışdan və qarğıdan məişət əşyalarının düzəldilməsi, keramika məmulatlarının bədii işlənməsi, bədii tikmə, ağac materiallardan məişət alətlərinin hazırlanması sahəsində fəaliyyət göstərən fiziki şəxslərin gəliri;',
        18, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '102'), '102.1.13',
        'müvafiq qaydada maliyyə bazarlarına nəzarət orqanında qeydiyyatdan keçmiş lotereyalardan, habelə dövlət daxili uduşlu istiqrazlardan əldə olunan uduşların dəyəri;',
        19, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '102'), '102.1.14',
        'Fiziki şəxslərə kompensasiya xarakterli aşağıdakı ödəmələr:',
        20, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '102'), '102.1.14.1',
        'iş vaxtı daimi yolda olan və ya işi gediş-gəliş (səyyar) xarakteri daşıyan, çöl təşkilatlarında işləyən işçilərə gündəlik ezamiyyə xərclərinin əvəzində verilən əlavə vəsaitin, habelə müvafiq icra hakimiyyəti orqanı tərəfindən müəyyən edilmiş dəniz nəqliyyatında ezamiyyə xərcləri əvəzinə üzücü heyətin üzvlərinə sutkalıq ödənişlərin qanunvericiliklə nəzərdə tutulan məbləği;',
        21, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '102'), '102.1.14.2',
        'müvafiq icra hakimiyyəti orqanının qərarı ilə müəyyən edilmiş ezamiyyə xərclərinin məbləğləri;',
        22, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '102'), '102.1.14.3',
        'Çıxarılmışdır.',
        23, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '102'), '102.1.14.4',
        'ağır, zərərli və təhlükəli istehsalatlarda işçilərin tibbi müayinədən keçirilməsi üçün işəgötürənin hesabına qanunvericiliklə müəyyən edilmiş qaydada ödənilmiş xərc məbləğləri;',
        24, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '102'), '102.1.14.5',
        'əmək şəraiti zərərli, ağır olan və yeraltı işlərdə çalışan işçilərə verilən pulsuz müalicə-profilaktik yeməklər, süd və ona bərabər tutulan digər məhsulların dəyəri və işçilərə müəyyən edilmiş müddətlərdə və tələb olunan çeşidlərdə verilən xüsusi geyim, xüsusi ayaqqabı və digər fərdi mühafizə vasitələrinin dəyəri;',
        25, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '102'), '102.1.14.6',
        'istehsalatdan ayrılmaqla təhsil almağa göndərilmiş tələbələrə, doktorantlara və magistrlərə müəssisə və təşkilatların hesabına ödənilən təqaüd məbləğləri;',
        26, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '102'), '102.1.14.7',
        'Çıxarılmışdır.',
        27, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '102'), '102.1.14.8',
        'təbii fəlakət və digər fövqəladə hallarla əlaqədar müvafiq icra hakimiyyəti orqanlarının qərarları əsasında, habelə xarici dövlətlər və digər təşkilatlar tərəfindən göstərilən birdəfəlik yardımlar;',
        28, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '102'), '102.1.14.9',
