       ((SELECT id FROM tax_articles WHERE article_number = '102'), '102.1.14.33',
        'dəniz nəqliyyatında xarici daşımaçılıqla məşğul olan ticarət donanmasının heyət üzvlərinə vəzifə maaşlarına verilən aylıq əlavə pul təminatının müvafiq icra hakimiyyəti orqanının müəyyən etdiyi orqan (qurum) tərəfindən təsdiq edilən məbləği.',
        53, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '102'), '102.1.15',
        'yarışlarda və müsabiqələrdə əşya şəklində alınan mükafatların tam dəyəri. Beynəlxalq yarışlarda (idman yarışları istisna olmaqla) və müsabiqələrdə pul şəklində alınan mükafatların dəyəri 4000 manatadək, respublika, regional, şəhər və rayon yarışlarında (idman yarışları istisna olmaqla) və müsabiqələrində isə 200 manatadək; Beynəlxalq, ölkələrarası idman yarışları ilə bağlı həmin yarışların təşkilatçıları və respublika idman federasiyaları (assosiasiyaları) tərəfindən verilən mükafatların tam dəyəri, habelə ölkədaxili (respublika, regional, şəhər və rayon səviyyəli) idman yarışları ilə bağlı respublika idman federasiyaları (assosiasiyaları) və idman klubları tərəfindən pul şəklində verilən mükafatların dəyəri 50000 manatadək.',
        54, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '102'), '102.1.16',
        'Dövlət qulluqçusu pensiya yaşına çatmasına görə öz arzusu ilə və ya dövlət qulluğunda olmanın yaş həddinə çatdığı üçün işdən çıxması ilə əlaqədar verilən birdəfəlik haqq.',
        55, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '102'), '102.1.17',
        'Müvafiq icra hakimiyyəti orqanının qərarı ilə vəzifəyə təyin olunan Azərbaycan Respublikasının icra hakimiyyəti və digər dövlət orqanlarının (təsisatlarının), Azərbaycan Respublikasının Mərkəzi Bankının və dövlətin adından yaradılan publik hüquqi şəxslərin rəhbər işçilərinə səlahiyyətlərinin icrası ilə bağlı təmsilçilik xərclərinin ödənilməsi üçün verilən vəzifə maaşlarına aylıq əlavə pul təminatı.',
        56, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '102'), '102.1.18',
        '"Torpaqların dövlət ehtiyacları üçün alınması haqqında" Azərbaycan Respublikasının Qanununa əsasən fiziki şəxslərə ödənilən kompensasiya;',
        57, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '102'), '102.1.19',
        '"Bədən tərbiyəsi və idman haqqında" Azərbaycan Respublikasının Qanununun 53-1-ci maddəsi ilə müəyyən edilmiş qaydada keçirilən idman mərc oyunlarından əldə edilən uduşlar.',
        58, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '102'), '102.1.20',
        'Azərbaycan Respublikasının keçmiş Prezidentinə və onun ailə üzvlərinə ödənilən pensiya, müavinət və digər ödənişlərin məbləği.',
        59, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '102'), '102.1.21',
        'Müvafiq icra hakimiyyəti orqanının müəyyən etdiyi orqanın (qurumun) yaratdığı sənaye, yaxud texnologiyalar parklarının rezidenti olan hüquqi şəxs yaratmadan sahibkarlıq fəaliyyətini həyata keçirən fiziki şəxslərin sənaye və texnologiyalar parkındakı fəaliyyətdən əldə etdikləri gəlir (əmək haqqından tutulan gəlir vergisi istisna olmaqla) - qanunvericiliyə uyğun olaraq sənaye və texnologiyalar parkında qeydiyyata alındıqları hesabat ilindən başlayaraq - 10 il müddətinə. Bu maddədə nəzərdə tutulan güzəşt texnologiyalar parkının rezidenti kimi texnologiyalar parkından kənar sistem inteqrasiyası, proqram təminatının hazırlanması və inkişaf etdirilməsi fəaliyyətini həyata keçirən şəxslərin həmin fəaliyyətdən (o cümlədən həmin fəaliyyətin həyata keçirilməsindən irəli gələrək alıcılara göstərilən təkmilləşmə, texniki dəstək və təlim xidmətləri) əldə etdikləri gəlirlərə münasibətdə də tətbiq edilir;',
        60, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '102'), '102.1.21-1',
        'texnologiyalar parkının rezidenti kimi texnologiyalar parkından kənar sistem inteqrasiyası, proqram təminatının hazırlanması və inkişaf etdirilməsi fəaliyyətini həyata keçirən şəxslər tərəfindən ödənilən dividend – texnologiyalar parkının qeydiyyat şəhadətnaməsinin alındığı hesabat ilindən başlayaraq 10 il müddətinə;',
        61, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '102'), '102.1.22',
        '2016-cı il fevralın 1-dən etibarən 7 (yeddi) il müddətində yerli bank və xarici bankın Azərbaycan Respublikasında fəaliyyət göstərən filialı tərəfindən fiziki şəxslərin əmanəti üzrə ödənilən illik faiz gəlirləri, habelə emitent tərəfindən investisiya qiymətli kağızları üzrə ödənilən dividend, diskont (istiqrazların nominalından aşağı yerləşdirilməsi nəticəsində yaranmış fərq) və faiz gəlirləri.',
        62, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '102'), '102.1.22-1',
        'Bu Məcəllə ilə müəyyən olunmuş qaydada gəlirlərin və xərclərin uçotunu aparan, ƏDV-nin məqsədləri üçün qeydiyyata alınmayan və əməliyyatlarının həcmi ardıcıl 12 aylıq dövrün istənilən ayında (aylarında) 200.000 manatadək olan rezident müəssisənin təsisçisi (payçısı) və yaxud səhmdarları olan fiziki şəxslərin dividend gəlirləri;',
        63, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '102'), '102.1.22-2',
        '2023-cü il fevralın 1-dən etibarən 5 (beş) il müddətində Azərbaycan Respublikasının ərazisində, habelə ölkə hüdudlarından kənarda rezident hüquqi şəxslər tərəfindən kütləvi təklif edilmiş və tənzimlənən bazarda ticarətə buraxılmış səhmlər və istiqrazlar üzrə ödənilən dividend, diskont (istiqrazların nominalından aşağı yerləşdirilməsi nəticəsində yaranmış fərq) və faiz gəlirləri.',
        64, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '102'), '102.1.22-3',
