        66, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '102'), '102.1.23',
        'investisiya təşviqi sənədini almış fərdi sahibkar həmin sənədi aldığı tarixdən əldə etdiyi gəlirin 50 faizi - 7 il müddətinə;',
        67, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '102'), '102.1.24',
        'Pərakəndə satış qaydasında malların satışının həyata keçirilməsi üzrə ticarət fəaliyyəti və (və ya) ictimai iaşə fəaliyyəti ilə məşğul olan fərdi sahibkar tərəfindən büdcəyə ödənilməli olan gəlir vergisinin məbləği 2019-cu il yanvarın 1-dən 3 il müddətinə "İstehlakçıların hüquqlarının müdafiəsi haqqında" Azərbaycan Respublikasının Qanunu ilə müəyyən edilmiş POS-terminal vasitəsilə nağdsız qaydada aparılan ödənişlərin ümumi gəlirdəki xüsusi çəkisinə uyğun müəyyən edilən verginin 25 faizi həcmində azaldılır. Bu güzəştin alınması hüququ müəyyən edilərkən vergi orqanında uçotda olan şəxslər tərəfindən POS-terminal vasitəsilə aparılan ödənişlərin məbləği nəzərə alınmır;',
