        74, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '102'), '102.1.30',
        'bu Məcəllənin 102.1.30-1-ci maddəsində nəzərdə tutulan hal istisna olmaqla, müvafiq il üzrə orta aylıq muzdlu işçi sayı 3 nəfərdən az olmayan və məcburi dövlət sosial sığorta haqları üzrə borcu olmayan mikro sahibkarlıq subyekti olan fərdi sahibkarların sahibkarlıq fəaliyyətindən əldə etdikləri gəlirinin 75 faizi. Müvafiq il üzrə orta aylıq muzdlu işçi sayı təqvim ili ərzində muzdlu işçilərin sayının cəmlənərək 12-yə bölünməsi yolu ilə müəyyən edilir. Vergi ödəyicisi vergi güzəştinin tətbiqi məqsədilə bu maddədə müəyyən edilən şərtlərə cavab vermədikdə və növbəti hesabat ilində mikro sahibkarlıq subyektindən digər kateqoriya sahibkarlıq subyektinə keçdikdə fərdi sahibkarın mikro sahibkar olduğu əvvəlki 3 təqvim ilinin yekunlarına görə hesablanmış və ödənilmiş gəlir vergisinin 75 faizi həcmində vergi güzəşti müəyyən edilməklə digər sahibkarlıq subyekti olduğu dövrlərdə gəlir vergisi öhdəliyindən çıxılır. Vergi ödəyicisi tərəfindən əmtəəsiz əməliyyatlar aparıldığı halda bu maddə ilə müəyyən edilmiş vergi güzəşti əmtəəsiz əməliyyatlardan yaranan gəlirlərə münasibətdə tətbiq edilmir;',
        75, false, NOW(), NOW()),
