       ((SELECT id FROM tax_articles WHERE article_number = '102'), '102.1.32',
        'KOB klasterin iştirakçısı olan fərdi sahibkarın KOB klaster şirkəti ilə bağlanmış müqavilə əsasında təqdim etdiyi mal (iş, xidmət) üzrə əldə etdiyi gəlirin kapital xarakterli xərclərin çəkilməsinə yönəldilən hissəsi – 7 il müddətinə;',
        91, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '102'), '102.1.33',
        '"Məşğulluq haqqında" Azərbaycan Respublikasının Qanununa uyğun olaraq müvafiq icra hakimiyyəti orqanının müəyyən etdiyi orqanın (qurumun) haqqı ödənilən ictimai işlərə cəlb etdiyi işçilərinin bu fəaliyyətlə əlaqədar gəlirləri;',
        92, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '102'), '102.1.33-1',
        'müvafiq icra hakimiyyəti orqanının müəyyən etdiyi orqanın (qurumun) təsdiqedici sənədi əsasında Birləşmiş Millətlər Təşkilatının İqlim Dəyişmələri üzrə Çərçivə Konvensiyasının Tərəflər Konfransının 29-cu sessiyasının (COP29) Azərbaycan Respublikasında keçirilməsi ilə əlaqədar malların təqdim edilməsinə, işlərin görülməsinə və xidmətlərin göstərilməsinə cəlb olunmuş qeyri-rezident fiziki şəxslərin bu fəaliyyət çərçivəsində əldə etdiyi gəlirlər – 2024-cü il martın 1-dən 9 ay müddətinə;',
        93, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '102'), '102.1.33-2',
        'müvafiq icra hakimiyyəti orqanının müəyyən etdiyi orqanın (qurumun) təsdiqedici sənədi əsasında Birləşmiş Millətlər Təşkilatının Ümumdünya Şəhərsalma Forumunun On Üçüncü sessiyasının (WUF13) Azərbaycan Respublikasında keçirilməsi ilə əlaqədar malların təqdim edilməsinə, işlərin görülməsinə və xidmətlərin göstərilməsinə cəlb olunmuş qeyri-rezident fiziki şəxslərin bu fəaliyyət çərçivəsində əldə etdikləri gəlirlər – 2025-ci il sentyabrın 1-dən 1 il müddətinə;',
        94, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '102'), '102.1.34',
        'müvafiq icra hakimiyyəti orqanının müəyyən etdiyi orqanın (qurumun) müəyyən etdiyi qaydada müvafiq icra hakimiyyəti orqanının müəyyən etdiyi orqan (qurum) tərəfindən verilmiş təsdiqedici sənəd əsasında Azərbaycan Respublikasında keçirilən UEFA 2019 Avropa Liqasının final oyunu və UEFA 2020 Futbol çempionatının oyunları ilə əlaqədar malların təqdim edilməsi, işlər görülməsi və xidmətlər göstərilməsinə cəlb olunmuş qeyri-rezident fiziki şəxslərin bu fəaliyyət çərçivəsində qeyri-rezident futbol klublarının oyunçularının və işçilərinin həmin oyunlarla bağlı əldə etdiyi gəlirləri;',
        95, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '102'), '102.1.35',
        'müvafiq icra hakimiyyəti orqanının müəyyən etdiyi orqan (qurum) tərəfindən təsdiq olunmuş qaydada dövlət büdcəsinin vəsaiti hesabına ödənilən ixrac təşviqi;',
        96, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '102'), '102.1.36',
        'lotereya biletlərinin satıcısı ilə bağlanmış müqavilə əsasında və ya onun tapşırığı əsasında lotereya biletlərinin bütün mərhələlərdə agent qaydasında satışının həyata keçirilməsi üzrə göstərilən xidmətlərdən əldə olunan gəlirlər;',
        97, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '102'), '102.1.37',
        'siyahısı müvafiq icra hakimiyyəti orqanının müəyyən etdiyi orqan (qurum) tərəfindən təsdiq edilmiş idxal mallarını yerli istehsal (emal) malları ilə əvəz edəcək qida (ərzaq) məhsullarının istehsalını həyata keçirən fərdi sahibkarların həmin fəaliyyətdən əldə etdiyi gəlirin 50 faizi - müvafiq siyahının təsdiq edildiyi ildən etibarən 7 il müddətinə;',
        98, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '102'), '102.1.38',
        '"Elektrik enerjisi istehsalında bərpa olunan enerji mənbələrindən istifadə haqqında" Azərbaycan Respublikası Qanununun 10-cu maddəsinə uyğun olaraq əhali qrupuna daxil olan aktiv istehlakçının bərpa olunan enerji mənbələri hesabına 150 kVt (150 kVt daxil olmaqla) güc həddinədək istehsal etdiyi elektrik enerjisinin elektrik təchizatı şəbəkəsinə ötürülməsindən əldə olunan gəlir;',
        99, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '102'), '102.1.39',
        'media subyektlərinin (audiovizual media subyektləri istisna olmaqla) öz fəaliyyətlərindən əldə etdikləri gəlirlər (o cümlədən reklam gəlirləri), habelə müvafiq icra hakimiyyəti orqanının müəyyən etdiyi orqan (qurum) tərəfindən verilən maddi yardımlar – 2023-cü il yanvarın 1-dən 6 il müddətinə;',
        100, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '102'), '102.1.40',
        'Bu Məcəllənin 165.5-ci, 165.6-cı və 228-ci maddələrinə əsasən fiziki şəxs olan istehlakçılar tərəfindən ödənilmiş ƏDV-nin qaytarılmasına görə əldə olunan gəlirlər;',
        101, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '102'), '102.1.41',
        'ictimai iaşə fəaliyyəti və özəl tibbi praktika ilə məşğul olan fiziki şəxslər tərəfindən dövlət büdcəsinə ƏDV hesablanarkən bu Məcəllənin 174.5-ci maddəsinə əsasən ƏDV məbləğinin azaldılmasından əldə edilən gəlirlər;',
        102, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '102'), '102.1.42',
        'Azərbaycan Respublikasında teatr, muzey, simfonik orkestr, habelə film istehsalı, yayımı və dublyajı fəaliyyətinə aid qeyri-maddi aktivlər üzərində müəllif hüquqlarından istifadə olunmasına, yaxud istifadə hüquqlarının verilməsinə görə royalti gəlirləri – 2025-ci il yanvarın 1-dən 5 il müddətinə;',
        103, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '102'), '102.1.43',
        'filmin istehsalı və dublyajı fəaliyyətini həyata keçirən fiziki şəxslərin və filmin prodüserinin həmin fəaliyyətdən əldə etdikləri gəlirlərin 90 faizi – 2025-ci il yanvarın 1-dən 5 il müddətinə;',
        104, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '102'), '102.1.44',
        'dövlət-özəl tərəfdaşlığı layihələri üzrə özəl tərəfdaş olan, habelə dövlətin satınalma öhdəliyi ilə bərpa olunan enerji mənbələrindən istifadə edilməklə, müvafiq icra hakimiyyəti orqanının müəyyən etdiyi orqanın (qurumun) müəyyən etdiyi məbləğdən aşağı olmayan elektrik enerjisi istehsalı layihələri üzrə istehsalçı olan fərdi sahibkarların həmin layihələr üzrə əldə etdikləri gəlir – müvafiq olaraq "Dövlət-özəl tərəfdaşlığı haqqında" Azərbaycan Respublikasının Qanununa uyğun olaraq bağlanılmış dövlət-özəl tərəfdaşlığı müqaviləsində və ya "Elektrik enerjisi istehsalında bərpa olunan enerji mənbələrindən istifadə haqqında" Azərbaycan Respublikasının Qanununa uyğun olaraq bağlanılmış elektrik enerjisinin satınalma müqaviləsi ilə müəyyən olunan müddətə, lakin 30 ildən (tikinti dövrü də daxil olmaqla) çox olmayaraq.',
        105, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '102'), '102.1-1',
        'şəhid statusu almış şəxslərin valideynlərinin, dul arvadlarının (ərlərinin) və övladlarının hər hansı muzdlu işdən vergi tutulmalı olan aylıq gəliri 800 manat məbləğində azaldılır.',
        106, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '102'), '102.2',
        'Aşağıdakı fiziki şəxslərin hər hansı muzdlu işdən vergi tutulmalı olan aylıq gəliri 400 manat məbləğində azaldılır:',
        107, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '102'), '102.2.1',
        'Azərbaycan Respublikasının Vətən Müharibəsi Qəhrəmanlarının;',
        108, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '102'), '102.2.1-1',
        'Azərbaycanın Milli Qəhrəmanlarının;',
        109, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '102'), '102.2.2',
        'Sovet İttifaqı və Sosialist Əməyi Qəhrəmanlarının;',
        110, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '102'), '102.2.3',
        'Şöhrət ordeninin hər üç dərəcəsi ilə təltif edilmiş şəxslərin;',
        111, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '102'), '102.2.4',
        'I və II qrup müharibə ilə əlaqədar əlilliyi olan şəxslərin;',
        112, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '102'), '102.2.5',
        'həlak olmuş, yaxud sonralar vəfat etmiş döyüşçülərin (şəhid statusu almış şəxslər istisna olmaqla) dul arvadlarının (ərlərinin) və övladlarının;',
        113, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '102'), '102.2.6',
        '1941-1945-ci illərdə arxa cəbhədə fədakar əməyinə görə orden və medallar ilə təltif edilmiş şəxslərin;',
        114, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '102'), '102.2.7',
        'qanunvericiliklə müəyyən edilmiş qaydada müharibə veteranı adı almış şəxslərin;',
        115, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '102'), '102.2.8',
        'Çernobıl AES-də qəza, mülki və ya hərbi təyinatlı atom obyektlərində digər radiasiya qəzaları nəticəsində, habelə nüvə qurğularının hər hansı növləri, o cümlədən nüvə silahı və kosmik texnika ilə bağlı olan sınaqlar, təlimlər və başqa işlər nəticəsində şüa xəstəliyinə və şüa yükü ilə əlaqədar xəstəliyə tutulmuş və ya bu xəstəlikləri keçirmiş şəxslərin;',
        116, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '102'), '102.2.9',
        'minatəmizləmə fəaliyyətini həyata keçirən zaman partlayıcı sursatların işə düşməsi nəticəsində baş verən bədbəxt hadisə ilə əlaqədar həlak olan və ya bu zaman aldığı xəsarətdən həyatını itirən minatəmizləyənlərin valideynlərinin, dul arvadlarının (ərlərinin) və övladlarının.',
        117, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '102'), '102.3',
        'Orqanizmin funksiyalarının 61-100 faiz pozulmasına görə əlilliyi müəyyən edilmiş şəxslərin (müharibə ilə əlaqədar əlilliyi müəyyən edilmiş şəxslər istisna olmaqla), əlilliyi olan uşaqların, daimi qulluq tələb edən əlilliyi olan uşağa və ya orqanizmin funksiyalarının 81-100 faiz pozulmasına görə əlilliyi müəyyən edilmiş şəxsə baxan və onunla birlikdə yaşayan valideynlərdən (o cümlədən övladlığa götürən şəxslərdən) birinin (özlərinin istəyi ilə), arvadın (ərin), himayəçinin və ya qəyyumun hər hansı muzdlu işdən vergi tutulmalı olan aylıq gəliri 200 manat məbləğində azaldılır.',
        118, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '102'), '102.4',
        'Aşağıdakı fiziki şəxslərin hər hansı muzdlu işdən vergi tutulmalı olan aylıq gəliri 100 manat məbləğində azaldılır:',
        119, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '102'), '102.4.1',
        'həlak olmuş, yaxud sonralar vəfat etmiş döyüşçülərin (şəhid statusu almış şəxslər istisna olmaqla) valideynləri, habelə vəzifələrinin icrası zamanı həlak olmuş dövlət qulluqçularının valideynləri və arvadları (ərləri). Bu şəxslərin arvadlarına (ərlərinə) güzəşt o halda verilir ki, onlar təkrar nikaha girmiş olmasınlar;',
        120, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '102'), '102.4.2',
        '1990-cı il yanvarın 20-də SSRİ qoşunlarının müdaxiləsi nəticəsində, habelə Azərbaycan Respublikasının ərazi bütövlüyünün müdafiəsi zamanı həlak olmuş şəxslərin valideynləri, arvadları (ərləri) və övladları. Bu şəxslərin arvadlarına (ərlərinə) güzəşt o halda verilir ki, onlar təkrar nikaha girmiş olmasınlar;',
        121, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '102'), '102.4.3',
        'Əfqanıstana və döyüş əməliyyatları aparılan başqa ölkələrə göndərilmiş hərbi qulluqçular və təlim-yoxlama toplanışlarına çağırılmış hərbi vəzifəlilər;',
        122, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '102'), '102.4.4',
        'daimi qulluq tələb edən sağlamlıq imkanları məhdud uşağa və ya I dərəcə əlilliyi olan şəxsə baxan və onunla birlikdə yaşayan valideynlərdən biri (özlərinin istəyi ilə), arvad (ər), himayəçi və ya qəyyum.',
        123, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '102'), '102.4.5',
        'məcburi köçkünlər və onlara bərabər tutulan şəxslər. Bu güzəşt mənzil qanunvericiliyinə və ya mülki hüquqi əqdlərə əsasən ayrıca mənzil sahəsi əldə etməsi nəticəsində daimi məskunlaşmış şəxslərə şamil edilmir.',
        124, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '102'), '102.5',
        'Qohumluq dərəcəsindən asılı olmayaraq himayəsində azı üç nəfər, o cümlədən gündüz təhsil alan 23 yaşınadək şagirdlər və tələbələr olan ər və ya arvaddan birinin vergi tutulmalı olan aylıq gəliri 50 manat məbləğində azaldılır. Bu qayda uşaqların 18 yaşa, tələbələrin və şagirdlərin 23 yaşa çatdığı ilin sonunadək, habelə uşaqların və himayədəkilərin öldüyü hallarda ölüm ilinin sonunadək saxlanılır. Fiziki şəxslərin vergi tutulan gəliri uşağın doğulduğu və himayədə olanın himayəyə götürüldüyü aydan başlayaraq azaldılır. Himayədə olanların sayı il ərzində azaldıqda (uşaqların ölüm halları istisna olmaqla) himayədə olanların sayının azaldığı aydan sonrakı aydan başlayaraq onların saxlanması üçün məbləğin çıxılmasına xitam verilir.',
        125, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '102'), '102.6',
        'Aşağıdakılar himayədə olanlara aid edilmirlər:',
        126, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '102'), '102.6.1',
        'təqaüd, pensiya və işsizlikdən sığorta ödənişi alan şəxslər (uşaqlardan başqa);',
        127, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '102'), '102.6.2',
        'qanuna əsasən tam dövlət təminatında olan şəxslər.',
        128, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '102'), '102.6.3',
        'xüsusi məktəblərin şagirdləri və internat evlərində olan, saxlanmasına görə qəyyumlardan haqq alınmayan uşaqlar, habelə tam dövlət təminatındakı məktəblər yanında internatlarda olan uşaqlar.',
        129, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '102'), '102.7',
        'Fiziki şəxsin bu Məcəllənin 102.1-1-ci, 102.2-ci, 102.3-cü və 102.4-cü maddələri üzrə güzəşt hüququ olduqda, ona bu güzəştlərdən biri, məbləğcə ən böyük olanı verilir.',
        130, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '102'), '102.8',
        'Əmək haqqından tutulan vergi hesablanarkən fiziki şəxslərin bu maddədə sadalanan vergi güzəştləri hüququ müvafiq icra hakimiyyəti orqanı tərəfindən müəyyənləşdirilmiş sənədlərin təqdim edildiyi andan tətbiq edilir və yalnız fiziki şəxsin əsas iş yerində (əmək kitabçasının olduğu yerdə) həyata keçirilir. Fiziki şəxsin bu maddədə sadalanan vergi güzəştlərini əldə etməyə əsas verən statusu olduğu, lakin güzəşt hüququnu təsdiq edən müvafiq sənədləri əmək müqaviləsi (kontraktı) hüquqi qüvvəyə mindikdən sonra təqdim etdiyi halda vergi güzəşti həmin fiziki şəxsin əmək müqaviləsi (kontraktı) hüquqi qüvvəyə mindiyi tarixdən hesablanır.',
        131, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '102'), '102.9',
        'Bu Məcəllənin 102.1.30-1-ci maddəsində nəzərdə tutulan fəaliyyət sahələrində muzdlu işçi kimi çalışan fiziki şəxsin əmək müqaviləsinə xitam verildiyi, həmin fəaliyyətlə fərdi sahibkar kimi məşğul olduğu və fərdi sahibkar kimi fəaliyyətə başladığı tarixdən 1 il müddətində eyni xidmətləri tam və ya qismən əvvəlki işəgötürənə göstərdiyi halda, həmin fərdi sahibkara bu Məcəllənin 102.1.30-1-ci maddəsində nəzərdə tutulan güzəşt şamil edilmir. Bu Məcəllənin 102.1.30-1-ci maddəsində nəzərdə tutulan fəaliyyət sahələri ilə məşğul olan fiziki şəxs eyni zamanda digər fəaliyyət sahəsi ilə də məşğul olduqda, həmin maddədə nəzərdə tutulan güzəşt hüququndan o halda istifadə edə bilər ki, bu Məcəllənin 102.1.30-1-ci maddəsində nəzərdə tutulan fəaliyyət sahələrindən əldə edilən illik gəlirlərin illik ümumi gəlirlərdə xüsusi çəkisi 50 faizdən az olmasın.',
        132, false, NOW(), NOW());

