INSERT INTO tax_sections (article_id, section_number, content, order_index, synced_to_vector_store, created_at,
                          updated_at)
VALUES ((SELECT id FROM tax_articles WHERE article_number = '103'), '103.1',
        'Azərbaycan Respublikasında rezident və qeyri-rezident müəssisələr, habelə sahibkarlıq fəaliyyətindən gəlir əldə edən qeyri-kommersiya təşkilatları mənfəət vergisinin ödəyiciləridir.',
        1, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '103'), '103.2',
        'Fiziki şəxs olmayan hər hansı xarici şəxs bu Məcəllənin 137-ci maddəsinə uyğun olaraq birgə sahibkarlıq fəaliyyətinin obyekti kimi baxılmalı olmadığını sübut etməyincə, bu fəsilin məqsədləri üçün ona müəssisə kimi baxılır.',
        2, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '103'), '103.3',
        'Bu Məcəllənin 103.1-ci və 103.2-ci maddələrinin müddəaları bu Məcəllənin 13.2.39.3-cü maddəsində göstərilənlərə şamil edilmir.',
        3, false, NOW(), NOW());


-- ============================
-- TAX ARTICLE (Maddə 104)
-- ============================
INSERT INTO tax_articles (article_number, title, chapter, active, created_at, updated_at)
VALUES ('104',
        'Vergitutma obyekti',
        'IX fəsil. Hüquqi şəxslərin mənfəət vergisi',
        true, NOW(), NOW());

INSERT INTO tax_sections (article_id, section_number, content, order_index, synced_to_vector_store, created_at,
                          updated_at)
VALUES ((SELECT id FROM tax_articles WHERE article_number = '104'), '104.1',
        'Rezident müəssisə üçün vergitutma obyekti onun mənfəətidir. Vergi ödəyicisinin bütün gəlirləri, o cümlədən onun Azərbaycan Respublikasının hüdudlarından kənarda daimi nümayəndəlikləri vasitəsilə əldə etdiyi gəlirləri, Azərbaycan Respublikasının hüdudlarından kənarda əldə etdiyi dividend, faiz, royalti (vergidən azad edilən gəlirdən başqa) ilə bu Məcəllənin X fəslində göstərilən, gəlirdən çıxılan xərc (vergidən azad edilən gəlirlər üzrə çəkilən xərclərdən başqa) arasındakı fərq mənfəətdir.',
        1, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '104'), '104.2',
        'Azərbaycan Respublikasında özünün daimi nümayəndəliyi vasitəsilə fəaliyyət göstərən qeyri-rezident müəssisəsi bu fəaliyyətdən əldə etdiyi mənfəətindən, yəni daimi nümayəndəliyi ilə bağlı Azərbaycan mənbəyindən əldə etdiyi ümumi gəlirinin bu Məcəlləyə uyğun olaraq həmin gəlirin əldə edilməsinə çəkilən xərclər çıxıldıqdan sonra qalan məbləğindən vergi ödəyir.',
        2, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '104'), '104.3',
        'Qeyri-rezidentin daimi nümayəndəliyi ilə bağlı olmayan ümumi gəliri, bu Məcəllənin 125-ci maddəsində nəzərdə tutulduğu hallarda xərclər çıxılmadan ödəmə mənbəyində vergiyə cəlb olunur.',
        3, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '104'), '104.4',
        'Azərbaycan Respublikasındakı daimi nümayəndəliklə bağlı olmayan əmlak təqdim edilməsindən gəlir əldə edən qeyri-rezident müəssisəsinin təqvim ili ərzində Azərbaycan mənbəyindən əldə etdiyi bu növ ümumi gəlirindən bu Məcəllədə göstərilən və həmin dövrdə bu cür gəlirə aid olan xərclər çıxıldıqdan sonra vergi tutulur.',
        4, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '104'), '104.5',
        'Əsas vəsaitlərin (vəsaitin) yenidən qiymətləndirilməsindən yaranan artım (yenidən qiymətləndirilmə nəticəsində yaranan müsbət fərq) mənfəət vergisinin vergitutma obyekti deyildir.',
        5, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '104'), '104.6',
        'Kütləvi təklif edilmiş və tənzimlənən bazarda ticarətə buraxılmış səhmlərin Azərbaycan Respublikasının ərazisində, habelə ölkə hüdudlarından kənarda fəaliyyət göstərən fond birjasında təqdim edilməsi istisna olmaqla, hüquqi şəxsin nizamnamə kapitalındakı iştirak payı və ya səhmlər xalis aktivlərin iştirak payı və ya səhmlərə mütənasib dəyərindən yuxarı qiymətə təqdim edildikdə faktiki təqdimetmə qiyməti ilə nizamnamə kapitalındakı iştirak payının və ya səhmin nominal dəyəri arasındakı fərq, iştirak payı və ya səhmlər xalis aktivlərin iştirak payı və ya səhmlərə mütənasib dəyərindən aşağı qiymətə (güzəştli qiymətlə) təqdim edildikdə isə alqı-satqı müqaviləsinin bağlanıldığı tarixə xalis aktivlərin mütənasib dəyəri ilə nizamnamə kapitalındakı iştirak payının nominal dəyəri arasındakı fərq vergiyə cəlb edilən mənfəətdir. İştirak payları və ya səhmlər nominal qiymətdən yuxarı qiymətə alınmışdırsa, həmin iştirak paylarının və ya səhmlərin təqdim edilməsi zamanı gəlirdən çıxılan xərclər bu aktivlərin faktiki satınalma qiyməti ilə nəzərə alınır. Bu zaman iştirak payı və ya səhmlərin təqdim edilməsi əməliyyatı ilə bağlı əldə olunan gəlirdən həmin gəlirin əldə olunması ilə bağlı çəkilən digər xərclər də çıxılır.',
        6, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '104'), '104.6-1',
        'Kütləvi təklif edilmiş və tənzimlənən bazarda ticarətə buraxılmış səhmlərin Azərbaycan Respublikasının ərazisində, habelə ölkə hüdudlarından kənarda fond birjasında təqdim edilməsi üzrə səhmin satış dəyəri ilə alış dəyəri və çəkilən digər xərclər arasındakı fərq vergitutma obyektidir.',
        7, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '104'), '104.7',
        'Vəkil qurumunun tərkibində fəaliyyət göstərən vəkillər tərəfindən göstərilən, yaxud göstərilməsi nəzərdə tutulan vəkillik fəaliyyəti ilə bağlı vəkil qurumuna daxil olan ödənişlərin vəkillərə ödənilən, yaxud ödənilməsi nəzərdə tutulan hissəsi qurumun vergi tutulan gəlirlərinə aid edilmir.',
        8, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '104'), '104.8',
        'Mediasiya təşkilatı ilə bağlanmış mülki-hüquqi müqavilə əsasında fəaliyyət göstərən mediatorlar tərəfindən göstərilən mediasiya xidməti ilə bağlı mediasiya təşkilatına daxil olan haqların və mükafatların həmin mediatorlara ödənilməli olan hissəsi mediasiya təşkilatının vergitutulan gəlirlərinə aid edilmir.',
        9, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '104'), '104.9',
        'Müvafiq icra hakimiyyəti orqanının müəyyən etdiyi orqanın (qurumun) müəyyən etdiyi meyarlara cavab verən investisiya layihələri üzrə dövlət müəssisələrinə dövlət büdcəsinin dövlət investisiya proqramı çərçivəsində ayrılan və aktivlərə aid edilən vəsait istisna olmaqla, dövlət büdcəsindən ayrılan və aktivlərə aid edilən digər vəsait hesabına alınan və ya quraşdırılan əsas vəsaitlərə və qeyri-maddi aktivlərə görə bu Məcəllənin 114-cü maddəsinə uyğun olaraq hesablanmış amortizasiyanın məbləği (vergi ödəyicisinin öz vəsaiti hesabına apardığı və əsas vəsaitlərin dəyərinə aid edilmiş təmir xərcləri üzrə hesablanmış amortizasiya məbləği istisna olmaqla) qədər həmin vəsaitin məbləği bu maddənin məqsədləri üçün vergitutma obyektidir.',
        10, false, NOW(), NOW());


