INSERT INTO tax_sections (article_id, section_number, content, order_index, synced_to_vector_store, created_at,
                          updated_at)
VALUES ((SELECT id FROM tax_articles WHERE article_number = '105'), '105.1',
        'Müəssisələrin mənfəətindən 20 faiz dərəcəsi ilə vergi tutulur.',
        1, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '105'), '105.2',
