INSERT INTO tax_articles (article_number, title, chapter, active, created_at, updated_at)
VALUES ('106',
        'Mənfəət vergisindən azadolmalar və güzəştlər',
        'IX fəsil. Hüquqi şəxslərin mənfəət vergisi',
        true, NOW(), NOW());

INSERT INTO tax_sections (article_id, section_number, content, order_index, synced_to_vector_store, created_at,
                          updated_at)
VALUES ((SELECT id FROM tax_articles WHERE article_number = '106'), '106.1',
        'Vergidən azaddır:',
        1, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '106'), '106.1.1',
        'xeyriyyə təşkilatlarının gəliri - sahibkarlıq fəaliyyətindən əldə etdikləri gəlirdən başqa;',
        2, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '106'), '106.1.2',
        'qeyri-kommersiya təşkilatlarının aldıqları əvəzsiz köçürmələr, üzvlük haqları və ianələr;',
        3, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '106'), '106.1.3',
        'beynəlxalq, dövlətlərarası və hökumətlərarası təşkilatların gəlirləri - sahibkarlıq fəaliyyətindən əldə etdikləri gəlirdən başqa;',
        4, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '106'), '106.1.4',
        'dövlət hakimiyyəti orqanlarının, büdcə təşkilatlarının, yerli özünüidarəetmə orqanlarının və dövlətin adından yaradılan publik hüquqi şəxslərin gəlirləri (dividend gəlirləri, sahibkarlıq fəaliyyətindən gəlir, o cümlədən publik hüquqi şəxslərin bu Məcəllənin 164.1.48-ci maddəsində göstərilmiş işlərin görülməsi və xidmətlərin göstərilməsindən (həmin maddədə nəzərdə tutulan müddətdə) başqa digər ödənişli işlər görməsindən və xidmətlər göstərməsindən əldə olunan gəlirləri və faiz gəlirləri istisna olmaqla);',
        5, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '106'), '106.1.5',
        'Azərbaycan Respublikası Mərkəzi Bankının və onun qurumlarının, ipoteka kreditləşməsi və sahibkarların aldıqları kreditlərə təminat verilməsi sahəsində fəaliyyət göstərən müvafiq icra hakimiyyəti orqanının müəyyən etdiyi orqanın (qurumun), Azərbaycan Respublikası Dövlət Neft Fondunun, Əmanətlərin Sığortalanması Fondunun, İcbari Sığorta Bürosunun gəlirləri, habelə müvafiq icra hakimiyyəti orqanının müəyyən etdiyi orqanın (qurumun) nizamnaməsinə (əsasnaməsinə) uyğun olaraq ayrılmış güzəştli kreditlər üzrə müvəkkil kredit təşkilatları tərəfindən həmin orqanlara (qurumlara) ödənilən faiz gəlirləri;',
        6, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '106'), '106.1.6',
        'alınmış sığorta ödənişləri (həmin sığorta hadisəsi ilə əlaqədar zərərə aid edilən məbləğlərdən başqa);',
        7, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '106'), '106.1.7',
        'təhsil müəssisələrinin, o cümlədən məktəbəqədər təhsil müəssisələrinin və sağlamlıq imkanları məhdud şəxslərin təhsil alması üçün yaradılmış xüsusi təhsil müəssisələrinin mənfəəti – mənfəətin dividendlərin ödənilməsinə yönəldilən hissəsi istisna olmaqla;',
        8, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '106'), '106.1.8',
        'Azərbaycan Respublikasının qanunvericiliyinə uyğun olaraq dövlət büdcəsinə olan vergi borclarının silinməsindən əldə olunan gəlir.',
        9, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '106'), '106.1.9',
        'Müvafiq icra hakimiyyəti orqanı tərəfindən müəyyən edilmiş hallarda hüquqi şəxsin qərarı ilə onun özünün və onun tam mülkiyyətində olan rezident törəmə müəssisələrinin birinin balansından digərinin balansına əvəzsiz olaraq verilən aktivlərin dəyəri;',
        10, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '106'), '106.1.10',
        'Müvafiq icra hakimiyyəti orqanının qərarına əsasən bir hüquqi şəxsin balansından əvəzsiz olaraq digər şəxsin balansına verilmiş əsas vəsaitlərin dəyəri;',
        11, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '106'), '106.1.11',
        'Neft-qaz ehtiyatlarının kəşfiyyatı, işlənməsi və hasilatın pay bölgüsü, ixrac boru kəmərləri haqqında və bu qəbildən olan digər sazişlərə uyğun olaraq əsas fondların, daşınar əmlakın və digər aktivlərin hər hansı şəkildə həmin sazişlərdə Azərbaycan Respublikasını təmsil edən tərəfə təqdim edilməsi üzrə əməliyyatlar;',
        12, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '106'), '106.1.12',
        'müvafiq icra hakimiyyəti orqanının müəyyən etdiyi orqanın (qurumun) yaratdığı sənaye, yaxud texnologiyalar parklarının idarəedici təşkilatının və ya operatorunun mənfəətinin sənaye, yaxud texnologiyalar parklarının infrastrukturunun tikintisinə və saxlanılmasına yönəldilmiş hissəsi;',
        13, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '106'), '106.1.13',
        'müvafiq icra hakimiyyəti orqanının müəyyən etdiyi orqanın (qurumun) yaratdığı sənaye, yaxud texnologiyalar parklarının rezidenti olan hüquqi şəxslərin sənaye və texnologiyalar parkındakı fəaliyyətdən əldə etdikləri gəlir - qanunvericiliyə uyğun olaraq sənaye və texnologiyalar parkında qeydiyyata alındıqları hesabat ilindən başlayaraq - 10 il müddətinə. Bu maddədə nəzərdə tutulan güzəşt texnologiyalar parkının rezidenti kimi texnologiyalar parkından kənar sistem inteqrasiyası, proqram təminatının hazırlanması və inkişaf etdirilməsi fəaliyyətini həyata keçirən hüquqi şəxslərin həmin fəaliyyətdən (o cümlədən həmin fəaliyyətin həyata keçirilməsindən irəli gələrək alıcılara göstərilən təkmilləşmə, texniki dəstək və təlim xidmətləri) əldə etdikləri gəlirə münasibətdə də tətbiq edilir;',
        14, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '106'), '106.1.13-1',
        'texnologiyalar parkının rezidenti kimi texnologiyalar parkından kənar sistem inteqrasiyası, proqram təminatının hazırlanması və inkişaf etdirilməsi fəaliyyətini həyata keçirən şəxslər tərəfindən ödənilən dividend – texnologiyalar parkının qeydiyyat şəhadətnaməsinin alındığı hesabat ilindən başlayaraq 10 il müddətinə;',
        15, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '106'), '106.1.13-2',
        'müvafiq icra hakimiyyəti orqanının müəyyən etdiyi orqanın (qurumun) yaratdığı sənaye parkında müvafiq icra hakimiyyəti orqanının müəyyən etdiyi orqanın (qurumun) müəyyən etdiyi fəaliyyətlə məşğul olan sənaye parkının rezidentinin sənaye parkındakı həmin fəaliyyətdən əldə etdiyi mənfəət - 2025-ci il yanvarın 1-dən 6 il müddətinə;',
        16, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '106'), '106.1.14',
        'kənd təsərrüfatı məhsullarının istehsalı ilə məşğul olan (o cümlədən, sənaye üsulu ilə) hüquqi şəxslərin bu fəaliyyətdən əldə etdikləri mənfəət - 2014-cü il yanvarın 1-dən 13 il müddətinə;',
        17, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '106'), '106.1.14-1',
        'kənd təsərrüfatı məhsullarının istehsalı ilə məşğul olan (o cümlədən sənaye üsulu ilə) hüquqi şəxslərin bu fəaliyyət üzrə satışdankənar gəlirləri, kənd təsərrüfatı məhsullarının istehsalı ilə əlaqədar hüquqi şəxslərə dövlət büdcəsinin vəsaiti hesabına verilən subsidiyalar, habelə kənd təsərrüfatı məhsullarının istehsalı ilə məşğul olan (o cümlədən sənaye üsulu ilə) rezident hüquqi şəxslərin iştirakçıları olan hüquqi şəxslərin bu sahə üzrə dividend gəlirləri - 2023-cü il yanvarın 1-dən 4 il müddətinə;',
        18, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '106'), '106.1.15',
        'məktəbəqədər təhsil müəssisələrinin və uşaq evlərinin bu fəaliyyətdən əldə etdikləri gəlirləri 2014-cü il yanvarın 1-dən 10 il müddətinə;',
        19, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '106'), '106.1.16',
        '"Torpaqların dövlət ehtiyacları üçün alınması haqqında" Azərbaycan Respublikasının Qanununa əsasən hüquqi şəxslərə ödənilən kompensasiya;',
        20, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '106'), '106.1.17',
        'investisiya təşviqi sənədini almış hüquqi şəxsin həmin sənədi aldığı tarixdən əldə etdiyi mənfəətin 50 faizi - 7 il müddətinə;',
        21, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '106'), '106.1.18',
        'paylarının (səhmlərinin) 51 və daha artıq faizi birbaşa və ya dolayısı ilə dövlətə məxsus olan hüquqi şəxslər və dövlətin adından yaradılan publik hüquqi şəxslər istisna olmaqla, vergi ödəyicisinin hesabat ilinin mənfəətinin 15 faizindən çox olmayan hissəsinin müvafiq icra hakimiyyəti orqanının müəyyən etdiyi orqan (qurum) tərəfindən müəyyən edilən meyarlara cavab verən elm, təhsil, səhiyyə, idman və mədəniyyət sahəsində fəaliyyət göstərən müəssisə, idarə və təşkilatlara, habelə siyahısı müvafiq icra hakimiyyəti orqanının müəyyən etdiyi orqan (qurum) tərəfindən təsdiq edilən ictimai və sosial məqsədlər üçün yaradılmış fondlara köçürülən hissəsi 2024-cü il yanvarın 1-dən 5 il müddətinə. Bu maddənin müddəaları yalnız nağdsız qaydada ödənilən xərclərə münasibətdə tətbiq edilir.',
        22, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '106'), '106.1.19',
        'vergi ödəyicisinin azı 3 (üç) il ərzində mülkiyyətində olan iştirak payının və ya səhmin təqdim edilməsindən əldə olunan gəlirlərinin 50 faizi;',
        23, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '106'), '106.1.20',
        'müvafiq il üzrə orta aylıq muzdlu işçi sayı 3 nəfərdən az olmayan və məcburi dövlət sosial sığorta haqları üzrə borcu olmayan mikro sahibkarlıq subyekti olan hüquqi şəxslərin sahibkarlıq fəaliyyətindən əldə etdikləri mənfəətin 75 faizi. Müvafiq il üzrə orta aylıq muzdlu işçi sayı təqvim ili ərzində muzdlu işçilərin sayının cəmlənərək 12-yə bölünməsi yolu ilə müəyyən edilir. Vergi ödəyicisi vergi güzəştinin tətbiqi məqsədilə bu maddədə müəyyən edilən şərtlərə cavab vermədikdə və növbəti hesabat ilində mikro sahibkarlıq subyektindən digər kateqoriya sahibkarlıq subyektinə keçdikdə hüquqi şəxsin mikro sahibkar olduğu əvvəlki 3 təqvim ilinin yekunlarına görə hesablanmış və ödənilmiş mənfəət vergisinin 75 faizi həcmində vergi güzəşti müəyyən edilməklə digər sahibkarlıq subyekti olduğu dövrlərdə mənfəət vergisi öhdəliyindən çıxılır. Vergi ödəyicisi tərəfindən əmtəəsiz əməliyyatlar aparıldığı halda bu maddə ilə müəyyən edilmiş vergi güzəşti əmtəəsiz əməliyyatlardan yaranan gəlirlərə münasibətdə tətbiq edilmir;',
        24, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '106'), '106.1.21',
        'KOB klaster şirkətinin mənfəəti – KOB klaster şirkətinin KOB klaster şirkətlərinin reyestrinə daxil edildiyi tarixdən 7 il müddətinə;',
        25, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '106'), '106.1.22',
        'KOB klasterin iştirakçısı olan hüquqi şəxsin KOB klaster şirkəti ilə bağlanmış müqavilə əsasında təqdim etdiyi mal (iş, xidmət) üzrə əldə etdiyi mənfəətin kapital xarakterli xərclərin çəkilməsinə yönəldilən hissəsi – 7 il müddətinə;',
        26, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '106'), '106.1.23',
        'mikro və ya kiçik sahibkarlıq subyekti olan və hüquqi şəxs kimi fəaliyyət göstərən startapların "Startap" şəhadətnaməsi aldığı tarixdən innovasiya fəaliyyətindən əldə etdikləri mənfəəti – 3 il müddətinə;',
        27, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '106'), '106.1.24',
        '"Məşğulluq haqqında" Azərbaycan Respublikasının Qanununa uyğun olaraq müvafiq icra hakimiyyəti orqanının müəyyən etdiyi orqanın (qurumun) haqqı ödənilən ictimai işlərin təşkili ilə bağlı fəaliyyətdən əldə etdiyi gəlir;',
        28, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '106'), '106.1.25',
        'müvafiq icra hakimiyyəti orqanının müəyyən etdiyi orqanın (qurumun) müəyyən etdiyi qaydada müvafiq icra hakimiyyəti orqanının müəyyən etdiyi orqan (qurum) tərəfindən verilmiş təsdiqedici sənəd əsasında Azərbaycan Respublikasında keçirilən UEFA 2019 Avropa Liqasının final oyunu ilə əlaqədar UEFA-nın, onun yaratdığı qeyri-rezident hüquqi şəxslərin, qeyri-rezident futbol klublarının (assosiasiyalarının) həmin oyunla bağlı əldə etdiyi gəlirləri;',
        29, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '106'), '106.1.26',
        'müvafiq icra hakimiyyəti orqanının müəyyən etdiyi orqanın (qurumun) müəyyən etdiyi qaydada müvafiq icra hakimiyyəti orqanının müəyyən etdiyi orqan (qurum) tərəfindən verilmiş təsdiqedici sənəd əsasında Azərbaycan Respublikasında keçirilən UEFA 2020 Futbol çempionatının oyunları ilə əlaqədar UEFA-nın, onu təmsil edən və onun yaratdığı qeyri-rezident hüquqi şəxslərin, habelə qeyri-rezident futbol klublarının (assosiasiyalarının) çempionatla bağlı əldə etdiyi gəlirləri;',
        30, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '106'), '106.1.27',
        'müvafiq icra hakimiyyəti orqanının müəyyən etdiyi orqan (qurum) tərəfindən təsdiq olunmuş qaydada dövlət büdcəsinin vəsaiti hesabına ödənilən ixrac təşviqi;',
        31, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '106'), '106.1.28',
        'Azərbaycan Respublikasında keçirilən Formula 1 və Formula 2 yarışlarına aid qeyri-maddi aktivlər üzərində müəllif hüquqlarından istifadə olunmasına, yaxud istifadə hüquqlarının verilməsinə görə müvafiq icra hakimiyyəti orqanının müəyyən etdiyi orqan (qurum) ilə bağlanılmış müqavilə əsasında onun tərəfindən qeyri-rezident hüquqi şəxsə ödənilən royalti gəlirləri - 2018-ci il yanvarın 1-dən 9 il müddətinə;',
        32, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '106'), '106.1.28-1',
        'Birləşmiş Millətlər Təşkilatının İqlim Dəyişmələri üzrə Çərçivə Konvensiyasının Tərəflər Konfransının 29-cu sessiyasının (COP29) Azərbaycan Respublikasında keçirilməsi ilə əlaqədar qeyri-maddi aktivlər üzərində müəllif hüquqlarından istifadə olunmasına, yaxud istifadə hüquqlarının verilməsinə görə müvafiq icra hakimiyyəti orqanının müəyyən etdiyi orqanla (qurumla) bağlanılmış müqavilə əsasında onun tərəfindən qeyri-rezident hüquqi şəxsə ödənilən royalti gəlirləri – 2024-cü il martın 1-dən 9 ay müddətinə;',
        33, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '106'), '106.1.28-2',
        'müvafiq icra hakimiyyəti orqanının müəyyən etdiyi orqanın (qurumun) təsdiqedici sənədi əsasında Birləşmiş Millətlər Təşkilatının İqlim Dəyişmələri üzrə Çərçivə Konvensiyasının Tərəflər Konfransının 29-cu sessiyasının (COP29) Azərbaycan Respublikasında keçirilməsi ilə əlaqədar qeyri-rezident hüquqi şəxslər tərəfindən işlərin görülməsindən və xidmətlərin göstərilməsindən əldə edilən gəlirlər – 2024-cü il martın 1-dən 9 ay müddətinə;',
        34, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '106'), '106.1.28-3',
        'Birləşmiş Millətlər Təşkilatının Ümumdünya Şəhərsalma Forumunun On Üçüncü sessiyasının (WUF13) Azərbaycan Respublikasında keçirilməsi ilə əlaqədar qeyri-maddi aktivlər üzərində müəllif hüquqlarından istifadə olunmasına, yaxud istifadə hüquqlarının verilməsinə görə müvafiq icra hakimiyyəti orqanının müəyyən etdiyi orqanla (qurumla) bağlanılmış müqavilə əsasında onun tərəfindən qeyri-rezident hüquqi şəxsə ödənilən royalti gəlirləri – 2025-ci il sentyabrın 1-dən 1 il müddətinə;',
        35, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '106'), '106.1.28-4',
        'müvafiq icra hakimiyyəti orqanının müəyyən etdiyi orqanın (qurumun) təsdiqedici sənədi əsasında Birləşmiş Millətlər Təşkilatının Ümumdünya Şəhərsalma Forumunun On Üçüncü sessiyasının (WUF13) Azərbaycan Respublikasında keçirilməsi ilə əlaqədar qeyri-rezident hüquqi şəxslər tərəfindən işlərin görülməsindən və xidmətlərin göstərilməsindən əldə edilən gəlirlər – 2025-ci il sentyabrın 1-dən 1 il müddətinə;',
        36, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '106'), '106.1.29',
        'lotereya biletlərinin satıcısı ilə bağlanmış müqavilə əsasında və ya onun tapşırığı əsasında lotereya biletlərinin bütün mərhələlərdə agent qaydasında satışının həyata keçirilməsi üzrə göstərilən xidmətlərdən əldə olunan gəlirlər;',
        37, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '106'), '106.1.30',
        'vəkillər və vəkil qurumları tərəfindən order markasının əldə edilməsi ilə bağlı Azərbaycan Respublikasının Vəkillər Kollegiyasına edilən ödənişlər;',
        38, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '106'), '106.1.31',
        'siyahısı müvafiq icra hakimiyyəti orqanının müəyyən etdiyi orqan (qurum) tərəfindən təsdiq edilmiş idxal mallarını yerli istehsal (emal) malları ilə əvəz edəcək qida (ərzaq) məhsullarının istehsalını həyata keçirən hüquqi şəxslərin həmin fəaliyyətdən əldə etdikləri mənfəətin 50 faizi - müvafiq siyahının təsdiq edildiyi ildən etibarən 7 il müddətinə;',
        39, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '106'), '106.1.32',
        'media subyektlərinin (audiovizual media subyektləri istisna olmaqla) öz fəaliyyətlərindən əldə etdikləri gəlirlər (o cümlədən reklam gəlirləri), habelə müvafiq icra hakimiyyəti orqanının müəyyən etdiyi orqan (qurum) tərəfindən verilən maddi yardımlar – 2023-cü il yanvarın 1-dən 6 il müddətinə;',
        40, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '106'), '106.1.33',
        'qanunla müəyyən olunmuş qaydada Azərbaycan Respublikasında qeydiyyatdan keçən və teatr, muzey, simfonik orkestr, habelə film istehsalını və dublyajını həyata keçirən kinematoqrafiya müəssisəsinin və filmin prodüserinin həmin fəaliyyətdən əldə etdiyi mənfəətin 90 faizi – 2025-ci il yanvarın 1-dən 5 il müddətinə;',
        41, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '106'), '106.1.34',
        'ictimai iaşə fəaliyyəti ilə məşğul olan şəxslər və tibb müəssisələri tərəfindən dövlət büdcəsinə ƏDV hesablanarkən bu Məcəllənin 174.5-ci maddəsinə əsasən ƏDV məbləğinin azaldılmasından əldə edilən gəlirlər;',
        42, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '106'), '106.1.35',
        'dövlət-özəl tərəfdaşlığı layihələri üzrə özəl tərəfdaş və ya layihə şirkəti olan, habelə dövlətin satınalma öhdəliyi ilə bərpa olunan enerji mənbələrindən istifadə edilməklə, müvafiq icra hakimiyyəti orqanının müəyyən etdiyi orqanın (qurumun) müəyyən etdiyi məbləğdən aşağı olmayan elektrik enerjisi istehsalı layihələri üzrə istehsalçı olan hüquqi şəxslərin həmin layihələr üzrə əldə etdikləri mənfəət – müvafiq olaraq "Dövlət-özəl tərəfdaşlığı haqqında" Azərbaycan Respublikasının Qanununa uyğun olaraq bağlanılmış dövlət-özəl tərəfdaşlığı müqaviləsində və ya "Elektrik enerjisi istehsalında bərpa olunan enerji mənbələrindən istifadə haqqında" Azərbaycan Respublikasının Qanununa uyğun olaraq bağlanılmış elektrik enerjisinin satınalma müqaviləsi ilə müəyyən olunan müddətə, lakin 30 ildən (tikinti dövrü də daxil olmaqla) çox olmayaraq;',
        43, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '106'), '106.1.36',
        '"Sosial sığorta haqqında" və "İşsizlikdən sığorta haqqında" Azərbaycan Respublikasının qanunlarına uyğun olaraq sərbəst vəsaitlərin investisiyaya yönəldilməsindən əldə olunan gəlirlər.',
        44, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '106'), '106.2',
        'Əlilliyi olan şəxslərin qeyri-hökumət təşkilatlarına məxsus olan işçilərinin ümumi sayının azı 50 faizi əlilliyi olan şəxslərdən ibarət olan istehsal müəssisələrinin mənfəət vergisinin dərəcəsi 50 faiz azaldılır. Bu güzəştlərin alınması hüququ müəyyən edilərkən işçilərin orta siyahı sayına əvəzçilik, podrat müqavilələri və mülki-hüquqi xarakterli digər müqavilələr üzrə işləyən əlilliyi olan şəxslər, o cümlədən sağlamlıq imkanları məhdud 18 yaşınadək uşaqlar daxil edilmir.',
        45, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '106'), '106.3',
        'Çıxarılmışdır.',
        46, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '106'), '106.4',
        'Çıxarılmışdır.',
        47, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '106'), '106.5',
        'Çıxarılmışdır.',
        48, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '106'), '106.6',
        'Çıxarılmışdır.',
        49, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '106'), '106.7',
        'Çıxarılmışdır.',
        50, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '106'), '106.8',
        'Çıxarılmışdır.',
        51, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '106'), '106.9',
        'Pərakəndə satış qaydasında malların satışının həyata keçirilməsi üzrə ticarət fəaliyyəti və (və ya) ictimai iaşə fəaliyyəti ilə məşğul olan hüquqi şəxslər tərəfindən büdcəyə ödənilməli olan mənfəət vergisinin məbləği 2019-cu il yanvarın 1-dən 3 il müddətinə "İstehlakçıların hüquqlarının müdafiəsi haqqında" Azərbaycan Respublikasının Qanunu ilə müəyyən edilmiş POS-terminal vasitəsilə nağdsız qaydada aparılan ödənişlərin ümumi gəlirdəki xüsusi çəkisinə uyğun müəyyən edilən verginin 25 faizi həcmində azaldılır. Bu güzəştin alınması hüququ müəyyən edilərkən vergi orqanında uçotda olan şəxslər tərəfindən POS-terminal vasitəsilə aparılan ödənişlərin məbləği nəzərə alınmır.',
        52, false, NOW(), NOW()),
       ((SELECT id FROM tax_articles WHERE article_number = '106'), '106.10',
        'Bu Məcəllə ilə müəyyən olunmuş qaydada gəlirlərin və xərclərin uçotunu aparan, ƏDV-nin məqsədləri üçün qeydiyyata alınmayan və əməliyyatlarının həcmi ardıcıl 12 aylıq dövrün istənilən ayında (aylarında) 200.000 manatadək olan rezident müəssisənin təsisçisi (payçısı) və yaxud səhmdarları olan hüquqi şəxslərin dividend gəlirləri vergidən azaddır.',
        53, false, NOW(), NOW());

